    pub async fn ui_protocols_summary_snapshot(
        &self,
        token: &str,
    ) -> Result<UiProtocolsSummary, SecurityError> {
        self.me(token).await?;
        let config = self.config_snapshot().await;
        // The binary is queried on every call on purpose: the Xray update flow
        // swaps it without restarting the panel, and a cached value in a field that
        // exists to detect mismatches is worse than none. The endpoint is
        // operator-facing and called on form render, not in a loop.
        let xray_version = match config.xray_binary_path.clone() {
            Some(path) => {
                tokio::task::spawn_blocking(move || xray_candidate_version(Path::new(&path)).ok())
                    .await
                    .unwrap_or(None)
            }
            None => None,
        };
        Ok(build_ui_protocols_summary(xray_version))
    }

