    pub async fn login(
        &self,
        client_ip: &str,
        username: &str,
        password: &str,
        two_factor_code: Option<&str>,
        challenge_token: Option<&str>,
    ) -> Result<LoginSuccess, LoginFailure> {
        let config = self.config_snapshot().await;
        let mut runtime = self.security.write().await;
        let result = runtime.login(
            &config,
            client_ip,
            username,
            password,
            two_factor_code,
            challenge_token,
        );
        match &result {
            Ok(success) => {
                drop(runtime);
                let _ = self
                    .append_audit_event(
                        AuditEventType::LoginSucceeded,
                        Some(success.admin.username.clone()),
                        Some(client_ip.to_string()),
                        "admin login succeeded".to_string(),
                    )
                    .await;
            }
            Err(failure) => {
                drop(runtime);
                let detail = match failure.reason {
                    "ip_banned" => "login rejected due to active IP ban".to_string(),
                    "admin_not_configured" => {
                        "login rejected because bootstrap admin is not configured".to_string()
                    }
                    "session_limit_reached" => {
                        "login rejected because session limit was reached".to_string()
                    }
                    "two_factor_required" => {
                        "login rejected because 2fa code was required".to_string()
                    }
                    "two_factor_second_step_required" => {
                        "first 2fa step accepted, second step pending".to_string()
                    }
                    "two_factor_wait_required" => {
                        "second 2fa step attempted before wait timer elapsed".to_string()
                    }
                    "invalid_two_factor_code" => {
                        "login rejected due to invalid 2fa code".to_string()
                    }
                    _ => "login rejected due to invalid credentials".to_string(),
                };
                let _ = self
                    .append_audit_event(
                        AuditEventType::LoginFailed,
                        Some(username.to_string()),
                        Some(client_ip.to_string()),
                        detail,
                    )
                    .await;
            }
        }
        result
    }

