    pub async fn update_telegram_settings(
        &self,
        token: &str,
        request: UpdateTelegramSettingsRequest,
    ) -> Result<TelegramSettings, SecurityError> {
        let admin = self.me(token).await?;
        let existing_bot_token_configured = {
            let runtime = self.telegram.read().await;
            runtime
                .settings
                .bot_token
                .as_deref()
                .map(|value| !value.trim().is_empty())
                .unwrap_or(false)
        };
        validate_telegram_settings(&request, existing_bot_token_configured)?;
        let config = self.config_snapshot().await;
        {
            let mut runtime = self.telegram.write().await;
            runtime.update_settings(&request);
            persist_telegram_settings(
                &config.telegram_settings_path,
                &config.telegram_secrets_key_path,
                &runtime.settings,
            )?;
        }
        let _ = self
            .append_audit_event(
                AuditEventType::TelegramSettingsUpdated,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!(
                    "telegram settings updated: enabled={} bot_token_supplied={} default_chat_id_supplied={}",
                    request.enabled,
                    request.bot_token.as_deref().is_some_and(|value| !value.trim().is_empty()),
                    request
                        .default_chat_id
                        .as_deref()
                        .is_some_and(|value| !value.trim().is_empty())
                ),
            )
            .await;
        self.notify_telegram_event(
            TelegramEventKind::Security,
            "Telegram settings updated".to_string(),
        )
        .await;
        self.telegram_settings(token).await
    }

