    pub async fn create_panel_installer_job(
        &self,
        token: &str,
        request: PanelInstallerCreateJobRequest,
    ) -> Result<PanelInstallerCreateJobResponse, SecurityError> {
        let admin = self.me(token).await?;
        let now = now_unix();
        let config = self.config_snapshot().await;
        let (job, executor_token, executor_token_hash) =
            build_panel_installer_job_record(request, now)?;
        {
            let mut runtime = self.installer.write().await;
            runtime.jobs.insert(
                job.job_id.clone(),
                InstallerJobRecord {
                    view: job.clone(),
                    executor_token_hash,
                },
            );
            runtime.compact(config.runtime_limits.max_panel_installer_jobs_buffered);
            persist_panel_installer_jobs(&config.panel_installer_jobs_path, &runtime)?;
        }
        let job_id = job.job_id.clone();
        let _ = self
            .append_audit_event(
                AuditEventType::PanelInstallerJobCreated,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!("panel installer job created: {job_id}"),
            )
            .await;
        Ok(PanelInstallerCreateJobResponse {
            job,
            executor_token,
        })
    }

