    pub async fn panel_installer_job_heartbeat(
        &self,
        request: PanelInstallerJobHeartbeatRequest,
    ) -> Result<PanelInstallerJobView, SecurityError> {
        let now = now_unix();
        let config = self.config_snapshot().await;
        let mut runtime = self.installer.write().await;
        let record = runtime.authenticate_job_mut(&request.job_id, &request.executor_token, now)?;
        record.view.status = PanelInstallerJobStatus::Running;
        record.view.updated_at_unix = now;
        record.view.last_heartbeat = Some(PanelInstallerJobHeartbeatView {
            observed_phase: request
                .observed_phase
                .filter(|value| !value.trim().is_empty()),
            message: request.message.filter(|value| !value.trim().is_empty()),
            reported_at_unix: now,
        });
        record.view.detail = "installer heartbeat accepted".to_string();
        let view = record.view.clone();
        runtime.compact(config.runtime_limits.max_panel_installer_jobs_buffered);
        persist_panel_installer_jobs(&config.panel_installer_jobs_path, &runtime)?;
        Ok(view)
    }

