    pub async fn panel_installer_job_result(
        &self,
        request: PanelInstallerJobResultRequest,
    ) -> Result<PanelInstallerJobView, SecurityError> {
        let now = now_unix();
        let config = self.config_snapshot().await;
        let mut runtime = self.installer.write().await;
        let record = runtime.authenticate_job_mut(&request.job_id, &request.executor_token, now)?;
        let expected_command_ids = record
            .view
            .session
            .command_envelopes
            .iter()
            .map(|command| command.command_id.clone())
            .collect::<Vec<_>>();
        let expected_operation_ids =
            panel_installer_expected_operation_ids(&record.view.session.command_envelopes);
        let result = validate_panel_installer_result(PanelInstallerSessionResultRequest {
            session_id: record.view.session.session_id.clone(),
            access_mode: record.view.bootstrap.plan.access_mode,
            expected_command_ids,
            expected_operation_ids,
            command_results: request.command_results,
        });
        record.view.status = if result.accepted {
            PanelInstallerJobStatus::Succeeded
        } else {
            PanelInstallerJobStatus::Rejected
        };
        record.view.updated_at_unix = now;
        record.view.detail = result.detail.clone();
        record.view.result = Some(result);
        let view = record.view.clone();
        runtime.compact(config.runtime_limits.max_panel_installer_jobs_buffered);
        persist_panel_installer_jobs(&config.panel_installer_jobs_path, &runtime)?;
        Ok(view)
    }

