    pub async fn create_ban(
        &self,
        token: &str,
        request: CreateBanRequest,
    ) -> Result<ActiveBanView, SecurityError> {
        let admin = self.me(token).await?;
        let client_ip: std::net::IpAddr = request.client_ip.parse().map_err(|_| {
            SecurityError::InvalidSecuritySettings("client_ip must be a valid IP address")
        })?;
        if matches!(request.ban_kind, BanKind::Temporary)
            && request.duration_seconds.unwrap_or(0) == 0
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "duration_seconds must be set for temporary bans",
            ));
        }
        if matches!(request.ban_kind, BanKind::Temporary)
            && request.duration_seconds.unwrap_or(0) > MANUAL_TEMPORARY_BAN_MAX_SECONDS
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "duration_seconds must be at most 2592000 for temporary bans",
            ));
        }
        let reason = normalize_manual_ban_reason(request.reason.as_deref())?;

        let view = {
            let mut runtime = self.security.write().await;
            runtime.create_ban(
                client_ip.to_string(),
                request.ban_kind,
                request.duration_seconds,
                reason,
            )
        };

        let _ = self
            .append_audit_event(
                AuditEventType::BanCreated,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!(
                    "manual {:?} ban created for {}",
                    view.ban_kind, view.client_ip
                )
                .to_ascii_lowercase(),
            )
            .await;

        Ok(view)
    }

