    pub async fn apply_security_preset(
        &self,
        token: &str,
        request: ApplySecurityPresetRequest,
    ) -> Result<SecuritySettings, SecurityError> {
        let admin = self.me(token).await?;
        let settings_path = {
            let config = self.config.read().await;
            config.security.settings_path.clone()
        };
        let preset_settings = {
            let config = self.config.read().await;
            security_preset_settings(request.preset, &config.security)
        };
        if let Err(error) = validate_security_settings(&preset_settings) {
            self.append_security_settings_update_failed(&admin, format!("{error}"))
                .await;
            return Err(error);
        }
        if let Err(error) = persist_security_settings(&settings_path, &preset_settings) {
            self.append_security_settings_update_failed(&admin, format!("{error}"))
                .await;
            return Err(error);
        }

        let updated = {
            let mut config = self.config.write().await;
            apply_security_settings(&mut config.security, &preset_settings);
            security_settings_from_config(&config.security)
        };

        let _ = self
            .append_audit_event(
                AuditEventType::SecurityPresetApplied,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!("security preset applied: {:?}", request.preset),
            )
            .await;
        self.notify_telegram_event(
            TelegramEventKind::Security,
            format!("Security preset applied: {:?}", request.preset),
        )
        .await;

        Ok(updated)
    }

