    async fn system_overview_for_config(&self, config: &AppConfig) -> SystemOverview {
        let (disk, memory_used_bytes, memory_total_bytes) = read_system_stats();
        let node_summary = self.node_health_summary().await;
        let active_alerts = self
            .evaluate_alerts_and_notify(
                config,
                &disk,
                memory_used_bytes,
                memory_total_bytes,
                Some(&node_summary),
            )
            .await;
        let runtime = self.system.read().await;
        SystemOverview {
            memory_budget_mb: config.runtime_limits.memory_budget_mb,
            memory_used_bytes,
            memory_total_bytes,
            disk,
            operational_log_lines_buffered: runtime.logs.len(),
            core_status: runtime.status,
            active_alerts,
        }
    }

    async fn resource_budget_report_for_config(&self, config: &AppConfig) -> ResourceBudgetReport {
        let limits = &config.runtime_limits;
        let process = read_current_process_stats();
        let process_memory_budget_bytes = (limits.memory_budget_mb as u64)
            .saturating_mul(1024)
            .saturating_mul(1024);
        let process_memory_item = resource_budget_item(
            "process.rss_mb",
            bytes_to_mib_ceil(process.memory_used_bytes),
            limits.memory_budget_mb,
            "Resident memory used by the panel process compared to the configured low-memory budget.",
        );
        let security = self.security.read().await;
        let mut items = vec![
            process_memory_item,
            resource_budget_item(
                "security.audit_events",
                security.audit_events.len(),
                limits.max_audit_events_buffered,
                "Buffered admin/security audit events.",
            ),
            resource_budget_item(
                "security.tracked_login_ips",
                security.attempts.len(),
                limits.max_tracked_login_ips,
                "Tracked login-protection IP counters.",
            ),
            resource_budget_item(
                "security.active_sessions",
                security.sessions.len(),
                limits.max_active_sessions,
                "Active admin sessions.",
            ),
        ];
        drop(security);

        let system = self.system.read().await;
        items.extend([
            resource_budget_item(
                "system.operational_logs",
                system.logs.len(),
                limits.max_operational_log_lines_buffered,
                "Buffered operational log lines.",
            ),
            resource_budget_item(
                "system.alert_events",
                system.alert_events.len(),
                limits.max_alert_events_buffered,
                "Buffered system alert history events.",
            ),
            resource_budget_item(
                "system.core_apply_history",
                system.apply_history.len(),
                limits.max_core_apply_events_buffered,
                "Buffered core apply history records.",
            ),
        ]);
        drop(system);

        let telegram = self.telegram.read().await;
        items.push(resource_budget_item(
            "telegram.events",
            telegram.events.len(),
            limits.max_telegram_events_buffered,
            "Buffered Telegram delivery events.",
        ));
        drop(telegram);

        let users = self.users.read().await;
        items.push(resource_budget_item(
            "users.activity",
            users.activity.len(),
            limits.max_user_activity_events_buffered,
            "Buffered user activity events.",
        ));
        drop(users);

        let subscriptions = self.subscriptions.read().await;
        items.extend([
            resource_budget_item(
                "subscriptions.devices",
                subscriptions.devices.len(),
                limits.max_subscription_devices_buffered,
                "Tracked subscription devices.",
            ),
            resource_budget_item(
                "subscriptions.enrollment_grants",
                subscriptions.enrollment_grants.len(),
                limits.max_subscription_enrollment_grants_buffered,
                "Bounded one-time device enrollment grants.",
            ),
            resource_budget_item(
                "subscriptions.sessions",
                subscriptions.sessions.len(),
                limits.max_subscription_sessions_buffered,
                "Tracked subscription runtime sessions.",
            ),
            resource_budget_item(
                "subscriptions.enforcement_actions",
                subscriptions.enforcement_actions.len(),
                limits.max_subscription_sessions_buffered,
                "Pending or recent subscription enforcement actions.",
            ),
            resource_budget_item(
                "subscriptions.usage_points",
                subscriptions.usage_points.len(),
                limits.max_subscription_usage_points_buffered,
                "Buffered subscription usage points.",
            ),
        ]);
        drop(subscriptions);

        let nodes = self.nodes.read().await;
        items.extend([
            resource_budget_item(
                "nodes.sync_history",
                nodes.sync_history.len(),
                limits.max_node_sync_events_buffered,
                "Buffered node sync reports.",
            ),
            resource_budget_item(
                "nodes.apply_results",
                nodes.apply_results.len(),
                limits.max_node_sync_events_buffered,
                "Buffered node apply results.",
            ),
            resource_budget_item(
                "nodes.bootstrap_history",
                nodes.bootstrap_history.len(),
                limits.max_node_bootstrap_events_buffered,
                "Buffered node bootstrap readiness probes.",
            ),
        ]);
        drop(nodes);

        let provisioning = self.provisioning.read().await;
        items.extend([
            resource_budget_item(
                "provisioning.tasks",
                provisioning.tasks.len(),
                limits.max_node_provisioning_events_buffered,
                "Tracked node provisioning tasks.",
            ),
            resource_budget_item(
                "provisioning.events",
                provisioning.events.len(),
                limits.max_node_provisioning_events_buffered,
                "Buffered node provisioning events.",
            ),
            resource_budget_item(
                "provisioning.executor_submissions",
                provisioning.executor_submissions.len(),
                limits.max_node_provisioning_events_buffered,
                "Buffered provisioning executor submissions.",
            ),
        ]);
        drop(provisioning);

        let installer = self.installer.read().await;
        items.push(resource_budget_item(
            "installer.jobs",
            installer.jobs.len(),
            limits.max_panel_installer_jobs_buffered,
            "Tracked panel installer jobs.",
        ));
        drop(installer);

        let status = items
            .iter()
            .fold(ResourceBudgetStatus::Ok, |current, item| {
                match (current, item.status) {
                    (ResourceBudgetStatus::OverLimit, _) | (_, ResourceBudgetStatus::OverLimit) => {
                        ResourceBudgetStatus::OverLimit
                    }
                    (ResourceBudgetStatus::Warning, _) | (_, ResourceBudgetStatus::Warning) => {
                        ResourceBudgetStatus::Warning
                    }
                    _ => ResourceBudgetStatus::Ok,
                }
            });
        let recommendations = build_resource_budget_recommendations(&items);

        ResourceBudgetReport {
            schema_version: SchemaId::ResourceBudget.version(),
            generated_at_unix: now_unix(),
            memory_budget_mb: limits.memory_budget_mb,
            process_memory_used_bytes: process.memory_used_bytes,
            process_memory_budget_bytes,
            process_memory_percent_of_budget: percent_u64(
                process.memory_used_bytes,
                process_memory_budget_bytes,
            ),
            process_cpu_usage_percent: process.cpu_usage_percent,
            target_vcpu: 1,
            target_disk_gb: 10,
            status,
            items,
            recommendations,
        }
    }

