    pub async fn update_system_thresholds(
        &self,
        token: &str,
        request: UpdateSystemThresholdsRequest,
    ) -> Result<SystemThresholds, SecurityError> {
        let admin = self.me(token).await?;
        validate_system_thresholds(&request)?;

        let thresholds_path = {
            let config = self.config.read().await;
            config.monitoring.thresholds_path.clone()
        };
        persist_monitoring_thresholds(&thresholds_path, &request)?;

        let updated = {
            let mut config = self.config.write().await;
            apply_monitoring_thresholds(&mut config, &request);
            system_thresholds_from_config(&config)
        };

        {
            let config = self.config_snapshot().await;
            let (disk, memory_used_bytes, memory_total_bytes) = read_system_stats();
            let node_summary = self.node_health_summary().await;
            self.evaluate_alerts_and_notify(
                &config,
                &disk,
                memory_used_bytes,
                memory_total_bytes,
                Some(&node_summary),
            )
            .await;
            let mut runtime = self.system.write().await;
            runtime.push_log(
                &config,
                "info",
                "system alert thresholds updated".to_string(),
            );
        }

        let _ = self
            .append_audit_event(
                AuditEventType::SystemThresholdsUpdated,
                Some(admin.username),
                Some(admin.session.client_ip),
                "system monitoring thresholds updated".to_string(),
            )
            .await;
        self.notify_telegram_event(
            TelegramEventKind::SystemAlert,
            "System monitoring thresholds updated".to_string(),
        )
        .await;

        Ok(updated)
    }

