    async fn evaluate_alerts_and_notify(
        &self,
        config: &AppConfig,
        disk: &DiskStats,
        memory_used_bytes: u64,
        memory_total_bytes: u64,
        node_summary: Option<&NodeHealthCenterSummary>,
    ) -> Vec<ActiveAlert> {
        let (alerts, events) = {
            let mut runtime = self.system.write().await;
            let events_before = runtime.alert_events.len();
            let alerts = runtime.evaluate_alerts(
                config,
                disk,
                memory_used_bytes,
                memory_total_bytes,
                Some(read_current_process_stats().memory_used_bytes),
                node_summary,
            );
            let events = runtime.alert_events[events_before..].to_vec();
            (alerts, events)
        };

        for event in events {
            self.notify_telegram_alert_event(&event).await;
        }

        alerts
    }

