    pub async fn xray_core_update(
        &self,
        token: &str,
        request: XrayCoreUpdateRequest,
    ) -> Result<XrayCoreUpdateReport, SecurityError> {
        let admin = self.me(token).await?;
        let config = self.config_snapshot().await;
        let generated = self.generated_core_config(token).await?;
        let xray_document = build_xray_config_document(&generated);
        let report = plan_xray_core_update(
            &config,
            request,
            xray_document.raw_config,
            xray_document.raw_config_validation,
        )
        .await;
        {
            let mut runtime = self.system.write().await;
            runtime.last_xray_update = Some(report.clone());
            runtime.push_log(
                &config,
                if report.status == XrayCoreUpdateStatus::Planned {
                    "info"
                } else {
                    "warn"
                },
                format!("xray core update lifecycle: {}", report.detail),
            );
        }
        let _ = self
            .append_audit_event(
                AuditEventType::CoreXrayUpdateRequested,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!("xray core update requested: {}", report.detail),
            )
            .await;
        Ok(report)
    }

