    pub async fn core_apply_generated(
        &self,
        token: &str,
        request: CoreApplyRequest,
    ) -> Result<CoreApplyRecord, SecurityError> {
        let admin = self.me(token).await?;
        let config = self.config_snapshot().await;
        let generated = self.generated_core_config(token).await?;
        let revision = request
            .revision
            .unwrap_or_else(|| generated.revision.clone());
        let xray_document = build_xray_config_document(&generated);
        let external_validation = if xray_document.raw_config_validation.valid {
            let binary_path = config.xray_binary_path.clone();
            let temp_dir = config.xray_validation_temp_dir.clone();
            let raw_config = xray_document.raw_config.clone();
            let internal_report = xray_document.raw_config_validation.clone();
            tokio::task::spawn_blocking(move || {
                run_xray_external_validation(raw_config, internal_report, binary_path, temp_dir)
            })
            .await
            .map_err(|_| SecurityError::PersistenceFailure)?
        } else {
            xray_external_validation_report(
                XrayExternalValidationStatus::Skipped,
                config.xray_binary_path.clone(),
                false,
                None,
                String::new(),
                String::new(),
                "internal raw config validation failed; external xray test was not run".to_string(),
            )
        };
        let record = {
            let mut runtime = self.system.write().await;

            runtime.apply_generated_config(
                &config,
                &generated,
                &revision,
                &xray_document.raw_config_validation,
                &external_validation,
            )
        };
        let _ = self
            .append_audit_event(
                AuditEventType::CoreApplyRequested,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!("core generated config apply requested: {}", record.revision),
            )
            .await;
        Ok(record)
    }

