    pub async fn execute_core_action(
        &self,
        token: &str,
        action: CoreAction,
    ) -> Result<(), SecurityError> {
        let admin = self.me(token).await?;
        let config = self.config_snapshot().await;
        let action_record = {
            let mut runtime = self.system.write().await;
            runtime.execute_core_action(&config, action)
        };
        let audit_detail = match action_record.detail.as_deref() {
            Some(detail) if !detail.is_empty() => {
                format!("core action requested: {:?}; {}", action, detail)
            }
            _ => format!("core action requested: {:?}", action),
        };
        let _ = self
            .append_audit_event(
                core_action_audit_event_type(action),
                Some(admin.username),
                Some(admin.session.client_ip),
                audit_detail,
            )
            .await;
        Ok(())
    }

