    pub async fn create_user(
        &self,
        token: &str,
        request: CreateUserRequest,
    ) -> Result<User, SecurityError> {
        let admin = self.me(token).await?;
        validate_create_user_request(&request)?;
        let template = {
            let templates = self.templates.read().await;
            validate_template_links(
                request.template_id.as_deref(),
                request.next_template_id.as_deref(),
                &templates,
            )?;
            request
                .template_id
                .as_deref()
                .map(|template_id| templates.get(template_id))
                .transpose()?
        };
        let request = apply_template_to_create_request(request, template.as_ref());
        {
            let network = self.network.read().await;
            validate_user_resource_links(
                request.proxy_profile_ids.as_deref().unwrap_or(&[]),
                request.excluded_inbound_tags.as_deref().unwrap_or(&[]),
                &network,
            )?;
        }
        let config = self.config_snapshot().await;
        let user = {
            let mut runtime = self.users.write().await;
            let user = runtime.create(request)?;
            runtime.push_activity(
                &config,
                UserActivityEntry {
                    username: user.username.clone(),
                    kind: UserActivityKind::Created,
                    actor_username: Some(admin.username.clone()),
                    detail: "user created".to_string(),
                    traffic_delta_bytes: None,
                    total_used_traffic_bytes: Some(user.used_traffic_bytes),
                    created_at_unix: now_unix(),
                },
            );
            persist_users(&config.users_path, &runtime)?;
            user
        };
        let _ = self
            .append_audit_event(
                AuditEventType::UserCreated,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!("user created: {}", user.username),
            )
            .await;
        Ok(user)
    }

    pub async fn update_user(
        &self,
        token: &str,
        username: &str,
        request: UpdateUserRequest,
    ) -> Result<User, SecurityError> {
        let admin = self.me(token).await?;
        validate_update_user_request(&request)?;
        {
            let templates = self.templates.read().await;
            validate_template_links(
                request.template_id.as_deref(),
                request.next_template_id.as_deref(),
                &templates,
            )?;
        }
        {
            let network = self.network.read().await;
            validate_optional_user_resource_links(
                request.proxy_profile_ids.as_deref(),
                request.excluded_inbound_tags.as_deref(),
                &network,
            )?;
        }
        let config = self.config_snapshot().await;
        let user = {
            let mut runtime = self.users.write().await;
            let user = runtime.update(username, request)?;
            runtime.push_activity(
                &config,
                UserActivityEntry {
                    username: user.username.clone(),
                    kind: UserActivityKind::Updated,
                    actor_username: Some(admin.username.clone()),
                    detail: "user updated".to_string(),
                    traffic_delta_bytes: None,
                    total_used_traffic_bytes: Some(user.used_traffic_bytes),
                    created_at_unix: now_unix(),
                },
            );
            persist_users(&config.users_path, &runtime)?;
            user
        };
        let _ = self
            .append_audit_event(
                AuditEventType::UserUpdated,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!("user updated: {}", user.username),
            )
            .await;
        Ok(user)
    }

    pub async fn delete_user(&self, token: &str, username: &str) -> Result<(), SecurityError> {
        let admin = self.me(token).await?;
        let config = self.config_snapshot().await;
        {
            let mut runtime = self.users.write().await;
            runtime.delete(username)?;
            runtime.push_activity(
                &config,
                UserActivityEntry {
                    username: username.to_string(),
                    kind: UserActivityKind::Deleted,
                    actor_username: Some(admin.username.clone()),
                    detail: "user deleted".to_string(),
                    traffic_delta_bytes: None,
                    total_used_traffic_bytes: None,
                    created_at_unix: now_unix(),
                },
            );
            persist_users(&config.users_path, &runtime)?;
        }
        let _ = self
            .append_audit_event(
                AuditEventType::UserDeleted,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!("user deleted: {username}"),
            )
            .await;
        Ok(())
    }

