    async fn notify_telegram_event(&self, kind: TelegramEventKind, message: String) {
        let _ = self
            .send_telegram_event_internal(kind, message, None, None)
            .await;
    }

    async fn notify_telegram_alert_event(&self, event: &AlertEvent) {
        let telegram_kind = if is_node_health_alert_event(event) {
            TelegramEventKind::NodeHealthAlert
        } else {
            TelegramEventKind::SystemAlert
        };
        let _ = self
            .send_telegram_event_internal(
                telegram_kind,
                format_alert_telegram_message(event),
                None,
                Some(TelegramAlertContext {
                    kind: event.kind,
                    severity: event.severity,
                    status: event.status,
                }),
            )
            .await;
    }

    async fn send_telegram_event(
        &self,
        kind: TelegramEventKind,
        message: String,
        chat_id_override: Option<String>,
    ) -> Result<TelegramEvent, SecurityError> {
        self.send_telegram_event_internal(kind, message, chat_id_override, None)
            .await
    }

    async fn send_telegram_event_internal(
        &self,
        kind: TelegramEventKind,
        message: String,
        chat_id_override: Option<String>,
        alert_context: Option<TelegramAlertContext>,
    ) -> Result<TelegramEvent, SecurityError> {
        let config = self.config_snapshot().await;
        let now = now_unix();
        let (settings, alert_policy_blocker) = {
            let runtime = self.telegram.read().await;
            let settings = runtime.settings.clone();
            let alert_policy_blocker = alert_context.and_then(|context| {
                telegram_alert_policy_blocker(&settings, &runtime.events, context, now)
            });
            (settings, alert_policy_blocker)
        };
        let chat_id = chat_id_override.or_else(|| settings.default_chat_id.clone());

        let allowed = match kind {
            TelegramEventKind::TestMessage => true,
            TelegramEventKind::Security => settings.notify_on_security_events,
            TelegramEventKind::SystemAlert => settings.notify_on_system_alerts,
            TelegramEventKind::Node => settings.notify_on_node_events,
            TelegramEventKind::NodeHealthAlert => settings.notify_on_node_health_alerts,
        };

        let mut event = TelegramEvent {
            id: generate_resource_id(),
            kind,
            status: TelegramEventStatus::Queued,
            alert_kind: alert_context.map(|context| context.kind),
            alert_severity: alert_context.map(|context| context.severity),
            alert_status: alert_context.map(|context| context.status),
            message: sanitize_telegram_event_text(&message),
            target_chat_id: chat_id.clone(),
            attempt_count: 0,
            last_error: None,
            next_retry_at_unix: None,
            delivered_at_unix: None,
            created_at_unix: now,
        };

        if !settings.enabled {
            event.status = TelegramEventStatus::Skipped;
            event.last_error = Some("telegram delivery is disabled".to_string());
        } else if !allowed {
            event.status = TelegramEventStatus::Skipped;
            event.last_error = Some("event kind is disabled by notification policy".to_string());
        } else if let Some(reason) = alert_policy_blocker {
            event.status = TelegramEventStatus::Skipped;
            event.last_error = Some(reason);
        } else if let (Some(bot_token), Some(target_chat_id)) =
            (settings.bot_token.clone(), chat_id)
        {
            attempt_telegram_delivery(&mut event, &bot_token, &target_chat_id).await;
        } else {
            event.status = TelegramEventStatus::Skipped;
            event.last_error = Some("bot token or target chat id is not configured".to_string());
        }

        {
            let mut runtime = self.telegram.write().await;
            runtime.push_event(&config, event.clone());
        }

        Ok(event)
    }

    async fn retry_due_telegram_events_internal(
        &self,
    ) -> Result<Vec<TelegramEvent>, SecurityError> {
        let config = self.config_snapshot().await;
        let settings = {
            let runtime = self.telegram.read().await;
            runtime.settings.clone()
        };
        if !settings.enabled {
            return Ok(Vec::new());
        }
        let (Some(bot_token), Some(default_chat_id)) =
            (settings.bot_token.clone(), settings.default_chat_id.clone())
        else {
            return Ok(Vec::new());
        };

        let now = now_unix();
        let due_events = {
            let runtime = self.telegram.read().await;
            runtime.due_retry_events(now)
        };

        let mut retried = Vec::new();
        for mut event in due_events {
            let target_chat_id = event
                .target_chat_id
                .clone()
                .unwrap_or_else(|| default_chat_id.clone());
            attempt_telegram_delivery(&mut event, &bot_token, &target_chat_id).await;
            let mut runtime = self.telegram.write().await;
            runtime.upsert_event(&config, event.clone());
            drop(runtime);
            retried.push(event);
        }

        Ok(retried)
    }

