    pub async fn render_subscription_by_token(
        &self,
        subscription_token: &str,
        format: SubscriptionFormat,
        device_id: Option<&str>,
    ) -> Result<RenderedSubscription, SecurityError> {
        if format == SubscriptionFormat::DiagnosticJson {
            return Err(SecurityError::Unauthorized);
        }
        {
            let users = self.users.read().await;
            if let Ok(user) = users.get_by_subscription_token(subscription_token) {
                if user.sub_revoked_at_unix.is_some() {
                    return Err(SecurityError::Unauthorized);
                }
                let network = self.network.read().await;
                return network.render_subscription(&user, format);
            }
        }

        let subscriptions = self.subscriptions.read().await;
        let client = subscriptions.get_client_by_subscription_token(subscription_token)?;
        validate_subscription_client_public_state(&client)?;
        let device = subscriptions.subscription_render_device(&client, device_id)?;
        if device
            .as_ref()
            .is_some_and(|device| device.subscription_token_hmac_sha256.is_some())
        {
            return Err(SecurityError::Unauthorized);
        }
        let network = self.network.read().await;
        network.render_subscription_client(&client, device.as_ref(), format)
    }

    pub async fn render_subscription_by_device_credential(
        &self,
        device_credential: &str,
        format: SubscriptionFormat,
    ) -> Result<RenderedSubscription, SecurityError> {
        if format == SubscriptionFormat::DiagnosticJson {
            return Err(SecurityError::Unauthorized);
        }
        validate_subscription_device_credential(device_credential)?;
        let config = self.config_snapshot().await;
        let master_key =
            load_or_create_subscription_devices_master_key(&config.subscription_devices_key_path)?;
        let credential_hmac_sha256 =
            hash_subscription_device_credential(device_credential, &master_key)?;
        let subscriptions = self.subscriptions.read().await;
        let (client, device) =
            subscriptions.subscription_device_by_credential(&credential_hmac_sha256)?;
        let network = self.network.read().await;
        network.render_subscription_client(&client, Some(&device), format)
    }

