    pub async fn node_health_center(
        &self,
        token: &str,
    ) -> Result<NodeHealthCenterView, SecurityError> {
        self.me(token).await?;
        let revision = self.current_generated_config_revision().await?;
        let runtime = self.nodes.read().await;
        let provisioning_tasks = self
            .provisioning
            .read()
            .await
            .tasks
            .values()
            .cloned()
            .collect::<Vec<_>>();
        let view = build_node_health_center(
            runtime.list_with_effective_sync_status(&revision),
            &revision,
            now_unix(),
            &runtime.sync_history,
            &runtime.apply_results,
            &provisioning_tasks,
        );
        drop(runtime);
        self.refresh_node_alerts(&view.summary).await;
        Ok(view)
    }

    async fn node_health_summary(&self) -> NodeHealthCenterSummary {
        let revision = self
            .current_generated_config_revision()
            .await
            .unwrap_or_else(|_| "unknown".to_string());
        let runtime = self.nodes.read().await;
        let provisioning_tasks = self
            .provisioning
            .read()
            .await
            .tasks
            .values()
            .cloned()
            .collect::<Vec<_>>();
        build_node_health_center(
            runtime.list_with_effective_sync_status(&revision),
            &revision,
            now_unix(),
            &runtime.sync_history,
            &runtime.apply_results,
            &provisioning_tasks,
        )
        .summary
    }

