    async fn refresh_node_alerts(&self, summary: &NodeHealthCenterSummary) {
        let config = self.config_snapshot().await;
        let (disk, memory_used_bytes, memory_total_bytes) = read_system_stats();
        self.evaluate_alerts_and_notify(
            &config,
            &disk,
            memory_used_bytes,
            memory_total_bytes,
            Some(summary),
        )
        .await;
    }

    pub async fn create_node(
        &self,
        token: &str,
        request: CreateNodeRequest,
    ) -> Result<Node, SecurityError> {
        let admin = self.me(token).await?;
        validate_create_node_request(&request)?;
        let config = self.config_snapshot().await;
        let local_api_token_provided = request
            .local_api_token
            .as_deref()
            .is_some_and(|value| !value.trim().is_empty());
        let node = {
            let mut runtime = self.nodes.write().await;
            let node = runtime.create(request)?;
            persist_nodes(&config.nodes_path, &config.node_secrets_key_path, &runtime)?;
            node
        };
        let _ = self
            .append_audit_event(
                AuditEventType::NodeCreated,
                Some(admin.username.clone()),
                Some(admin.session.client_ip.clone()),
                format!("node created: {}", node.id),
            )
            .await;
        if local_api_token_provided {
            let _ = self
                .append_audit_event(
                    AuditEventType::NodeLocalApiTokenUpdated,
                    Some(admin.username.clone()),
                    Some(admin.session.client_ip.clone()),
                    format!("node local api token configured: {}", node.id),
                )
                .await;
        }
        self.notify_telegram_event(
            TelegramEventKind::Node,
            format!("Node created: {}", node.name),
        )
        .await;
        Ok(node)
    }

    pub async fn update_node(
        &self,
        token: &str,
        node_id: &str,
        request: UpdateNodeRequest,
    ) -> Result<Node, SecurityError> {
        let admin = self.me(token).await?;
        validate_update_node_request(&request)?;
        let config = self.config_snapshot().await;
        let local_api_token_change = request.local_api_token.as_ref().map(|value| {
            if value.trim().is_empty() {
                "cleared"
            } else {
                "configured"
            }
        });
        let node = {
            let mut runtime = self.nodes.write().await;
            let node = runtime.update(node_id, request)?;
            persist_nodes(&config.nodes_path, &config.node_secrets_key_path, &runtime)?;
            node
        };
        let _ = self
            .append_audit_event(
                AuditEventType::NodeUpdated,
                Some(admin.username.clone()),
                Some(admin.session.client_ip.clone()),
                format!("node updated: {}", node.id),
            )
            .await;
        if let Some(change) = local_api_token_change {
            let _ = self
                .append_audit_event(
                    AuditEventType::NodeLocalApiTokenUpdated,
                    Some(admin.username.clone()),
                    Some(admin.session.client_ip.clone()),
                    format!("node local api token {change}: {}", node.id),
                )
                .await;
        }
        self.notify_telegram_event(
            TelegramEventKind::Node,
            format!("Node updated: {}", node.name),
        )
        .await;
        Ok(node)
    }

