    pub async fn retry_node_apply(
        &self,
        token: &str,
        node_id: &str,
        request: NodeApplyRetryRequest,
    ) -> Result<Node, SecurityError> {
        let admin = self.me(token).await?;
        let config = self.config_snapshot().await;
        let revision = match request.revision {
            Some(revision) => revision,
            None => self.current_generated_config_revision().await?,
        };
        let reason = request
            .reason
            .filter(|reason| !reason.trim().is_empty())
            .unwrap_or_else(|| "admin requested apply retry".to_string());
        let node = {
            let mut runtime = self.nodes.write().await;
            let node = runtime.request_apply_with_detail(
                &config,
                node_id,
                &revision,
                format!("apply retry requested: {reason}"),
            )?;
            persist_nodes(&config.nodes_path, &config.node_secrets_key_path, &runtime)?;
            node
        };
        let _ = self
            .append_audit_event(
                AuditEventType::NodeApplyRetryRequested,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!(
                    "node apply retry requested: {} revision {}",
                    node.id, revision
                ),
            )
            .await;
        Ok(node)
    }

    pub async fn request_node_rollback(
        &self,
        token: &str,
        node_id: &str,
        request: NodeRollbackRequest,
    ) -> Result<Node, SecurityError> {
        let admin = self.me(token).await?;
        let config = self.config_snapshot().await;
        let fallback_revision = self.current_generated_config_revision().await?;
        let reason = request
            .reason
            .filter(|reason| !reason.trim().is_empty())
            .unwrap_or_else(|| "admin requested runtime rollback".to_string());
        let node = {
            let mut runtime = self.nodes.write().await;
            let target_revision = request
                .target_revision
                .or_else(|| {
                    runtime.latest_last_good_revision(node_id).or_else(|| {
                        runtime
                            .nodes
                            .get(node_id)
                            .and_then(|node| node.last_applied_revision.clone())
                    })
                })
                .unwrap_or(fallback_revision);
            let node = runtime.request_rollback(
                &config,
                node_id,
                &target_revision,
                format!("rollback requested: {reason}"),
            )?;
            persist_nodes(&config.nodes_path, &config.node_secrets_key_path, &runtime)?;
            node
        };
        let _ = self
            .append_audit_event(
                AuditEventType::NodeRollbackRequested,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!("node rollback requested: {}", node.id),
            )
            .await;
        Ok(node)
    }

