    pub async fn node_apply_status(
        &self,
        token: &str,
        node_id: &str,
    ) -> Result<NodeApplyStatusView, SecurityError> {
        self.me(token).await?;
        let revision = self.current_generated_config_revision().await?;
        let config = self.config_snapshot().await;
        let generated = self.generated_core_config_snapshot().await;
        let node_generated = node_agent_generated_config(generated, node_id);
        let runtime_components =
            node_agent_runtime_component_requirements_for_inbounds(&node_generated.inbounds);
        let route_credentials = route_material_apply_diagnostics(&config, &node_generated).ok();
        let (node, recent_sync_history, recent_apply_results) = {
            let runtime = self.nodes.read().await;
            let mut node = runtime.nodes.get(node_id).cloned().ok_or(
                SecurityError::InvalidSecuritySettings("node does not exist"),
            )?;
            node.sync_status = effective_node_sync_status(&node, &revision);
            let history = runtime.sync_history_for(
                node_id,
                config.runtime_limits.max_node_sync_events_buffered.min(10),
            );
            let apply_results = runtime.apply_results_for(
                node_id,
                config.runtime_limits.max_node_sync_events_buffered.min(10),
            );
            (node, history, apply_results)
        };
        let local_state = fetch_node_local_json::<NodeLocalStateView>(&node, "state")
            .await
            .ok();
        Ok(build_node_apply_status_view(
            node,
            revision,
            recent_sync_history,
            recent_apply_results,
            local_state,
            route_credentials,
            runtime_components,
            now_unix(),
        ))
    }

    pub async fn rotate_node_auth_token(
        &self,
        token: &str,
        node_id: &str,
    ) -> Result<RotateNodeAuthTokenResponse, SecurityError> {
        let admin = self.me(token).await?;
        let config = self.config_snapshot().await;
        let rotated = {
            let mut runtime = self.nodes.write().await;
            let rotated = runtime.rotate_auth_token(node_id)?;
            persist_nodes(&config.nodes_path, &config.node_secrets_key_path, &runtime)?;
            rotated
        };
        {
            let mut provisioning = self.provisioning.write().await;
            if provisioning.confirm_token_issued(&config, &rotated)? {
                persist_node_provisioning_tasks(
                    &config.node_provisioning_tasks_path,
                    &provisioning,
                    config.runtime_limits.max_node_provisioning_events_buffered,
                )?;
            }
        }
        let _ = self
            .append_audit_event(
                AuditEventType::NodeAuthTokenRotated,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!("node auth token rotated: {}", rotated.node_id),
            )
            .await;
        Ok(rotated)
    }

