    pub async fn rotate_route_credential(
        &self,
        token: &str,
        credential_ref: &str,
    ) -> Result<RouteMaterialStoreView, SecurityError> {
        let admin = self.me(token).await?;
        let config = self.config.read().await;
        let master_key =
            load_or_create_route_material_master_key(&config.route_materials_key_path)?;
        let mut store = load_route_material_store(&config.route_materials_path)?;
        rotate_route_credential_in_store(&mut store, credential_ref, &master_key)?;
        encrypt_route_material_store(&mut store, &master_key)?;
        persist_route_material_store(&config.route_materials_path, &store)?;
        drop(config);
        let _ = self
            .append_audit_event(
                AuditEventType::RouteCredentialRotated,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!("route credential rotated: {credential_ref}"),
            )
            .await;
        Ok(route_material_store_view(&store))
    }

