        let _ = self
            .append_audit_event(
                AuditEventType::NodeHeartbeatReceived,
                Some("node-agent".to_string()),
                Some(node.address.clone()),
                format!("node heartbeat received: {}", node.id),
            )
            .await;
        Ok(node)
