    pub async fn node_agent_report_subscription_usage(
        &self,
        auth_token: &str,
        client_id: &str,
        mut request: ReportSubscriptionUsageRequest,
    ) -> Result<SubscriptionCatalogClient, SecurityError> {
        let config = self.config_snapshot().await;
        let node = {
            let nodes = self.nodes.read().await;
            nodes.find_by_auth_token(auth_token)?
        };
        if request
            .node_id
            .as_deref()
            .is_some_and(|reported_node_id| reported_node_id != node.id)
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "subscription usage report node_id does not match authenticated node",
            ));
        }
        request.node_id = Some(node.id.clone());
        let client = {
            let mut runtime = self.subscriptions.write().await;
            let client = runtime.report_client_usage(
                client_id,
                request,
                config.runtime_limits.max_subscription_usage_points_buffered,
                now_unix(),
            )?;
            persist_subscription_catalog(&config.subscription_catalog_path, &runtime)?;
            persist_subscription_usage(&config.subscription_usage_path, &runtime)?;
            client
        };
        Ok(client)
    }

