    pub async fn node_agent_report_subscription_sessions(
        &self,
        auth_token: &str,
        request: ReportSubscriptionSessionsRequest,
    ) -> Result<ReportSubscriptionSessionsResponse, SecurityError> {
        let config = self.config_snapshot().await;
        let max_observations = config
            .runtime_limits
            .max_subscription_sessions_buffered
            .min(512);
        if request.observations.len() > max_observations {
            return Err(SecurityError::InvalidSecuritySettings(
                "session observation report exceeds request limit",
            ));
        }
        for observation in &request.observations {
            validate_subscription_session_observation(observation)?;
        }
        validate_subscription_session_report_capabilities(
            request.observation_source,
            &request.runtime_capabilities,
        )?;
        let generated = self.generated_core_config_snapshot().await;
        let node = {
            let runtime = self.nodes.read().await;
            runtime.find_by_auth_token(auth_token)?
        };
        let projected = node_agent_generated_config(generated, &node.id);
        let local_runtime_usernames: HashSet<_> = projected
            .users
            .iter()
            .map(|user| user.username.clone())
            .collect();
        let master_key =
            load_or_create_subscription_devices_master_key(&config.subscription_devices_key_path)?;
        let response = {
            let mut runtime = self.subscriptions.write().await;
            runtime.report_node_sessions(
                &node.id,
                &local_runtime_usernames,
                &request.runtime_capabilities,
                request.observations,
                &master_key,
                config.runtime_limits.max_subscription_sessions_buffered,
                now_unix(),
            )?
        };
        let _ = self
            .append_audit_event(
                AuditEventType::SubscriptionSessionReported,
                Some("node-agent".to_string()),
                Some(node.address),
                format!(
                    "node subscription sessions reported: {} allowed / {} blocked",
                    response.allowed_count, response.blocked_count
                ),
            )
            .await;
        Ok(response)
    }

