    pub async fn node_local_runtime_component_action(
        &self,
        token: &str,
        node_id: &str,
        component: &str,
        action: &str,
    ) -> Result<NodeLocalActionResponse, SecurityError> {
        // Parsed into a type at the boundary: no strings remain downstream, and an
        // unknown value from the URL never reaches business logic.
        let component = RuntimeComponent::parse(component).ok_or(
            SecurityError::InvalidSecuritySettings("runtime component is not supported"),
        )?;
        let action = RuntimeComponentAction::parse(action).ok_or(
            SecurityError::InvalidSecuritySettings("runtime component action is not supported"),
        )?;
        let admin = self.me(token).await?;
        let node =
            {
                let runtime = self.nodes.read().await;
                runtime.nodes.get(node_id).cloned().ok_or(
                    SecurityError::InvalidSecuritySettings("node does not exist"),
                )?
            };
        let response = post_node_local_action(
            &node,
            &format!(
                "runtime-components/{}/{}",
                component.as_str(),
                action.as_str()
            ),
        )
        .await?;
        let config = self.config_snapshot().await;
        {
            let mut system = self.system.write().await;
            system.push_log(
                &config,
                "info",
                format!(
                    "node {} runtime component action {} {}: {}",
                    node.name,
                    component.as_str(),
                    action.as_str(),
                    response.detail
                ),
            );
        }
        let _ = self
            .append_audit_event(
                AuditEventType::NodeLocalRuntimeActionRequested,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!(
                    "node runtime component action executed: {} {} {}",
                    node.id,
                    component.as_str(),
                    action.as_str()
                ),
            )
            .await;
        Ok(response)
    }

