    pub async fn run_node_bootstrap_probe(
        &self,
        token: &str,
        node_id: &str,
    ) -> Result<NodeBootstrapProbeView, SecurityError> {
        let admin = self.me(token).await?;
        let revision = self.current_generated_config_revision().await?;
        let config = self.config_snapshot().await;
        let node = {
            let runtime = self.nodes.read().await;
            let mut node = runtime.nodes.get(node_id).cloned().ok_or(
                SecurityError::InvalidSecuritySettings("node does not exist"),
            )?;
            node.sync_status = effective_node_sync_status(&node, &revision);
            node
        };

        let probe_id = generate_resource_id();
        let checked_at_unix = now_unix();
        let mut steps = Vec::new();
        let base_url = format!("http://{}:{}", node.address, node.api_port);

        let health_probe = reqwest::Client::new()
            .get(format!("{base_url}/health"))
            .send()
            .await;
        match health_probe {
            Ok(response) if response.status().is_success() => {
                steps.push(NodeBootstrapProbeEntry {
                    probe_id: probe_id.clone(),
                    node_id: node.id.clone(),
                    step: "reachability".to_string(),
                    status: NodeBootstrapStepStatus::Succeeded,
                    detail: "node local api is reachable".to_string(),
                    created_at_unix: checked_at_unix,
                });
            }
            Ok(response) => {
                let entry = NodeBootstrapProbeEntry {
                    probe_id: probe_id.clone(),
                    node_id: node.id.clone(),
                    step: "reachability".to_string(),
                    status: NodeBootstrapStepStatus::Failed,
                    detail: format!("node local api returned HTTP {}", response.status()),
                    created_at_unix: checked_at_unix,
                };
                let view = NodeBootstrapProbeView {
                    probe_id: probe_id.clone(),
                    node,
                    ready: false,
                    checked_at_unix,
                    recommendations: vec![
                        "Check that the Rust node agent is running and that api_port is reachable from the panel."
                            .to_string(),
                    ],
                    steps: vec![entry],
                };
                self.persist_bootstrap_probe(&config, &view).await?;
                let _ = self
                    .append_audit_event(
                        AuditEventType::NodeBootstrapProbeRequested,
                        Some(admin.username),
                        Some(admin.session.client_ip),
                        format!("node bootstrap probe failed: {}", view.node.id),
                    )
                    .await;
                return Ok(view);
            }
            Err(error) => {
                let entry = NodeBootstrapProbeEntry {
                    probe_id: probe_id.clone(),
                    node_id: node.id.clone(),
                    step: "reachability".to_string(),
                    status: NodeBootstrapStepStatus::Failed,
                    detail: format!("failed to reach node local api: {error}"),
                    created_at_unix: checked_at_unix,
                };
                let view = NodeBootstrapProbeView {
                    probe_id: probe_id.clone(),
                    node,
                    ready: false,
                    checked_at_unix,
                    recommendations: vec![
                        "Verify node address/api_port, firewall rules, and reverse connectivity from panel to node."
                            .to_string(),
                    ],
                    steps: vec![entry],
                };
                self.persist_bootstrap_probe(&config, &view).await?;
                let _ = self
                    .append_audit_event(
                        AuditEventType::NodeBootstrapProbeRequested,
                        Some(admin.username),
                        Some(admin.session.client_ip),
                        format!("node bootstrap probe failed: {}", view.node.id),
                    )
                    .await;
                return Ok(view);
            }
        }

        let local_health = self.node_local_health(token, node_id).await.ok();
        match &local_health {
            Some(health) if health.status == "healthy" => steps.push(NodeBootstrapProbeEntry {
                probe_id: probe_id.clone(),
                node_id: node.id.clone(),
                step: "health".to_string(),
                status: NodeBootstrapStepStatus::Succeeded,
                detail: "node local health reports healthy".to_string(),
                created_at_unix: checked_at_unix,
            }),
            Some(health) => steps.push(NodeBootstrapProbeEntry {
                probe_id: probe_id.clone(),
                node_id: node.id.clone(),
                step: "health".to_string(),
                status: NodeBootstrapStepStatus::Failed,
                detail: format!("node local health reports {}", health.status),
                created_at_unix: checked_at_unix,
            }),
            None => steps.push(NodeBootstrapProbeEntry {
                probe_id: probe_id.clone(),
                node_id: node.id.clone(),
                step: "health".to_string(),
                status: NodeBootstrapStepStatus::Failed,
                detail: "failed to read node local health".to_string(),
                created_at_unix: checked_at_unix,
            }),
        }

        let agent_heartbeat_after_latest_token = node_agent_heartbeat_after_latest_token(&node);
        steps.push(NodeBootstrapProbeEntry {
            probe_id: probe_id.clone(),
            node_id: node.id.clone(),
            step: "agent_heartbeat".to_string(),
            status: if agent_heartbeat_after_latest_token {
                NodeBootstrapStepStatus::Succeeded
            } else {
                NodeBootstrapStepStatus::Failed
            },
            detail: match (
                node.last_agent_heartbeat_at_unix,
                node.auth_token_issued_at_unix,
            ) {
                (Some(heartbeat_at), Some(token_at)) if heartbeat_at >= token_at => format!(
                    "authenticated node-agent heartbeat observed at {heartbeat_at} after token issuance at {token_at}"
                ),
                (Some(heartbeat_at), Some(token_at)) => format!(
                    "latest authenticated node-agent heartbeat at {heartbeat_at} predates token issuance at {token_at}"
                ),
                (Some(heartbeat_at), None) => format!(
                    "authenticated node-agent heartbeat observed at {heartbeat_at}, but no deployable token issuance is recorded"
                ),
                (None, _) => "no authenticated node-agent heartbeat has been observed".to_string(),
            },
            created_at_unix: checked_at_unix,
        });

        let local_state = self.node_local_state(token, node_id).await.ok();
        match &local_state {
            Some(state) => {
                steps.push(NodeBootstrapProbeEntry {
                    probe_id: probe_id.clone(),
                    node_id: node.id.clone(),
                    step: "state".to_string(),
                    status: NodeBootstrapStepStatus::Succeeded,
                    detail: format!(
                        "runtime={}, applied_revision={}",
                        format!("{:?}", state.xray_runtime_status).to_ascii_lowercase(),
                        state
                            .applied_revision
                            .clone()
                            .unwrap_or_else(|| "none".to_string())
                    ),
                    created_at_unix: checked_at_unix,
                });
            }
            None => {
                steps.push(NodeBootstrapProbeEntry {
                    probe_id: probe_id.clone(),
                    node_id: node.id.clone(),
                    step: "state".to_string(),
                    status: NodeBootstrapStepStatus::Failed,
                    detail: "failed to fetch node local state".to_string(),
                    created_at_unix: checked_at_unix,
                });
            }
        }

        let sync_ok = matches!(node.sync_status, NodeSyncStatus::Synced);
        steps.push(NodeBootstrapProbeEntry {
            probe_id: probe_id.clone(),
            node_id: node.id.clone(),
            step: "sync_readiness".to_string(),
            status: if sync_ok {
                NodeBootstrapStepStatus::Succeeded
            } else {
                NodeBootstrapStepStatus::Failed
            },
            detail: format!("panel-side sync status is {:?}", node.sync_status)
                .to_ascii_lowercase(),
            created_at_unix: checked_at_unix,
        });
        let recommendations = build_bootstrap_probe_recommendations(
            &node,
            local_health.as_ref(),
            local_state.as_ref(),
        );
        let ready = steps
            .iter()
            .all(|entry| matches!(entry.status, NodeBootstrapStepStatus::Succeeded));
        let view = NodeBootstrapProbeView {
            probe_id,
            node,
            ready,
            checked_at_unix,
            steps,
            recommendations,
        };
        self.persist_bootstrap_probe(&config, &view).await?;
        let _ = self
            .append_audit_event(
                AuditEventType::NodeBootstrapProbeRequested,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!(
                    "node bootstrap probe completed: {} ready={}",
                    view.node.id, view.ready
                ),
            )
            .await;
        Ok(view)
    }

