    pub async fn node_bootstrap_readiness(
        &self,
        token: &str,
        node_id: &str,
    ) -> Result<NodeBootstrapReadinessView, SecurityError> {
        let probe = self.run_node_bootstrap_probe(token, node_id).await?;
        let failed_steps = probe
            .steps
            .iter()
            .filter(|entry| matches!(entry.status, NodeBootstrapStepStatus::Failed))
            .map(|entry| entry.step.clone())
            .collect();
        Ok(NodeBootstrapReadinessView {
            node: probe.node,
            ready: probe.ready,
            checked_at_unix: probe.checked_at_unix,
            failed_steps,
            recommendations: probe.recommendations,
        })
    }

