    pub async fn node_provisioning_preflight(
        &self,
        token: &str,
        node_id: &str,
    ) -> Result<NodeProvisioningPreflightReport, SecurityError> {
        self.me(token).await?;
        let revision = self.current_generated_config_revision().await?;
        let node = {
            let runtime = self.nodes.read().await;
            let mut node = runtime.nodes.get(node_id).cloned().ok_or(
                SecurityError::InvalidSecuritySettings("node does not exist"),
            )?;
            node.sync_status = effective_node_sync_status(&node, &revision);
            node
        };

        let checked_at_unix = now_unix();
        let local_health = fetch_node_local_json::<NodeLocalHealthView>(&node, "health")
            .await
            .ok();
        let local_state = fetch_node_local_json::<NodeLocalStateView>(&node, "state")
            .await
            .ok();

        let mut checks = Vec::new();
        checks.push(NodeProvisioningPreflightCheck {
            check: "node_enabled".to_string(),
            status: if node.enabled {
                NodeProvisioningPreflightStatus::Passed
            } else {
                NodeProvisioningPreflightStatus::Failed
            },
            detail: if node.enabled {
                "node is enabled in panel".to_string()
            } else {
                "node is disabled in panel settings".to_string()
            },
        });
        checks.push(NodeProvisioningPreflightCheck {
            check: "api_port".to_string(),
            status: if node.api_port > 0 {
                NodeProvisioningPreflightStatus::Passed
            } else {
                NodeProvisioningPreflightStatus::Failed
            },
            detail: format!("api_port is {}", node.api_port),
        });
        checks.push(NodeProvisioningPreflightCheck {
            check: "node_auth_token_issued".to_string(),
            status: if node.auth_token_issued_at_unix.is_some() {
                NodeProvisioningPreflightStatus::Passed
            } else {
                NodeProvisioningPreflightStatus::Failed
            },
            detail: node
                .auth_token_issued_at_unix
                .map(|issued_at| format!("node auth token issued at {issued_at}"))
                .unwrap_or_else(|| "no deployable node auth token has been issued".to_string()),
        });
        checks.push(NodeProvisioningPreflightCheck {
            check: "local_health".to_string(),
            status: match &local_health {
                Some(health) if health.status == "healthy" => {
                    NodeProvisioningPreflightStatus::Passed
                }
                _ => NodeProvisioningPreflightStatus::Failed,
            },
            detail: match &local_health {
                Some(health) => format!("local health is {}", health.status),
                None => "panel cannot reach node local health".to_string(),
            },
        });
        checks.push(NodeProvisioningPreflightCheck {
            check: "runtime_state".to_string(),
            status: match &local_state {
                Some(state)
                    if !matches!(
                        state.xray_runtime_status,
                        panel_domain::node::NodeLocalRuntimeStatus::Failed
                    ) =>
                {
                    NodeProvisioningPreflightStatus::Passed
                }
                _ => NodeProvisioningPreflightStatus::Failed,
            },
            detail: match &local_state {
                Some(state) => format!(
                    "runtime={} restart_attempts={}",
                    format!("{:?}", state.xray_runtime_status).to_ascii_lowercase(),
                    state.xray_restart_attempts
                ),
                None => "panel cannot fetch node local state".to_string(),
            },
        });
        checks.push(NodeProvisioningPreflightCheck {
            check: "sync_state".to_string(),
            status: if matches!(
                node.sync_status,
                NodeSyncStatus::Synced | NodeSyncStatus::Unknown
            ) {
                NodeProvisioningPreflightStatus::Passed
            } else {
                NodeProvisioningPreflightStatus::Failed
            },
            detail: format!("panel sync status is {:?}", node.sync_status).to_ascii_lowercase(),
        });

        let passed = checks
            .iter()
            .all(|check| matches!(check.status, NodeProvisioningPreflightStatus::Passed));
        let recommendations =
            build_node_provisioning_preflight_recommendations(&node, &checks, local_state.as_ref());

        Ok(NodeProvisioningPreflightReport {
            node_id: node.id,
            passed,
            checked_at_unix,
            checks,
            recommendations,
        })
    }

