    pub async fn node_provisioning_executor_handshake(
        &self,
        token: &str,
        request: NodeProvisioningExecutorHandshakeRequest,
    ) -> Result<NodeProvisioningExecutorHandshakeView, SecurityError> {
        let admin = self.me(token).await?;
        let config = self.config_snapshot().await;
        if request.executor_id.trim().is_empty() {
            return Err(SecurityError::InvalidSecuritySettings(
                "executor id must not be empty",
            ));
        }
        let mut view = build_node_provisioning_executor_handshake(request.clone());
        {
            let mut runtime = self.provisioning.write().await;
            let existing = runtime.executors.get(&request.executor_id);
            let registration = NodeProvisioningExecutorRegistrationView {
                executor_id: request.executor_id.clone(),
                enabled: existing.is_none_or(|item| item.enabled),
                auth_token_configured: existing.is_some_and(|item| item.auth_token_configured),
                auth_token_issued_at_unix: existing.and_then(|item| item.auth_token_issued_at_unix),
                auth_token_hash: existing.and_then(|item| item.auth_token_hash.clone()),
                executor_version: request.executor_version.clone(),
                last_contract_version: request.executor_contract_version,
                capabilities: request.capabilities.clone(),
                last_handshake_at_unix: now_unix(),
                last_compatibility_status: view.compatibility.status,
                accepted_result_count: existing.map_or(0, |item| item.accepted_result_count),
                rejected_result_count: existing.map_or(0, |item| item.rejected_result_count),
            };
            runtime
                .executors
                .insert(request.executor_id.clone(), registration.clone());
            persist_node_provisioning_tasks(
                &config.node_provisioning_tasks_path,
                &runtime,
                config.runtime_limits.max_node_provisioning_events_buffered,
            )?;
            view.executor = public_executor_registration(registration);
        }
        let _ = self
            .append_audit_event(
                AuditEventType::ProvisioningExecutorHandshaked,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!("provisioning executor handshake: {}", request.executor_id),
            )
            .await;
        Ok(view)
    }

    pub async fn node_provisioning_executors(
        &self,
        token: &str,
    ) -> Result<Vec<NodeProvisioningExecutorRegistrationView>, SecurityError> {
        self.me(token).await?;
        let runtime = self.provisioning.read().await;
        let mut executors = runtime
            .executors
            .values()
            .cloned()
            .map(public_executor_registration)
            .collect::<Vec<_>>();
        executors.sort_by(|left, right| left.executor_id.cmp(&right.executor_id));
        Ok(executors)
    }

