    pub async fn create_subscription_device_enrollment(
        &self,
        token: &str,
        client_id: &str,
        request: CreateSubscriptionDeviceEnrollmentRequest,
    ) -> Result<CreateSubscriptionDeviceEnrollmentResponse, SecurityError> {
        let admin = self.me(token).await?;
        let expires_in_seconds = subscription_device_enrollment_ttl(&request)?;
        let enrollment_token = generate_subscription_device_enrollment_token();
        let config = self.config_snapshot().await;
        let master_key =
            load_or_create_subscription_devices_master_key(&config.subscription_devices_key_path)?;
        let token_hmac_sha256 =
            hash_subscription_device_enrollment_token(&enrollment_token, &master_key)?;
        let grant = {
            let mut runtime = self.subscriptions.write().await;
            let grant = runtime.create_device_enrollment(
                client_id,
                token_hmac_sha256,
                expires_in_seconds,
                config
                    .runtime_limits
                    .max_subscription_enrollment_grants_buffered,
                now_unix(),
            )?;
            if let Err(error) =
                persist_subscription_catalog(&config.subscription_catalog_path, &runtime)
            {
                runtime.enrollment_grants.remove(&grant.id);
                return Err(error);
            }
            grant
        };
        let view = subscription_enrollment_view(&grant, now_unix());
        let _ = self
            .append_audit_event(
                AuditEventType::SubscriptionDeviceEnrollmentCreated,
                Some(admin.username),
                Some(admin.session.client_ip),
                format!(
                    "subscription device enrollment created: {client_id} / {}",
                    grant.id
                ),
            )
            .await;
        Ok(CreateSubscriptionDeviceEnrollmentResponse {
            grant: view,
            enrollment_token,
        })
    }

