    pub async fn exchange_subscription_device_enrollment(
        &self,
        request: ExchangeSubscriptionDeviceEnrollmentRequest,
    ) -> Result<ExchangeSubscriptionDeviceEnrollmentResponse, SecurityError> {
        validate_subscription_device_enrollment_token(&request.enrollment_token)?;
        validate_register_subscription_device_request(&request.device)?;
        let config = self.config_snapshot().await;
        let master_key =
            load_or_create_subscription_devices_master_key(&config.subscription_devices_key_path)?;
        let token_hmac_sha256 =
            hash_subscription_device_enrollment_token(&request.enrollment_token, &master_key)?;
        let device_credential = generate_subscription_device_credential();
        let device_credential_hmac_sha256 =
            hash_subscription_device_credential(&device_credential, &master_key)?;
        let fingerprint_hmac_sha256 =
            hash_subscription_device_fingerprint(request.device.fingerprint.trim(), &master_key)?;
        let wireguard_fingerprint_hmac_sha256 = request
            .device
            .wireguard_public_key
            .as_deref()
            .map(str::trim)
            .map(wireguard_device_fingerprint)
            .map(|fingerprint| hash_subscription_device_fingerprint(&fingerprint, &master_key))
            .transpose()?;
        let (device, client) = {
            let mut runtime = self.subscriptions.write().await;
            let result = runtime.consume_device_enrollment(
                &token_hmac_sha256,
                fingerprint_hmac_sha256,
                device_credential_hmac_sha256,
                wireguard_fingerprint_hmac_sha256,
                request.device,
                config.runtime_limits.max_subscription_devices_buffered,
                now_unix(),
            )?;
            if let Err(error) =
                persist_subscription_catalog(&config.subscription_catalog_path, &runtime)
            {
                runtime.rollback_device_enrollment_consumption(&token_hmac_sha256, &result.0.id);
                return Err(error);
            }
            result
        };
        let _ = self
            .append_audit_event(
                AuditEventType::SubscriptionDeviceEnrollmentConsumed,
                None,
                None,
                format!(
                    "subscription device enrollment consumed: {} / {}",
                    client.id, device.id
                ),
            )
            .await;
        Ok(ExchangeSubscriptionDeviceEnrollmentResponse {
            subscription_path: format!("/sub/device/{}", encode(&device_credential)),
            subscription_formats: vec![
                SubscriptionFormat::Base64,
                SubscriptionFormat::PlainText,
                SubscriptionFormat::Json,
            ],
            device_credential,
            device,
        })
    }

    pub async fn register_subscription_client_device(
        &self,
        token: &str,
        client_id: &str,
        request: RegisterSubscriptionDeviceRequest,
    ) -> Result<RegisterSubscriptionDeviceResponse, SecurityError> {
        let admin = self.me(token).await?;
        validate_register_subscription_device_request(&request)?;
        let config = self.config_snapshot().await;
        let master_key =
            load_or_create_subscription_devices_master_key(&config.subscription_devices_key_path)?;
        let fingerprint_hmac_sha256 =
            hash_subscription_device_fingerprint(request.fingerprint.trim(), &master_key)?;
        let wireguard_fingerprint_hmac_sha256 = request
            .wireguard_public_key
            .as_deref()
            .map(str::trim)
            .map(wireguard_device_fingerprint)
            .map(|fingerprint| hash_subscription_device_fingerprint(&fingerprint, &master_key))
            .transpose()?;
        let response = {
            let mut runtime = self.subscriptions.write().await;
            let response = runtime.register_device(
                client_id,
                fingerprint_hmac_sha256,
                None,
                wireguard_fingerprint_hmac_sha256,
                request,
                config.runtime_limits.max_subscription_devices_buffered,
            )?;
            if response.admitted {
                persist_subscription_catalog(&config.subscription_catalog_path, &runtime)?;
            }
            response
        };
        if response.admitted {
            let _ = self
                .append_audit_event(
                    AuditEventType::SubscriptionDeviceRegistered,
                    Some(admin.username),
                    Some(admin.session.client_ip),
                    format!(
                        "subscription client device admitted: {client_id} / {}",
                        response
                            .device
                            .as_ref()
                            .map(|device| device.id.as_str())
                            .unwrap_or("existing")
                    ),
                )
                .await;
        }
        Ok(response)
    }

