    async fn validate_subscription_access_policy(
        &self,
        policy: &SubscriptionClientNodeAccessPolicy,
    ) -> Result<(), SecurityError> {
        validate_subscription_access_policy_shape(policy)?;
        if !policy.node_ids.is_empty() {
            let nodes = self.nodes.read().await;
            for node_id in &policy.node_ids {
                if !nodes.nodes.contains_key(node_id) {
                    return Err(SecurityError::InvalidSecuritySettings(
                        "subscription access policy references unknown node",
                    ));
                }
            }
        }
        if !policy.cluster_ids.is_empty() {
            let clusters = self.clusters.read().await;
            for cluster_id in &policy.cluster_ids {
                if !clusters.clusters.contains_key(cluster_id) {
                    return Err(SecurityError::InvalidSecuritySettings(
                        "subscription access policy references unknown cluster",
                    ));
                }
            }
        }
        Ok(())
    }

