    async fn validate_resource_binding(
        &self,
        node_id: Option<&str>,
        cluster_id: Option<&str>,
    ) -> Result<(), SecurityError> {
        if let Some(node_id) = node_id {
            let nodes = self.nodes.read().await;
            if !nodes.nodes.contains_key(node_id) {
                return Err(SecurityError::InvalidSecuritySettings(
                    "resource references unknown node",
                ));
            }
        }
        if let Some(cluster_id) = cluster_id {
            let clusters = self.clusters.read().await;
            if !clusters.clusters.contains_key(cluster_id) {
                return Err(SecurityError::InvalidSecuritySettings(
                    "resource references unknown cluster",
                ));
            }
        }
        Ok(())
    }

