impl SecurityRuntime {
    fn new(_config: &SecurityConfig) -> Self {
        Self {
            attempts: HashMap::new(),
            bans: HashMap::new(),
            sessions: HashMap::new(),
            audit_events: Vec::new(),
            pending_two_factor: HashMap::new(),
        }
    }

    #[cfg(test)]
    fn with_audit_events(events: Vec<AuditEvent>) -> Self {
        Self {
            attempts: HashMap::new(),
            bans: HashMap::new(),
            sessions: HashMap::new(),
            audit_events: events,
            pending_two_factor: HashMap::new(),
        }
    }

    fn login(
        &mut self,
        app_config: &AppConfig,
        client_ip: &str,
        username: &str,
        password: &str,
        two_factor_code: Option<&str>,
        challenge_token: Option<&str>,
    ) -> Result<LoginSuccess, LoginFailure> {
        self.evict_expired(now_unix());

        if let Some(ban) = self.bans.get(client_ip)
            && (ban.kind == BanKind::Permanent || ban.blocked_until_unix > now_unix())
        {
            return Err(LoginFailure {
                reason: "ip_banned",
                blocked_until_unix: Some(ban.blocked_until_unix),
                ban_kind: Some(ban.kind),
                challenge_token: None,
                wait_seconds: None,
            });
        }

        if !credentials_configured(&app_config.security) {
            return Err(LoginFailure {
                reason: "admin_not_configured",
                blocked_until_unix: None,
                ban_kind: None,
                challenge_token: None,
                wait_seconds: None,
            });
        }

        if !verify_credentials(&app_config.security, username, password) {
            return Err(self.register_failure(app_config, client_ip));
        }

        if app_config.security.bootstrap_admin.two_factor_enabled {
            let secret = match app_config
                .security
                .bootstrap_admin
                .two_factor_secret_base32
                .as_deref()
            {
                Some(secret) => secret,
                None => {
                    return Err(LoginFailure {
                        reason: "two_factor_required",
                        blocked_until_unix: None,
                        ban_kind: None,
                        challenge_token: None,
                        wait_seconds: None,
                    });
                }
            };
            let Some(code) = two_factor_code else {
                return Err(LoginFailure {
                    reason: "two_factor_required",
                    blocked_until_unix: None,
                    ban_kind: None,
                    challenge_token: None,
                    wait_seconds: None,
                });
            };

            if app_config
                .security
                .bootstrap_admin
                .two_factor_two_step_enabled
            {
                match challenge_token {
                    Some(challenge_token) => {
                        let challenge = self
                            .pending_two_factor
                            .get(challenge_token)
                            .filter(|challenge| {
                                challenge.username == username && challenge.client_ip == client_ip
                            })
                            .cloned();
                        let Some(challenge) = challenge else {
                            return Err(self.register_two_factor_failure(app_config, client_ip));
                        };
                        let now = now_unix();
                        if now < challenge.earliest_second_code_at_unix {
                            return Err(LoginFailure {
                                reason: "two_factor_wait_required",
                                blocked_until_unix: None,
                                ban_kind: None,
                                challenge_token: Some(challenge_token.to_string()),
                                wait_seconds: Some(challenge.earliest_second_code_at_unix - now),
                            });
                        }
                        if !verify_totp_code(secret, code, now) {
                            return Err(self.register_two_factor_failure(app_config, client_ip));
                        }
                        self.pending_two_factor.remove(challenge_token);
                    }
                    None => {
                        if !verify_totp_code(secret, code, now_unix()) {
                            return Err(self.register_two_factor_failure(app_config, client_ip));
                        }
                        let challenge_token = generate_token();
                        self.pending_two_factor.insert(
                            challenge_token.clone(),
                            PendingTwoFactorChallenge {
                                username: username.to_string(),
                                client_ip: client_ip.to_string(),
                                earliest_second_code_at_unix: now_unix() + 40,
                                expires_at_unix: now_unix() + 300,
                            },
                        );
                        return Err(LoginFailure {
                            reason: "two_factor_second_step_required",
                            blocked_until_unix: None,
                            ban_kind: None,
                            challenge_token: Some(challenge_token),
                            wait_seconds: Some(40),
                        });
                    }
                }
            } else if !verify_totp_code(secret, code, now_unix()) {
                return Err(self.register_two_factor_failure(app_config, client_ip));
            }
        }

        self.attempts.remove(client_ip);
        self.bans.remove(client_ip);

        if self.sessions.len() >= app_config.runtime_limits.max_active_sessions {
            return Err(LoginFailure {
                reason: "session_limit_reached",
                blocked_until_unix: None,
                ban_kind: None,
                challenge_token: None,
                wait_seconds: None,
            });
        }

        let token = generate_token();
        let now = now_unix();
        let expires_at = now + app_config.security.session_ttl_seconds;
        let session = SessionState {
            username: username.to_string(),
            client_ip: client_ip.to_string(),
            issued_at_unix: now,
            expires_at_unix: expires_at,
        };

        self.sessions.insert(token.clone(), session.clone());

        Ok(LoginSuccess {
            token: token.clone(),
            admin: AuthenticatedAdmin {
                username: username.to_string(),
                session: session.into_view(&token),
            },
        })
    }

    fn get_admin_by_token(
        &mut self,
        app_config: &AppConfig,
        token: &str,
    ) -> Result<AuthenticatedAdmin, SecurityError> {
        self.evict_expired(now_unix());
        let session = self
            .sessions
            .get(token)
            .ok_or(SecurityError::Unauthorized)?;

        if session.expires_at_unix <= now_unix() {
            self.sessions.remove(token);
            return Err(SecurityError::Unauthorized);
        }

        Ok(AuthenticatedAdmin {
            username: session.username.clone(),
            session: SessionView {
                session_id: session_public_id(token),
                username: session.username.clone(),
                issued_at_unix: session.issued_at_unix,
                expires_at_unix: session
                    .expires_at_unix
                    .min(now_unix() + app_config.security.session_ttl_seconds),
                client_ip: session.client_ip.clone(),
            },
        })
    }

    fn logout(&mut self, token: &str) -> Result<(), SecurityError> {
        self.sessions
            .remove(token)
            .map(|_| ())
            .ok_or(SecurityError::Unauthorized)
    }

    fn active_sessions(&mut self) -> Vec<SessionView> {
        self.evict_expired(now_unix());
        let mut sessions = self
            .sessions
            .iter()
            .map(|(token, session)| session.clone().into_view(token))
            .collect::<Vec<_>>();
        sessions.sort_by_key(|session| std::cmp::Reverse(session.issued_at_unix));
        sessions
    }

    fn revoke_session(&mut self, session_id: &str) -> Result<SessionView, SecurityError> {
        self.evict_expired(now_unix());
        let Some(token) = self
            .sessions
            .keys()
            .find(|token| session_public_id(token) == session_id)
            .cloned()
        else {
            return Err(SecurityError::InvalidSecuritySettings(
                "session does not exist",
            ));
        };
        let session =
            self.sessions
                .remove(&token)
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "session does not exist",
                ))?;
        Ok(session.into_view(&token))
    }

    fn login_status(&self, client_ip: &str) -> LoginProtectionStatus {
        let now = now_unix();
        let attempt = self.attempts.get(client_ip);
        let ban = self
            .bans
            .get(client_ip)
            .filter(|ban| ban.kind == BanKind::Permanent || ban.blocked_until_unix > now);

        LoginProtectionStatus {
            failed_attempts_in_window: attempt.map(|it| it.failed_attempts_in_window).unwrap_or(0),
            blocked_until_unix: ban.map(|it| it.blocked_until_unix),
            ban_kind: ban.map(|it| it.kind),
            ban_level: attempt.map(|it| it.ban_level).unwrap_or(0),
        }
    }

    fn active_bans(&mut self) -> Vec<ActiveBanView> {
        let now = now_unix();
        self.evict_expired(now);
        self.bans
            .iter()
            .map(|(client_ip, ban)| active_ban_view(client_ip, ban, now))
            .collect()
    }

    fn create_ban(
        &mut self,
        client_ip: String,
        ban_kind: BanKind,
        duration_seconds: Option<u64>,
        reason: String,
    ) -> ActiveBanView {
        let now = now_unix();
        let blocked_until_unix = match ban_kind {
            BanKind::Permanent => u64::MAX,
            BanKind::Temporary => now + duration_seconds.unwrap_or(0),
        };

        let ban = BanState {
            kind: ban_kind,
            source: BanSource::Manual,
            reason,
            created_at_unix: now,
            blocked_until_unix,
            ban_level: 0,
        };
        self.bans.insert(client_ip.clone(), ban.clone());

        active_ban_view(&client_ip, &ban, now)
    }

    fn remove_ban(&mut self, client_ip: &str) -> Result<(), SecurityError> {
        self.bans
            .remove(client_ip)
            .map(|_| ())
            .ok_or(SecurityError::InvalidSecuritySettings("ban does not exist"))
    }

    fn register_failure(&mut self, app_config: &AppConfig, client_ip: &str) -> LoginFailure {
        let limits = &app_config.runtime_limits;
        if self.attempts.len() >= limits.max_tracked_login_ips
            && !self.attempts.contains_key(client_ip)
        {
            self.evict_one_attempt();
        }
        if self.bans.len() >= limits.max_tracked_login_ips && !self.bans.contains_key(client_ip) {
            self.evict_one_ban();
        }

        let now = now_unix();
        let state = self
            .attempts
            .entry(client_ip.to_string())
            .or_insert(LoginAttemptState {
                window_started_unix: now,
                failed_attempts_in_window: 0,
                ban_level: 0,
            });

        if now.saturating_sub(state.window_started_unix)
            > app_config.security.attempt_window_seconds
        {
            state.window_started_unix = now;
            state.failed_attempts_in_window = 0;
        }

        state.failed_attempts_in_window += 1;

        if !app_config.security.login_protection_enabled
            || state.failed_attempts_in_window < app_config.security.max_failed_attempts
        {
            return LoginFailure {
                reason: "invalid_credentials",
                blocked_until_unix: None,
                ban_kind: None,
                challenge_token: None,
                wait_seconds: None,
            };
        }

        state.failed_attempts_in_window = 0;
        state.window_started_unix = now;
        state.ban_level += 1;

        let (ban_kind, blocked_until_unix) = compute_ban(app_config, state.ban_level, now);

        self.bans.insert(
            client_ip.to_string(),
            BanState {
                kind: ban_kind,
                source: BanSource::Automatic,
                reason: format!(
                    "login protection triggered after {} failed attempt(s) in the active window",
                    app_config.security.max_failed_attempts
                ),
                created_at_unix: now,
                blocked_until_unix,
                ban_level: state.ban_level,
            },
        );

        LoginFailure {
            reason: "ip_banned",
            blocked_until_unix: Some(blocked_until_unix),
            ban_kind: Some(ban_kind),
            challenge_token: None,
            wait_seconds: None,
        }
    }

    fn register_two_factor_failure(
        &mut self,
        app_config: &AppConfig,
        client_ip: &str,
    ) -> LoginFailure {
        let failure = self.register_failure(app_config, client_ip);
        if failure.reason == "ip_banned" {
            failure
        } else {
            LoginFailure {
                reason: "invalid_two_factor_code",
                blocked_until_unix: None,
                ban_kind: None,
                challenge_token: None,
                wait_seconds: None,
            }
        }
    }

    fn evict_expired(&mut self, now: u64) {
        self.sessions
            .retain(|_, session| session.expires_at_unix > now);
        self.bans
            .retain(|_, ban| ban.kind == BanKind::Permanent || ban.blocked_until_unix > now);
        self.pending_two_factor
            .retain(|_, challenge| challenge.expires_at_unix > now);
    }

    fn evict_one_attempt(&mut self) {
        if let Some(key) = self.attempts.keys().next().cloned() {
            self.attempts.remove(&key);
        }
    }

    fn evict_one_ban(&mut self) {
        if let Some(key) = self
            .bans
            .iter()
            .find(|(_, ban)| ban.kind != BanKind::Permanent)
            .map(|(key, _)| key.clone())
            .or_else(|| self.bans.keys().next().cloned())
        {
            self.bans.remove(&key);
        }
    }

    fn push_audit_event(&mut self, max_events: usize, event: AuditEvent) {
        if self.audit_events.len() >= max_events {
            let drop_count = self.audit_events.len() + 1 - max_events;
            self.audit_events.drain(0..drop_count);
        }
        self.audit_events.push(event);
    }

    fn audit_events(&self, query: AuditEventsQuery, default_limit: usize) -> Vec<AuditEvent> {
        let search = query
            .search
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_ascii_lowercase);
        let username = query
            .username
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(str::to_ascii_lowercase);
        let client_ip = query
            .client_ip
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty());
        let mut items: Vec<_> = self
            .audit_events
            .iter()
            .filter(|event| query.event_type.is_none_or(|kind| event.event_type == kind))
            .filter(|event| {
                query
                    .created_from_unix
                    .is_none_or(|from| event.created_at_unix >= from)
            })
            .filter(|event| {
                query
                    .created_to_unix
                    .is_none_or(|to| event.created_at_unix <= to)
            })
            .filter(|event| {
                username.as_ref().is_none_or(|username| {
                    event
                        .username
                        .as_deref()
                        .map(str::to_ascii_lowercase)
                        .is_some_and(|value| value.contains(username))
                })
            })
            .filter(|event| {
                client_ip.is_none_or(|client_ip| event.client_ip.as_deref() == Some(client_ip))
            })
            .filter(|event| {
                search.as_ref().is_none_or(|search| {
                    event.detail.to_ascii_lowercase().contains(search)
                        || event
                            .username
                            .as_deref()
                            .map(str::to_ascii_lowercase)
                            .is_some_and(|value| value.contains(search))
                        || event
                            .client_ip
                            .as_deref()
                            .is_some_and(|value| value.contains(search))
                })
            })
            .cloned()
            .collect();
        let limit = resolve_limit(query.limit, default_limit);
        if items.len() > limit {
            items = items.split_off(items.len() - limit);
        }
        items
    }

    fn audit_summary(&self) -> UiAuditSummary {
        UiAuditSummary {
            total_events_buffered: self.audit_events.len(),
            latest_event_at_unix: self.audit_events.last().map(|event| event.created_at_unix),
        }
    }
}

impl SystemRuntime {
    fn new(config: &AppConfig) -> Self {
        let path = Path::new(&config.core_config_path);
        let config_text = fs::read_to_string(path)
            .unwrap_or_else(|_| "{\n  \"log\": {\n    \"level\": \"warning\"\n  }\n}".to_string());
        let valid_json = serde_json::from_str::<serde_json::Value>(&config_text).is_ok();
        let logs = read_ndjson_lines::<OperationalLogLine>(
            &config.operational_log_path,
            config.runtime_limits.max_operational_log_lines_buffered,
        );
        let alert_events = read_ndjson_lines::<AlertEvent>(
            &config.monitoring.alert_history_path,
            config.runtime_limits.max_alert_events_buffered,
        );
        let apply_history = read_ndjson_lines::<CoreApplyRecord>(
            &config.core_apply_history_path,
            config.runtime_limits.max_core_apply_events_buffered,
        );
        let mut runtime = Self {
            config: config_text,
            saved_at_unix: path
                .metadata()
                .ok()
                .and_then(|metadata| metadata.modified().ok())
                .and_then(system_time_to_unix),
            valid_json,
            status: CoreStatus::Running,
            applied_revision: None,
            last_xray_update: None,
            logs,
            apply_history,
            active_alerts: HashMap::new(),
            alert_events,
            last_action: None,
        };
        let (disk, memory_used_bytes, memory_total_bytes) = read_system_stats();
        runtime.evaluate_alerts(
            config,
            &disk,
            memory_used_bytes,
            memory_total_bytes,
            Some(read_current_process_stats().memory_used_bytes),
            None,
        );
        runtime
    }

    fn push_log(&mut self, config: &AppConfig, level: &str, message: String) {
        let max_logs = config.runtime_limits.max_operational_log_lines_buffered;
        if self.logs.len() >= max_logs {
            let drop_count = self.logs.len() + 1 - max_logs;
            self.logs.drain(0..drop_count);
        }
        let line = OperationalLogLine {
            created_at_unix: now_unix(),
            level: level.to_string(),
            message,
        };
        self.logs.push(line.clone());
        let _ = append_ndjson_line(&config.operational_log_path, &line);
    }

    fn evaluate_alerts(
        &mut self,
        config: &AppConfig,
        disk: &DiskStats,
        memory_used_bytes: u64,
        memory_total_bytes: u64,
        panel_process_memory_used_bytes: Option<u64>,
        node_summary: Option<&NodeHealthCenterSummary>,
    ) -> Vec<ActiveAlert> {
        let now = now_unix();
        let mut next_active = HashMap::new();

        let mut candidates = build_alert_candidates(
            config,
            disk,
            memory_used_bytes,
            memory_total_bytes,
            panel_process_memory_used_bytes,
        );
        if let Some(summary) = node_summary {
            candidates.extend(build_node_alert_candidates(summary));
        }

        for candidate in candidates {
            let first_seen_at_unix = self
                .active_alerts
                .get(&candidate.kind)
                .map(|existing| existing.first_seen_at_unix)
                .unwrap_or(now);
            let alert = ActiveAlert {
                first_seen_at_unix,
                ..candidate
            };

            match self.active_alerts.get(&alert.kind) {
                Some(existing)
                    if existing.severity == alert.severity
                        && existing.observed_percent == alert.observed_percent
                        && existing.threshold_percent == alert.threshold_percent
                        && existing.observed_value == alert.observed_value
                        && existing.threshold_value == alert.threshold_value => {}
                _ => {
                    self.push_alert_event_persisted(
                        config,
                        AlertEvent {
                            kind: alert.kind,
                            severity: alert.severity,
                            status: AlertEventStatus::Activated,
                            observed_percent: alert.observed_percent,
                            threshold_percent: alert.threshold_percent,
                            observed_value: alert.observed_value,
                            threshold_value: alert.threshold_value,
                            created_at_unix: now,
                            message: alert.message.clone(),
                        },
                    );
                    self.push_log(
                        config,
                        match alert.severity {
                            AlertSeverity::Warning => "warn",
                            AlertSeverity::Critical => "error",
                        },
                        format!("system alert activated: {}", alert.message),
                    );
                }
            }

            next_active.insert(alert.kind, alert);
        }

        let resolved_alerts: Vec<_> = self
            .active_alerts
            .iter()
            .filter(|(kind, _)| !next_active.contains_key(*kind))
            .map(|(kind, resolved)| (*kind, resolved.clone()))
            .collect();

        for (kind, resolved) in resolved_alerts {
            if !next_active.contains_key(&kind) {
                self.push_alert_event_persisted(
                    config,
                    AlertEvent {
                        kind,
                        severity: resolved.severity,
                        status: AlertEventStatus::Resolved,
                        observed_percent: resolved.observed_percent,
                        threshold_percent: resolved.threshold_percent,
                        observed_value: resolved.observed_value,
                        threshold_value: resolved.threshold_value,
                        created_at_unix: now,
                        message: format!("{} resolved", resolved.message),
                    },
                );
                self.push_log(
                    config,
                    "info",
                    format!("system alert resolved: {}", resolved.message),
                );
            }
        }

        self.active_alerts = next_active;
        let mut alerts: Vec<_> = self.active_alerts.values().cloned().collect();
        alerts.sort_by_key(|alert| {
            (
                match alert.severity {
                    AlertSeverity::Critical => 0_u8,
                    AlertSeverity::Warning => 1_u8,
                },
                match alert.kind {
                    AlertKind::DiskUsage => 0_u8,
                    AlertKind::MemoryUsage => 1_u8,
                    AlertKind::PanelMemoryBudget => 2_u8,
                    AlertKind::NodeOffline => 3_u8,
                    AlertKind::NodeStaleHeartbeat => 4_u8,
                    AlertKind::NodeConfigDrift => 5_u8,
                    AlertKind::NodeProvisioningStale => 6_u8,
                    AlertKind::NodeProvisioningFailed => 7_u8,
                    AlertKind::NodeReportedApplyFailed => 8_u8,
                    AlertKind::NodeRuntimeAlert => 9_u8,
                },
            )
        });
        alerts
    }

    fn push_alert_event(&mut self, max_events: usize, event: AlertEvent) {
        if self.alert_events.len() >= max_events {
            let drop_count = self.alert_events.len() + 1 - max_events;
            self.alert_events.drain(0..drop_count);
        }
        self.alert_events.push(event);
    }

    fn push_alert_event_persisted(&mut self, config: &AppConfig, event: AlertEvent) {
        self.push_alert_event(
            config.runtime_limits.max_alert_events_buffered,
            event.clone(),
        );
        let _ = append_ndjson_line(&config.monitoring.alert_history_path, &event);
    }

    fn filtered_logs(
        &self,
        query: OperationalLogsQuery,
        max_limit: usize,
    ) -> Vec<OperationalLogLine> {
        let mut logs: Vec<_> = self
            .logs
            .iter()
            .filter(|line| match &query.level {
                Some(level) => line.level.eq_ignore_ascii_case(level),
                None => true,
            })
            .cloned()
            .collect();

        let limit = resolve_limit(query.limit, max_limit);
        if logs.len() > limit {
            logs = logs.split_off(logs.len() - limit);
        }

        logs
    }

    fn filtered_alert_history(
        &self,
        query: AlertHistoryQuery,
        max_limit: usize,
    ) -> Vec<AlertEvent> {
        let mut events: Vec<_> = self
            .alert_events
            .iter()
            .filter(|event| match query.kind {
                Some(kind) => event.kind == kind,
                None => true,
            })
            .filter(|event| match query.severity {
                Some(severity) => event.severity == severity,
                None => true,
            })
            .filter(|event| match query.status {
                Some(status) => event.status == status,
                None => true,
            })
            .cloned()
            .collect();

        let limit = resolve_limit(query.limit, max_limit);
        if events.len() > limit {
            events = events.split_off(events.len() - limit);
        }

        events
    }

    fn execute_core_action(&mut self, config: &AppConfig, action: CoreAction) -> CoreActionRecord {
        let (result, detail) = match action {
            CoreAction::Start => {
                self.status = CoreStatus::Running;
                let detail = "core start requested; runtime state set to running".to_string();
                self.push_log(config, "info", detail.clone());
                (CoreActionResult::Completed, detail)
            }
            CoreAction::Stop => {
                self.status = CoreStatus::Idle;
                let detail = "core stop requested; runtime state set to idle".to_string();
                self.push_log(config, "warn", detail.clone());
                (CoreActionResult::Completed, detail)
            }
            CoreAction::Restart => {
                self.status = CoreStatus::Restarting;
                self.push_log(config, "warn", "core restart requested".to_string());
                self.status = CoreStatus::Running;
                let detail = self.core_restart_gate_detail();
                self.push_log(config, "info", detail.clone());
                (CoreActionResult::Completed, detail)
            }
        };
        let action_record = CoreActionRecord {
            action,
            created_at_unix: now_unix(),
            result: Some(result),
            detail: Some(detail),
        };
        self.last_action = Some(action_record.clone());
        action_record
    }

    fn core_restart_gate_detail(&self) -> String {
        match self.last_xray_update.as_ref().map(|report| report.status) {
            Some(XrayCoreUpdateStatus::Swapped) => {
                "core restart completed after validated Xray binary swap".to_string()
            }
            Some(XrayCoreUpdateStatus::Planned) => {
                "core restart completed; last Xray update only validated a candidate and did not swap the active binary".to_string()
            }
            Some(XrayCoreUpdateStatus::Failed) => {
                "core restart completed; last Xray update failed, so active binary should be inspected before relying on the restart".to_string()
            }
            Some(XrayCoreUpdateStatus::Blocked) => {
                "core restart completed; last Xray update was blocked before a safe swap".to_string()
            }
            None => "core restart completed; no Xray update lifecycle is recorded".to_string(),
        }
    }

    fn apply_generated_config(
        &mut self,
        config: &AppConfig,
        generated: &GeneratedCoreConfigPreview,
        requested_revision: &str,
        internal_validation: &XrayRawConfigValidationReport,
        external_validation: &XrayExternalValidationReport,
    ) -> CoreApplyRecord {
        let now = now_unix();
        let mut stages = vec![
            CoreApplyStageRecord {
                stage: CoreApplyStage::Generated,
                status: CoreApplyStageStatus::Passed,
                detail: format!("generated revision {}", generated.revision),
            },
            CoreApplyStageRecord {
                stage: CoreApplyStage::InternalValidated,
                status: if internal_validation.valid {
                    CoreApplyStageStatus::Passed
                } else {
                    CoreApplyStageStatus::Failed
                },
                detail: format!(
                    "internal validation: {} issue(s)",
                    internal_validation.issue_count
                ),
            },
            CoreApplyStageRecord {
                stage: CoreApplyStage::ExternalValidated,
                status: core_apply_stage_status_from_xray_external(external_validation.status),
                detail: external_validation.detail.clone(),
            },
        ];

        let (result, detail, runtime_stage_status, runtime_stage_detail) = if generated.revision
            != requested_revision
        {
            self.push_log(
                    config,
                    "warn",
                    format!(
                        "generated core config apply skipped due to revision mismatch: requested={}, current={}",
                        requested_revision, generated.revision
                    ),
                );
            (
                    CoreApplyResult::Skipped,
                    "requested revision does not match current generated revision".to_string(),
                    CoreApplyStageStatus::Skipped,
                    "runtime state was not updated because requested revision does not match current generated revision".to_string(),
                )
        } else if !internal_validation.valid {
            self.status = CoreStatus::Failed;
            self.push_log(
                config,
                "error",
                format!(
                    "generated core config apply failed internal validation: {} issue(s)",
                    internal_validation.issue_count
                ),
            );
            (
                CoreApplyResult::Failed,
                "internal raw Xray config validation failed".to_string(),
                CoreApplyStageStatus::Skipped,
                "runtime state was not updated because internal validation failed".to_string(),
            )
        } else if external_validation.status == XrayExternalValidationStatus::Failed {
            self.status = CoreStatus::Failed;
            self.push_log(
                config,
                "error",
                format!(
                    "generated core config apply failed external Xray validation: {}",
                    external_validation.detail
                ),
            );
            (
                CoreApplyResult::Failed,
                "external Xray validation failed".to_string(),
                CoreApplyStageStatus::Skipped,
                "runtime state was not updated because external Xray validation failed".to_string(),
            )
        } else {
            self.applied_revision = Some(generated.revision.clone());
            self.status = CoreStatus::Running;
            self.push_log(
                config,
                "info",
                format!("generated core config applied: {}", generated.revision),
            );
            (
                CoreApplyResult::Applied,
                if external_validation.status == XrayExternalValidationStatus::Skipped {
                    "generated config revision applied; external Xray validation was skipped"
                        .to_string()
                } else {
                    "generated config revision applied after validation".to_string()
                },
                CoreApplyStageStatus::Passed,
                "runtime state updated".to_string(),
            )
        };

        stages.push(CoreApplyStageRecord {
            stage: CoreApplyStage::RuntimeStateUpdated,
            status: runtime_stage_status,
            detail: runtime_stage_detail,
        });

        let record = CoreApplyRecord {
            revision: requested_revision.to_string(),
            created_at_unix: now,
            result,
            detail,
            stages,
        };
        self.push_apply_record(config, record.clone());
        record
    }

    fn push_apply_record(&mut self, config: &AppConfig, record: CoreApplyRecord) {
        self.apply_history.push(record.clone());
        if self.apply_history.len() > config.runtime_limits.max_core_apply_events_buffered {
            let drain =
                self.apply_history.len() - config.runtime_limits.max_core_apply_events_buffered;
            self.apply_history.drain(0..drain);
        }
        let _ = append_ndjson_line(&config.core_apply_history_path, &record);
    }

    fn filtered_apply_history(
        &self,
        query: CoreApplyHistoryQuery,
        default_limit: usize,
    ) -> Vec<CoreApplyRecord> {
        let mut items: Vec<_> = self
            .apply_history
            .iter()
            .filter(|record| query.result.is_none_or(|result| record.result == result))
            .cloned()
            .collect();
        let limit = resolve_limit(query.limit, default_limit);
        if items.len() > limit {
            items = items.split_off(items.len() - limit);
        }
        items
    }
}

impl TelegramRuntime {
    fn new(config: &AppConfig) -> Result<Self, PersistedFileError> {
        let settings = load_telegram_settings(
            &config.telegram_settings_path,
            &config.telegram_secrets_key_path,
        )?;
        let events = compact_telegram_events(read_ndjson_lines::<TelegramEvent>(
            &config.telegram_events_path,
            config.runtime_limits.max_telegram_events_buffered,
        ));
        Ok(Self { settings, events })
    }

    fn public_settings(&self) -> TelegramSettings {
        TelegramSettings {
            enabled: self.settings.enabled,
            bot_token_configured: self
                .settings
                .bot_token
                .as_deref()
                .map(|value| !value.is_empty())
                .unwrap_or(false),
            default_chat_id: self.settings.default_chat_id.clone(),
            notify_on_security_events: self.settings.notify_on_security_events,
            notify_on_system_alerts: self.settings.notify_on_system_alerts,
            notify_on_node_events: self.settings.notify_on_node_events,
            notify_on_node_health_alerts: self.settings.notify_on_node_health_alerts,
            alert_policy: self.settings.alert_policy.clone(),
        }
    }

    fn summary(&self) -> UiTelegramSummary {
        let mut summary = UiTelegramSummary {
            settings: Some(self.public_settings()),
            total_events_buffered: self.events.len(),
            ..UiTelegramSummary::default()
        };
        for event in &self.events {
            match event.status {
                TelegramEventStatus::Queued => summary.queued += 1,
                TelegramEventStatus::Delivered => summary.delivered += 1,
                TelegramEventStatus::RetryScheduled => summary.retry_scheduled += 1,
                TelegramEventStatus::Skipped => summary.skipped += 1,
                TelegramEventStatus::Failed => summary.failed += 1,
            }
        }
        summary
    }

    fn update_settings(&mut self, request: &UpdateTelegramSettingsRequest) {
        if request.bot_token.is_some() {
            self.settings.bot_token = normalize_optional_secret(request.bot_token.clone());
            self.settings.bot_token_ciphertext_b64 = None;
            self.settings.bot_token_nonce_b64 = None;
        }
        self.settings.enabled = request.enabled;
        self.settings.default_chat_id = request.default_chat_id.clone();
        self.settings.notify_on_security_events = request.notify_on_security_events;
        self.settings.notify_on_system_alerts = request.notify_on_system_alerts;
        self.settings.notify_on_node_events = request.notify_on_node_events;
        self.settings.notify_on_node_health_alerts = request.notify_on_node_health_alerts;
        self.settings.alert_policy = request.alert_policy.clone();
    }

    fn push_event(&mut self, config: &AppConfig, event: TelegramEvent) {
        self.events.push(event.clone());
        if self.events.len() > config.runtime_limits.max_telegram_events_buffered {
            let drain = self.events.len() - config.runtime_limits.max_telegram_events_buffered;
            self.events.drain(0..drain);
        }
        let _ = append_ndjson_line(&config.telegram_events_path, &event);
    }

    fn upsert_event(&mut self, config: &AppConfig, event: TelegramEvent) {
        if let Some(existing) = self
            .events
            .iter_mut()
            .find(|existing| !existing.id.is_empty() && existing.id == event.id)
        {
            *existing = event.clone();
            let _ = append_ndjson_line(&config.telegram_events_path, &event);
            return;
        }
        self.push_event(config, event);
    }

    fn due_retry_events(&self, now: u64) -> Vec<TelegramEvent> {
        self.events
            .iter()
            .filter(|event| event.status == TelegramEventStatus::RetryScheduled)
            .filter(|event| {
                event
                    .next_retry_at_unix
                    .is_some_and(|retry_at| retry_at <= now)
            })
            .filter(|event| event.attempt_count < TELEGRAM_MAX_DELIVERY_ATTEMPTS)
            .cloned()
            .collect()
    }

    fn filtered_events(
        &self,
        query: TelegramEventsQuery,
        default_limit: usize,
    ) -> Vec<TelegramEvent> {
        let mut items: Vec<_> = self
            .events
            .iter()
            .filter(|event| query.kind.is_none_or(|kind| event.kind == kind))
            .filter(|event| query.status.is_none_or(|status| event.status == status))
            .cloned()
            .collect();
        let limit = resolve_limit(query.limit, default_limit);
        if items.len() > limit {
            items = items.split_off(items.len() - limit);
        }
        items
    }
}

impl UserRuntime {
    fn new(config: &AppConfig) -> Result<Self, PersistedFileError> {
        let users = load_users(&config.users_path)?
            .into_iter()
            .map(|user| (user.username.clone(), user))
            .collect();
        let activity = read_ndjson_lines::<UserActivityEntry>(
            &config.user_activity_log_path,
            config.runtime_limits.max_user_activity_events_buffered,
        );
        Ok(Self { users, activity })
    }

    /// Full enumeration for config generation.
    ///
    /// A separate method rather than `list` with a large limit: generating
    /// xray.json must see every user, and bounding it to a page would silently drop
    /// some of them from the emitted config.
    fn all(&self) -> Vec<User> {
        self.users.values().cloned().collect()
    }

    fn list(&self, query: UsersQuery, max_limit: usize) -> Vec<User> {
        let mut users: Vec<_> = self.users.values().cloned().collect();
        if let Some(status) = query.status {
            users.retain(|user| user.status == status);
        }
        if let Some(search) = query.search {
            let search = search.to_ascii_lowercase();
            users.retain(|user| {
                user.username.to_ascii_lowercase().contains(&search)
                    || user
                        .note
                        .as_deref()
                        .map(|note| note.to_ascii_lowercase().contains(&search))
                        .unwrap_or(false)
            });
        }
        users.sort_by(|left, right| left.username.cmp(&right.username));
        users.truncate(resolve_limit(query.limit, max_limit));
        users
    }

    fn get(&self, username: &str) -> Result<User, SecurityError> {
        self.users
            .get(username)
            .cloned()
            .ok_or(SecurityError::InvalidSecuritySettings(
                "user does not exist",
            ))
    }

    fn get_by_subscription_token(&self, subscription_token: &str) -> Result<User, SecurityError> {
        self.users
            .values()
            .find(|user| user.subscription_token == subscription_token)
            .cloned()
            .ok_or(SecurityError::Unauthorized)
    }

    fn create(&mut self, request: CreateUserRequest) -> Result<User, SecurityError> {
        if self.users.contains_key(&request.username) {
            return Err(SecurityError::InvalidSecuritySettings(
                "user already exists",
            ));
        }
        let now = now_unix();
        let user = User {
            username: request.username.clone(),
            template_id: request.template_id,
            next_template_id: request.next_template_id,
            status: request.status.unwrap_or(UserStatus::Active),
            data_limit_bytes: request.data_limit_bytes,
            used_traffic_bytes: 0,
            expire_at_unix: request.expire_at_unix,
            note: request.note,
            proxy_profile_ids: request.proxy_profile_ids.unwrap_or_default(),
            excluded_inbound_tags: request.excluded_inbound_tags.unwrap_or_default(),
            subscription_token: generate_subscription_token(),
            sub_revoked_at_unix: None,
            created_at_unix: now,
            updated_at_unix: now,
        };
        self.users.insert(user.username.clone(), user.clone());
        Ok(user)
    }

    fn update(
        &mut self,
        username: &str,
        request: UpdateUserRequest,
    ) -> Result<User, SecurityError> {
        let user = self
            .users
            .get_mut(username)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "user does not exist",
            ))?;
        if request.data_limit_bytes.is_none()
            && request.status.is_none()
            && request.expire_at_unix.is_none()
            && request.note.is_none()
            && request.proxy_profile_ids.is_none()
            && request.excluded_inbound_tags.is_none()
            && request.template_id.is_none()
            && request.next_template_id.is_none()
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "update request is empty",
            ));
        }
        if let Some(template_id) = request.template_id {
            user.template_id = Some(template_id);
        }
        if let Some(next_template_id) = request.next_template_id {
            user.next_template_id = Some(next_template_id);
        }
        if let Some(status) = request.status {
            user.status = status;
        }
        if let Some(data_limit_bytes) = request.data_limit_bytes {
            user.data_limit_bytes = Some(data_limit_bytes);
        }
        if let Some(expire_at_unix) = request.expire_at_unix {
            user.expire_at_unix = Some(expire_at_unix);
        }
        if let Some(note) = request.note {
            user.note = Some(note);
        }
        if let Some(proxy_profile_ids) = request.proxy_profile_ids {
            user.proxy_profile_ids = proxy_profile_ids;
        }
        if let Some(excluded_inbound_tags) = request.excluded_inbound_tags {
            user.excluded_inbound_tags = excluded_inbound_tags;
        }
        user.updated_at_unix = now_unix();
        Ok(user.clone())
    }

    fn delete(&mut self, username: &str) -> Result<(), SecurityError> {
        self.users
            .remove(username)
            .map(|_| ())
            .ok_or(SecurityError::InvalidSecuritySettings(
                "user does not exist",
            ))
    }

    fn reset_usage(&mut self, username: &str) -> Result<User, SecurityError> {
        let user = self
            .users
            .get_mut(username)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "user does not exist",
            ))?;
        user.used_traffic_bytes = 0;
        user.updated_at_unix = now_unix();
        Ok(user.clone())
    }

    fn revoke_subscription(&mut self, username: &str) -> Result<User, SecurityError> {
        let user = self
            .users
            .get_mut(username)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "user does not exist",
            ))?;
        user.sub_revoked_at_unix = Some(now_unix());
        user.subscription_token = generate_subscription_token();
        user.updated_at_unix = now_unix();
        Ok(user.clone())
    }

    fn report_usage(&mut self, username: &str, bytes_delta: u64) -> Result<User, SecurityError> {
        let user = self
            .users
            .get_mut(username)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "user does not exist",
            ))?;
        user.used_traffic_bytes = user.used_traffic_bytes.saturating_add(bytes_delta);
        user.updated_at_unix = now_unix();
        Ok(user.clone())
    }

    fn subscription(&self, username: &str) -> Result<UserSubscriptionView, SecurityError> {
        let user = self
            .users
            .get(username)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "user does not exist",
            ))?;
        Ok(UserSubscriptionView {
            username: user.username.clone(),
            subscription_token: user.subscription_token.clone(),
            subscription_path: format!("/sub/{}", user.subscription_token),
            revoked_at_unix: user.sub_revoked_at_unix,
        })
    }

    fn push_activity(&mut self, config: &AppConfig, entry: UserActivityEntry) {
        self.activity.push(entry.clone());
        if self.activity.len() > config.runtime_limits.max_user_activity_events_buffered {
            let drain =
                self.activity.len() - config.runtime_limits.max_user_activity_events_buffered;
            self.activity.drain(0..drain);
        }
        let _ = append_ndjson_line(&config.user_activity_log_path, &entry);
    }

    fn activity(
        &self,
        username: Option<&str>,
        query: UserActivityQuery,
        default_limit: usize,
    ) -> Vec<UserActivityEntry> {
        let mut items: Vec<_> = self
            .activity
            .iter()
            .filter(|entry| username.is_none_or(|value| entry.username == value))
            .filter(|entry| query.kind.is_none_or(|kind| entry.kind == kind))
            .cloned()
            .collect();
        let limit = resolve_limit(query.limit, default_limit);
        if items.len() > limit {
            items = items.split_off(items.len() - limit);
        }
        items
    }
}

impl UserTemplateRuntime {
    fn new(config: &AppConfig) -> Result<Self, PersistedFileError> {
        let templates = load_user_templates(&config.user_templates_path)?
            .into_iter()
            .map(|template| (template.id.clone(), template))
            .collect();
        Ok(Self { templates })
    }

    fn list(&self) -> Vec<UserTemplate> {
        let mut items: Vec<_> = self.templates.values().cloned().collect();
        items.sort_by(|left, right| left.name.cmp(&right.name));
        items
    }

    fn create(
        &mut self,
        request: CreateUserTemplateRequest,
    ) -> Result<UserTemplate, SecurityError> {
        let id = generate_resource_id();
        let now = now_unix();
        let template = UserTemplate {
            id: id.clone(),
            name: request.name,
            status: request.status,
            data_limit_bytes: request.data_limit_bytes,
            expire_duration_seconds: request.expire_duration_seconds,
            note: request.note,
            proxy_profile_ids: request.proxy_profile_ids,
            excluded_inbound_tags: request.excluded_inbound_tags,
            created_at_unix: now,
            updated_at_unix: now,
        };
        self.templates.insert(id, template.clone());
        Ok(template)
    }

    fn update(
        &mut self,
        template_id: &str,
        request: UpdateUserTemplateRequest,
    ) -> Result<UserTemplate, SecurityError> {
        let template =
            self.templates
                .get_mut(template_id)
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "user template does not exist",
                ))?;
        if let Some(name) = request.name {
            template.name = name;
        }
        if let Some(status) = request.status {
            template.status = status;
        }
        if let Some(data_limit_bytes) = request.data_limit_bytes {
            template.data_limit_bytes = Some(data_limit_bytes);
        }
        if let Some(expire_duration_seconds) = request.expire_duration_seconds {
            template.expire_duration_seconds = Some(expire_duration_seconds);
        }
        if let Some(note) = request.note {
            template.note = Some(note);
        }
        if let Some(proxy_profile_ids) = request.proxy_profile_ids {
            template.proxy_profile_ids = proxy_profile_ids;
        }
        if let Some(excluded_inbound_tags) = request.excluded_inbound_tags {
            template.excluded_inbound_tags = excluded_inbound_tags;
        }
        template.updated_at_unix = now_unix();
        Ok(template.clone())
    }

    fn delete(&mut self, template_id: &str) -> Result<(), SecurityError> {
        self.templates.remove(template_id).map(|_| ()).ok_or(
            SecurityError::InvalidSecuritySettings("user template does not exist"),
        )
    }

    fn get(&self, template_id: &str) -> Result<UserTemplate, SecurityError> {
        self.templates
            .get(template_id)
            .cloned()
            .ok_or(SecurityError::InvalidSecuritySettings(
                "user template does not exist",
            ))
    }
}

impl SubscriptionCatalogRuntime {
    fn new(config: &AppConfig) -> Result<Self, PersistedFileError> {
        let persisted = load_subscription_catalog(&config.subscription_catalog_path)?;
        let usage = load_subscription_usage(
            &config.subscription_usage_path,
            config.runtime_limits.max_subscription_usage_points_buffered,
        )?;
        Ok(Self {
            plans: persisted
                .plans
                .into_iter()
                .map(|plan| (plan.id.clone(), plan))
                .collect(),
            clients: persisted
                .clients
                .into_iter()
                .map(|client| (client.id.clone(), client))
                .collect(),
            devices: persisted
                .devices
                .into_iter()
                .map(|device| (device.id.clone(), device))
                .collect(),
            enrollment_grants: persisted
                .enrollment_grants
                .into_iter()
                .map(|grant| (grant.id.clone(), grant))
                .collect(),
            sessions: HashMap::new(),
            enforcement_actions: HashMap::new(),
            usage_points: usage
                .points
                .into_iter()
                .map(|point| SubscriptionUsagePointRecord {
                    client_id: point.client_id,
                    point: point.point,
                })
                .collect(),
        })
    }

    fn list_plans(
        &self,
        query: SubscriptionCatalogQuery,
        max_limit: usize,
    ) -> Vec<SubscriptionCatalogPlan> {
        let mut plans: Vec<_> = self.plans.values().cloned().collect();
        if let Some(search) = query.search {
            let search = search.to_ascii_lowercase();
            plans.retain(|plan| {
                plan.name.to_ascii_lowercase().contains(&search)
                    || plan
                        .description
                        .as_deref()
                        .map(|description| description.to_ascii_lowercase().contains(&search))
                        .unwrap_or(false)
            });
        }
        plans.sort_by(|left, right| left.name.cmp(&right.name).then(left.id.cmp(&right.id)));
        plans.truncate(resolve_limit(query.limit, max_limit));
        plans
    }

    fn get_plan(&self, plan_id: &str) -> Result<SubscriptionCatalogPlan, SecurityError> {
        self.plans
            .get(plan_id)
            .cloned()
            .ok_or(SecurityError::InvalidSecuritySettings(
                "subscription plan does not exist",
            ))
    }

    fn create_plan(
        &mut self,
        request: CreateSubscriptionPlanRequest,
    ) -> Result<SubscriptionCatalogPlan, SecurityError> {
        let now = now_unix();
        let plan = SubscriptionCatalogPlan {
            id: generate_resource_id(),
            name: request.name,
            description: request.description,
            enabled: request.enabled.unwrap_or(true),
            created_at_unix: now,
            updated_at_unix: now,
        };
        self.plans.insert(plan.id.clone(), plan.clone());
        Ok(plan)
    }

    fn update_plan(
        &mut self,
        plan_id: &str,
        request: UpdateSubscriptionPlanRequest,
    ) -> Result<SubscriptionCatalogPlan, SecurityError> {
        let plan = self
            .plans
            .get_mut(plan_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "subscription plan does not exist",
            ))?;
        if request.name.is_none() && request.description.is_none() && request.enabled.is_none() {
            return Err(SecurityError::InvalidSecuritySettings(
                "update request is empty",
            ));
        }
        if let Some(name) = request.name {
            plan.name = name;
        }
        if let Some(description) = request.description {
            plan.description = Some(description);
        }
        if let Some(enabled) = request.enabled {
            plan.enabled = enabled;
        }
        plan.updated_at_unix = now_unix();
        Ok(plan.clone())
    }

    fn delete_plan(&mut self, plan_id: &str) -> Result<(), SecurityError> {
        if self
            .clients
            .values()
            .any(|client| client.plan_id == plan_id)
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "subscription plan has clients",
            ));
        }
        self.plans
            .remove(plan_id)
            .map(|_| ())
            .ok_or(SecurityError::InvalidSecuritySettings(
                "subscription plan does not exist",
            ))
    }

    /// Full enumeration for config generation; see `UserRuntime::all`.
    fn all_clients(&self) -> Vec<SubscriptionCatalogClient> {
        self.clients.values().cloned().collect()
    }

    fn list_clients(
        &self,
        plan_id: Option<&str>,
        query: SubscriptionCatalogQuery,
        max_limit: usize,
    ) -> Vec<SubscriptionCatalogClient> {
        let mut clients: Vec<_> = self
            .clients
            .values()
            .filter(|client| plan_id.is_none_or(|id| client.plan_id == id))
            .cloned()
            .collect();
        if let Some(search) = query.search {
            let search = search.to_ascii_lowercase();
            clients.retain(|client| {
                client.name.to_ascii_lowercase().contains(&search)
                    || client
                        .note
                        .as_deref()
                        .map(|note| note.to_ascii_lowercase().contains(&search))
                        .unwrap_or(false)
            });
        }
        clients.sort_by(|left, right| left.name.cmp(&right.name).then(left.id.cmp(&right.id)));
        clients.truncate(resolve_limit(query.limit, max_limit));
        clients
    }

    fn get_client(&self, client_id: &str) -> Result<SubscriptionCatalogClient, SecurityError> {
        self.clients
            .get(client_id)
            .cloned()
            .ok_or(SecurityError::InvalidSecuritySettings(
                "subscription client does not exist",
            ))
    }

    fn get_client_by_subscription_token(
        &self,
        subscription_token: &str,
    ) -> Result<SubscriptionCatalogClient, SecurityError> {
        self.clients
            .values()
            .find(|client| client.subscription_token == subscription_token)
            .cloned()
            .ok_or(SecurityError::Unauthorized)
    }

    fn create_client(
        &mut self,
        plan_id: &str,
        request: CreateSubscriptionClientRequest,
    ) -> Result<SubscriptionCatalogClient, SecurityError> {
        if !self.plans.contains_key(plan_id) {
            return Err(SecurityError::InvalidSecuritySettings(
                "subscription plan does not exist",
            ));
        }
        let now = now_unix();
        let client = SubscriptionCatalogClient {
            id: generate_resource_id(),
            plan_id: plan_id.to_string(),
            name: request.name,
            status: request
                .status
                .unwrap_or(SubscriptionCatalogClientStatus::Active),
            max_simultaneous_devices: request.max_simultaneous_devices,
            max_simultaneous_ips: request.max_simultaneous_ips,
            data_limit_bytes: request.data_limit_bytes,
            used_traffic_bytes: 0,
            expire_at_unix: request.expire_at_unix,
            note: request.note,
            access_policy: request.access_policy.unwrap_or_default(),
            subscription_token: generate_subscription_token(),
            revoked_at_unix: None,
            created_at_unix: now,
            updated_at_unix: now,
        };
        self.clients.insert(client.id.clone(), client.clone());
        Ok(client)
    }

    fn update_client(
        &mut self,
        client_id: &str,
        request: UpdateSubscriptionClientRequest,
    ) -> Result<SubscriptionCatalogClient, SecurityError> {
        let client =
            self.clients
                .get_mut(client_id)
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "subscription client does not exist",
                ))?;
        if request.name.is_none()
            && request.status.is_none()
            && request.max_simultaneous_devices.is_none()
            && request.max_simultaneous_ips.is_none()
            && request.data_limit_bytes.is_none()
            && request.expire_at_unix.is_none()
            && request.note.is_none()
            && request.access_policy.is_none()
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "update request is empty",
            ));
        }
        if let Some(name) = request.name {
            client.name = name;
        }
        if let Some(status) = request.status {
            client.status = status;
        }
        if let Some(max_devices) = request.max_simultaneous_devices {
            client.max_simultaneous_devices = Some(max_devices);
        }
        if let Some(max_ips) = request.max_simultaneous_ips {
            client.max_simultaneous_ips = Some(max_ips);
        }
        if let Some(data_limit_bytes) = request.data_limit_bytes {
            client.data_limit_bytes = Some(data_limit_bytes);
        }
        if let Some(expire_at_unix) = request.expire_at_unix {
            client.expire_at_unix = Some(expire_at_unix);
        }
        if let Some(note) = request.note {
            client.note = Some(note);
        }
        if let Some(access_policy) = request.access_policy {
            client.access_policy = access_policy;
        }
        client.updated_at_unix = now_unix();
        Ok(client.clone())
    }

    fn update_client_access(
        &mut self,
        client_id: &str,
        access_policy: SubscriptionClientNodeAccessPolicy,
    ) -> Result<SubscriptionCatalogClient, SecurityError> {
        let client =
            self.clients
                .get_mut(client_id)
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "subscription client does not exist",
                ))?;
        client.access_policy = access_policy;
        client.updated_at_unix = now_unix();
        Ok(client.clone())
    }

    fn reset_client_usage(
        &mut self,
        client_id: &str,
    ) -> Result<SubscriptionCatalogClient, SecurityError> {
        let client =
            self.clients
                .get_mut(client_id)
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "subscription client does not exist",
                ))?;
        client.used_traffic_bytes = 0;
        client.updated_at_unix = now_unix();
        self.usage_points
            .retain(|record| record.client_id != client_id);
        Ok(client.clone())
    }

    fn report_client_usage(
        &mut self,
        client_id: &str,
        request: ReportSubscriptionUsageRequest,
        max_usage_points_buffered: usize,
        now: u64,
    ) -> Result<SubscriptionCatalogClient, SecurityError> {
        validate_report_subscription_usage_request(&request)?;
        let point = SubscriptionUsagePoint {
            at_unix: request.at_unix.unwrap_or(now),
            node_id: request.node_id,
            cluster_id: request.cluster_id,
            bytes_downlink: request.bytes_downlink,
            bytes_uplink: request.bytes_uplink,
        };
        let client =
            self.clients
                .get_mut(client_id)
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "subscription client does not exist",
                ))?;
        let delta = point.bytes_downlink.saturating_add(point.bytes_uplink);
        client.used_traffic_bytes = client.used_traffic_bytes.saturating_add(delta);
        client.updated_at_unix = now;
        let client = client.clone();
        self.push_usage_point(client_id.to_string(), point, max_usage_points_buffered);
        Ok(client)
    }

    fn revoke_client(
        &mut self,
        client_id: &str,
    ) -> Result<SubscriptionCatalogClient, SecurityError> {
        let client =
            self.clients
                .get_mut(client_id)
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "subscription client does not exist",
                ))?;
        client.subscription_token = generate_subscription_token();
        client.revoked_at_unix = Some(now_unix());
        client.status = SubscriptionCatalogClientStatus::Revoked;
        client.updated_at_unix = now_unix();
        for device in self.devices.values_mut().filter(|device| {
            device.client_id == client_id && device.status == SubscriptionDeviceStatus::Active
        }) {
            device.status = SubscriptionDeviceStatus::Revoked;
            device.revoked_at_unix = Some(now_unix());
        }
        for grant in self.enrollment_grants.values_mut().filter(|grant| {
            grant.client_id == client_id
                && grant.status == SubscriptionDeviceEnrollmentStatus::Active
        }) {
            grant.status = SubscriptionDeviceEnrollmentStatus::Revoked;
            grant.revoked_at_unix = Some(now_unix());
        }
        self.sessions
            .retain(|_, session| session.client_id != client_id);
        Ok(client.clone())
    }

    fn delete_client(&mut self, client_id: &str) -> Result<(), SecurityError> {
        self.clients.remove(client_id).map(|_| ()).ok_or(
            SecurityError::InvalidSecuritySettings("subscription client does not exist"),
        )?;
        self.devices
            .retain(|_, device| device.client_id != client_id);
        self.enrollment_grants
            .retain(|_, grant| grant.client_id != client_id);
        self.sessions
            .retain(|_, session| session.client_id != client_id);
        self.usage_points
            .retain(|record| record.client_id != client_id);
        Ok(())
    }

    fn create_device_enrollment(
        &mut self,
        client_id: &str,
        token_hmac_sha256: String,
        expires_in_seconds: u64,
        max_grants_buffered: usize,
        now: u64,
    ) -> Result<SubscriptionDeviceEnrollmentGrant, SecurityError> {
        let client = self
            .clients
            .get(client_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "subscription client does not exist",
            ))?;
        validate_subscription_client_public_state(client)?;
        if client
            .max_simultaneous_devices
            .is_some_and(|limit| self.active_device_count(client_id) >= usize::from(limit))
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "subscription client device limit is already reached",
            ));
        }
        if self
            .enrollment_grants
            .values()
            .filter(|grant| {
                grant.client_id == client_id
                    && subscription_enrollment_status(grant, now)
                        == SubscriptionDeviceEnrollmentStatus::Active
            })
            .count()
            >= MAX_ACTIVE_SUBSCRIPTION_ENROLLMENTS_PER_CLIENT
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "active device enrollment grant limit reached",
            ));
        }

        self.compact_device_enrollments(max_grants_buffered, now);
        if self.enrollment_grants.len() >= max_grants_buffered {
            return Err(SecurityError::InvalidSecuritySettings(
                "device enrollment grant capacity reached",
            ));
        }
        if self
            .enrollment_grants
            .values()
            .any(|grant| constant_time_str_eq(&grant.token_hmac_sha256, &token_hmac_sha256))
        {
            return Err(SecurityError::PersistenceFailure);
        }

        let grant = SubscriptionDeviceEnrollmentGrant {
            id: generate_resource_id(),
            client_id: client_id.to_string(),
            token_hmac_sha256,
            status: SubscriptionDeviceEnrollmentStatus::Active,
            created_at_unix: now,
            expires_at_unix: now.saturating_add(expires_in_seconds),
            consumed_at_unix: None,
            consumed_device_id: None,
            revoked_at_unix: None,
        };
        self.enrollment_grants
            .insert(grant.id.clone(), grant.clone());
        Ok(grant)
    }

    fn list_device_enrollments(
        &self,
        client_id: &str,
        query: SubscriptionDeviceEnrollmentsQuery,
        max_limit: usize,
        now: u64,
    ) -> Result<Vec<SubscriptionDeviceEnrollmentGrantView>, SecurityError> {
        if !self.clients.contains_key(client_id) {
            return Err(SecurityError::InvalidSecuritySettings(
                "subscription client does not exist",
            ));
        }
        let mut grants = self
            .enrollment_grants
            .values()
            .filter(|grant| grant.client_id == client_id)
            .filter(|grant| {
                query
                    .status
                    .is_none_or(|status| subscription_enrollment_status(grant, now) == status)
            })
            .map(|grant| subscription_enrollment_view(grant, now))
            .collect::<Vec<_>>();
        grants.sort_by(|left, right| {
            right
                .created_at_unix
                .cmp(&left.created_at_unix)
                .then(left.id.cmp(&right.id))
        });
        grants.truncate(resolve_limit(query.limit, max_limit));
        Ok(grants)
    }

    fn revoke_device_enrollment(
        &mut self,
        client_id: &str,
        grant_id: &str,
        now: u64,
    ) -> Result<SubscriptionDeviceEnrollmentGrantView, SecurityError> {
        if !self.clients.contains_key(client_id) {
            return Err(SecurityError::InvalidSecuritySettings(
                "subscription client does not exist",
            ));
        }
        let grant = self
            .enrollment_grants
            .get_mut(grant_id)
            .filter(|grant| grant.client_id == client_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "device enrollment grant does not exist",
            ))?;
        if subscription_enrollment_status(grant, now) != SubscriptionDeviceEnrollmentStatus::Active
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "only an active device enrollment grant can be revoked",
            ));
        }
        grant.status = SubscriptionDeviceEnrollmentStatus::Revoked;
        grant.revoked_at_unix = Some(now);
        Ok(subscription_enrollment_view(grant, now))
    }

    fn consume_device_enrollment(
        &mut self,
        token_hmac_sha256: &str,
        fingerprint_hmac_sha256: String,
        device_credential_hmac_sha256: String,
        wireguard_fingerprint_hmac_sha256: Option<String>,
        request: RegisterSubscriptionDeviceRequest,
        max_devices_buffered: usize,
        now: u64,
    ) -> Result<(SubscriptionClientDeviceView, SubscriptionCatalogClient), SecurityError> {
        let grant_id = self
            .enrollment_grants
            .values()
            .find(|grant| {
                constant_time_str_eq(&grant.token_hmac_sha256, token_hmac_sha256)
                    && subscription_enrollment_status(grant, now)
                        == SubscriptionDeviceEnrollmentStatus::Active
            })
            .map(|grant| grant.id.clone())
            .ok_or(SecurityError::Unauthorized)?;
        let client_id = self
            .enrollment_grants
            .get(&grant_id)
            .map(|grant| grant.client_id.clone())
            .ok_or(SecurityError::Unauthorized)?;
        let client = self
            .clients
            .get(&client_id)
            .cloned()
            .ok_or(SecurityError::Unauthorized)?;
        validate_subscription_client_public_state(&client)
            .map_err(|_| SecurityError::Unauthorized)?;
        if self.devices.values().any(|device| {
            constant_time_str_eq(&device.fingerprint_hmac_sha256, &fingerprint_hmac_sha256)
        }) {
            return Err(SecurityError::InvalidSecuritySettings(
                "device fingerprint is already registered",
            ));
        }
        if self.devices.values().any(|device| {
            device
                .subscription_token_hmac_sha256
                .as_deref()
                .is_some_and(|existing| {
                    constant_time_str_eq(existing, &device_credential_hmac_sha256)
                })
        }) {
            return Err(SecurityError::PersistenceFailure);
        }

        let registration = self.register_device(
            &client_id,
            fingerprint_hmac_sha256,
            Some(device_credential_hmac_sha256),
            wireguard_fingerprint_hmac_sha256,
            request,
            max_devices_buffered,
        )?;
        if !registration.admitted {
            return Err(SecurityError::InvalidSecuritySettings(
                "device enrollment was not admitted",
            ));
        }
        let device = registration
            .device
            .ok_or(SecurityError::PersistenceFailure)?;
        let grant = self
            .enrollment_grants
            .get_mut(&grant_id)
            .ok_or(SecurityError::Unauthorized)?;
        if subscription_enrollment_status(grant, now) != SubscriptionDeviceEnrollmentStatus::Active
        {
            return Err(SecurityError::Unauthorized);
        }
        grant.status = SubscriptionDeviceEnrollmentStatus::Consumed;
        grant.consumed_at_unix = Some(now);
        grant.consumed_device_id = Some(device.id.clone());
        Ok((device, client))
    }

    fn compact_device_enrollments(&mut self, max_grants_buffered: usize, now: u64) {
        if self.enrollment_grants.len() < max_grants_buffered {
            return;
        }
        let mut removable = self
            .enrollment_grants
            .values()
            .filter(|grant| {
                subscription_enrollment_status(grant, now)
                    != SubscriptionDeviceEnrollmentStatus::Active
            })
            .map(|grant| (grant.created_at_unix, grant.id.clone()))
            .collect::<Vec<_>>();
        removable.sort();
        for (_, grant_id) in removable {
            if self.enrollment_grants.len() < max_grants_buffered {
                break;
            }
            self.enrollment_grants.remove(&grant_id);
        }
    }

    fn rollback_device_enrollment_consumption(&mut self, token_hmac_sha256: &str, device_id: &str) {
        self.devices.remove(device_id);
        if let Some(grant) = self.enrollment_grants.values_mut().find(|grant| {
            constant_time_str_eq(&grant.token_hmac_sha256, token_hmac_sha256)
                && grant.status == SubscriptionDeviceEnrollmentStatus::Consumed
                && grant.consumed_device_id.as_deref() == Some(device_id)
        }) {
            grant.status = SubscriptionDeviceEnrollmentStatus::Active;
            grant.consumed_at_unix = None;
            grant.consumed_device_id = None;
        }
    }

    fn list_devices(
        &self,
        client_id: &str,
        query: SubscriptionDevicesQuery,
        max_limit: usize,
    ) -> Result<Vec<SubscriptionClientDevice>, SecurityError> {
        if !self.clients.contains_key(client_id) {
            return Err(SecurityError::InvalidSecuritySettings(
                "subscription client does not exist",
            ));
        }
        let mut devices: Vec<_> = self
            .devices
            .values()
            .filter(|device| device.client_id == client_id)
            .filter(|device| query.status.is_none_or(|status| device.status == status))
            .cloned()
            .collect();
        devices.sort_by(|left, right| {
            right
                .last_seen_at_unix
                .cmp(&left.last_seen_at_unix)
                .then(left.id.cmp(&right.id))
        });
        devices.truncate(resolve_limit(query.limit, max_limit));
        Ok(devices)
    }

    fn subscription_device_by_credential(
        &self,
        credential_hmac_sha256: &str,
    ) -> Result<(SubscriptionCatalogClient, SubscriptionClientDevice), SecurityError> {
        let device = self
            .devices
            .values()
            .find(|device| {
                device.status == SubscriptionDeviceStatus::Active
                    && device
                        .subscription_token_hmac_sha256
                        .as_deref()
                        .is_some_and(|stored| constant_time_str_eq(stored, credential_hmac_sha256))
            })
            .ok_or(SecurityError::Unauthorized)?;
        let client = self
            .clients
            .get(&device.client_id)
            .cloned()
            .ok_or(SecurityError::Unauthorized)?;
        validate_subscription_client_public_state(&client)
            .map_err(|_| SecurityError::Unauthorized)?;
        Ok((client, device.clone()))
    }

    fn register_device(
        &mut self,
        client_id: &str,
        fingerprint_hmac_sha256: String,
        subscription_token_hmac_sha256: Option<String>,
        wireguard_fingerprint_hmac_sha256: Option<String>,
        request: RegisterSubscriptionDeviceRequest,
        max_devices_buffered: usize,
    ) -> Result<RegisterSubscriptionDeviceResponse, SecurityError> {
        let client = self
            .clients
            .get(client_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "subscription client does not exist",
            ))?
            .clone();
        validate_subscription_client_public_state(&client)?;
        let active_device_count = self.active_device_count(client_id);
        let requested_wireguard_public_key = request
            .wireguard_public_key
            .as_deref()
            .map(str::trim)
            .map(str::to_string);
        let requested_wireguard_allowed_ips =
            normalize_wireguard_allowed_ips(&request.wireguard_allowed_ips)?;
        let existing_device_id = self
            .devices
            .values()
            .find(|device| {
                device.client_id == client_id
                    && device.fingerprint_hmac_sha256 == fingerprint_hmac_sha256
            })
            .map(|device| device.id.clone());

        if let Some(public_key) = requested_wireguard_public_key.as_deref()
            && self.devices.values().any(|device| {
                device.wireguard_public_key.as_deref() == Some(public_key)
                    && existing_device_id.as_deref() != Some(device.id.as_str())
            })
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "WireGuard public key is already bound to another device",
            ));
        }
        if !requested_wireguard_allowed_ips.is_empty()
            && self.devices.values().any(|device| {
                existing_device_id.as_deref() != Some(device.id.as_str())
                    && device
                        .wireguard_allowed_ips
                        .iter()
                        .any(|assigned| requested_wireguard_allowed_ips.contains(assigned))
            })
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "WireGuard AllowedIPs are already bound to another device",
            ));
        }

        if let Some(device) = self.devices.values_mut().find(|device| {
            device.client_id == client_id
                && device.fingerprint_hmac_sha256 == fingerprint_hmac_sha256
        }) {
            if device.status == SubscriptionDeviceStatus::Revoked {
                return Ok(RegisterSubscriptionDeviceResponse {
                    admitted: false,
                    active_device_count,
                    max_simultaneous_devices: client.max_simultaneous_devices,
                    device: Some(subscription_device_view(device)),
                    reason: "device was revoked and cannot be admitted".to_string(),
                });
            }
            if let Some(public_key) = requested_wireguard_public_key {
                match device.wireguard_public_key.as_deref() {
                    Some(existing) if existing != public_key => {
                        return Err(SecurityError::InvalidSecuritySettings(
                            "WireGuard key rotation requires revoking the existing device",
                        ));
                    }
                    Some(_) if device.wireguard_allowed_ips != requested_wireguard_allowed_ips => {
                        return Err(SecurityError::InvalidSecuritySettings(
                            "WireGuard AllowedIPs cannot be changed on an existing device",
                        ));
                    }
                    Some(_) => {}
                    None => {
                        device.wireguard_public_key = Some(public_key);
                        device.wireguard_fingerprint_hmac_sha256 =
                            wireguard_fingerprint_hmac_sha256;
                        device.wireguard_allowed_ips = requested_wireguard_allowed_ips;
                        device.wireguard_key_registered_at_unix = Some(now_unix());
                    }
                }
            }
            device.last_seen_at_unix = now_unix();
            if request.label.is_some() {
                device.label = request.label;
            }
            if request.platform.is_some() {
                device.platform = request.platform;
            }
            return Ok(RegisterSubscriptionDeviceResponse {
                admitted: true,
                active_device_count,
                max_simultaneous_devices: client.max_simultaneous_devices,
                device: Some(subscription_device_view(device)),
                reason: "known active device admitted".to_string(),
            });
        }

        if client
            .max_simultaneous_devices
            .is_some_and(|limit| active_device_count >= usize::from(limit))
        {
            return Ok(RegisterSubscriptionDeviceResponse {
                admitted: false,
                active_device_count,
                max_simultaneous_devices: client.max_simultaneous_devices,
                device: None,
                reason: "maximum active device limit reached".to_string(),
            });
        }
        if self.devices.len() >= max_devices_buffered {
            return Err(SecurityError::InvalidSecuritySettings(
                "subscription device registry capacity reached",
            ));
        }
        let now = now_unix();
        let device = SubscriptionClientDevice {
            id: generate_resource_id(),
            client_id: client_id.to_string(),
            fingerprint_hmac_sha256,
            subscription_token_hmac_sha256,
            wireguard_public_key: requested_wireguard_public_key,
            wireguard_fingerprint_hmac_sha256,
            wireguard_allowed_ips: requested_wireguard_allowed_ips,
            wireguard_key_registered_at_unix: request.wireguard_public_key.as_ref().map(|_| now),
            label: request.label,
            platform: request.platform,
            status: SubscriptionDeviceStatus::Active,
            first_seen_at_unix: now,
            last_seen_at_unix: now,
            revoked_at_unix: None,
        };
        self.devices.insert(device.id.clone(), device.clone());
        Ok(RegisterSubscriptionDeviceResponse {
            admitted: true,
            active_device_count: active_device_count + 1,
            max_simultaneous_devices: client.max_simultaneous_devices,
            device: Some(subscription_device_view(&device)),
            reason: "new device admitted".to_string(),
        })
    }

    fn revoke_device(
        &mut self,
        client_id: &str,
        device_id: &str,
    ) -> Result<SubscriptionClientDevice, SecurityError> {
        if !self.clients.contains_key(client_id) {
            return Err(SecurityError::InvalidSecuritySettings(
                "subscription client does not exist",
            ));
        }
        let device = self
            .devices
            .get_mut(device_id)
            .filter(|device| device.client_id == client_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "subscription device does not exist",
            ))?;
        device.status = SubscriptionDeviceStatus::Revoked;
        device.revoked_at_unix = Some(now_unix());
        Ok(device.clone())
    }

    fn active_device_count(&self, client_id: &str) -> usize {
        self.devices
            .values()
            .filter(|device| {
                device.client_id == client_id && device.status == SubscriptionDeviceStatus::Active
            })
            .count()
    }

    fn subscription_render_device(
        &self,
        client: &SubscriptionCatalogClient,
        device_id: Option<&str>,
    ) -> Result<Option<SubscriptionClientDevice>, SecurityError> {
        let Some(device_id) = device_id else {
            if client.max_simultaneous_devices.is_some() {
                return Err(SecurityError::InvalidSecuritySettings(
                    "device_id is required when subscription device limiting is enabled",
                ));
            }
            return Ok(None);
        };
        let device = self
            .devices
            .get(device_id)
            .filter(|device| {
                device.client_id == client.id && device.status == SubscriptionDeviceStatus::Active
            })
            .cloned()
            .ok_or(SecurityError::InvalidSecuritySettings(
                "active subscription device does not exist",
            ))?;
        Ok(Some(device))
    }

    fn list_sessions(
        &mut self,
        client_id: &str,
        query: SubscriptionSessionsQuery,
        max_limit: usize,
        now: u64,
    ) -> Result<Vec<SubscriptionClientSessionView>, SecurityError> {
        if !self.clients.contains_key(client_id) {
            return Err(SecurityError::InvalidSecuritySettings(
                "subscription client does not exist",
            ));
        }
        self.prune_stale_sessions(now);
        let mut sessions: Vec<_> = self
            .sessions
            .values()
            .filter(|session| session.client_id == client_id)
            .filter(|session| {
                query
                    .verdict
                    .is_none_or(|verdict| session.verdict == verdict)
            })
            .map(|session| subscription_session_view(session, &self.enforcement_actions))
            .collect();
        sessions.sort_by(|left, right| {
            right
                .last_observed_at_unix
                .cmp(&left.last_observed_at_unix)
                .then(left.session_id.cmp(&right.session_id))
        });
        sessions.truncate(resolve_limit(query.limit, max_limit));
        Ok(sessions)
    }

    fn report_node_sessions(
        &mut self,
        node_id: &str,
        local_runtime_usernames: &HashSet<String>,
        runtime_capabilities: &[SubscriptionSessionRuntimeCapability],
        observations: Vec<SubscriptionSessionObservation>,
        master_key: &[u8; 32],
        max_sessions_buffered: usize,
        now: u64,
    ) -> Result<ReportSubscriptionSessionsResponse, SecurityError> {
        self.prune_stale_sessions(now);
        self.sessions
            .retain(|_, session| session.node_id != node_id);
        let reported_count = observations.len();
        let mut verdicts = Vec::with_capacity(reported_count);
        for observation in observations {
            let verdict = self.evaluate_session_observation(
                node_id,
                local_runtime_usernames,
                runtime_capabilities,
                observation,
                master_key,
                max_sessions_buffered,
                now,
            )?;
            verdicts.push(verdict);
        }
        let allowed_count = verdicts
            .iter()
            .filter(|verdict| verdict.verdict == SubscriptionSessionVerdict::Allow)
            .count();
        Ok(ReportSubscriptionSessionsResponse {
            node_id: node_id.to_string(),
            reported_count,
            allowed_count,
            blocked_count: verdicts.len().saturating_sub(allowed_count),
            verdicts,
        })
    }

    fn evaluate_session_observation(
        &mut self,
        node_id: &str,
        local_runtime_usernames: &HashSet<String>,
        runtime_capabilities: &[SubscriptionSessionRuntimeCapability],
        observation: SubscriptionSessionObservation,
        master_key: &[u8; 32],
        max_sessions_buffered: usize,
        now: u64,
    ) -> Result<SubscriptionSessionVerdictView, SecurityError> {
        if !local_runtime_usernames.contains(&observation.runtime_username) {
            let (enforcement, enforcement_unavailable_reason) = self.blocked_session_enforcement(
                node_id,
                &observation.session_id,
                observation.runtime_session_ref.as_deref(),
                "runtime principal is not assigned to this node",
                runtime_capabilities,
                master_key,
                max_sessions_buffered,
                now,
            )?;
            return Ok(SubscriptionSessionVerdictView {
                session_id: observation.session_id,
                verdict: SubscriptionSessionVerdict::Block,
                reason: "runtime principal is not assigned to this node".to_string(),
                enforcement,
                enforcement_unavailable_reason,
            });
        }
        let Some((client_id, runtime_device_id)) =
            parse_subscription_runtime_username(&observation.runtime_username)
        else {
            let (enforcement, enforcement_unavailable_reason) = self.blocked_session_enforcement(
                node_id,
                &observation.session_id,
                observation.runtime_session_ref.as_deref(),
                "runtime principal is not managed by subscription device policy",
                runtime_capabilities,
                master_key,
                max_sessions_buffered,
                now,
            )?;
            return Ok(SubscriptionSessionVerdictView {
                session_id: observation.session_id,
                verdict: SubscriptionSessionVerdict::Block,
                reason: "runtime principal is not managed by subscription device policy"
                    .to_string(),
                enforcement,
                enforcement_unavailable_reason,
            });
        };
        let Some(client) = self.clients.get(client_id).cloned() else {
            let (enforcement, enforcement_unavailable_reason) = self.blocked_session_enforcement(
                node_id,
                &observation.session_id,
                observation.runtime_session_ref.as_deref(),
                "runtime principal is not assigned to this node",
                runtime_capabilities,
                master_key,
                max_sessions_buffered,
                now,
            )?;
            return Ok(SubscriptionSessionVerdictView {
                session_id: observation.session_id,
                verdict: SubscriptionSessionVerdict::Block,
                reason: "runtime principal is not assigned to this node".to_string(),
                enforcement,
                enforcement_unavailable_reason,
            });
        };
        let (verdict, reason, device_id) = if let Some(device_id) = runtime_device_id {
            self.session_runtime_device_verdict(&client, device_id)
        } else {
            self.session_device_verdict(
                &client,
                observation.device_fingerprint.as_deref(),
                master_key,
            )?
        };
        let source_ip_hmac_sha256 = observation
            .source_ip
            .as_deref()
            .map(|source_ip| hash_subscription_session_source_ip(source_ip.trim(), master_key))
            .transpose()?;
        let (verdict, reason) = if verdict == SubscriptionSessionVerdict::Allow {
            self.session_ip_verdict(&client, source_ip_hmac_sha256.as_deref(), reason)
        } else {
            (verdict, reason)
        };
        if self.sessions.len() >= max_sessions_buffered {
            let (enforcement, enforcement_unavailable_reason) = self.blocked_session_enforcement(
                node_id,
                &observation.session_id,
                observation.runtime_session_ref.as_deref(),
                "session observation registry capacity reached",
                runtime_capabilities,
                master_key,
                max_sessions_buffered,
                now,
            )?;
            return Ok(SubscriptionSessionVerdictView {
                session_id: observation.session_id,
                verdict: SubscriptionSessionVerdict::Block,
                reason: "session observation registry capacity reached".to_string(),
                enforcement,
                enforcement_unavailable_reason,
            });
        }
        let (enforcement, enforcement_unavailable_reason) =
            if verdict == SubscriptionSessionVerdict::Block {
                self.blocked_session_enforcement(
                    node_id,
                    &observation.session_id,
                    observation.runtime_session_ref.as_deref(),
                    &reason,
                    runtime_capabilities,
                    master_key,
                    max_sessions_buffered,
                    now,
                )?
            } else {
                (None, None)
            };
        let session_id = observation.session_id;
        let session = SubscriptionSessionRecord {
            session_id: session_id.clone(),
            client_id: client.id,
            runtime_username: observation.runtime_username,
            node_id: node_id.to_string(),
            device_id,
            source_ip_hmac_sha256,
            verdict,
            reason: reason.clone(),
            enforcement_unavailable_reason: enforcement_unavailable_reason.clone(),
            connected_at_unix: observation.connected_at_unix,
            last_observed_at_unix: now,
            enforcement_action_id: enforcement
                .as_ref()
                .map(|enforcement| enforcement.action_id.clone()),
        };
        self.sessions
            .insert(format!("{node_id}/{session_id}"), session);
        Ok(SubscriptionSessionVerdictView {
            session_id,
            verdict,
            reason,
            enforcement,
            enforcement_unavailable_reason,
        })
    }

    fn blocked_session_enforcement(
        &mut self,
        node_id: &str,
        session_id: &str,
        runtime_session_ref: Option<&str>,
        reason: &str,
        runtime_capabilities: &[SubscriptionSessionRuntimeCapability],
        master_key: &[u8; 32],
        max_sessions_buffered: usize,
        now: u64,
    ) -> Result<(Option<SubscriptionSessionEnforcementView>, Option<String>), SecurityError> {
        let exact_supported = runtime_capabilities
            .contains(&SubscriptionSessionRuntimeCapability::OpaqueSessionReference)
            && runtime_capabilities
                .contains(&SubscriptionSessionRuntimeCapability::ExactSessionTermination)
            && runtime_capabilities
                .contains(&SubscriptionSessionRuntimeCapability::PostActionAbsenceVerification);
        if !exact_supported {
            let unavailable_reason = if runtime_capabilities
                .contains(&SubscriptionSessionRuntimeCapability::PrincipalWideTerminationOnly)
            {
                "node supports only principal-wide termination; panel will not issue destructive fallback action"
            } else {
                "node does not declare exact-session termination capabilities"
            };
            return Ok((None, Some(unavailable_reason.to_string())));
        }
        if runtime_session_ref.is_none() {
            return Ok((
                None,
                Some("node did not report an opaque exact runtime session reference".to_string()),
            ));
        }
        Ok((
            Some(self.issue_session_termination_action(
                node_id,
                session_id,
                runtime_session_ref,
                reason,
                master_key,
                max_sessions_buffered,
                now,
            )?),
            None,
        ))
    }

    fn issue_session_termination_action(
        &mut self,
        node_id: &str,
        session_id: &str,
        runtime_session_ref: Option<&str>,
        reason: &str,
        master_key: &[u8; 32],
        max_sessions_buffered: usize,
        now: u64,
    ) -> Result<SubscriptionSessionEnforcementView, SecurityError> {
        if let Some(existing) = self.enforcement_actions.values().find(|action| {
            action.node_id == node_id
                && action.session_id == session_id
                && action.status == SubscriptionSessionEnforcementStatus::Pending
        }) {
            return Ok(subscription_session_enforcement_view(existing));
        }
        while self.enforcement_actions.len() >= max_sessions_buffered.max(1) {
            let oldest = self
                .enforcement_actions
                .values()
                .min_by_key(|action| action.updated_at_unix)
                .map(|action| action.action_id.clone());
            let Some(oldest) = oldest else {
                break;
            };
            self.enforcement_actions.remove(&oldest);
        }
        let action = SubscriptionSessionEnforcementRecord {
            action_id: generate_resource_id(),
            session_id: session_id.to_string(),
            node_id: node_id.to_string(),
            action: SubscriptionSessionEnforcementAction::TerminateSession,
            status: SubscriptionSessionEnforcementStatus::Pending,
            reason: reason.to_string(),
            required_adapter: SubscriptionSessionRuntimeAdapter::NodeManagedExactSession,
            runtime_session_ref_hmac_sha256: runtime_session_ref
                .map(|runtime_session_ref| {
                    hash_subscription_runtime_session_ref(runtime_session_ref.trim(), master_key)
                })
                .transpose()?,
            requires_absence_verification: true,
            issued_at_unix: now,
            updated_at_unix: now,
            detail: None,
        };
        let view = subscription_session_enforcement_view(&action);
        self.enforcement_actions
            .insert(action.action_id.clone(), action);
        Ok(view)
    }

    fn report_session_enforcement_result(
        &mut self,
        node_id: &str,
        request: ReportSubscriptionSessionEnforcementResultRequest,
        master_key: &[u8; 32],
        now: u64,
    ) -> Result<SubscriptionSessionEnforcementView, SecurityError> {
        if request.status == SubscriptionSessionEnforcementStatus::Pending {
            return Err(SecurityError::InvalidSecuritySettings(
                "enforcement result status must be applied or failed",
            ));
        }
        let action = self
            .enforcement_actions
            .get_mut(&request.action_id)
            .filter(|action| action.node_id == node_id && action.session_id == request.session_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "session enforcement action does not exist for this node",
            ))?;
        if request.status == SubscriptionSessionEnforcementStatus::Applied {
            let runtime_session_ref = request.runtime_session_ref.as_deref().ok_or(
                SecurityError::InvalidSecuritySettings(
                    "applied enforcement result requires a runtime session reference",
                ),
            )?;
            let expected_ref = action.runtime_session_ref_hmac_sha256.as_deref().ok_or(
                SecurityError::InvalidSecuritySettings(
                    "enforcement action lacks an exact runtime session reference",
                ),
            )?;
            let reported_ref =
                hash_subscription_runtime_session_ref(runtime_session_ref.trim(), master_key)?;
            if reported_ref != expected_ref {
                return Err(SecurityError::InvalidSecuritySettings(
                    "runtime session reference does not match enforcement action",
                ));
            }
            if request.adapter != Some(action.required_adapter) {
                return Err(SecurityError::InvalidSecuritySettings(
                    "enforcement result does not use the required exact-session adapter",
                ));
            }
            if request.session_absent_after_action != Some(true)
                || request.verified_at_unix.is_none()
            {
                return Err(SecurityError::InvalidSecuritySettings(
                    "applied enforcement result requires post-action absence verification",
                ));
            }
        }
        action.status = request.status;
        action.updated_at_unix = now;
        action.detail = request
            .detail
            .map(|detail| detail.trim().chars().take(512).collect());
        Ok(subscription_session_enforcement_view(action))
    }

    fn session_device_verdict(
        &self,
        client: &SubscriptionCatalogClient,
        device_fingerprint: Option<&str>,
        master_key: &[u8; 32],
    ) -> Result<(SubscriptionSessionVerdict, String, Option<String>), SecurityError> {
        if validate_subscription_client_public_state(client).is_err() {
            return Ok((
                SubscriptionSessionVerdict::Block,
                "subscription client is not active".to_string(),
                None,
            ));
        }
        if client.max_simultaneous_devices.is_none() {
            return Ok((
                SubscriptionSessionVerdict::Allow,
                "no device registration enforcement configured".to_string(),
                None,
            ));
        }
        let Some(fingerprint) = device_fingerprint.filter(|value| !value.trim().is_empty()) else {
            return Ok((
                SubscriptionSessionVerdict::Block,
                "registered device fingerprint is required".to_string(),
                None,
            ));
        };
        let fingerprint_hmac_sha256 =
            hash_subscription_device_fingerprint(fingerprint.trim(), master_key)?;
        let Some(device) = self.devices.values().find(|device| {
            device.client_id == client.id
                && (device.fingerprint_hmac_sha256 == fingerprint_hmac_sha256
                    || device.wireguard_fingerprint_hmac_sha256.as_deref()
                        == Some(fingerprint_hmac_sha256.as_str()))
        }) else {
            return Ok((
                SubscriptionSessionVerdict::Block,
                "device is not registered".to_string(),
                None,
            ));
        };
        if device.status == SubscriptionDeviceStatus::Revoked {
            return Ok((
                SubscriptionSessionVerdict::Block,
                "device is revoked".to_string(),
                Some(device.id.clone()),
            ));
        }
        Ok((
            SubscriptionSessionVerdict::Allow,
            "registered active device admitted".to_string(),
            Some(device.id.clone()),
        ))
    }

    fn session_runtime_device_verdict(
        &self,
        client: &SubscriptionCatalogClient,
        device_id: &str,
    ) -> (SubscriptionSessionVerdict, String, Option<String>) {
        if validate_subscription_client_public_state(client).is_err() {
            return (
                SubscriptionSessionVerdict::Block,
                "subscription client is not active".to_string(),
                None,
            );
        }
        let Some(device) = self
            .devices
            .get(device_id)
            .filter(|device| device.client_id == client.id)
        else {
            return (
                SubscriptionSessionVerdict::Block,
                "runtime device credential is not registered".to_string(),
                None,
            );
        };
        if device.status != SubscriptionDeviceStatus::Active {
            return (
                SubscriptionSessionVerdict::Block,
                "runtime device credential is revoked".to_string(),
                Some(device.id.clone()),
            );
        }
        (
            SubscriptionSessionVerdict::Allow,
            "registered active runtime device credential admitted".to_string(),
            Some(device.id.clone()),
        )
    }

    fn session_ip_verdict(
        &self,
        client: &SubscriptionCatalogClient,
        source_ip_hmac_sha256: Option<&str>,
        allowed_reason: String,
    ) -> (SubscriptionSessionVerdict, String) {
        let Some(max_ips) = client.max_simultaneous_ips else {
            return (SubscriptionSessionVerdict::Allow, allowed_reason);
        };
        let Some(source_ip_hmac_sha256) = source_ip_hmac_sha256 else {
            return (
                SubscriptionSessionVerdict::Block,
                "source IP is required by concurrent IP policy".to_string(),
            );
        };
        let active_ips: HashSet<_> = self
            .sessions
            .values()
            .filter(|session| {
                session.client_id == client.id
                    && session.verdict == SubscriptionSessionVerdict::Allow
            })
            .filter_map(|session| session.source_ip_hmac_sha256.as_deref())
            .collect();
        if active_ips.contains(source_ip_hmac_sha256) || active_ips.len() < usize::from(max_ips) {
            (SubscriptionSessionVerdict::Allow, allowed_reason)
        } else {
            (
                SubscriptionSessionVerdict::Block,
                "maximum simultaneous source IP limit reached".to_string(),
            )
        }
    }

    fn prune_stale_sessions(&mut self, now: u64) {
        self.sessions.retain(|_, session| {
            now.saturating_sub(session.last_observed_at_unix)
                <= SUBSCRIPTION_SESSION_STALE_AFTER_SECONDS
        });
        self.enforcement_actions.retain(|_, action| {
            now.saturating_sub(action.updated_at_unix) <= SUBSCRIPTION_SESSION_STALE_AFTER_SECONDS
        });
    }

    fn usage_detail(
        &self,
        client_id: &str,
        query: SubscriptionUsageQuery,
        now: u64,
    ) -> Result<SubscriptionUsageDetail, SecurityError> {
        if !self.clients.contains_key(client_id) {
            return Err(SecurityError::InvalidSecuritySettings(
                "subscription client does not exist",
            ));
        }
        let (window, from_unix, to_unix) = resolve_subscription_usage_window(query, now)?;
        let points: Vec<_> = self
            .usage_points
            .iter()
            .filter(|record| record.client_id == client_id)
            .filter(|record| record.point.at_unix >= from_unix && record.point.at_unix <= to_unix)
            .map(|record| record.point.clone())
            .collect();
        let total_downlink_bytes = points
            .iter()
            .map(|point| point.bytes_downlink)
            .fold(0_u64, u64::saturating_add);
        let total_uplink_bytes = points
            .iter()
            .map(|point| point.bytes_uplink)
            .fold(0_u64, u64::saturating_add);
        Ok(SubscriptionUsageDetail {
            client_id: client_id.to_string(),
            window,
            from_unix,
            to_unix,
            total_downlink_bytes,
            total_uplink_bytes,
            points,
        })
    }

    #[allow(dead_code)]
    fn push_usage_point(
        &mut self,
        client_id: String,
        point: SubscriptionUsagePoint,
        max_usage_points_buffered: usize,
    ) {
        self.usage_points
            .push(SubscriptionUsagePointRecord { client_id, point });
        let max_items = max_usage_points_buffered.max(1);
        if self.usage_points.len() > max_items {
            let overflow = self.usage_points.len().saturating_sub(max_items);
            self.usage_points.drain(0..overflow);
        }
    }
}

impl NetworkRuntime {
    fn new(config: &AppConfig) -> Result<Self, PersistedFileError> {
        let resources = load_network_resources(&config.network_resources_path)?;
        Ok(Self {
            inbounds: resources
                .inbounds
                .into_iter()
                .map(|inbound| (inbound.tag.clone(), inbound))
                .collect(),
            hosts: resources
                .hosts
                .into_iter()
                .map(|host| (host.id.clone(), host))
                .collect(),
            proxy_profiles: resources
                .proxy_profiles
                .into_iter()
                .map(|profile| (profile.id.clone(), profile))
                .collect(),
        })
    }

    fn list_inbounds(&self) -> Vec<Inbound> {
        let mut items: Vec<_> = self.inbounds.values().cloned().collect();
        items.sort_by(|left, right| left.tag.cmp(&right.tag));
        items
    }

    fn create_inbound(&mut self, request: CreateInboundRequest) -> Result<Inbound, SecurityError> {
        if self.inbounds.contains_key(&request.tag) {
            return Err(SecurityError::InvalidSecuritySettings(
                "inbound already exists",
            ));
        }
        let now = now_unix();
        let inbound = Inbound {
            tag: request.tag.clone(),
            port: request.port,
            protocol: request.protocol,
            network: request.network,
            tls_enabled: request.tls_enabled,
            node_id: request.node_id,
            cluster_id: request.cluster_id,
            created_at_unix: now,
            updated_at_unix: now,
        };
        self.inbounds.insert(inbound.tag.clone(), inbound.clone());
        Ok(inbound)
    }

    fn update_inbound(
        &mut self,
        tag: &str,
        request: UpdateInboundRequest,
    ) -> Result<Inbound, SecurityError> {
        let inbound = self
            .inbounds
            .get_mut(tag)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "inbound does not exist",
            ))?;
        let mut candidate = inbound.clone();
        if let Some(port) = request.port {
            candidate.port = port;
        }
        if let Some(protocol) = request.protocol {
            candidate.protocol = protocol;
        }
        if let Some(network) = request.network {
            candidate.network = network;
        }
        if let Some(tls_enabled) = request.tls_enabled {
            candidate.tls_enabled = tls_enabled;
        }
        if request.node_id.is_some() {
            candidate.node_id = request.node_id;
        }
        if request.cluster_id.is_some() {
            candidate.cluster_id = request.cluster_id;
        }
        validate_inbound_protocol_mode(
            &candidate.protocol,
            candidate.network,
            candidate.tls_enabled,
        )?;
        candidate.updated_at_unix = now_unix();
        *inbound = candidate;
        Ok(inbound.clone())
    }

    fn delete_inbound(&mut self, tag: &str) -> Result<(), SecurityError> {
        self.inbounds
            .remove(tag)
            .map(|_| ())
            .ok_or(SecurityError::InvalidSecuritySettings(
                "inbound does not exist",
            ))
    }

    fn list_hosts(&self) -> Vec<Host> {
        let mut items: Vec<_> = self.hosts.values().cloned().collect();
        items.sort_by(|left, right| left.id.cmp(&right.id));
        items
    }

    fn create_host(&mut self, request: CreateHostRequest) -> Result<Host, SecurityError> {
        let id = generate_resource_id();
        let now = now_unix();
        let host = Host {
            id: id.clone(),
            remark: request.remark,
            address: request.address,
            port: request.port,
            path: request.path,
            sni: request.sni,
            security: request.security,
            behind_cdn: request.behind_cdn,
            node_id: request.node_id,
            cluster_id: request.cluster_id,
            created_at_unix: now,
            updated_at_unix: now,
        };
        self.hosts.insert(id, host.clone());
        Ok(host)
    }

    fn update_host(
        &mut self,
        host_id: &str,
        request: UpdateHostRequest,
    ) -> Result<Host, SecurityError> {
        let host = self
            .hosts
            .get_mut(host_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "host does not exist",
            ))?;
        if let Some(remark) = request.remark {
            host.remark = remark;
        }
        if let Some(address) = request.address {
            host.address = address;
        }
        if let Some(port) = request.port {
            host.port = port;
        }
        if request.path.is_some() {
            host.path = request.path;
        }
        if request.sni.is_some() {
            host.sni = request.sni;
        }
        if let Some(security) = request.security {
            host.security = security;
        }
        if let Some(behind_cdn) = request.behind_cdn {
            host.behind_cdn = behind_cdn;
        }
        if request.node_id.is_some() {
            host.node_id = request.node_id;
        }
        if request.cluster_id.is_some() {
            host.cluster_id = request.cluster_id;
        }
        host.updated_at_unix = now_unix();
        Ok(host.clone())
    }

    fn delete_host(&mut self, host_id: &str) -> Result<(), SecurityError> {
        self.hosts
            .remove(host_id)
            .map(|_| ())
            .ok_or(SecurityError::InvalidSecuritySettings(
                "host does not exist",
            ))
    }

    fn list_proxy_profiles(&self) -> Vec<ProxyProfile> {
        let mut items: Vec<_> = self.proxy_profiles.values().cloned().collect();
        items.sort_by(|left, right| left.id.cmp(&right.id));
        items
    }

    fn create_proxy_profile(
        &mut self,
        request: CreateProxyProfileRequest,
    ) -> Result<ProxyProfile, SecurityError> {
        let id = generate_resource_id();
        let now = now_unix();
        let profile = ProxyProfile {
            id: id.clone(),
            name: request.name,
            proxy_type: request.proxy_type,
            settings_json: request.settings_json,
            excluded_inbound_tags: request.excluded_inbound_tags,
            created_at_unix: now,
            updated_at_unix: now,
        };
        self.proxy_profiles.insert(id, profile.clone());
        Ok(profile)
    }

    fn update_proxy_profile(
        &mut self,
        profile_id: &str,
        request: UpdateProxyProfileRequest,
    ) -> Result<ProxyProfile, SecurityError> {
        let profile = self.proxy_profiles.get_mut(profile_id).ok_or(
            SecurityError::InvalidSecuritySettings("proxy profile does not exist"),
        )?;
        if let Some(name) = request.name {
            profile.name = name;
        }
        if let Some(settings_json) = request.settings_json {
            profile.settings_json = settings_json;
        }
        if let Some(excluded_inbound_tags) = request.excluded_inbound_tags {
            profile.excluded_inbound_tags = excluded_inbound_tags;
        }
        profile.updated_at_unix = now_unix();
        Ok(profile.clone())
    }

    fn delete_proxy_profile(&mut self, profile_id: &str) -> Result<(), SecurityError> {
        self.proxy_profiles.remove(profile_id).map(|_| ()).ok_or(
            SecurityError::InvalidSecuritySettings("proxy profile does not exist"),
        )
    }

    fn user_config_preview(&self, user: &User) -> Result<UserConfigPreview, SecurityError> {
        let mut proxy_profiles = Vec::new();
        let mut profile_excluded = Vec::new();
        for profile_id in &user.proxy_profile_ids {
            let profile = self.proxy_profiles.get(profile_id).ok_or(
                SecurityError::InvalidSecuritySettings("user references unknown proxy profile"),
            )?;
            profile_excluded.extend(profile.excluded_inbound_tags.iter().cloned());
            proxy_profiles.push(UserConfigProxyProfile {
                id: profile.id.clone(),
                name: profile.name.clone(),
                proxy_type: format!("{:?}", profile.proxy_type).to_ascii_lowercase(),
                excluded_inbound_tags: profile.excluded_inbound_tags.clone(),
                settings_json: profile.settings_json.clone(),
            });
        }

        let mut available_inbounds: Vec<String> = self
            .inbounds
            .values()
            .filter(|inbound| {
                !user
                    .excluded_inbound_tags
                    .iter()
                    .any(|tag| tag == &inbound.tag)
                    && !profile_excluded.iter().any(|tag| tag == &inbound.tag)
            })
            .map(|inbound| inbound.tag.clone())
            .collect();
        available_inbounds.sort();

        let mut hosts: Vec<UserConfigHost> = self
            .hosts
            .values()
            .cloned()
            .map(|host| UserConfigHost {
                id: host.id,
                remark: host.remark,
                address: host.address,
                port: host.port,
                path: host.path,
                sni: host.sni,
                security: format!("{:?}", host.security).to_ascii_lowercase(),
            })
            .collect();
        hosts.sort_by(|left, right| left.id.cmp(&right.id));

        Ok(UserConfigPreview {
            username: user.username.clone(),
            status: user.status,
            proxy_profiles,
            available_inbounds,
            excluded_inbound_tags: user.excluded_inbound_tags.clone(),
            hosts,
        })
    }

    fn generated_user_config(&self, user: &User) -> Result<GeneratedUserConfig, SecurityError> {
        let preview = self.user_config_preview(user)?;
        let inbounds = preview
            .available_inbounds
            .iter()
            .filter_map(|tag| self.inbounds.get(tag).cloned())
            .collect();
        let hosts = preview
            .hosts
            .into_iter()
            .map(|host| GeneratedHost {
                node_id: self
                    .hosts
                    .get(&host.id)
                    .and_then(|source| source.node_id.clone()),
                cluster_id: self
                    .hosts
                    .get(&host.id)
                    .and_then(|source| source.cluster_id.clone()),
                behind_cdn: self
                    .hosts
                    .get(&host.id)
                    .is_some_and(|source| source.behind_cdn),
                id: host.id,
                remark: host.remark,
                address: host.address,
                port: host.port,
                path: host.path,
                sni: host.sni,
                security: host.security,
                // Filled later at the AppState level; the Reality material store is
                // not reachable from here.
                reality_public_key: None,
                reality_short_id: None,
            })
            .collect();
        let proxy_profiles = preview
            .proxy_profiles
            .into_iter()
            .map(|profile| GeneratedProxyProfile {
                id: profile.id,
                name: profile.name,
                proxy_type: profile.proxy_type,
                settings_json: profile.settings_json,
            })
            .map(|profile| {
                generated_runtime_proxy_profile(profile, &user.username, &user.subscription_token)
            })
            .collect();

        Ok(GeneratedUserConfig {
            username: user.username.clone(),
            status: user.status,
            data_limit_bytes: user.data_limit_bytes,
            expire_at_unix: user.expire_at_unix,
            subscription_token: user.subscription_token.clone(),
            proxy_profiles,
            inbounds,
            hosts,
            access_policy: None,
        })
    }

    fn generated_subscription_client_config(
        &self,
        client: &SubscriptionCatalogClient,
    ) -> Result<GeneratedUserConfig, SecurityError> {
        self.generated_subscription_client_config_with_device(client, None, &[])
    }

    fn generated_subscription_client_config_for_runtime(
        &self,
        client: &SubscriptionCatalogClient,
        subscription_devices: &[SubscriptionClientDevice],
    ) -> Result<GeneratedUserConfig, SecurityError> {
        self.generated_subscription_client_config_with_device(client, None, subscription_devices)
    }

    fn generated_subscription_client_device_config(
        &self,
        client: &SubscriptionCatalogClient,
        device: &SubscriptionClientDevice,
    ) -> Result<GeneratedUserConfig, SecurityError> {
        self.generated_subscription_client_config_with_device(
            client,
            Some(device),
            std::slice::from_ref(device),
        )
    }

    fn generated_subscription_client_configs_for_runtime(
        &self,
        client: &SubscriptionCatalogClient,
        subscription_devices: &[SubscriptionClientDevice],
    ) -> Vec<GeneratedUserConfig> {
        if client.max_simultaneous_devices.is_none() {
            return self
                .generated_subscription_client_config_for_runtime(client, subscription_devices)
                .into_iter()
                .collect();
        }
        let mut devices = subscription_devices
            .iter()
            .filter(|device| {
                device.client_id == client.id && device.status == SubscriptionDeviceStatus::Active
            })
            .collect::<Vec<_>>();
        devices.sort_by(|left, right| left.id.cmp(&right.id));
        devices
            .into_iter()
            .filter_map(|device| {
                self.generated_subscription_client_device_config(client, device)
                    .ok()
            })
            .collect()
    }

    fn generated_subscription_client_config_with_device(
        &self,
        client: &SubscriptionCatalogClient,
        selected_device: Option<&SubscriptionClientDevice>,
        subscription_devices: &[SubscriptionClientDevice],
    ) -> Result<GeneratedUserConfig, SecurityError> {
        let mut proxy_profiles: Vec<_> = self
            .proxy_profiles
            .values()
            .filter(|&profile| subscription_proxy_profile_allowed(profile, &client.access_policy))
            .cloned()
            .flat_map(|profile| {
                if let Some(device) = selected_device {
                    generated_subscription_proxy_profile_for_device(profile, client, device)
                        .into_iter()
                        .collect()
                } else {
                    generated_subscription_proxy_profiles(profile, client, subscription_devices)
                }
            })
            .collect();
        proxy_profiles
            .sort_by(|left, right| left.name.cmp(&right.name).then(left.id.cmp(&right.id)));
        let mut inbounds: Vec<_> = self
            .inbounds
            .values()
            .filter(|inbound| subscription_inbound_allowed(inbound, &client.access_policy))
            .cloned()
            .collect();
        inbounds.sort_by(|left, right| left.tag.cmp(&right.tag));
        let mut hosts: Vec<_> = self
            .hosts
            .values()
            .filter(|&host| subscription_host_allowed(host, &client.access_policy))
            .cloned()
            .map(|host| GeneratedHost {
                id: host.id,
                remark: host.remark,
                address: host.address,
                port: host.port,
                path: host.path,
                sni: host.sni,
                security: format!("{:?}", host.security).to_ascii_lowercase(),
                behind_cdn: host.behind_cdn,
                reality_public_key: None,
                reality_short_id: None,
                node_id: host.node_id,
                cluster_id: host.cluster_id,
            })
            .collect();
        hosts.sort_by(|left, right| left.id.cmp(&right.id));

        Ok(GeneratedUserConfig {
            username: selected_device.map_or_else(
                || subscription_client_runtime_username(client),
                |device| subscription_client_device_runtime_username(client, device),
            ),
            status: subscription_client_status_to_user_status(client.status),
            data_limit_bytes: client.data_limit_bytes,
            expire_at_unix: client.expire_at_unix,
            subscription_token: client.subscription_token.clone(),
            proxy_profiles,
            inbounds,
            hosts,
            access_policy: Some(GeneratedSubscriptionAccessPolicy {
                allow_all_nodes: client.access_policy.allow_all_nodes,
                node_ids: client.access_policy.node_ids.clone(),
                cluster_ids: client.access_policy.cluster_ids.clone(),
                allow_all_protocols: client.access_policy.allow_all_protocols,
                protocols: client.access_policy.protocols.clone(),
            }),
        })
    }

    fn generated_core_config(
        &self,
        users: Vec<User>,
        subscription_clients: Vec<SubscriptionCatalogClient>,
        subscription_devices: Vec<SubscriptionClientDevice>,
        nodes: Vec<Node>,
        clusters: Vec<GeneratedClusterConfig>,
        cluster_node_targets: Vec<GeneratedClusterNodeTarget>,
        node_route_assignments: Vec<NodeRouteAssignment>,
    ) -> GeneratedCoreConfigPreview {
        let mut generated_users = Vec::new();
        for user in users {
            if matches!(user.status, UserStatus::Disabled | UserStatus::Expired) {
                continue;
            }
            if let Ok(generated) = self.generated_user_config(&user) {
                generated_users.push(generated);
            }
        }
        for client in subscription_clients {
            if validate_subscription_client_public_state(&client).is_err() {
                continue;
            }
            generated_users.extend(
                self.generated_subscription_client_configs_for_runtime(
                    &client,
                    &subscription_devices,
                ),
            );
        }
        generated_users.sort_by(|left, right| left.username.cmp(&right.username));

        let mut inbounds: Vec<_> = self.inbounds.values().cloned().collect();
        inbounds.sort_by(|left, right| left.tag.cmp(&right.tag));
        let mut hosts: Vec<_> = self
            .hosts
            .values()
            .cloned()
            .map(|host| GeneratedHost {
                id: host.id,
                remark: host.remark,
                address: host.address,
                port: host.port,
                path: host.path,
                sni: host.sni,
                security: format!("{:?}", host.security).to_ascii_lowercase(),
                behind_cdn: host.behind_cdn,
                reality_public_key: None,
                reality_short_id: None,
                node_id: host.node_id,
                cluster_id: host.cluster_id,
            })
            .collect();
        hosts.sort_by(|left, right| left.id.cmp(&right.id));
        let mut nodes = nodes;
        nodes.sort_by(|left, right| left.name.cmp(&right.name).then(left.id.cmp(&right.id)));

        let revision = compute_generated_config_revision(
            &generated_users,
            &inbounds,
            &hosts,
            &nodes,
            &clusters,
            &cluster_node_targets,
            &node_route_assignments,
        );

        GeneratedCoreConfigPreview {
            generated_at_unix: now_unix(),
            revision,
            users: generated_users,
            inbounds,
            hosts,
            nodes,
            clusters,
            cluster_node_targets,
            node_route_assignments,
        }
    }

    fn render_subscription(
        &self,
        user: &User,
        format: SubscriptionFormat,
    ) -> Result<RenderedSubscription, SecurityError> {
        let generated = self.generated_user_config(user)?;
        let (content_type, body) = render_subscription_body(&generated, format)?;

        Ok(RenderedSubscription {
            username: generated.username.clone(),
            subject_type: "user".to_string(),
            plan_id: None,
            client_id: None,
            format,
            content_type,
            body,
            generated_config: generated,
        })
    }

    fn render_subscription_client(
        &self,
        client: &SubscriptionCatalogClient,
        device: Option<&SubscriptionClientDevice>,
        format: SubscriptionFormat,
    ) -> Result<RenderedSubscription, SecurityError> {
        let generated = if let Some(device) = device {
            self.generated_subscription_client_device_config(client, device)?
        } else {
            self.generated_subscription_client_config(client)?
        };
        let (content_type, body) = render_subscription_body(&generated, format)?;

        Ok(RenderedSubscription {
            username: generated.username.clone(),
            subject_type: "subscription_client".to_string(),
            plan_id: Some(client.plan_id.clone()),
            client_id: Some(client.id.clone()),
            format,
            content_type,
            body,
            generated_config: generated,
        })
    }

    fn subscription_client_access_preview(
        &self,
        client: &SubscriptionCatalogClient,
    ) -> SubscriptionClientAccessPreview {
        let mut allowed_inbounds = Vec::new();
        let mut denied_inbounds = Vec::new();
        let mut inbounds: Vec<_> = self.inbounds.values().cloned().collect();
        inbounds.sort_by(|left, right| left.tag.cmp(&right.tag));
        for inbound in inbounds {
            let allowed = subscription_inbound_allowed(&inbound, &client.access_policy);
            let item = SubscriptionAccessInboundPreview {
                tag: inbound.tag.clone(),
                protocol: inbound.protocol.clone(),
                port: inbound.port,
                node_id: inbound.node_id.clone(),
                cluster_id: inbound.cluster_id.clone(),
                reason: subscription_endpoint_reason(
                    allowed,
                    inbound.node_id.as_deref(),
                    inbound.cluster_id.as_deref(),
                    Some(inbound.protocol.as_str()),
                    &client.access_policy,
                ),
                inbound,
            };
            if allowed {
                allowed_inbounds.push(item);
            } else {
                denied_inbounds.push(item);
            }
        }

        let mut allowed_hosts = Vec::new();
        let mut denied_hosts = Vec::new();
        let mut hosts: Vec<_> = self.hosts.values().cloned().collect();
        hosts.sort_by(|left, right| left.id.cmp(&right.id));
        for host in hosts {
            let allowed = subscription_host_allowed(&host, &client.access_policy);
            let item = SubscriptionAccessHostPreview {
                id: host.id,
                remark: host.remark,
                address: host.address,
                port: host.port,
                node_id: host.node_id.clone(),
                cluster_id: host.cluster_id.clone(),
                reason: subscription_endpoint_reason(
                    allowed,
                    host.node_id.as_deref(),
                    host.cluster_id.as_deref(),
                    None,
                    &client.access_policy,
                ),
            };
            if allowed {
                allowed_hosts.push(item);
            } else {
                denied_hosts.push(item);
            }
        }

        let mut warnings = Vec::new();
        if validate_subscription_client_public_state(client).is_err() {
            warnings.push("client is not currently renderable because it is disabled, expired, revoked, or past expiration".to_string());
        }
        if allowed_inbounds.is_empty() {
            warnings.push("no allowed inbounds after applying access policy".to_string());
        }
        if allowed_hosts.is_empty() {
            warnings.push("no allowed hosts after applying access policy".to_string());
        }
        if !client.access_policy.allow_all_nodes
            && client.access_policy.node_ids.is_empty()
            && client.access_policy.cluster_ids.is_empty()
        {
            warnings
                .push("explicit access policy does not include any nodes or clusters".to_string());
        }
        if !client.access_policy.allow_all_protocols && client.access_policy.protocols.is_empty() {
            warnings.push("explicit access policy does not include any protocols".to_string());
        }
        let renderable = warnings.is_empty();

        SubscriptionClientAccessPreview {
            schema_version: SchemaId::SubscriptionClientAccessPreview.version(),
            client_id: client.id.clone(),
            plan_id: client.plan_id.clone(),
            access_policy: client.access_policy.clone(),
            renderable,
            allowed_inbounds,
            denied_inbounds,
            allowed_hosts,
            denied_hosts,
            warnings,
        }
    }
}

impl ClusterRuntime {
    fn new(config: &AppConfig) -> Result<Self, PersistedFileError> {
        let persisted = load_clusters(&config.clusters_path)?;
        Ok(Self {
            clusters: persisted
                .clusters
                .into_iter()
                .map(|cluster| (cluster.id.clone(), cluster))
                .collect(),
        })
    }

    fn list(&self) -> Vec<Cluster> {
        let mut items: Vec<_> = self.clusters.values().cloned().collect();
        items.sort_by(|left, right| left.name.cmp(&right.name).then(left.id.cmp(&right.id)));
        items
    }

    fn create(
        &mut self,
        request: CreateClusterRequest,
        known_node_ids: &HashSet<String>,
    ) -> Result<Cluster, SecurityError> {
        validate_cluster_name(&request.name)?;
        let id = generate_resource_id();
        let now = now_unix();
        let nodes = build_cluster_nodes(request.nodes)?;
        let edges = build_cluster_edges(request.edges)?;
        let routing_policy = request
            .routing_policy
            .unwrap_or_else(default_cluster_routing_policy);
        let failover_policy = request
            .failover_policy
            .unwrap_or_else(default_cluster_failover_policy);
        let revision = compute_cluster_revision(
            &request.name,
            &nodes,
            &edges,
            &routing_policy,
            &failover_policy,
        );
        let cluster = Cluster {
            id: id.clone(),
            name: request.name,
            description: request.description,
            status: request.status.unwrap_or(ClusterStatus::Draft),
            nodes,
            edges,
            routing_policy,
            failover_policy,
            revision,
            created_at_unix: now,
            updated_at_unix: now,
        };
        validate_cluster_graph(&cluster, known_node_ids)?;
        self.clusters.insert(id, cluster.clone());
        Ok(cluster)
    }

    fn update(
        &mut self,
        cluster_id: &str,
        request: UpdateClusterRequest,
        known_node_ids: &HashSet<String>,
    ) -> Result<Cluster, SecurityError> {
        let cluster =
            self.clusters
                .get_mut(cluster_id)
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "cluster does not exist",
                ))?;
        if let Some(name) = request.name {
            validate_cluster_name(&name)?;
            cluster.name = name;
        }
        if let Some(description) = request.description {
            cluster.description = Some(description);
        }
        if let Some(status) = request.status {
            cluster.status = status;
        }
        if let Some(nodes) = request.nodes {
            cluster.nodes = build_cluster_nodes(nodes)?;
        }
        if let Some(edges) = request.edges {
            cluster.edges = build_cluster_edges(edges)?;
        }
        if let Some(routing_policy) = request.routing_policy {
            cluster.routing_policy = routing_policy;
        }
        if let Some(failover_policy) = request.failover_policy {
            cluster.failover_policy = failover_policy;
        }
        validate_cluster_graph(cluster, known_node_ids)?;
        cluster.revision = compute_cluster_revision(
            &cluster.name,
            &cluster.nodes,
            &cluster.edges,
            &cluster.routing_policy,
            &cluster.failover_policy,
        );
        cluster.updated_at_unix = now_unix();
        Ok(cluster.clone())
    }

    fn delete(&mut self, cluster_id: &str) -> Result<(), SecurityError> {
        self.clusters
            .remove(cluster_id)
            .map(|_| ())
            .ok_or(SecurityError::InvalidSecuritySettings(
                "cluster does not exist",
            ))
    }

    fn validation_report(
        &self,
        cluster_id: &str,
        known_node_ids: &HashSet<String>,
    ) -> Result<ClusterValidationReport, SecurityError> {
        let cluster =
            self.clusters
                .get(cluster_id)
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "cluster does not exist",
                ))?;
        let (errors, warnings) = inspect_cluster_graph(cluster, known_node_ids);
        Ok(ClusterValidationReport {
            cluster_id: cluster.id.clone(),
            valid: errors.is_empty(),
            errors,
            warnings,
        })
    }

    fn preview(
        &self,
        cluster_id: &str,
        known_node_ids: &HashSet<String>,
    ) -> Result<ClusterPreview, SecurityError> {
        let cluster =
            self.clusters
                .get(cluster_id)
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "cluster does not exist",
                ))?;
        let report = self.validation_report(cluster_id, known_node_ids)?;
        if !report.valid {
            return Err(SecurityError::InvalidSecuritySettings(
                "cluster graph is invalid",
            ));
        }
        let paths = build_cluster_paths(cluster);
        Ok(ClusterPreview {
            cluster_id: cluster.id.clone(),
            revision: cluster.revision.clone(),
            path_count: paths.len(),
            paths,
            warnings: report.warnings,
        })
    }

    fn generated_cluster_configs(
        &self,
        known_node_ids: &HashSet<String>,
    ) -> Vec<GeneratedClusterConfig> {
        let mut clusters: Vec<_> = self
            .clusters
            .values()
            .filter(|cluster| cluster.status != ClusterStatus::Disabled)
            .filter(|cluster| inspect_cluster_graph(cluster, known_node_ids).0.is_empty())
            .map(|cluster| GeneratedClusterConfig {
                id: cluster.id.clone(),
                name: cluster.name.clone(),
                status: format!("{:?}", cluster.status).to_ascii_lowercase(),
                revision: cluster.revision.clone(),
                routing_policy_name: cluster.routing_policy.name.clone(),
                controlled_egress: cluster.routing_policy.controlled_egress,
                failover_enabled: cluster.failover_policy.enabled,
                paths: build_cluster_paths(cluster)
                    .into_iter()
                    .map(|path| GeneratedClusterPath {
                        hops: path
                            .hops
                            .into_iter()
                            .map(|hop| GeneratedClusterHop {
                                cluster_node_id: hop.cluster_node_id,
                                node_id: hop.node_id,
                                role: hop.role,
                            })
                            .collect(),
                    })
                    .collect(),
            })
            .collect();
        clusters.sort_by(|left, right| left.name.cmp(&right.name).then(left.id.cmp(&right.id)));
        clusters
    }

    fn generated_cluster_node_targets(
        &self,
        known_node_ids: &HashSet<String>,
    ) -> Vec<GeneratedClusterNodeTarget> {
        let mut targets = Vec::new();
        for cluster in self
            .clusters
            .values()
            .filter(|cluster| cluster.status != ClusterStatus::Disabled)
            .filter(|cluster| inspect_cluster_graph(cluster, known_node_ids).0.is_empty())
        {
            let mut upstream: HashMap<&str, Vec<String>> = HashMap::new();
            let mut downstream: HashMap<&str, Vec<String>> = HashMap::new();
            let mut edge_ids: HashMap<&str, Vec<String>> = HashMap::new();
            let by_cluster_node_id: HashMap<_, _> = cluster
                .nodes
                .iter()
                .map(|node| (node.id.as_str(), node))
                .collect();

            for edge in cluster.edges.iter().filter(|edge| edge.enabled) {
                let Some(from) = by_cluster_node_id.get(edge.from_cluster_node_id.as_str()) else {
                    continue;
                };
                let Some(to) = by_cluster_node_id.get(edge.to_cluster_node_id.as_str()) else {
                    continue;
                };
                downstream
                    .entry(from.id.as_str())
                    .or_default()
                    .push(to.node_id.clone());
                upstream
                    .entry(to.id.as_str())
                    .or_default()
                    .push(from.node_id.clone());
                edge_ids
                    .entry(from.id.as_str())
                    .or_default()
                    .push(edge.id.clone());
                edge_ids
                    .entry(to.id.as_str())
                    .or_default()
                    .push(edge.id.clone());
            }

            for node in &cluster.nodes {
                let mut upstream_node_ids = upstream.remove(node.id.as_str()).unwrap_or_default();
                upstream_node_ids.sort();
                upstream_node_ids.dedup();
                let mut downstream_node_ids =
                    downstream.remove(node.id.as_str()).unwrap_or_default();
                downstream_node_ids.sort();
                downstream_node_ids.dedup();
                let mut route_edge_ids = edge_ids.remove(node.id.as_str()).unwrap_or_default();
                route_edge_ids.sort();
                route_edge_ids.dedup();
                targets.push(GeneratedClusterNodeTarget {
                    node_id: node.node_id.clone(),
                    cluster_id: cluster.id.clone(),
                    cluster_name: cluster.name.clone(),
                    cluster_revision: cluster.revision.clone(),
                    cluster_node_id: node.id.clone(),
                    role: node.role,
                    upstream_node_ids,
                    downstream_node_ids,
                    route_edge_ids,
                });
            }
        }
        targets.sort_by(|left, right| {
            left.node_id
                .cmp(&right.node_id)
                .then(left.cluster_name.cmp(&right.cluster_name))
                .then(left.cluster_node_id.cmp(&right.cluster_node_id))
        });
        targets
    }

    fn generated_node_route_assignments(
        &self,
        known_node_ids: &HashSet<String>,
        panel_nodes: &HashMap<String, Node>,
    ) -> Vec<NodeRouteAssignment> {
        let mut assignments = Vec::new();
        for cluster in self
            .clusters
            .values()
            .filter(|cluster| cluster.status != ClusterStatus::Disabled)
            .filter(|cluster| inspect_cluster_graph(cluster, known_node_ids).0.is_empty())
        {
            let by_cluster_node_id: HashMap<_, _> = cluster
                .nodes
                .iter()
                .map(|node| (node.id.as_str(), node))
                .collect();

            for (path_index, path) in build_cluster_paths(cluster).into_iter().enumerate() {
                for (hop_index, hop) in path.hops.iter().enumerate() {
                    let Some(cluster_node) = by_cluster_node_id.get(hop.cluster_node_id.as_str())
                    else {
                        continue;
                    };
                    let Some(local_node) = panel_nodes.get(cluster_node.node_id.as_str()) else {
                        continue;
                    };
                    let previous_peer = hop_index
                        .checked_sub(1)
                        .and_then(|index| path.hops.get(index))
                        .map(|previous| NodeRoutePeer {
                            direction: NodePeerDirection::Previous,
                            opaque_peer_id: opaque_cluster_peer_id(
                                &cluster.id,
                                &previous.cluster_node_id,
                            ),
                            address: None,
                            port: None,
                            public_key: None,
                            sni: None,
                            transport: None,
                            security: Some(cluster_hop_security(
                                &cluster.id,
                                &previous.cluster_node_id,
                                None,
                            )),
                            auth: Some(cluster_peer_auth(&cluster.id, &previous.cluster_node_id)),
                        });
                    let next_peer = path.hops.get(hop_index + 1).and_then(|next| {
                        panel_nodes
                            .get(next.node_id.as_str())
                            .map(|next_node| NodeRoutePeer {
                                direction: NodePeerDirection::Next,
                                opaque_peer_id: opaque_cluster_peer_id(
                                    &cluster.id,
                                    &next.cluster_node_id,
                                ),
                                address: Some(next_node.address.clone()),
                                port: Some(next_node.port),
                                public_key: None,
                                sni: None,
                                transport: Some("xray".to_string()),
                                security: Some(cluster_hop_security(
                                    &cluster.id,
                                    &cluster_node.id,
                                    Some(&next_node.address),
                                )),
                                auth: Some(cluster_peer_auth(&cluster.id, &next.cluster_node_id)),
                            })
                    });
                    let route_id = format!("{}-path-{}-hop-{}", cluster.id, path_index, hop_index);
                    assignments.push(NodeRouteAssignment {
                        node_id: local_node.id.clone(),
                        route_id: route_id.clone(),
                        cluster_id: cluster.id.clone(),
                        cluster_revision: cluster.revision.clone(),
                        role: cluster_node.role,
                        listen: Some(NodeRouteListen {
                            tag: route_id,
                            port: local_node.port,
                            protocol: "xray".to_string(),
                            network: "tcp".to_string(),
                            tls_enabled: false,
                            security: Some(cluster_hop_security(
                                &cluster.id,
                                &cluster_node.id,
                                Some(&local_node.address),
                            )),
                            auth: Some(cluster_listen_auth(&cluster.id, &cluster_node.id)),
                        }),
                        previous_peer,
                        next_peer,
                    });
                }
            }
        }
        assignments.sort_by(|left, right| {
            left.node_id
                .cmp(&right.node_id)
                .then(left.cluster_id.cmp(&right.cluster_id))
                .then(left.route_id.cmp(&right.route_id))
        });
        assignments
    }
}

impl NodeRuntime {
    fn new(config: &AppConfig) -> Result<Self, PersistedFileError> {
        let nodes = load_nodes(&config.nodes_path, &config.node_secrets_key_path)?
            .into_iter()
            .map(|node| (node.id.clone(), node))
            .collect();
        let sync_history = read_ndjson_lines::<NodeSyncHistoryEntry>(
            &config.node_sync_history_path,
            config.runtime_limits.max_node_sync_events_buffered,
        );
        let apply_results = read_ndjson_lines::<NodeApplyResultEntry>(
            &config.node_apply_results_path,
            config.runtime_limits.max_node_sync_events_buffered,
        );
        let bootstrap_history = read_ndjson_lines::<NodeBootstrapProbeEntry>(
            &config.node_bootstrap_history_path,
            config.runtime_limits.max_node_bootstrap_events_buffered,
        );
        Ok(Self {
            nodes,
            sync_history,
            apply_results,
            bootstrap_history,
        })
    }

    fn list(&self) -> Vec<Node> {
        let mut items: Vec<_> = self.nodes.values().cloned().collect();
        items.sort_by(|left, right| left.name.cmp(&right.name).then(left.id.cmp(&right.id)));
        items
    }

    fn list_with_effective_sync_status(&self, expected_revision: &str) -> Vec<Node> {
        let mut items = self.list();
        for node in &mut items {
            node.sync_status = effective_node_sync_status(node, expected_revision);
        }
        items
    }

    fn push_bootstrap_entry(&mut self, config: &AppConfig, entry: NodeBootstrapProbeEntry) {
        self.bootstrap_history.push(entry);
        let max_items = config.runtime_limits.max_node_bootstrap_events_buffered;
        if self.bootstrap_history.len() > max_items {
            let overflow = self.bootstrap_history.len().saturating_sub(max_items);
            self.bootstrap_history.drain(0..overflow);
        }
    }

    fn bootstrap_history_for(&self, node_id: &str, limit: usize) -> Vec<NodeBootstrapProbeEntry> {
        let mut items: Vec<_> = self
            .bootstrap_history
            .iter()
            .filter(|entry| entry.node_id == node_id)
            .cloned()
            .collect();
        if items.len() > limit {
            items = items.split_off(items.len() - limit);
        }
        items
    }

    fn find_by_auth_token(&self, auth_token: &str) -> Result<Node, SecurityError> {
        let auth_token_hash = hash_node_auth_token(auth_token);
        self.nodes
            .values()
            .find(|node| {
                node.enabled && constant_time_str_eq(&node.auth_token_hash, &auth_token_hash)
            })
            .cloned()
            .ok_or(SecurityError::Unauthorized)
    }

    fn find_id_by_auth_token(&self, auth_token: &str) -> Result<String, SecurityError> {
        Ok(self.find_by_auth_token(auth_token)?.id)
    }

    fn authenticate(
        &self,
        auth_token: &str,
        expected_revision: &str,
    ) -> Result<NodeAgentIdentity, SecurityError> {
        let node = self.find_by_auth_token(auth_token)?;
        let sync_status = effective_node_sync_status(&node, expected_revision);
        Ok(NodeAgentIdentity {
            node_id: node.id,
            name: node.name,
            status: node.status,
            sync_status,
            last_applied_revision: node.last_applied_revision,
        })
    }

    fn create(&mut self, request: CreateNodeRequest) -> Result<Node, SecurityError> {
        if self
            .nodes
            .values()
            .any(|node| node.name.eq_ignore_ascii_case(&request.name))
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "node name already exists",
            ));
        }

        let id = generate_resource_id();
        let now = now_unix();
        let node = Node {
            id: id.clone(),
            name: request.name,
            address: request.address,
            port: request.port,
            api_port: request.api_port,
            usage_coefficient: request.usage_coefficient,
            enabled: request.enabled,
            auth_token_hash: hash_node_auth_token(&generate_token()),
            auth_token_issued_at_unix: None,
            local_api_token_configured: request
                .local_api_token
                .as_deref()
                .is_some_and(|value| !value.trim().is_empty()),
            local_api_token: normalize_optional_secret(request.local_api_token),
            xray_version: None,
            node_version: None,
            status: NodeStatus::Unknown,
            sync_status: NodeSyncStatus::Unknown,
            provisioning_status: NodeProvisioningStatus::None,
            last_applied_revision: None,
            last_registered_at_unix: None,
            last_heartbeat_at_unix: None,
            last_agent_heartbeat_at_unix: None,
            last_metrics_at_unix: None,
            reported_memory_used_bytes: None,
            reported_memory_total_bytes: None,
            reported_disk_used_bytes: None,
            reported_disk_total_bytes: None,
            last_sync_at_unix: None,
            created_at_unix: now,
            updated_at_unix: now,
        };
        self.nodes.insert(id, node.clone());
        Ok(node)
    }

    fn update(&mut self, node_id: &str, request: UpdateNodeRequest) -> Result<Node, SecurityError> {
        if let Some(name) = request.name.as_deref()
            && self
                .nodes
                .iter()
                .any(|(id, node)| id != node_id && node.name.eq_ignore_ascii_case(name))
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "node name already exists",
            ));
        }

        let node = self
            .nodes
            .get_mut(node_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "node does not exist",
            ))?;
        if let Some(name) = request.name {
            node.name = name;
        }
        if let Some(address) = request.address {
            node.address = address;
        }
        if let Some(port) = request.port {
            node.port = port;
        }
        if let Some(api_port) = request.api_port {
            node.api_port = api_port;
        }
        if let Some(usage_coefficient) = request.usage_coefficient {
            node.usage_coefficient = usage_coefficient;
        }
        if let Some(enabled) = request.enabled {
            node.enabled = enabled;
        }
        if let Some(local_api_token) = request.local_api_token {
            node.local_api_token = normalize_optional_secret(Some(local_api_token));
            node.local_api_token_configured = node.local_api_token.is_some();
        }
        node.updated_at_unix = now_unix();
        Ok(node.clone())
    }

    fn delete(&mut self, node_id: &str) -> Result<(), SecurityError> {
        self.nodes
            .remove(node_id)
            .map(|_| ())
            .ok_or(SecurityError::InvalidSecuritySettings(
                "node does not exist",
            ))
    }

    fn record_heartbeat(
        &mut self,
        node_id: &str,
        request: NodeHeartbeatRequest,
    ) -> Result<Node, SecurityError> {
        let node = self
            .nodes
            .get_mut(node_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "node does not exist",
            ))?;
        node.xray_version = request.xray_version;
        node.node_version = request.node_version;
        node.status = request.status;
        let now = now_unix();
        node.last_registered_at_unix = Some(now);
        node.last_heartbeat_at_unix = Some(now);
        node.updated_at_unix = now;
        Ok(node.clone())
    }

    fn record_agent_heartbeat(
        &mut self,
        node_id: &str,
        request: NodeHeartbeatRequest,
    ) -> Result<Node, SecurityError> {
        let mut node = self.record_heartbeat(node_id, request)?;
        let now = node.last_heartbeat_at_unix.unwrap_or_else(now_unix);
        let persisted =
            self.nodes
                .get_mut(node_id)
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "node does not exist",
                ))?;
        persisted.last_agent_heartbeat_at_unix = Some(now);
        node.last_agent_heartbeat_at_unix = Some(now);
        Ok(node)
    }

    fn update_sync_status(
        &mut self,
        config: &AppConfig,
        node_id: &str,
        mut request: NodeSyncRequest,
        expected_revision: &str,
    ) -> Result<Node, SecurityError> {
        let node = self
            .nodes
            .get_mut(node_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "node does not exist",
            ))?;
        let mut sync_status = request.sync_status;
        if let Some(applied_revision) = request.applied_revision.as_deref()
            && applied_revision != expected_revision
        {
            sync_status = NodeSyncStatus::Drifted;
        }
        compact_node_sync_report(&mut request, config);
        let now = now_unix();
        node.sync_status = sync_status;
        node.last_applied_revision = request.applied_revision.clone();
        node.last_sync_at_unix = Some(now);
        node.updated_at_unix = now_unix();
        let lifecycle_state = request.apply_lifecycle_state.or_else(|| {
            infer_apply_lifecycle_from_sync_report(&request, sync_status, expected_revision)
        });
        let entry = NodeSyncHistoryEntry {
            node_id: node.id.clone(),
            sync_status,
            applied_revision: request.applied_revision,
            expected_revision: expected_revision.to_string(),
            detail: request.detail,
            apply_lifecycle_state: lifecycle_state,
            last_good_revision: request.last_good_revision,
            rollback_available: request.rollback_available,
            apply_stages: request.apply_stages,
            apply_issues: request.apply_issues,
            retry_state: request.retry_state,
            runtime_components: request.runtime_components,
            external_xray_validation: request.external_xray_validation,
            runtime_alerts: request.runtime_alerts,
            created_at_unix: now,
        };
        let node = node.clone();
        self.push_sync_history(config, entry);
        Ok(node)
    }

    fn request_apply(
        &mut self,
        config: &AppConfig,
        node_id: &str,
        revision: &str,
    ) -> Result<Node, SecurityError> {
        self.request_apply_with_detail(
            config,
            node_id,
            revision,
            "panel requested config apply".to_string(),
        )
    }

    fn request_apply_with_detail(
        &mut self,
        config: &AppConfig,
        node_id: &str,
        revision: &str,
        detail: String,
    ) -> Result<Node, SecurityError> {
        let node = self
            .nodes
            .get_mut(node_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "node does not exist",
            ))?;
        node.sync_status = NodeSyncStatus::Pending;
        node.updated_at_unix = now_unix();
        let entry = NodeSyncHistoryEntry {
            node_id: node.id.clone(),
            sync_status: NodeSyncStatus::Pending,
            applied_revision: node.last_applied_revision.clone(),
            expected_revision: revision.to_string(),
            detail: Some(truncate_node_report_field(&detail)),
            apply_lifecycle_state: Some(NodeApplyLifecycleState::Pending),
            last_good_revision: node.last_applied_revision.clone(),
            rollback_available: false,
            apply_stages: Vec::new(),
            apply_issues: Vec::new(),
            retry_state: None,
            runtime_components: Vec::new(),
            external_xray_validation: None,
            runtime_alerts: Vec::new(),
            created_at_unix: now_unix(),
        };
        let node = node.clone();
        self.push_sync_history(config, entry);
        Ok(node)
    }

    fn request_rollback(
        &mut self,
        config: &AppConfig,
        node_id: &str,
        target_revision: &str,
        detail: String,
    ) -> Result<Node, SecurityError> {
        let node = self
            .nodes
            .get_mut(node_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "node does not exist",
            ))?;
        node.sync_status = NodeSyncStatus::Pending;
        node.updated_at_unix = now_unix();
        let entry = NodeSyncHistoryEntry {
            node_id: node.id.clone(),
            sync_status: NodeSyncStatus::Pending,
            applied_revision: node.last_applied_revision.clone(),
            expected_revision: target_revision.to_string(),
            detail: Some(truncate_node_report_field(&detail)),
            apply_lifecycle_state: Some(NodeApplyLifecycleState::Pending),
            last_good_revision: Some(target_revision.to_string()),
            rollback_available: true,
            apply_stages: vec![NodeApplyStageView {
                stage: "rollback".to_string(),
                status: NodeApplyStageStatus::Warning,
                detail: "panel requested runtime rollback".to_string(),
            }],
            apply_issues: Vec::new(),
            retry_state: None,
            runtime_components: Vec::new(),
            external_xray_validation: None,
            runtime_alerts: Vec::new(),
            created_at_unix: now_unix(),
        };
        let node = node.clone();
        self.push_sync_history(config, entry);
        Ok(node)
    }

    fn rotate_auth_token(
        &mut self,
        node_id: &str,
    ) -> Result<RotateNodeAuthTokenResponse, SecurityError> {
        let node = self
            .nodes
            .get_mut(node_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "node does not exist",
            ))?;
        let auth_token = generate_token();
        let generated_at_unix = now_unix();
        node.auth_token_hash = hash_node_auth_token(&auth_token);
        node.auth_token_issued_at_unix = Some(generated_at_unix);
        node.updated_at_unix = generated_at_unix;
        Ok(RotateNodeAuthTokenResponse {
            node_id: node.id.clone(),
            auth_token,
            generated_at_unix,
        })
    }

    fn update_metrics(
        &mut self,
        node_id: &str,
        request: NodeMetricsRequest,
    ) -> Result<Node, SecurityError> {
        let node = self
            .nodes
            .get_mut(node_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "node does not exist",
            ))?;
        node.reported_memory_used_bytes = Some(request.memory_used_bytes);
        node.reported_memory_total_bytes = Some(request.memory_total_bytes);
        node.reported_disk_used_bytes = Some(request.disk_used_bytes);
        node.reported_disk_total_bytes = Some(request.disk_total_bytes);
        node.last_metrics_at_unix = Some(now_unix());
        node.updated_at_unix = now_unix();
        Ok(node.clone())
    }

    fn sync_history_for(&self, node_id: &str, limit: usize) -> Vec<NodeSyncHistoryEntry> {
        let mut items: Vec<_> = self
            .sync_history
            .iter()
            .filter(|entry| entry.node_id == node_id)
            .cloned()
            .collect();
        if items.len() > limit {
            items = items.split_off(items.len() - limit);
        }
        items
    }

    fn apply_results_for(&self, node_id: &str, limit: usize) -> Vec<NodeApplyResultEntry> {
        let mut items: Vec<_> = self
            .apply_results
            .iter()
            .filter(|entry| entry.node_id == node_id)
            .cloned()
            .collect();
        if items.len() > limit {
            items = items.split_off(items.len() - limit);
        }
        items
    }

    fn latest_last_good_revision(&self, node_id: &str) -> Option<String> {
        self.apply_results
            .iter()
            .rev()
            .find(|entry| entry.node_id == node_id && entry.last_good_revision.is_some())
            .and_then(|entry| entry.last_good_revision.clone())
            .or_else(|| {
                self.sync_history
                    .iter()
                    .rev()
                    .find(|entry| entry.node_id == node_id && entry.last_good_revision.is_some())
                    .and_then(|entry| entry.last_good_revision.clone())
            })
    }

    fn record_apply_result(
        &mut self,
        config: &AppConfig,
        node_id: &str,
        mut request: NodeApplyResultRequest,
        expected_revision: &str,
    ) -> Result<NodeApplyResultEntry, SecurityError> {
        if let Some(existing) = self.apply_results.iter().rev().find(|entry| {
            entry.node_id == node_id
                && entry.target_revision == request.target_revision
                && entry.attempt_id == request.attempt_id
        }) {
            return Ok(existing.clone());
        }

        let node = self
            .nodes
            .get_mut(node_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "node does not exist",
            ))?;
        compact_node_apply_result_report(&mut request, config);
        let now = now_unix();
        let sync_status = if request.status == NodeApplyResultStatus::Applied
            && request.applied_revision.as_deref() == Some(expected_revision)
        {
            NodeSyncStatus::Synced
        } else if matches!(
            request.status,
            NodeApplyResultStatus::Failed | NodeApplyResultStatus::RolledBack
        ) || request.applied_revision.as_deref() != Some(expected_revision)
        {
            NodeSyncStatus::Drifted
        } else {
            node.sync_status
        };
        node.sync_status = sync_status;
        node.last_applied_revision = request.applied_revision.clone();
        node.last_sync_at_unix = Some(now);
        node.updated_at_unix = now;
        let lifecycle_state = match request.status {
            NodeApplyResultStatus::Applied => NodeApplyLifecycleState::Applied,
            NodeApplyResultStatus::Failed => NodeApplyLifecycleState::Failed,
            NodeApplyResultStatus::RolledBack => NodeApplyLifecycleState::RolledBack,
            NodeApplyResultStatus::Skipped => NodeApplyLifecycleState::Unknown,
        };
        let detail = request.detail.clone();
        let entry = NodeApplyResultEntry {
            node_id: node.id.clone(),
            attempt_id: request.attempt_id,
            target_revision: request.target_revision.clone(),
            status: request.status,
            started_at_unix: request.started_at_unix,
            finished_at_unix: request.finished_at_unix,
            applied_revision: request.applied_revision.clone(),
            last_good_revision: request.last_good_revision.clone(),
            rollback_available: request.rollback_available,
            safe_to_restart: request.safe_to_restart,
            detail: request.detail,
            apply_stages: request.apply_stages.clone(),
            apply_issues: request.apply_issues.clone(),
            external_xray_validation: request.external_xray_validation.clone(),
            recorded_at_unix: now,
        };
        let sync_entry = NodeSyncHistoryEntry {
            node_id: node.id.clone(),
            sync_status,
            applied_revision: request.applied_revision,
            expected_revision: expected_revision.to_string(),
            detail,
            apply_lifecycle_state: Some(lifecycle_state),
            last_good_revision: request.last_good_revision,
            rollback_available: request.rollback_available,
            apply_stages: request.apply_stages,
            apply_issues: request.apply_issues,
            retry_state: None,
            runtime_components: request.runtime_components,
            external_xray_validation: request.external_xray_validation,
            runtime_alerts: Vec::new(),
            created_at_unix: now,
        };
        self.push_apply_result(config, entry.clone());
        self.push_sync_history(config, sync_entry);
        Ok(entry)
    }

    fn push_sync_history(&mut self, config: &AppConfig, entry: NodeSyncHistoryEntry) {
        self.sync_history.push(entry.clone());
        if self.sync_history.len() > config.runtime_limits.max_node_sync_events_buffered {
            let drain =
                self.sync_history.len() - config.runtime_limits.max_node_sync_events_buffered;
            self.sync_history.drain(0..drain);
        }
        let _ = append_ndjson_line(&config.node_sync_history_path, &entry);
    }

    fn push_apply_result(&mut self, config: &AppConfig, entry: NodeApplyResultEntry) {
        self.apply_results.push(entry.clone());
        if self.apply_results.len() > config.runtime_limits.max_node_sync_events_buffered {
            let drain =
                self.apply_results.len() - config.runtime_limits.max_node_sync_events_buffered;
            self.apply_results.drain(0..drain);
        }
        let _ = append_ndjson_line(&config.node_apply_results_path, &entry);
    }
}

impl ProvisioningRuntime {
    fn new(config: &AppConfig) -> Result<Self, PersistedFileError> {
        let persisted = load_node_provisioning_tasks(&config.node_provisioning_tasks_path)?;
        let tasks = persisted
            .tasks
            .into_iter()
            .map(|task| (task.task_id.clone(), task))
            .collect();
        let executors = persisted
            .executors
            .into_iter()
            .map(|executor| (executor.executor_id.clone(), executor))
            .collect();
        let mut executor_submissions = persisted.executor_submissions;
        let max_submissions = config
            .runtime_limits
            .max_node_provisioning_events_buffered
            .max(1);
        if executor_submissions.len() > max_submissions {
            let overflow = executor_submissions.len().saturating_sub(max_submissions);
            executor_submissions.drain(0..overflow);
        }
        let events = read_ndjson_lines::<NodeProvisioningEvent>(
            &config.node_provisioning_events_path,
            config.runtime_limits.max_node_provisioning_events_buffered,
        );
        let mut runtime = Self {
            tasks,
            events,
            executors,
            executor_submissions,
        };
        runtime.compact_tasks(config.runtime_limits.max_node_provisioning_events_buffered);
        Ok(runtime)
    }

    fn compact_tasks(&mut self, max_tasks: usize) {
        let max_tasks = max_tasks.max(1);
        if self.tasks.len() <= max_tasks {
            return;
        }
        let mut candidates = self
            .tasks
            .values()
            .map(|task| {
                let active_rank = if node_provisioning_task_is_active(task) {
                    1
                } else {
                    0
                };
                (active_rank, task.updated_at_unix, task.task_id.clone())
            })
            .collect::<Vec<_>>();
        candidates.sort();
        let remove_count = self.tasks.len().saturating_sub(max_tasks);
        for (_, _, task_id) in candidates.into_iter().take(remove_count) {
            self.tasks.remove(&task_id);
        }
    }

    fn executor_submissions(
        &self,
        query: NodeProvisioningExecutorSubmissionsQuery,
        default_limit: usize,
    ) -> Vec<NodeProvisioningExecutorSubmissionEntry> {
        let mut items: Vec<_> = self
            .executor_submissions
            .iter()
            .filter(|entry| {
                query
                    .executor_id
                    .as_ref()
                    .is_none_or(|executor_id| entry.executor_id.contains(executor_id))
            })
            .filter(|entry| {
                query
                    .node_id
                    .as_ref()
                    .is_none_or(|node_id| entry.node_id == *node_id)
            })
            .filter(|entry| {
                query
                    .task_id
                    .as_ref()
                    .is_none_or(|task_id| entry.task_id == *task_id)
            })
            .filter(|entry| query.status.is_none_or(|status| entry.status == status))
            .cloned()
            .collect();
        items.sort_by_key(|item| std::cmp::Reverse(item.created_at_unix));
        let limit = resolve_limit(query.limit, default_limit);
        items.truncate(limit);
        items
    }

    fn push_executor_submission(
        &mut self,
        config: &AppConfig,
        entry: NodeProvisioningExecutorSubmissionEntry,
    ) {
        if let Some(executor) = self.executors.get_mut(&entry.executor_id) {
            match entry.status {
                NodeProvisioningExecutorSubmissionStatus::Accepted => {
                    executor.accepted_result_count =
                        executor.accepted_result_count.saturating_add(1);
                }
                NodeProvisioningExecutorSubmissionStatus::Rejected => {
                    executor.rejected_result_count =
                        executor.rejected_result_count.saturating_add(1);
                }
            }
        }
        self.executor_submissions.push(entry);
        let max_items = config
            .runtime_limits
            .max_node_provisioning_events_buffered
            .max(1);
        if self.executor_submissions.len() > max_items {
            let overflow = self.executor_submissions.len().saturating_sub(max_items);
            self.executor_submissions.drain(0..overflow);
        }
    }

    fn tasks_for_node(&self, node_id: &str) -> Vec<NodeProvisioningTask> {
        let mut items: Vec<_> = self
            .tasks
            .values()
            .filter(|task| task.node_id == node_id)
            .cloned()
            .collect();
        items.sort_by_key(|item| std::cmp::Reverse(item.created_at_unix));
        items
    }

    fn has_fresh_active_task_for_node(&self, node_id: &str, now: u64) -> bool {
        self.tasks.values().any(|task| {
            task.node_id == node_id
                && node_provisioning_task_is_active(task)
                && !node_provisioning_task_is_stale(task, now)
        })
    }

    fn events_for_node(
        &self,
        node_id: &str,
        query: NodeProvisioningEventsQuery,
        default_limit: usize,
    ) -> Vec<NodeProvisioningEvent> {
        let mut items: Vec<_> = self
            .events
            .iter()
            .filter(|event| event.node_id == node_id)
            .filter(|event| {
                query
                    .task_id
                    .as_deref()
                    .is_none_or(|task_id| event.task_id == task_id)
            })
            .filter(|event| {
                query
                    .kind
                    .as_deref()
                    .is_none_or(|kind| event.kind.eq_ignore_ascii_case(kind))
            })
            .cloned()
            .collect();
        let limit = resolve_limit(query.limit, default_limit);
        if items.len() > limit {
            items = items.split_off(items.len() - limit);
        }
        items
    }

    fn push_event(
        &mut self,
        config: &AppConfig,
        event: NodeProvisioningEvent,
    ) -> Result<(), SecurityError> {
        append_ndjson_line(&config.node_provisioning_events_path, &event)?;
        self.events.push(event);
        let max_items = config.runtime_limits.max_node_provisioning_events_buffered;
        if self.events.len() > max_items {
            let overflow = self.events.len().saturating_sub(max_items);
            self.events.drain(0..overflow);
        }
        Ok(())
    }

    fn record_handoff(
        &mut self,
        config: &AppConfig,
        node_id: &str,
        task_id: &str,
        request: ReportNodeProvisioningHandoffRequest,
    ) -> Result<NodeProvisioningTask, SecurityError> {
        let now = now_unix();
        let task = self
            .tasks
            .get_mut(task_id)
            .filter(|task| task.node_id == node_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "provisioning task does not exist",
            ))?;
        if !node_provisioning_task_is_active(task) {
            return Err(SecurityError::InvalidSecuritySettings(
                "only active provisioning tasks accept handoff reports",
            ));
        }
        if request.kind == NodeProvisioningHandoffKind::NodeEnvWritten
            && request.status == NodeProvisioningHandoffStatus::Succeeded
            && !node_env_attestation_is_valid(request.node_env_attestation.as_ref())
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "successful node_env_written handoff requires valid node env attestation",
            ));
        }
        if request.kind == NodeProvisioningHandoffKind::ServiceStarted
            && request.status == NodeProvisioningHandoffStatus::Succeeded
            && !service_started_attestation_is_valid(
                request.service_started_attestation.as_ref(),
                task.request_context.sidecar_install.install_wireguard,
            )
        {
            return Err(SecurityError::InvalidSecuritySettings(
                "successful service_started handoff requires valid service attestation",
            ));
        }
        let record = NodeProvisioningHandoffRecord {
            kind: request.kind,
            status: request.status,
            detail: sanitize_node_provisioning_freeform_detail(&request.detail),
            created_at_unix: now,
        };
        task.updated_at_unix = now;
        task.handoff.retain(|item| item.kind != record.kind);
        task.handoff.push(record.clone());
        let cloned = task.clone();
        self.push_event(
            config,
            NodeProvisioningEvent {
                task_id: task_id.to_string(),
                node_id: node_id.to_string(),
                kind: format!("handoff_{}", handoff_kind_label(record.kind)),
                detail: format!("{}: {}", handoff_status_label(record.status), record.detail),
                created_at_unix: now,
            },
        )?;
        Ok(cloned)
    }

    fn confirm_agent_returned(
        &mut self,
        config: &AppConfig,
        node: &Node,
    ) -> Result<bool, SecurityError> {
        let now = now_unix();
        let latest_active_task_id = self.latest_fresh_active_ssh_task_id(&node.id, now);
        let Some(task_id) = latest_active_task_id else {
            return Ok(false);
        };
        let already_confirmed = self.tasks.get(&task_id).is_some_and(|task| {
            task.handoff.iter().any(|record| {
                record.kind == NodeProvisioningHandoffKind::AgentReturned
                    && record.status == NodeProvisioningHandoffStatus::Succeeded
            })
        });
        if already_confirmed {
            return Ok(false);
        }
        self.record_handoff(
            config,
            &node.id,
            &task_id,
            ReportNodeProvisioningHandoffRequest {
                kind: NodeProvisioningHandoffKind::AgentReturned,
                status: NodeProvisioningHandoffStatus::Succeeded,
                detail: format!(
                    "authenticated node-agent heartbeat observed after token issuance at {}",
                    node.last_agent_heartbeat_at_unix.unwrap_or(now)
                ),
                node_env_attestation: None,
                service_started_attestation: None,
            },
        )?;
        Ok(true)
    }

    fn confirm_token_issued(
        &mut self,
        config: &AppConfig,
        rotated: &RotateNodeAuthTokenResponse,
    ) -> Result<bool, SecurityError> {
        let now = now_unix();
        let Some(task_id) = self.latest_fresh_active_ssh_task_id(&rotated.node_id, now) else {
            return Ok(false);
        };
        let already_confirmed = self.tasks.get(&task_id).is_some_and(|task| {
            task.handoff.iter().any(|record| {
                record.kind == NodeProvisioningHandoffKind::TokenIssued
                    && record.status == NodeProvisioningHandoffStatus::Succeeded
                    && record.created_at_unix >= rotated.generated_at_unix
            })
        });
        if already_confirmed {
            return Ok(false);
        }
        self.record_handoff(
            config,
            &rotated.node_id,
            &task_id,
            ReportNodeProvisioningHandoffRequest {
                kind: NodeProvisioningHandoffKind::TokenIssued,
                status: NodeProvisioningHandoffStatus::Succeeded,
                detail: format!(
                    "panel issued deployable node auth token at {}",
                    rotated.generated_at_unix
                ),
                node_env_attestation: None,
                service_started_attestation: None,
            },
        )?;
        Ok(true)
    }

    fn latest_fresh_active_ssh_task_id(&self, node_id: &str, now: u64) -> Option<String> {
        self.tasks
            .values()
            .filter(|task| task.node_id == node_id)
            .filter(|task| {
                matches!(
                    task.request_context.transport,
                    NodeProvisioningTransportKind::Ssh
                )
            })
            .filter(|task| node_provisioning_task_is_active(task))
            .filter(|task| !node_provisioning_task_is_stale(task, now))
            .max_by_key(|task| task.created_at_unix)
            .map(|task| task.task_id.clone())
    }

    fn start_task(
        &mut self,
        config: &AppConfig,
        node_id: &str,
        verify_after_finish: bool,
        request_context: NodeProvisioningRequestContext,
        executor_readiness: NodeProvisioningExecutorReadinessReport,
        parent_task_id: Option<String>,
        reason: String,
    ) -> Result<NodeProvisioningTask, SecurityError> {
        let now = now_unix();
        if self.has_fresh_active_task_for_node(node_id, now) {
            return Err(SecurityError::InvalidSecuritySettings(
                "node already has an active provisioning task",
            ));
        }
        let planned_steps = provisioning_step_templates(request_context.transport);
        let task = NodeProvisioningTask {
            task_id: generate_resource_id(),
            node_id: node_id.to_string(),
            parent_task_id,
            reason: Some(reason.clone()),
            status: NodeProvisioningTaskStatus::Running,
            created_at_unix: now,
            started_at_unix: Some(now),
            finished_at_unix: None,
            updated_at_unix: now,
            verify_after_finish,
            verified_ready: None,
            verify_probe_id: None,
            recommendations: Vec::new(),
            failures: Vec::new(),
            remediation: Vec::new(),
            request_context,
            executor_readiness,
            remote_prerequisites: Vec::new(),
            planned_steps,
            steps: Vec::new(),
            handoff: Vec::new(),
        };
        self.push_event(
            config,
            NodeProvisioningEvent {
                task_id: task.task_id.clone(),
                node_id: task.node_id.clone(),
                kind: "started".to_string(),
                detail: format!("node provisioning task started ({reason})"),
                created_at_unix: now,
            },
        )?;
        self.tasks.insert(task.task_id.clone(), task.clone());
        Ok(task)
    }

    fn push_step(
        &mut self,
        config: &AppConfig,
        node_id: &str,
        task_id: &str,
        mut request: UpdateNodeProvisioningStepRequest,
        required_ports: &[u16],
    ) -> Result<NodeProvisioningTask, SecurityError> {
        let now = now_unix();
        let task = self
            .tasks
            .get_mut(task_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "provisioning task does not exist",
            ))?;
        if task.node_id != node_id {
            return Err(SecurityError::InvalidSecuritySettings(
                "provisioning task does not belong to node",
            ));
        }
        validate_executor_step_report(&request)?;
        request.detail = sanitize_node_provisioning_freeform_detail(&request.detail);
        task.updated_at_unix = now;
        if matches!(request.status, NodeProvisioningStepStatus::Failed) {
            task.status = NodeProvisioningTaskStatus::Failed;
        } else if !matches!(task.status, NodeProvisioningTaskStatus::Failed) {
            task.status = NodeProvisioningTaskStatus::Running;
        }
        task.steps.push(NodeProvisioningStep {
            step: request.step,
            status: request.status,
            detail: request.detail.clone(),
            failure_category: request.failure_category,
            created_at_unix: now,
        });
        if matches!(request.step, NodeProvisioningStepKind::Preflight)
            && let Some(output) = request.ssh_preflight_output.take()
        {
            request.remote_prerequisites =
                parse_ssh_remote_preflight_output(&output, required_ports);
        }
        if matches!(request.step, NodeProvisioningStepKind::Preflight)
            && !request.remote_prerequisites.is_empty()
        {
            task.remote_prerequisites = compact_remote_prerequisites(request.remote_prerequisites);
            let prerequisite_failures = remote_prerequisite_failures(&task.remote_prerequisites);
            task.failures.extend(prerequisite_failures);
            task.remediation =
                build_node_provisioning_remediation(&task.failures, task.verified_ready);
        }
        if matches!(request.status, NodeProvisioningStepStatus::Failed) {
            let category = request
                .failure_category
                .unwrap_or(NodeProvisioningFailureCategory::Unknown);
            task.failures.push(NodeProvisioningFailure {
                step: request.step,
                category,
                detail: request.detail.clone(),
            });
            task.remediation =
                build_node_provisioning_remediation(&task.failures, task.verified_ready);
        }
        let cloned = task.clone();
        self.push_event(
            config,
            NodeProvisioningEvent {
                task_id: cloned.task_id.clone(),
                node_id: cloned.node_id.clone(),
                kind: "step".to_string(),
                detail: request.detail,
                created_at_unix: now,
            },
        )?;
        Ok(cloned)
    }

    fn touch_task(
        &mut self,
        config: &AppConfig,
        node_id: &str,
        task_id: &str,
        request: TouchNodeProvisioningTaskRequest,
    ) -> Result<NodeProvisioningTask, SecurityError> {
        let now = now_unix();
        let task = self
            .tasks
            .get_mut(task_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "provisioning task does not exist",
            ))?;
        if task.node_id != node_id {
            return Err(SecurityError::InvalidSecuritySettings(
                "provisioning task does not belong to node",
            ));
        }
        if !node_provisioning_task_is_active(task) {
            return Err(SecurityError::InvalidSecuritySettings(
                "only active provisioning tasks can be touched",
            ));
        }
        task.updated_at_unix = now;
        let cloned = task.clone();
        self.push_event(
            config,
            NodeProvisioningEvent {
                task_id: cloned.task_id.clone(),
                node_id: cloned.node_id.clone(),
                kind: "heartbeat".to_string(),
                detail: request
                    .detail
                    .unwrap_or_else(|| "executor heartbeat".to_string()),
                created_at_unix: now,
            },
        )?;
        Ok(cloned)
    }

    fn finish_task(
        &mut self,
        config: &AppConfig,
        node_id: &str,
        task_id: &str,
        request: FinishNodeProvisioningRequest,
        probe: Option<&NodeBootstrapProbeView>,
    ) -> Result<NodeProvisioningTask, SecurityError> {
        let now = now_unix();
        let task = self
            .tasks
            .get_mut(task_id)
            .ok_or(SecurityError::InvalidSecuritySettings(
                "provisioning task does not exist",
            ))?;
        if task.node_id != node_id {
            return Err(SecurityError::InvalidSecuritySettings(
                "provisioning task does not belong to node",
            ));
        }
        let mut status = request.status;
        let mut recommendations = Vec::new();
        let mut verify_probe_id = None;
        let mut verified_ready = None;
        if let Some(probe) = probe {
            verify_probe_id = Some(probe.probe_id.clone());
            verified_ready = Some(probe.ready);
            recommendations = probe.recommendations.clone();
            if probe.ready && matches!(status, NodeProvisioningTaskStatus::Completed) {
                status = NodeProvisioningTaskStatus::Verified;
            }
            if !probe.ready && matches!(status, NodeProvisioningTaskStatus::Verified) {
                status = NodeProvisioningTaskStatus::Completed;
            }
        }
        task.status = status;
        task.finished_at_unix = Some(now);
        task.updated_at_unix = now;
        task.verified_ready = verified_ready;
        task.verify_probe_id = verify_probe_id;
        task.recommendations = recommendations;
        if let Some(detail) = request.detail
            && !detail.is_empty()
        {
            task.steps.push(NodeProvisioningStep {
                step: NodeProvisioningStepKind::BootstrapVerify,
                status: match status {
                    NodeProvisioningTaskStatus::Failed => NodeProvisioningStepStatus::Failed,
                    _ => NodeProvisioningStepStatus::Succeeded,
                },
                detail: detail.clone(),
                failure_category: if matches!(status, NodeProvisioningTaskStatus::Failed) {
                    Some(NodeProvisioningFailureCategory::Unknown)
                } else {
                    None
                },
                created_at_unix: now,
            });
            if matches!(status, NodeProvisioningTaskStatus::Failed) {
                task.failures.push(NodeProvisioningFailure {
                    step: NodeProvisioningStepKind::BootstrapVerify,
                    category: NodeProvisioningFailureCategory::Unknown,
                    detail,
                });
            }
        }
        if probe.is_some() && verified_ready == Some(false) {
            task.failures.push(NodeProvisioningFailure {
                step: NodeProvisioningStepKind::BootstrapVerify,
                category: NodeProvisioningFailureCategory::BootstrapVerification,
                detail: "bootstrap verification did not reach a ready state".to_string(),
            });
        }
        task.remediation = build_node_provisioning_remediation(&task.failures, task.verified_ready);
        let cloned = task.clone();
        self.push_event(
            config,
            NodeProvisioningEvent {
                task_id: cloned.task_id.clone(),
                node_id: cloned.node_id.clone(),
                kind: "finished".to_string(),
                detail: format!(
                    "node provisioning task finished with status {:?}",
                    cloned.status
                )
                .to_ascii_lowercase(),
                created_at_unix: now,
            },
        )?;
        Ok(cloned)
    }
}

#[derive(Debug, Clone)]
struct LoginAttemptState {
    window_started_unix: u64,
    failed_attempts_in_window: usize,
    ban_level: usize,
}

#[derive(Debug, Clone)]
struct BanState {
    kind: BanKind,
    source: BanSource,
    reason: String,
    created_at_unix: u64,
    blocked_until_unix: u64,
    ban_level: usize,
}

#[derive(Debug, Clone)]
struct SessionState {
    username: String,
    client_ip: String,
    issued_at_unix: u64,
    expires_at_unix: u64,
}

#[derive(Debug, Clone)]
struct PendingTwoFactorChallenge {
    username: String,
    client_ip: String,
    earliest_second_code_at_unix: u64,
    expires_at_unix: u64,
}

impl SessionState {
    fn into_view(self, token: &str) -> SessionView {
        SessionView {
            session_id: session_public_id(token),
            username: self.username,
            issued_at_unix: self.issued_at_unix,
            expires_at_unix: self.expires_at_unix,
            client_ip: self.client_ip,
        }
    }
}

fn credentials_configured(config: &SecurityConfig) -> bool {
    config.bootstrap_admin.username.is_some()
        && (config.bootstrap_admin.password.is_some()
            || config.bootstrap_admin.password_hash.is_some())
}

fn verify_credentials(config: &SecurityConfig, username: &str, password: &str) -> bool {
    let Some(expected_username) = config.bootstrap_admin.username.as_deref() else {
        return false;
    };
    if expected_username != username {
        return false;
    }

    if let Some(hash) = config.bootstrap_admin.password_hash.as_deref() {
        let Ok(parsed_hash) = PasswordHash::new(hash) else {
            return false;
        };
        return Argon2::default()
            .verify_password(password.as_bytes(), &parsed_hash)
            .is_ok();
    }

    match config.bootstrap_admin.password.as_deref() {
        Some(expected_password) => constant_time_str_eq(expected_password, password),
        None => false,
    }
}

fn hash_password(password: &str) -> Option<String> {
    let salt = SaltString::encode_b64(&random::<[u8; 16]>()).ok()?;
    Argon2::default()
        .hash_password(password.as_bytes(), &salt)
        .ok()
        .map(|hash| hash.to_string())
}

fn generate_totp_secret_base32() -> String {
    BASE32_NOPAD.encode(&random::<[u8; 20]>())
}

fn verify_totp_code(secret_base32: &str, code: &str, now: u64) -> bool {
    if code.len() != 6 || !code.chars().all(|ch| ch.is_ascii_digit()) {
        return false;
    }
    let Ok(secret_bytes) = BASE32_NOPAD.decode(secret_base32.as_bytes()) else {
        return false;
    };

    [-1_i64, 0, 1].into_iter().any(|offset| {
        let step = ((now / 30) as i64).saturating_add(offset);
        if step < 0 {
            return false;
        }
        match totp_code_for_counter(&secret_bytes, step as u64) {
            Some(expected) => constant_time_str_eq(&expected, code),
            None => false,
        }
    })
}

fn totp_code_for_counter(secret_bytes: &[u8], counter: u64) -> Option<String> {
    let mut mac = <HmacSha1 as Mac>::new_from_slice(secret_bytes).ok()?;
    mac.update(&counter.to_be_bytes());
    let result = mac.finalize().into_bytes();
    let offset = (result[19] & 0x0f) as usize;
    let binary = ((u32::from(result[offset]) & 0x7f) << 24)
        | (u32::from(result[offset + 1]) << 16)
        | (u32::from(result[offset + 2]) << 8)
        | u32::from(result[offset + 3]);
    Some(format!("{:06}", binary % 1_000_000))
}

fn build_otpauth_url(username: &str, secret_base32: &str) -> String {
    let issuer = "Hydra Panel";
    let label = format!("{issuer}:{username}");
    format!(
        "otpauth://totp/{}?secret={}&issuer={}&algorithm=SHA1&digits=6&period=30",
        encode(&label),
        secret_base32,
        encode(issuer),
    )
}

fn compute_ban(app_config: &AppConfig, ban_level: usize, now: u64) -> (BanKind, u64) {
    if !app_config.security.smart_ban_enabled {
        return (
            BanKind::Temporary,
            now + app_config.security.block_for_seconds,
        );
    }

    match ban_level {
        1 => (
            BanKind::Temporary,
            now + app_config.security.block_for_seconds,
        ),
        2 => (
            BanKind::Temporary,
            now + (app_config.security.block_for_seconds * 10).max(300),
        ),
        3 => (
            BanKind::Temporary,
            now + (app_config.security.block_for_seconds * 25).max(900),
        ),
        _ => (BanKind::Permanent, u64::MAX),
    }
}

fn active_ban_view(client_ip: &str, ban: &BanState, now: u64) -> ActiveBanView {
    ActiveBanView {
        client_ip: client_ip.to_string(),
        ban_kind: ban.kind,
        source: ban.source,
        reason: ban.reason.clone(),
        created_at_unix: ban.created_at_unix,
        blocked_until_unix: ban.blocked_until_unix,
        ban_level: ban.ban_level,
        remaining_seconds: match ban.kind {
            BanKind::Permanent => None,
            BanKind::Temporary => Some(ban.blocked_until_unix.saturating_sub(now)),
        },
    }
}

fn normalize_manual_ban_reason(reason: Option<&str>) -> Result<String, SecurityError> {
    let reason = reason
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("manual operator ban");
    if reason.chars().count() > MANUAL_BAN_REASON_MAX_CHARS {
        return Err(SecurityError::InvalidSecuritySettings(
            "reason must contain at most 256 characters",
        ));
    }
    if reason.chars().any(|ch| ch.is_control()) {
        return Err(SecurityError::InvalidSecuritySettings(
            "reason must not contain control characters",
        ));
    }
    Ok(reason.to_string())
}

fn generate_token() -> String {
    let bytes: [u8; 32] = random();
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

/// Generates a Reality private key, equivalent to `xray x25519`.
///
/// The format matches the reference implementation: base64url without padding,
/// 43 characters. This is secret material: persisted encrypted only
/// (AES-256-GCM, as with route materials), never returned in API responses and
/// never written to logs or the audit trail.
///
/// Only the private half is returned. The public half is recomputed from it on
/// every read, which is what makes the two impossible to desynchronize;
/// returning both here would put a second copy into circulation for no reason.
fn generate_reality_private_key() -> String {
    let secret = x25519_dalek::StaticSecret::from(random::<[u8; 32]>());
    BASE64URL_NOPAD.encode(&secret.to_bytes())
}

/// The public key derived from the private one.
///
/// Lets us avoid storing the public half beside the private one: it is always
/// derivable, and a second copy is one more thing that can drift.
fn reality_public_key_from_private(private_key_b64: &str) -> Result<String, SecurityError> {
    let bytes = BASE64URL_NOPAD
        .decode(private_key_b64.as_bytes())
        .map_err(|_| {
            SecurityError::InvalidSecuritySettings("reality private key is not base64url")
        })?;
    let bytes: [u8; 32] = bytes.try_into().map_err(|_| {
        SecurityError::InvalidSecuritySettings("reality private key must be 32 bytes")
    })?;
    let secret = x25519_dalek::StaticSecret::from(bytes);
    Ok(BASE64URL_NOPAD.encode(x25519_dalek::PublicKey::from(&secret).as_bytes()))
}

/// A Reality short id: 1 to 8 bytes in hex, of even length.
///
/// Xray also accepts an empty string, but an empty short id removes client
/// distinction, so a full 8 bytes is always issued here.
fn generate_reality_short_id() -> String {
    random::<[u8; 8]>()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

