fn hash_node_auth_token(token: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(token.as_bytes());
    format!("{:x}", hasher.finalize())
}

fn constant_time_str_eq(left: &str, right: &str) -> bool {
    let left = left.as_bytes();
    let right = right.as_bytes();
    let max_len = left.len().max(right.len());
    let mut diff = left.len() ^ right.len();
    for index in 0..max_len {
        let left = left.get(index).copied().unwrap_or(0);
        let right = right.get(index).copied().unwrap_or(0);
        diff |= usize::from(left ^ right);
    }
    diff == 0
}

fn hash_subscription_device_fingerprint(
    fingerprint: &str,
    master_key: &[u8; 32],
) -> Result<String, SecurityError> {
    let mut mac = <HmacSha256 as Mac>::new_from_slice(master_key)
        .map_err(|_| SecurityError::PersistenceFailure)?;
    mac.update(b"subscription-device-fingerprint-v1:");
    mac.update(fingerprint.as_bytes());
    Ok(format!("{:x}", mac.finalize().into_bytes()))
}

