fn validate_subscription_device_enrollment_token(token: &str) -> Result<(), SecurityError> {
    if token.len() != 43
        || !BASE64URL_NOPAD
            .decode(token.as_bytes())
            .is_ok_and(|decoded| decoded.len() == 32)
    {
        return Err(SecurityError::Unauthorized);
    }
    Ok(())
}

fn validate_subscription_device_credential(credential: &str) -> Result<(), SecurityError> {
    if credential.len() != 43
        || !BASE64URL_NOPAD
            .decode(credential.as_bytes())
            .is_ok_and(|decoded| decoded.len() == 32)
    {
        return Err(SecurityError::Unauthorized);
    }
    Ok(())
}

fn subscription_device_enrollment_ttl(
    request: &CreateSubscriptionDeviceEnrollmentRequest,
) -> Result<u64, SecurityError> {
    let ttl = request
        .expires_in_seconds
        .unwrap_or(SUBSCRIPTION_ENROLLMENT_DEFAULT_TTL_SECONDS);
    if !(SUBSCRIPTION_ENROLLMENT_MIN_TTL_SECONDS..=SUBSCRIPTION_ENROLLMENT_MAX_TTL_SECONDS)
        .contains(&ttl)
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "device enrollment expires_in_seconds must be between 60 and 1800",
        ));
    }
    Ok(ttl)
}

fn subscription_enrollment_status(
    grant: &SubscriptionDeviceEnrollmentGrant,
    now: u64,
) -> SubscriptionDeviceEnrollmentStatus {
    if grant.status == SubscriptionDeviceEnrollmentStatus::Active && grant.expires_at_unix <= now {
        SubscriptionDeviceEnrollmentStatus::Expired
    } else {
        grant.status
    }
}

fn subscription_enrollment_view(
    grant: &SubscriptionDeviceEnrollmentGrant,
    now: u64,
) -> SubscriptionDeviceEnrollmentGrantView {
    SubscriptionDeviceEnrollmentGrantView {
        id: grant.id.clone(),
        client_id: grant.client_id.clone(),
        status: subscription_enrollment_status(grant, now),
        created_at_unix: grant.created_at_unix,
        expires_at_unix: grant.expires_at_unix,
        consumed_at_unix: grant.consumed_at_unix,
        consumed_device_id: grant.consumed_device_id.clone(),
        revoked_at_unix: grant.revoked_at_unix,
    }
}

fn wireguard_device_fingerprint(public_key: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(b"hydra-wireguard-device-v1\0");
    hasher.update(public_key.as_bytes());
    format!("wireguard-sha256:{:x}", hasher.finalize())
}

fn is_wireguard_public_key(value: &str) -> bool {
    value.len() == 44
        && value.ends_with('=')
        && value[..43].chars().all(|character| {
            character.is_ascii_alphanumeric() || character == '+' || character == '/'
        })
        && BASE64
            .decode(value.as_bytes())
            .is_ok_and(|decoded| decoded.len() == 32)
}

fn normalize_wireguard_allowed_ips(values: &[String]) -> Result<Vec<String>, SecurityError> {
    let mut unique = HashSet::new();
    let mut normalized = Vec::with_capacity(values.len());
    for value in values {
        let network = value.trim().parse::<IpNet>().map_err(|_| {
            SecurityError::InvalidSecuritySettings(
                "WireGuard AllowedIPs must contain valid CIDR host addresses",
            )
        })?;
        let is_host_route = match network {
            IpNet::V4(network) => network.prefix_len() == 32,
            IpNet::V6(network) => network.prefix_len() == 128,
        };
        let canonical = network.to_string();
        if !is_host_route || !unique.insert(canonical.clone()) {
            return Err(SecurityError::InvalidSecuritySettings(
                "WireGuard AllowedIPs must be unique /32 or /128 host routes",
            ));
        }
        normalized.push(canonical);
    }
    Ok(normalized)
}

