fn compute_generated_config_revision(
    users: &[GeneratedUserConfig],
    inbounds: &[Inbound],
    hosts: &[GeneratedHost],
    nodes: &[Node],
    clusters: &[GeneratedClusterConfig],
    cluster_node_targets: &[GeneratedClusterNodeTarget],
    node_route_assignments: &[NodeRouteAssignment],
) -> String {
    let node_config: Vec<_> = nodes
        .iter()
        .map(|node| {
            serde_json::json!({
                "id": node.id,
                "name": node.name,
                "address": node.address,
                "port": node.port,
                "api_port": node.api_port,
                "usage_coefficient": node.usage_coefficient,
                "enabled": node.enabled,
            })
        })
        .collect();
    let payload = serde_json::json!({
        "users": users,
        "inbounds": inbounds,
        "hosts": hosts,
        "nodes": node_config,
        "clusters": clusters,
        "cluster_node_targets": cluster_node_targets,
        "node_route_assignments": node_route_assignments,
    });
    let bytes = serde_json::to_vec(&payload).unwrap_or_default();
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    format!("{:x}", hasher.finalize())
}

fn node_agent_generated_config(
    mut generated: GeneratedCoreConfigPreview,
    node_id: &str,
) -> GeneratedCoreConfigPreview {
    let route_assignments = generated
        .node_route_assignments
        .iter()
        .filter(|assignment| assignment.node_id == node_id)
        .cloned()
        .collect::<Vec<_>>();
    let needs_user_config = route_assignments
        .iter()
        .any(|assignment| assignment.role == ClusterNodeRole::Entry);

    generated.nodes.retain(|node| node.id == node_id);
    generated.clusters.clear();
    generated.cluster_node_targets.clear();
    generated.node_route_assignments = route_assignments;
    if !needs_user_config && !generated.node_route_assignments.is_empty() {
        generated.users.clear();
        generated.inbounds.clear();
        generated.hosts.clear();
    } else {
        let allowed_cluster_ids = generated
            .node_route_assignments
            .iter()
            .filter(|assignment| assignment.role == ClusterNodeRole::Entry)
            .map(|assignment| assignment.cluster_id.clone())
            .collect::<HashSet<_>>();
        filter_generated_node_user_config(&mut generated, node_id, &allowed_cluster_ids);
    }
    generated
}

fn filter_generated_node_user_config(
    generated: &mut GeneratedCoreConfigPreview,
    node_id: &str,
    allowed_cluster_ids: &HashSet<String>,
) {
    generated.inbounds.retain(|inbound| {
        generated_endpoint_belongs_to_node(
            inbound.node_id.as_deref(),
            inbound.cluster_id.as_deref(),
            node_id,
            allowed_cluster_ids,
        )
    });
    generated.hosts.retain(|host| {
        generated_endpoint_belongs_to_node(
            host.node_id.as_deref(),
            host.cluster_id.as_deref(),
            node_id,
            allowed_cluster_ids,
        )
    });

    let inbound_tags = generated
        .inbounds
        .iter()
        .map(|inbound| inbound.tag.clone())
        .collect::<HashSet<_>>();
    let host_ids = generated
        .hosts
        .iter()
        .map(|host| host.id.clone())
        .collect::<HashSet<_>>();

    for user in &mut generated.users {
        user.inbounds
            .retain(|inbound| inbound_tags.contains(&inbound.tag));
        user.hosts.retain(|host| host_ids.contains(&host.id));
        let user_protocols = user
            .inbounds
            .iter()
            .map(|inbound| inbound.protocol.as_str())
            .collect::<HashSet<_>>();
        user.proxy_profiles
            .retain(|profile| user_protocols.contains(profile.proxy_type.as_str()));
    }
    generated
        .users
        .retain(|user| !user.inbounds.is_empty() && !user.proxy_profiles.is_empty());
}

fn generated_endpoint_belongs_to_node(
    endpoint_node_id: Option<&str>,
    endpoint_cluster_id: Option<&str>,
    node_id: &str,
    allowed_cluster_ids: &HashSet<String>,
) -> bool {
    endpoint_node_id == Some(node_id)
        || endpoint_cluster_id.is_some_and(|cluster_id| allowed_cluster_ids.contains(cluster_id))
        || (endpoint_node_id.is_none() && endpoint_cluster_id.is_none())
}

fn effective_node_sync_status(node: &Node, expected_revision: &str) -> NodeSyncStatus {
    match node.last_applied_revision.as_deref() {
        Some(revision) if revision == expected_revision => NodeSyncStatus::Synced,
        Some(_) => NodeSyncStatus::Drifted,
        None if matches!(node.sync_status, NodeSyncStatus::Pending) => NodeSyncStatus::Pending,
        None => node.sync_status,
    }
}

fn compact_node_sync_report(request: &mut NodeSyncRequest, config: &AppConfig) {
    let max_items = config
        .runtime_limits
        .max_node_sync_events_buffered
        .clamp(1, 32);
    if request.apply_stages.len() > max_items {
        request.apply_stages = request
            .apply_stages
            .split_off(request.apply_stages.len() - max_items);
    }
    if request.apply_issues.len() > max_items {
        request.apply_issues = request
            .apply_issues
            .split_off(request.apply_issues.len() - max_items);
    }
    if request.runtime_components.len() > max_items {
        request.runtime_components = request
            .runtime_components
            .split_off(request.runtime_components.len() - max_items);
    }
    if request.runtime_alerts.len() > max_items {
        request.runtime_alerts = request
            .runtime_alerts
            .split_off(request.runtime_alerts.len() - max_items);
    }
    for stage in &mut request.apply_stages {
        stage.stage = truncate_node_report_field(&stage.stage);
        stage.detail = truncate_node_report_field(&stage.detail);
    }
    for issue in &mut request.apply_issues {
        issue.route_id = truncate_node_report_field(&issue.route_id);
        issue.scope = truncate_node_report_field(&issue.scope);
        issue.severity = truncate_node_report_field(&issue.severity);
        issue.reason = truncate_node_report_field(&issue.reason);
    }
    if let Some(retry_state) = &mut request.retry_state {
        retry_state.last_transport_error = retry_state
            .last_transport_error
            .as_deref()
            .map(truncate_node_report_field);
    }
    for component in &mut request.runtime_components {
        component.component = truncate_node_report_field(&component.component);
        component.version = component.version.as_deref().map(truncate_node_report_field);
        component.last_error = component
            .last_error
            .as_deref()
            .map(truncate_node_report_field);
    }
    for alert in &mut request.runtime_alerts {
        alert.alert_id = truncate_node_report_field(&alert.alert_id);
        alert.detail = truncate_node_report_field(&alert.detail);
    }
    if let Some(report) = &mut request.external_xray_validation {
        truncate_xray_external_validation_report(report);
    }
}

fn compact_node_apply_result_report(request: &mut NodeApplyResultRequest, config: &AppConfig) {
    let max_items = config
        .runtime_limits
        .max_node_sync_events_buffered
        .clamp(1, 32);
    if request.apply_stages.len() > max_items {
        request.apply_stages = request
            .apply_stages
            .split_off(request.apply_stages.len() - max_items);
    }
    if request.apply_issues.len() > max_items {
        request.apply_issues = request
            .apply_issues
            .split_off(request.apply_issues.len() - max_items);
    }
    if request.runtime_components.len() > max_items {
        request.runtime_components = request
            .runtime_components
            .split_off(request.runtime_components.len() - max_items);
    }
    request.attempt_id = truncate_node_report_field(&request.attempt_id);
    request.target_revision = truncate_node_report_field(&request.target_revision);
    request.detail = request.detail.as_deref().map(truncate_node_report_field);
    for stage in &mut request.apply_stages {
        stage.stage = truncate_node_report_field(&stage.stage);
        stage.detail = truncate_node_report_field(&stage.detail);
    }
    for issue in &mut request.apply_issues {
        issue.route_id = truncate_node_report_field(&issue.route_id);
        issue.scope = truncate_node_report_field(&issue.scope);
        issue.severity = truncate_node_report_field(&issue.severity);
        issue.reason = truncate_node_report_field(&issue.reason);
    }
    for component in &mut request.runtime_components {
        component.component = truncate_node_report_field(&component.component);
        component.version = component.version.as_deref().map(truncate_node_report_field);
        component.last_error = component
            .last_error
            .as_deref()
            .map(truncate_node_report_field);
    }
    if let Some(report) = &mut request.external_xray_validation {
        truncate_xray_external_validation_report(report);
    }
}

fn truncate_xray_external_validation_report(report: &mut XrayExternalValidationReport) {
    report.binary_path = report
        .binary_path
        .as_deref()
        .map(truncate_node_report_field);
    report.stdout = truncate_node_report_field(&report.stdout);
    report.stderr = truncate_node_report_field(&report.stderr);
    report.detail = truncate_node_report_field(&report.detail);
}

fn truncate_node_report_field(value: &str) -> String {
    const MAX_FIELD_BYTES: usize = 512;
    let redacted = redact_telegram_bot_url(&redact_sensitive_text(value));
    if redacted.len() <= MAX_FIELD_BYTES {
        return redacted;
    }
    let mut end = MAX_FIELD_BYTES;
    while !redacted.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}...", &redacted[..end])
}

fn build_node_health_center(
    nodes: Vec<Node>,
    generated_revision: &str,
    checked_at_unix: u64,
    sync_history: &[NodeSyncHistoryEntry],
    apply_results: &[NodeApplyResultEntry],
    provisioning_tasks: &[NodeProvisioningTask],
) -> NodeHealthCenterView {
    let mut summary = NodeHealthCenterSummary::default();
    let mut items = Vec::with_capacity(nodes.len());
    let reported_apply_by_node = latest_reported_apply_health(sync_history);
    let retry_state_by_node = latest_retry_state_health(sync_history);
    let runtime_alerts_by_node = latest_runtime_alerts_by_node(sync_history);
    let apply_result_by_node = latest_apply_result_health(apply_results);
    let provisioning_task_by_node = latest_provisioning_task_by_node(provisioning_tasks);

    for node in nodes {
        summary.total += 1;
        if node.enabled {
            summary.enabled += 1;
        } else {
            summary.disabled += 1;
        }

        match node.status {
            NodeStatus::Healthy => summary.healthy += 1,
            NodeStatus::Degraded => summary.degraded += 1,
            NodeStatus::Offline => summary.offline += 1,
            NodeStatus::Unknown => summary.unknown += 1,
        }

        match node.sync_status {
            NodeSyncStatus::Synced => summary.synced += 1,
            NodeSyncStatus::Drifted => summary.drifted += 1,
            NodeSyncStatus::Pending => summary.pending += 1,
            NodeSyncStatus::Unknown => {}
        }

        match node.provisioning_status {
            NodeProvisioningStatus::Running => summary.provisioning_running += 1,
            NodeProvisioningStatus::Failed => summary.provisioning_failed += 1,
            NodeProvisioningStatus::None
            | NodeProvisioningStatus::Pending
            | NodeProvisioningStatus::Completed => {}
        }

        let mut health_flags = Vec::new();
        let mut recommendations = Vec::new();

        if !node.enabled {
            health_flags.push(NodeHealthFlag::Disabled);
            recommendations.push("Node is disabled in panel settings.".to_string());
        }

        if matches!(node.status, NodeStatus::Offline) {
            health_flags.push(NodeHealthFlag::Offline);
            recommendations.push(
                "Node is offline. Check agent service, network reachability, and firewall."
                    .to_string(),
            );
        } else if matches!(node.status, NodeStatus::Degraded) {
            health_flags.push(NodeHealthFlag::Degraded);
            recommendations.push(
                "Node reports degraded state. Inspect local runtime state and Xray logs."
                    .to_string(),
            );
        } else if matches!(node.status, NodeStatus::Unknown) && node.enabled {
            health_flags.push(NodeHealthFlag::UnknownStatus);
            recommendations.push(
                "Node has no confirmed healthy heartbeat yet. Wait for the agent heartbeat or run diagnostics."
                    .to_string(),
            );
        }

        if node.enabled
            && timestamp_is_stale(
                node.last_heartbeat_at_unix,
                checked_at_unix,
                NODE_HEARTBEAT_STALE_AFTER_SECONDS,
            )
        {
            summary.stale_heartbeat += 1;
            health_flags.push(NodeHealthFlag::StaleHeartbeat);
            recommendations.push(
                "Heartbeat is stale. Verify panel/node token, node-agent service, and outbound access to the panel."
                    .to_string(),
            );
        }

        if node.enabled
            && timestamp_is_stale(
                node.last_metrics_at_unix,
                checked_at_unix,
                NODE_METRICS_STALE_AFTER_SECONDS,
            )
        {
            summary.stale_metrics += 1;
            health_flags.push(NodeHealthFlag::StaleMetrics);
            recommendations.push(
                "Metrics are stale. Verify node metrics reporting and agent tick loop.".to_string(),
            );
        }

        if matches!(node.sync_status, NodeSyncStatus::Drifted) {
            health_flags.push(NodeHealthFlag::ConfigDrift);
            recommendations.push(format!(
                "Node config differs from generated revision {generated_revision}. Request config apply."
            ));
        } else if matches!(node.sync_status, NodeSyncStatus::Pending) {
            health_flags.push(NodeHealthFlag::ApplyPending);
            recommendations.push(
                "Config apply is pending. Watch sync history and node runtime state.".to_string(),
            );
        }

        let stale_provisioning = provisioning_task_by_node
            .get(&node.id)
            .is_some_and(|task| node_provisioning_task_is_stale(task, checked_at_unix));
        if stale_provisioning {
            summary.provisioning_stale += 1;
            health_flags.push(NodeHealthFlag::ProvisioningStale);
            recommendations.push(
                "Provisioning stopped reporting progress. Inspect the executor and retry or reprovision if it is abandoned."
                    .to_string(),
            );
        } else if matches!(node.provisioning_status, NodeProvisioningStatus::Running) {
            health_flags.push(NodeHealthFlag::ProvisioningRunning);
            recommendations.push(
                "Provisioning is running. Avoid conflicting manual runtime actions until it finishes."
                    .to_string(),
            );
        } else if matches!(node.provisioning_status, NodeProvisioningStatus::Failed) {
            health_flags.push(NodeHealthFlag::ProvisioningFailed);
            recommendations.push(
                "Provisioning failed. Open provisioning history, fix the failing preflight/step, then retry."
                    .to_string(),
            );
        }

        let reported_apply = reported_apply_by_node.get(&node.id);
        let reported_apply_failed_stage_count =
            reported_apply.map_or(0, |report| report.failed_stage_count);
        let reported_apply_error_issue_count =
            reported_apply.map_or(0, |report| report.error_issue_count);
        let reported_apply_failed =
            reported_apply_failed_stage_count > 0 || reported_apply_error_issue_count > 0;

        if reported_apply_failed {
            summary.reported_apply_failed += 1;
            health_flags.push(NodeHealthFlag::ReportedApplyFailed);
            recommendations.push(format!(
                "Latest node-reported apply failed with {reported_apply_failed_stage_count} failed stage(s) and {reported_apply_error_issue_count} error issue(s). Inspect apply status before retrying."
            ));
        }

        let latest_retry_state = retry_state_by_node.get(&node.id).cloned();
        let retry_backoff_active = latest_retry_state.as_ref().is_some_and(|state| {
            state
                .next_retry_not_before_unix
                .is_some_and(|retry_at| retry_at > checked_at_unix)
        });
        if retry_backoff_active {
            summary.retry_backoff_active += 1;
            health_flags.push(NodeHealthFlag::RetryBackoffActive);
            let retry_state = latest_retry_state
                .as_ref()
                .expect("active retry backoff implies retry state");
            recommendations.push(format!(
                "Node-agent is in retry backoff after {} consecutive transport failure(s). Next retry is not before {}.",
                retry_state.consecutive_failures,
                retry_state
                    .next_retry_not_before_unix
                    .expect("active retry backoff implies retry timestamp")
            ));
        }

        let apply_result = apply_result_by_node.get(&node.id);
        let latest_apply_status = apply_result.and_then(|result| result.latest_status);
        let latest_apply_target_revision =
            apply_result.and_then(|result| result.latest_target_revision.clone());
        let latest_apply_recorded_at_unix =
            apply_result.and_then(|result| result.latest_recorded_at_unix);
        let latest_successful_apply_revision =
            apply_result.and_then(|result| result.latest_successful_revision.clone());
        let latest_failed_apply_revision =
            apply_result.and_then(|result| result.latest_failed_revision.clone());
        let rollback_available = apply_result.is_some_and(|result| result.rollback_available);

        if rollback_available {
            summary.apply_rollback_available += 1;
            health_flags.push(NodeHealthFlag::RollbackAvailable);
            recommendations.push(
                "Rollback material is available for this node. Prefer rollback over blind retry if the latest apply broke runtime."
                    .to_string(),
            );
        }

        let latest_runtime_alerts = runtime_alerts_by_node
            .get(&node.id)
            .cloned()
            .unwrap_or_default();
        let runtime_alert_count = latest_runtime_alerts
            .iter()
            .filter(|alert| alert.active)
            .count();
        let runtime_critical_alert_count = latest_runtime_alerts
            .iter()
            .filter(|alert| alert.active && alert.severity == NodeRuntimeAlertSeverity::Critical)
            .count();
        if runtime_alert_count > 0 {
            summary.runtime_alerts_active += 1;
            summary.runtime_alerts_critical += runtime_critical_alert_count;
            health_flags.push(NodeHealthFlag::RuntimeAlertsActive);
            recommendations.push(format!(
                "Node reported {runtime_alert_count} active runtime alert(s), including {runtime_critical_alert_count} critical. Inspect node runtime alerts and local diagnostics."
            ));
        }

        let reported_memory_percent = percent_used(
            node.reported_memory_used_bytes,
            node.reported_memory_total_bytes,
        );
        let reported_disk_percent = percent_used(
            node.reported_disk_used_bytes,
            node.reported_disk_total_bytes,
        );

        if node.enabled && reported_memory_percent.is_some_and(|value| value >= 90.0) {
            health_flags.push(NodeHealthFlag::MemoryHigh);
            recommendations.push(
                "Node memory usage is high. Check Xray load, active users, and host memory pressure."
                    .to_string(),
            );
        }

        if node.enabled && reported_disk_percent.is_some_and(|value| value >= 90.0) {
            health_flags.push(NodeHealthFlag::DiskHigh);
            recommendations.push(
                "Node disk usage is high. Rotate logs, inspect backups, and check Xray/node log growth."
                    .to_string(),
            );
        }

        if !health_flags.is_empty() {
            summary.attention_required += 1;
        }

        if recommendations.is_empty() {
            recommendations.push("No immediate issues detected.".to_string());
        }

        items.push(NodeHealthCenterItem {
            node_id: node.id,
            name: node.name,
            enabled: node.enabled,
            status: node.status,
            sync_status: node.sync_status,
            provisioning_status: node.provisioning_status,
            last_applied_revision: node.last_applied_revision,
            last_heartbeat_at_unix: node.last_heartbeat_at_unix,
            last_metrics_at_unix: node.last_metrics_at_unix,
            reported_memory_percent,
            reported_disk_percent,
            reported_apply_failed,
            reported_apply_failed_stage_count,
            reported_apply_error_issue_count,
            latest_retry_state,
            retry_backoff_active,
            latest_apply_status,
            latest_apply_target_revision,
            latest_apply_recorded_at_unix,
            latest_successful_apply_revision,
            latest_failed_apply_revision,
            rollback_available,
            runtime_alert_count,
            runtime_critical_alert_count,
            latest_runtime_alerts,
            health_flags,
            recommendations,
        });
    }

    let recommendations = build_node_health_center_recommendations(&summary);
    NodeHealthCenterView {
        generated_revision: generated_revision.to_string(),
        checked_at_unix,
        summary,
        nodes: items,
        recommendations,
    }
}

#[derive(Debug, Clone, Copy, Default)]
struct NodeReportedApplyHealth {
    failed_stage_count: usize,
    error_issue_count: usize,
}

fn latest_retry_state_health(
    sync_history: &[NodeSyncHistoryEntry],
) -> HashMap<String, NodeAgentRetryStateView> {
    let mut reported = HashMap::new();
    for entry in sync_history {
        if let Some(retry_state) = &entry.retry_state {
            reported.insert(entry.node_id.clone(), retry_state.clone());
        }
    }
    reported
}

fn latest_runtime_alerts_by_node(
    sync_history: &[NodeSyncHistoryEntry],
) -> HashMap<String, Vec<NodeRuntimeAlertView>> {
    let mut alerts = HashMap::new();
    for entry in sync_history {
        if entry.runtime_alerts.is_empty() {
            continue;
        }
        alerts.insert(entry.node_id.clone(), entry.runtime_alerts.clone());
    }
    alerts
}

#[derive(Debug, Clone, Default)]
struct NodeApplyResultHealth {
    latest_status: Option<NodeApplyResultStatus>,
    latest_target_revision: Option<String>,
    latest_recorded_at_unix: Option<u64>,
    latest_successful_revision: Option<String>,
    latest_failed_revision: Option<String>,
    rollback_available: bool,
}

fn latest_apply_result_health(
    apply_results: &[NodeApplyResultEntry],
) -> HashMap<String, NodeApplyResultHealth> {
    let mut reported: HashMap<String, NodeApplyResultHealth> = HashMap::new();
    for entry in apply_results {
        let item = reported.entry(entry.node_id.clone()).or_default();
        item.latest_status = Some(entry.status);
        item.latest_target_revision = Some(entry.target_revision.clone());
        item.latest_recorded_at_unix = Some(entry.recorded_at_unix);
        item.rollback_available = entry.rollback_available;

        match entry.status {
            NodeApplyResultStatus::Applied => {
                item.latest_successful_revision = entry
                    .applied_revision
                    .clone()
                    .or_else(|| Some(entry.target_revision.clone()));
            }
            NodeApplyResultStatus::Failed => {
                item.latest_failed_revision = Some(entry.target_revision.clone());
            }
            NodeApplyResultStatus::RolledBack => {
                item.latest_successful_revision = entry
                    .applied_revision
                    .clone()
                    .or_else(|| entry.last_good_revision.clone())
                    .or_else(|| Some(entry.target_revision.clone()));
            }
            NodeApplyResultStatus::Skipped => {}
        }
    }
    reported
}

fn latest_reported_apply_health(
    sync_history: &[NodeSyncHistoryEntry],
) -> HashMap<String, NodeReportedApplyHealth> {
    let mut reported = HashMap::new();
    for entry in sync_history {
        if entry.apply_stages.is_empty() && entry.apply_issues.is_empty() {
            continue;
        }
        reported.insert(
            entry.node_id.clone(),
            NodeReportedApplyHealth {
                failed_stage_count: count_failed_apply_stages(&entry.apply_stages),
                error_issue_count: count_error_apply_issues(&entry.apply_issues),
            },
        );
    }
    reported
}

fn count_failed_apply_stages(stages: &[NodeApplyStageView]) -> usize {
    stages
        .iter()
        .filter(|stage| matches!(stage.status, NodeApplyStageStatus::Failed))
        .count()
}

fn count_error_apply_issues(issues: &[XrayRenderIssueView]) -> usize {
    issues
        .iter()
        .filter(|issue| issue.severity.eq_ignore_ascii_case("error"))
        .count()
}

fn infer_apply_lifecycle_from_sync_report(
    request: &NodeSyncRequest,
    sync_status: NodeSyncStatus,
    expected_revision: &str,
) -> Option<NodeApplyLifecycleState> {
    if count_failed_apply_stages(&request.apply_stages) > 0
        || count_error_apply_issues(&request.apply_issues) > 0
    {
        return Some(NodeApplyLifecycleState::Failed);
    }

    let last_stage_name = request
        .apply_stages
        .last()
        .map(|stage| stage.stage.as_str());
    match last_stage_name {
        Some("download_config") | Some("fetch_config") => Some(NodeApplyLifecycleState::Downloaded),
        Some("render_xray") | Some("render_config") => Some(NodeApplyLifecycleState::Rendered),
        Some("validate_xray") | Some("xray_test") => Some(NodeApplyLifecycleState::Validated),
        Some("rollback") | Some("rollback_runtime") => Some(NodeApplyLifecycleState::RolledBack),
        Some("apply_runtime") | Some("restart_xray") => {
            if request.applied_revision.as_deref() == Some(expected_revision)
                && sync_status == NodeSyncStatus::Synced
            {
                Some(NodeApplyLifecycleState::Applied)
            } else {
                Some(NodeApplyLifecycleState::Validated)
            }
        }
        _ if sync_status == NodeSyncStatus::Pending => Some(NodeApplyLifecycleState::Pending),
        _ if request.applied_revision.as_deref() == Some(expected_revision)
            && sync_status == NodeSyncStatus::Synced =>
        {
            Some(NodeApplyLifecycleState::Applied)
        }
        _ => None,
    }
}

fn build_node_agent_apply_directive(
    node: &Node,
    target_revision: &str,
    sync_history: &[NodeSyncHistoryEntry],
) -> NodeAgentApplyDirective {
    let latest_pending_request = sync_history.iter().rev().find(|entry| {
        entry.expected_revision == target_revision
            && matches!(
                entry.apply_lifecycle_state,
                Some(NodeApplyLifecycleState::Pending)
            )
    });
    let current_sync_status = if latest_pending_request.is_some() {
        NodeSyncStatus::Pending
    } else {
        effective_node_sync_status(node, target_revision)
    };
    let revision_mismatch = node.last_applied_revision.as_deref() != Some(target_revision);
    let apply_required = matches!(
        current_sync_status,
        NodeSyncStatus::Pending | NodeSyncStatus::Drifted | NodeSyncStatus::Unknown
    ) || revision_mismatch;

    let reason = if latest_pending_request.is_some() {
        "panel requested apply for this revision"
    } else if revision_mismatch {
        "node applied revision differs from target revision"
    } else if current_sync_status != NodeSyncStatus::Synced {
        "node sync status is not synced"
    } else {
        "node already matches target revision"
    };

    NodeAgentApplyDirective {
        apply_required,
        target_revision: target_revision.to_string(),
        current_applied_revision: node.last_applied_revision.clone(),
        current_sync_status,
        requested_at_unix: latest_pending_request.map(|entry| entry.created_at_unix),
        reason: reason.to_string(),
    }
}

fn build_node_runtime_config_document(
    node: &Node,
    generated: &GeneratedCoreConfigPreview,
    apply: NodeAgentApplyDirective,
) -> NodeRuntimeConfigDocument {
    let mut document = NodeRuntimeConfigDocument {
        schema_version: SchemaId::NodeRuntimeConfig.version(),
        generated_at_unix: generated.generated_at_unix,
        revision: generated.revision.clone(),
        node: NodeRuntimeIdentity {
            node_id: node.id.clone(),
            name: node.name.clone(),
            address: node.address.clone(),
            port: Some(node.port),
            api_port: Some(node.api_port),
            enabled: node.enabled,
        },
        apply,
        runtime: NodeRuntimeSettings {
            xray_config_path: "node-runtime/xray.json".to_string(),
            xray_binary_path: None,
            restart_policy: "manual_after_validation".to_string(),
            least_knowledge: true,
        },
        contract: NodeRuntimeContractDiagnostics {
            valid: false,
            fail_closed: true,
            least_knowledge: true,
            node_id: node.id.clone(),
            projected_node_ids: Vec::new(),
            route_assignment_count: 0,
            credential_ref_count: 0,
            issue_count: 0,
            issues: Vec::new(),
        },
        config: NodeRuntimeConfigProjection {
            users: generated.users.clone(),
            inbounds: generated.inbounds.clone(),
            hosts: generated.hosts.clone(),
            nodes: generated
                .nodes
                .iter()
                .map(|node| NodeRuntimeIdentity {
                    node_id: node.id.clone(),
                    name: node.name.clone(),
                    address: node.address.clone(),
                    port: Some(node.port),
                    api_port: Some(node.api_port),
                    enabled: node.enabled,
                })
                .collect(),
        },
        route_assignments: generated.node_route_assignments.clone(),
        credential_refs: node_runtime_credential_refs(generated),
    };
    document.contract = build_node_runtime_contract_diagnostics(&document);
    document
}

fn build_node_runtime_contract_diagnostics(
    document: &NodeRuntimeConfigDocument,
) -> NodeRuntimeContractDiagnostics {
    let mut issues = Vec::new();
    let local_node_id = document.node.node_id.as_str();
    let projected_node_ids = document
        .config
        .nodes
        .iter()
        .map(|node| node.node_id.clone())
        .collect::<Vec<_>>();

    if !document.runtime.least_knowledge {
        issues.push(NodeRuntimeContractIssue {
            scope: "runtime.least_knowledge".to_string(),
            severity: "error".to_string(),
            reason: "node runtime config must be marked as least-knowledge".to_string(),
        });
    }
    if projected_node_ids.is_empty() {
        issues.push(NodeRuntimeContractIssue {
            scope: "config.nodes".to_string(),
            severity: "error".to_string(),
            reason: "node runtime config must include the local node identity".to_string(),
        });
    }
    for projected_node_id in &projected_node_ids {
        if projected_node_id != local_node_id {
            issues.push(NodeRuntimeContractIssue {
                scope: "config.nodes".to_string(),
                severity: "error".to_string(),
                reason: format!(
                    "node runtime config leaked unrelated node identity {projected_node_id}"
                ),
            });
        }
    }
    for assignment in &document.route_assignments {
        if assignment.node_id != local_node_id {
            issues.push(NodeRuntimeContractIssue {
                scope: "route_assignments".to_string(),
                severity: "error".to_string(),
                reason: format!(
                    "node runtime config leaked route assignment for unrelated node {}",
                    assignment.node_id
                ),
            });
        }
    }

    let mut expected_refs =
        node_runtime_credential_refs_from_assignments(&document.route_assignments);
    expected_refs.sort();
    expected_refs.dedup();
    let mut actual_refs = document.credential_refs.clone();
    actual_refs.sort();
    actual_refs.dedup();
    if actual_refs != expected_refs {
        issues.push(NodeRuntimeContractIssue {
            scope: "credential_refs".to_string(),
            severity: "error".to_string(),
            reason: "credential refs must exactly match local route assignment refs".to_string(),
        });
    }

    NodeRuntimeContractDiagnostics {
        valid: issues.iter().all(|issue| issue.severity != "error"),
        fail_closed: true,
        least_knowledge: document.runtime.least_knowledge,
        node_id: document.node.node_id.clone(),
        projected_node_ids,
        route_assignment_count: document.route_assignments.len(),
        credential_ref_count: document.credential_refs.len(),
        issue_count: issues.len(),
        issues,
    }
}

fn build_node_agent_apply_plan(runtime_config: &NodeRuntimeConfigDocument) -> NodeAgentApplyPlan {
    let requires_route_credentials = !runtime_config.credential_refs.is_empty();
    let xray_binary_configured = runtime_config.runtime.xray_binary_path.is_some();
    let runtime_components = node_agent_runtime_component_requirements(runtime_config);
    let runtime_components_ready = runtime_components
        .iter()
        .all(|component| component.production_ready && component.disabled_reason.is_none());
    let requires_xray_validation = runtime_components
        .iter()
        .any(|component| component.owner == ProtocolRuntimeOwner::Xray);
    let mut steps = vec![NodeAgentApplyPlanStep {
        step: "fetch_runtime_config".to_string(),
        required: true,
        detail:
            "Persist this least-knowledge node-runtime-config.json before rendering runtime files."
                .to_string(),
    }];

    steps.push(NodeAgentApplyPlanStep {
        step: "verify_runtime_components".to_string(),
        required: true,
        detail: "Verify required runtime components, binaries, validation strategy, and disabled reasons before rendering or restarting any runtime.".to_string(),
    });
    steps.push(NodeAgentApplyPlanStep {
        step: "fetch_route_credentials".to_string(),
        required: requires_route_credentials,
        detail: if requires_route_credentials {
            "Fetch private route material through /api/node-agent/route-credentials and store it with strict filesystem permissions.".to_string()
        } else {
            "No route credential refs are present for this projection.".to_string()
        },
    });
    steps.push(NodeAgentApplyPlanStep {
        step: "render_xray_config".to_string(),
        required: requires_xray_validation,
        detail: "Render xray.json locally from runtime_config or fetch the panel-rendered document from /api/node-agent/xray-config.".to_string(),
    });
    steps.push(NodeAgentApplyPlanStep {
        step: "validate_xray_config".to_string(),
        required: requires_xray_validation,
        detail: "Run Xray config validation before replacing the active runtime config or restarting Xray.".to_string(),
    });
    steps.push(NodeAgentApplyPlanStep {
        step: "write_runtime_state".to_string(),
        required: runtime_config.apply.apply_required,
        detail: "Write the validated runtime config and keep rollback material for the previous good revision.".to_string(),
    });
    steps.push(NodeAgentApplyPlanStep {
        step: "restart_xray".to_string(),
        required: runtime_config.apply.apply_required && runtime_components_ready,
        detail: if runtime_components_ready {
            "Restart Xray only after successful validation and durable runtime state write."
                .to_string()
        } else {
            "Runtime restart is blocked until every required runtime component is production-ready."
                .to_string()
        },
    });
    steps.push(NodeAgentApplyPlanStep {
        step: "report_sync".to_string(),
        required: true,
        detail:
            "Report lifecycle, bounded stages, and bounded issues through /api/node-agent/sync."
                .to_string(),
    });
    steps.push(NodeAgentApplyPlanStep {
        step: "report_apply_result".to_string(),
        required: runtime_config.apply.apply_required,
        detail: "Report final idempotent apply result through /api/node-agent/apply-result."
            .to_string(),
    });

    NodeAgentApplyPlan {
        schema_version: SchemaId::ApplyPlan.version(),
        generated_at_unix: now_unix(),
        target_revision: runtime_config.revision.clone(),
        apply_required: runtime_config.apply.apply_required,
        least_knowledge: runtime_config.runtime.least_knowledge,
        credential_ref_count: runtime_config.credential_refs.len(),
        requires_route_credentials,
        requires_xray_validation,
        xray_binary_configured,
        safe_restart_after_successful_validation: runtime_components_ready,
        runtime_components,
        steps,
    }
}

fn node_agent_runtime_component_requirements(
    runtime_config: &NodeRuntimeConfigDocument,
) -> Vec<NodeAgentRuntimeComponentRequirement> {
    node_agent_runtime_component_requirements_for_inbounds(&runtime_config.config.inbounds)
}

fn node_agent_runtime_component_requirements_for_inbounds(
    inbounds: &[Inbound],
) -> Vec<NodeAgentRuntimeComponentRequirement> {
    let mut required_owners = HashSet::from([ProtocolRuntimeOwner::Xray]);
    let capabilities = protocol_capabilities_view();
    for inbound in inbounds {
        if let Some(capability) = capabilities
            .capabilities
            .iter()
            .find(|capability| capability.protocol == inbound.protocol)
        {
            required_owners.insert(capability.runtime_owner);
        }
    }

    protocol_runtime_components_view()
        .into_iter()
        .filter(|component| required_owners.contains(&component.owner))
        .map(|component| NodeAgentRuntimeComponentRequirement {
            owner: component.owner,
            component: component.component,
            required: true,
            production_ready: component.production_ready,
            required_binaries: component.required_binaries,
            validation_strategy: component.validation_strategy,
            update_strategy: component.update_strategy,
            disabled_reason: component.disabled_reason,
        })
        .collect()
}

fn node_runtime_credential_refs(generated: &GeneratedCoreConfigPreview) -> Vec<String> {
    node_runtime_credential_refs_from_assignments(&generated.node_route_assignments)
}

fn node_runtime_credential_refs_from_assignments(
    assignments: &[NodeRouteAssignment],
) -> Vec<String> {
    let mut refs = Vec::new();
    for assignment in assignments {
        if let Some(listen) = assignment.listen.as_ref() {
            if let Some(credential_ref) = listen
                .security
                .as_ref()
                .and_then(|security| security.credential_ref.clone())
            {
                refs.push(credential_ref);
            }
            if let Some(credential_ref) = listen
                .auth
                .as_ref()
                .and_then(|auth| auth.credential_ref.clone())
            {
                refs.push(credential_ref);
            }
        }
        for peer in [&assignment.previous_peer, &assignment.next_peer]
            .into_iter()
            .flatten()
        {
            if let Some(credential_ref) = peer
                .security
                .as_ref()
                .and_then(|security| security.credential_ref.clone())
            {
                refs.push(credential_ref);
            }
            if let Some(credential_ref) = peer
                .auth
                .as_ref()
                .and_then(|auth| auth.credential_ref.clone())
            {
                refs.push(credential_ref);
            }
        }
    }
    refs.sort();
    refs.dedup();
    refs
}

fn build_node_apply_status_view(
    node: Node,
    generated_revision: String,
    recent_sync_history: Vec<NodeSyncHistoryEntry>,
    recent_apply_results: Vec<NodeApplyResultEntry>,
    local_state: Option<NodeLocalStateView>,
    route_credentials: Option<RouteMaterialApplyDiagnostics>,
    runtime_components: Vec<NodeAgentRuntimeComponentRequirement>,
    checked_at_unix: u64,
) -> NodeApplyStatusView {
    let local_applied_revision = local_state
        .as_ref()
        .and_then(|state| state.applied_revision.clone());
    let local_render_summary = local_state
        .as_ref()
        .and_then(|state| state.last_xray_render_summary.clone());
    let mut stages = Vec::new();
    let mut blocking_issues = Vec::new();
    let mut recommendations = Vec::new();

    let enabled_status = if node.enabled {
        NodeApplyStageStatus::Ok
    } else {
        blocking_issues.push("node is disabled".to_string());
        recommendations
            .push("Enable the node before expecting apply/runtime convergence.".to_string());
        NodeApplyStageStatus::Failed
    };
    stages.push(NodeApplyStageView {
        stage: "panel_node_enabled".to_string(),
        status: enabled_status,
        detail: if node.enabled {
            "node is enabled".to_string()
        } else {
            "node is disabled in panel settings".to_string()
        },
    });

    let heartbeat_stale = timestamp_is_stale(
        node.last_heartbeat_at_unix,
        checked_at_unix,
        NODE_HEARTBEAT_STALE_AFTER_SECONDS,
    );
    let heartbeat_status = if !node.enabled {
        NodeApplyStageStatus::Unknown
    } else if heartbeat_stale {
        blocking_issues.push("heartbeat is stale".to_string());
        recommendations.push(
            "Check node-agent service, panel reachability, auth token, and firewall.".to_string(),
        );
        NodeApplyStageStatus::Failed
    } else {
        NodeApplyStageStatus::Ok
    };
    stages.push(NodeApplyStageView {
        stage: "heartbeat".to_string(),
        status: heartbeat_status,
        detail: match node.last_heartbeat_at_unix {
            Some(value) => format!("last heartbeat at {value}"),
            None => "no heartbeat has been recorded".to_string(),
        },
    });

    let sync_status = match node.sync_status {
        NodeSyncStatus::Synced => NodeApplyStageStatus::Ok,
        NodeSyncStatus::Pending => {
            recommendations.push(
                "Wait for node-agent tick or inspect local state if pending persists.".to_string(),
            );
            NodeApplyStageStatus::Warning
        }
        NodeSyncStatus::Drifted => {
            blocking_issues.push("node config revision is drifted".to_string());
            recommendations
                .push("Request config apply for the current generated revision.".to_string());
            NodeApplyStageStatus::Failed
        }
        NodeSyncStatus::Unknown => NodeApplyStageStatus::Unknown,
    };
    stages.push(NodeApplyStageView {
        stage: "panel_sync_revision".to_string(),
        status: sync_status,
        detail: format!(
            "panel applied revision: {}; generated revision: {}",
            node.last_applied_revision.as_deref().unwrap_or("none"),
            generated_revision
        ),
    });

    let local_state_status = if local_state.is_some() {
        NodeApplyStageStatus::Ok
    } else {
        recommendations.push(
            "Panel cannot read node local state. Check node local API address/api_port."
                .to_string(),
        );
        NodeApplyStageStatus::Unknown
    };
    stages.push(NodeApplyStageView {
        stage: "local_state".to_string(),
        status: local_state_status,
        detail: if local_state.is_some() {
            "node local state is available".to_string()
        } else {
            "node local state is unavailable".to_string()
        },
    });

    let blocked_runtime_components = runtime_components
        .iter()
        .filter(|component| !component.production_ready || component.disabled_reason.is_some())
        .collect::<Vec<_>>();
    let reported_runtime_components = latest_reported_runtime_components(
        &recent_sync_history,
        local_state
            .as_ref()
            .map(|state| state.runtime_components.as_slice()),
    );
    let missing_reported_components = runtime_components
        .iter()
        .filter(|component| {
            !reported_runtime_components.iter().any(|reported| {
                reported.owner == component.owner
                    && reported.component == component.component.as_str()
            })
        })
        .collect::<Vec<_>>();
    let unhealthy_reported_components = reported_runtime_components
        .iter()
        .filter(|component| !component.installed || !component.healthy)
        .collect::<Vec<_>>();
    let runtime_component_status = if blocked_runtime_components.is_empty()
        && unhealthy_reported_components.is_empty()
    {
        if missing_reported_components.is_empty() {
            NodeApplyStageStatus::Ok
        } else {
            recommendations.push(
                    "Wait for node-agent runtime component report before treating runtime readiness as fully verified."
                        .to_string(),
                );
            NodeApplyStageStatus::Warning
        }
    } else {
        for component in &blocked_runtime_components {
            blocking_issues.push(format!(
                "runtime component {} is not ready: {}",
                component.component.as_str(),
                component
                    .disabled_reason
                    .as_deref()
                    .unwrap_or("component is not production-ready")
            ));
        }
        for component in &unhealthy_reported_components {
            blocking_issues.push(format!(
                "runtime component {} reported unhealthy: {}",
                component.component,
                component
                    .last_error
                    .as_deref()
                    .unwrap_or("component is missing or unhealthy")
            ));
        }
        recommendations.push(
            "Do not restart runtimes until all required runtime components are production-ready."
                .to_string(),
        );
        NodeApplyStageStatus::Failed
    };
    stages.push(NodeApplyStageView {
        stage: "runtime_components".to_string(),
        status: runtime_component_status,
        detail: format!(
            "required components: {}; reported components: {}; blocked components: {}; missing reports: {}; unhealthy reports: {}",
            runtime_components.len(),
            reported_runtime_components.len(),
            blocked_runtime_components.len(),
            missing_reported_components.len(),
            unhealthy_reported_components.len()
        ),
    });

    let requires_external_xray_validation = runtime_components
        .iter()
        .any(|component| component.owner == ProtocolRuntimeOwner::Xray);
    let latest_external_xray_validation = latest_external_xray_validation_report(
        &recent_sync_history,
        &recent_apply_results,
        local_state.as_ref(),
    );
    if requires_external_xray_validation {
        let (status, detail) = match latest_external_xray_validation {
            Some(report) if report.status == XrayExternalValidationStatus::Passed => (
                NodeApplyStageStatus::Ok,
                format!(
                    "external Xray validation passed at {}; binary: {}; detail: {}",
                    report.checked_at_unix,
                    report.binary_path.as_deref().unwrap_or("unknown"),
                    report.detail
                ),
            ),
            Some(report) if report.status == XrayExternalValidationStatus::Failed => {
                blocking_issues.push(format!(
                    "external Xray validation failed: {}",
                    report.detail
                ));
                recommendations.push(
                    "Do not restart Xray until node-agent reports a passed external validation."
                        .to_string(),
                );
                (
                    NodeApplyStageStatus::Failed,
                    format!(
                        "external Xray validation failed at {}; exit code: {}; detail: {}",
                        report.checked_at_unix,
                        report
                            .exit_code
                            .map_or_else(|| "none".to_string(), |value| value.to_string()),
                        report.detail
                    ),
                )
            }
            Some(report) => {
                blocking_issues.push(format!(
                    "external Xray validation was skipped: {}",
                    report.detail
                ));
                recommendations.push(
                    "Run external Xray validation with the real binary before runtime restart."
                        .to_string(),
                );
                (
                    NodeApplyStageStatus::Warning,
                    format!(
                        "external Xray validation skipped at {}; detail: {}",
                        report.checked_at_unix, report.detail
                    ),
                )
            }
            None => {
                blocking_issues.push("external Xray validation has not been reported".to_string());
                recommendations.push(
                    "Wait for node-agent to run `xray run -test -config ...` and report the result."
                        .to_string(),
                );
                (
                    NodeApplyStageStatus::Unknown,
                    "no external Xray validation report is available".to_string(),
                )
            }
        };
        stages.push(NodeApplyStageView {
            stage: "xray_external_validation".to_string(),
            status,
            detail,
        });
    }

    if let Some(route_credentials) = route_credentials.as_ref() {
        match route_credentials.status {
            NodeApplyStageStatus::Failed => {
                for credential_ref in &route_credentials.revoked_required_refs {
                    blocking_issues.push(format!(
                        "route credential {credential_ref} is revoked and fail-closed"
                    ));
                }
                for credential_ref in &route_credentials.missing_active_refs {
                    blocking_issues.push(format!(
                        "route credential {credential_ref} is required but no active material is available"
                    ));
                }
                recommendations.push(
                    "Rotate revoked route credentials or reissue missing material before applying this node config."
                        .to_string(),
                );
            }
            NodeApplyStageStatus::Warning => {
                recommendations.push(
                    "Let node-agent fetch route credentials before restart, or inspect route material store if this persists."
                        .to_string(),
                );
            }
            _ => {}
        }
        stages.push(NodeApplyStageView {
            stage: "route_credentials".to_string(),
            status: route_credentials.status,
            detail: route_credentials.detail.clone(),
        });
    } else {
        recommendations.push(
            "Panel could not inspect route material store; verify route material storage/key readiness if apply fails closed."
                .to_string(),
        );
        stages.push(NodeApplyStageView {
            stage: "route_credentials".to_string(),
            status: NodeApplyStageStatus::Unknown,
            detail: "route material store diagnostics are unavailable".to_string(),
        });
    }

    if let Some(latest_report) = recent_sync_history
        .iter()
        .rev()
        .find(|entry| !entry.apply_stages.is_empty() || !entry.apply_issues.is_empty())
    {
        let failed_stage_count = latest_report
            .apply_stages
            .iter()
            .filter(|stage| stage.status == NodeApplyStageStatus::Failed)
            .count();
        let error_issue_count = latest_report
            .apply_issues
            .iter()
            .filter(|issue| issue.severity.eq_ignore_ascii_case("error"))
            .count();
        let reported_status = if failed_stage_count > 0 || error_issue_count > 0 {
            blocking_issues.push(format!(
                "node-agent reported {failed_stage_count} failed apply stage(s) and {error_issue_count} error issue(s)"
            ));
            recommendations.push(
                "Inspect recent sync history apply_stages/apply_issues before retrying apply."
                    .to_string(),
            );
            NodeApplyStageStatus::Failed
        } else if !latest_report.apply_issues.is_empty() {
            recommendations.push(
                "Node-agent reported apply issues; inspect sync history before restart."
                    .to_string(),
            );
            NodeApplyStageStatus::Warning
        } else {
            NodeApplyStageStatus::Ok
        };
        stages.push(NodeApplyStageView {
            stage: "node_reported_apply".to_string(),
            status: reported_status,
            detail: format!(
                "reported stages: {}; reported issues: {}; sync detail: {}",
                latest_report.apply_stages.len(),
                latest_report.apply_issues.len(),
                latest_report.detail.as_deref().unwrap_or("none")
            ),
        });
    }

    if let Some(retry_state) = recent_sync_history
        .iter()
        .rev()
        .find_map(|entry| entry.retry_state.as_ref())
    {
        let retry_active = retry_state
            .next_retry_not_before_unix
            .is_some_and(|retry_at| retry_at > checked_at_unix);
        let status = if retry_active {
            recommendations.push(format!(
                "Node-agent is waiting before its next panel retry after {} consecutive transport failure(s).",
                retry_state.consecutive_failures
            ));
            NodeApplyStageStatus::Warning
        } else if retry_state.consecutive_failures > 0 {
            recommendations.push(
                "Node-agent recently reported transport failures; inspect retry state if sync does not recover."
                    .to_string(),
            );
            NodeApplyStageStatus::Warning
        } else {
            NodeApplyStageStatus::Ok
        };
        stages.push(NodeApplyStageView {
            stage: "node_agent_retry".to_string(),
            status,
            detail: format!(
                "consecutive failures: {}; backoff seconds: {}; next retry not before: {}; last transport error: {}",
                retry_state.consecutive_failures,
                retry_state
                    .retry_backoff_seconds
                    .map_or_else(|| "none".to_string(), |value| value.to_string()),
                retry_state
                    .next_retry_not_before_unix
                    .map_or_else(|| "none".to_string(), |value| value.to_string()),
                retry_state.last_transport_error.as_deref().unwrap_or("none")
            ),
        });
    }

    if let Some(state) = local_state.as_ref() {
        let local_revision_status = match state.applied_revision.as_deref() {
            Some(revision) if revision == generated_revision => NodeApplyStageStatus::Ok,
            Some(_) => {
                blocking_issues.push(
                    "local runtime applied revision differs from generated revision".to_string(),
                );
                recommendations.push(
                    "Inspect node apply history and re-apply the generated config.".to_string(),
                );
                NodeApplyStageStatus::Failed
            }
            None => {
                recommendations.push(
                    "Node local runtime has not reported an applied revision yet.".to_string(),
                );
                NodeApplyStageStatus::Unknown
            }
        };
        stages.push(NodeApplyStageView {
            stage: "local_applied_revision".to_string(),
            status: local_revision_status,
            detail: format!(
                "local applied revision: {}; generated revision: {}",
                state.applied_revision.as_deref().unwrap_or("none"),
                generated_revision
            ),
        });

        let runtime_status = match state.xray_runtime_status {
            panel_domain::node::NodeLocalRuntimeStatus::Running => NodeApplyStageStatus::Ok,
            panel_domain::node::NodeLocalRuntimeStatus::Failed => {
                blocking_issues.push("xray runtime is failed".to_string());
                recommendations.push(
                    "Inspect xray_last_detail, runtime events, and consider restart or rollback."
                        .to_string(),
                );
                NodeApplyStageStatus::Failed
            }
            panel_domain::node::NodeLocalRuntimeStatus::Stopped => {
                recommendations.push(
                    "Xray runtime is stopped. Start or restart it after successful config validation if this node should serve traffic."
                        .to_string(),
                );
                NodeApplyStageStatus::Warning
            }
            panel_domain::node::NodeLocalRuntimeStatus::Unknown => NodeApplyStageStatus::Unknown,
        };
        stages.push(NodeApplyStageView {
            stage: "xray_runtime".to_string(),
            status: runtime_status,
            detail: state
                .xray_last_detail
                .clone()
                .unwrap_or_else(|| format!("runtime status: {:?}", state.xray_runtime_status)),
        });

        if let Some(update_status) = state.last_xray_update_status {
            let status = match update_status {
                panel_domain::node::NodeLocalXrayUpdateStatus::Succeeded => {
                    NodeApplyStageStatus::Ok
                }
                panel_domain::node::NodeLocalXrayUpdateStatus::Running => {
                    recommendations.push(
                        "Xray core update is currently running; avoid concurrent runtime actions."
                            .to_string(),
                    );
                    NodeApplyStageStatus::Warning
                }
                panel_domain::node::NodeLocalXrayUpdateStatus::Failed => {
                    blocking_issues.push("last xray core update failed".to_string());
                    recommendations.push(
                        "Inspect Xray update phase/detail and verify restored backup binary."
                            .to_string(),
                    );
                    NodeApplyStageStatus::Failed
                }
            };
            stages.push(NodeApplyStageView {
                stage: "xray_update".to_string(),
                status,
                detail: format!(
                    "status: {:?}; phase: {}; detail: {}",
                    update_status,
                    state.last_xray_update_phase.as_deref().unwrap_or("unknown"),
                    state
                        .last_xray_update_detail
                        .as_deref()
                        .unwrap_or("no detail")
                ),
            });
        }

        let render_status = match state.last_xray_render_summary.as_ref() {
            Some(summary)
                if summary.fail_closed
                    && summary
                        .issues
                        .iter()
                        .any(|issue| issue.severity.eq_ignore_ascii_case("error")) =>
            {
                blocking_issues.push("last xray render failed closed".to_string());
                blocking_issues.extend(
                    summary
                        .issues
                        .iter()
                        .filter(|issue| issue.severity.eq_ignore_ascii_case("error"))
                        .take(3)
                        .map(|issue| {
                            format!(
                                "xray render issue on {} / {}: {}",
                                issue.route_id, issue.scope, issue.reason
                            )
                        }),
                );
                recommendations.push(
                    "Inspect render issues, route credentials, and peer endpoint data.".to_string(),
                );
                NodeApplyStageStatus::Failed
            }
            Some(summary) if summary.issue_count > 0 => {
                recommendations
                    .push("Inspect bounded Xray render issues before restart.".to_string());
                NodeApplyStageStatus::Warning
            }
            Some(_) => NodeApplyStageStatus::Ok,
            None => {
                recommendations.push("No Xray render summary is available yet.".to_string());
                NodeApplyStageStatus::Unknown
            }
        };
        stages.push(NodeApplyStageView {
            stage: "xray_render".to_string(),
            status: render_status,
            detail: state
                .last_xray_render_summary
                .as_ref()
                .map(|summary| {
                    format!(
                        "inbounds: {}, outbounds: {}, rules: {}, issues: {}, fail_closed: {}",
                        summary.inbound_count,
                        summary.outbound_count,
                        summary.routing_rule_count,
                        summary.issue_count,
                        summary.fail_closed
                    )
                })
                .unwrap_or_else(|| "no render summary".to_string()),
        });

        if state.consecutive_tick_failures > 0 {
            blocking_issues.push(format!(
                "node-agent has {} consecutive tick failure(s)",
                state.consecutive_tick_failures
            ));
            recommendations.push(
                "Inspect node last_error, panel connectivity, and route material access."
                    .to_string(),
            );
        }
    }

    if recommendations.is_empty() {
        recommendations.push("Apply flow has no immediate issues.".to_string());
    }

    let synced = node.sync_status == NodeSyncStatus::Synced
        && local_applied_revision.as_deref() == Some(generated_revision.as_str())
        && blocking_issues.is_empty();
    let panel_last_applied_revision = node.last_applied_revision.clone();
    let lifecycle = build_node_apply_lifecycle_view(
        &node,
        &generated_revision,
        panel_last_applied_revision.clone(),
        local_applied_revision.clone(),
        &recent_sync_history,
        local_state.as_ref(),
        synced,
        blocking_issues.is_empty(),
    );
    let timeline = build_node_apply_timeline(
        &lifecycle,
        &stages,
        &recent_sync_history,
        &recent_apply_results,
        local_state.as_ref(),
    );

    NodeApplyStatusView {
        node,
        generated_revision,
        panel_last_applied_revision,
        local_applied_revision,
        checked_at_unix,
        synced,
        local_state_available: local_state.is_some(),
        local_render_summary,
        recent_sync_history,
        recent_apply_results,
        lifecycle,
        stages,
        timeline,
        blocking_issues,
        recommendations,
    }
}

fn latest_reported_runtime_components(
    recent_sync_history: &[NodeSyncHistoryEntry],
    local_state_components: Option<&[NodeReportedRuntimeComponentView]>,
) -> Vec<NodeReportedRuntimeComponentView> {
    if let Some(components) = local_state_components
        && !components.is_empty()
    {
        return components.to_vec();
    }
    recent_sync_history
        .iter()
        .rev()
        .find(|entry| !entry.runtime_components.is_empty())
        .map(|entry| entry.runtime_components.clone())
        .unwrap_or_default()
}

fn latest_external_xray_validation_report<'a>(
    recent_sync_history: &'a [NodeSyncHistoryEntry],
    recent_apply_results: &'a [NodeApplyResultEntry],
    local_state: Option<&'a NodeLocalStateView>,
) -> Option<&'a XrayExternalValidationReport> {
    local_state
        .and_then(|state| state.external_xray_validation.as_ref())
        .or_else(|| {
            recent_apply_results
                .iter()
                .rev()
                .find_map(|entry| entry.external_xray_validation.as_ref())
        })
        .or_else(|| {
            recent_sync_history
                .iter()
                .rev()
                .find_map(|entry| entry.external_xray_validation.as_ref())
        })
}

fn build_node_apply_lifecycle_view(
    node: &Node,
    generated_revision: &str,
    panel_last_applied_revision: Option<String>,
    local_applied_revision: Option<String>,
    recent_sync_history: &[NodeSyncHistoryEntry],
    local_state: Option<&NodeLocalStateView>,
    synced: bool,
    has_no_blocking_issues: bool,
) -> NodeApplyLifecycleView {
    let latest_report = recent_sync_history.last();
    let latest_lifecycle_report = recent_sync_history
        .iter()
        .rev()
        .find(|entry| entry.apply_lifecycle_state.is_some());
    let latest_reported_state =
        latest_lifecycle_report.and_then(|entry| entry.apply_lifecycle_state);
    let latest_reported_at_unix = latest_report.map(|entry| entry.created_at_unix);
    let rollback_available = latest_report.is_some_and(|entry| entry.rollback_available)
        || local_state
            .and_then(|state| state.rollback_marker_path.as_ref())
            .is_some();
    let last_good_revision = latest_report
        .and_then(|entry| entry.last_good_revision.clone())
        .or_else(|| local_state.and_then(|state| state.applied_revision.clone()))
        .or_else(|| panel_last_applied_revision.clone());

    let state = if synced {
        NodeApplyLifecycleState::Applied
    } else if matches!(
        latest_reported_state,
        Some(NodeApplyLifecycleState::RolledBack)
    ) {
        NodeApplyLifecycleState::RolledBack
    } else if !has_no_blocking_issues {
        NodeApplyLifecycleState::Failed
    } else if let Some(state) = latest_reported_state {
        state
    } else if node.sync_status == NodeSyncStatus::Pending {
        NodeApplyLifecycleState::Pending
    } else if local_applied_revision.as_deref() == Some(generated_revision) {
        NodeApplyLifecycleState::Applied
    } else {
        NodeApplyLifecycleState::Unknown
    };

    let safe_to_restart = matches!(
        state,
        NodeApplyLifecycleState::Validated | NodeApplyLifecycleState::Applied
    ) && has_no_blocking_issues;

    let detail = match latest_report {
        Some(entry) => format!(
            "latest sync status: {:?}; lifecycle: {}; detail: {}",
            entry.sync_status,
            entry
                .apply_lifecycle_state
                .map(|state| format!("{state:?}"))
                .unwrap_or_else(|| "inferred".to_string()),
            entry.detail.as_deref().unwrap_or("none")
        ),
        None => "no sync history is available yet".to_string(),
    };

    NodeApplyLifecycleView {
        state,
        revision: generated_revision.to_string(),
        panel_expected_revision: generated_revision.to_string(),
        panel_last_applied_revision,
        local_applied_revision,
        last_good_revision,
        rollback_available,
        safe_to_restart,
        last_reported_at_unix: latest_reported_at_unix,
        detail,
    }
}

fn build_node_apply_timeline(
    lifecycle: &NodeApplyLifecycleView,
    stages: &[NodeApplyStageView],
    recent_sync_history: &[NodeSyncHistoryEntry],
    recent_apply_results: &[NodeApplyResultEntry],
    local_state: Option<&NodeLocalStateView>,
) -> Vec<NodeApplyTimelineItem> {
    let latest_sync_at = recent_sync_history
        .last()
        .map(|entry| entry.created_at_unix);
    let latest_apply_result = recent_apply_results.last();
    let local_sync_at = local_state.and_then(|state| state.last_sync_reported_at_unix);
    let observed_at_unix = latest_sync_at.or(local_sync_at);
    let phases = [
        (
            NodeApplyTimelineStage::FetchRuntimeConfig,
            "Node-agent fetched and persisted the least-knowledge runtime config.",
        ),
        (
            NodeApplyTimelineStage::FetchRouteCredentials,
            "Node-agent fetched required private route material.",
        ),
        (
            NodeApplyTimelineStage::RenderXrayConfig,
            "Node-agent rendered candidate xray.json.",
        ),
        (
            NodeApplyTimelineStage::ValidateXrayConfig,
            "Node-agent validated candidate xray.json with Xray before activation.",
        ),
        (
            NodeApplyTimelineStage::WriteRuntimeState,
            "Node-agent durably wrote validated runtime state and rollback material.",
        ),
        (
            NodeApplyTimelineStage::RestartXray,
            "Node-agent restarted Xray after successful validation and state write.",
        ),
        (
            NodeApplyTimelineStage::ReportSync,
            "Node-agent reported lifecycle/stages/issues to the panel.",
        ),
        (
            NodeApplyTimelineStage::ReportApplyResult,
            "Node-agent reported final idempotent apply result to the panel.",
        ),
    ];

    phases
        .into_iter()
        .map(|(phase, default_detail)| {
            let (status, detail, source) = timeline_phase_status(
                phase,
                default_detail,
                lifecycle,
                stages,
                latest_apply_result,
            );
            NodeApplyTimelineItem {
                phase,
                status,
                detail,
                source,
                observed_at_unix,
            }
        })
        .collect()
}

fn timeline_phase_status(
    phase: NodeApplyTimelineStage,
    default_detail: &str,
    lifecycle: &NodeApplyLifecycleView,
    stages: &[NodeApplyStageView],
    latest_apply_result: Option<&NodeApplyResultEntry>,
) -> (NodeApplyTimelineStatus, String, String) {
    if let Some(stage) = stages
        .iter()
        .find(|stage| stage_matches_timeline_phase(&stage.stage, phase))
    {
        let status = match stage.status {
            NodeApplyStageStatus::Ok => NodeApplyTimelineStatus::Ok,
            NodeApplyStageStatus::Warning => NodeApplyTimelineStatus::Warning,
            NodeApplyStageStatus::Failed => NodeApplyTimelineStatus::Failed,
            NodeApplyStageStatus::Unknown => NodeApplyTimelineStatus::Unknown,
        };
        return (
            status,
            stage.detail.clone(),
            format!("stage:{}", stage.stage),
        );
    }

    if phase == NodeApplyTimelineStage::ReportApplyResult
        && let Some(result) = latest_apply_result
    {
        let status = match result.status {
            NodeApplyResultStatus::Applied => NodeApplyTimelineStatus::Ok,
            NodeApplyResultStatus::Failed => NodeApplyTimelineStatus::Failed,
            NodeApplyResultStatus::RolledBack => NodeApplyTimelineStatus::Warning,
            NodeApplyResultStatus::Skipped => NodeApplyTimelineStatus::Skipped,
        };
        return (
            status,
            result
                .detail
                .clone()
                .unwrap_or_else(|| format!("latest apply result: {:?}", result.status)),
            "apply_result".to_string(),
        );
    }

    if matches!(lifecycle.state, NodeApplyLifecycleState::Failed) {
        let failed_after = lifecycle_rank(lifecycle.state);
        if timeline_phase_rank(phase) >= failed_after {
            return (
                NodeApplyTimelineStatus::Unknown,
                default_detail.to_string(),
                "lifecycle_inferred".to_string(),
            );
        }
    }

    if matches!(lifecycle.state, NodeApplyLifecycleState::RolledBack) {
        return (
            if phase == NodeApplyTimelineStage::ReportApplyResult {
                NodeApplyTimelineStatus::Warning
            } else {
                NodeApplyTimelineStatus::Unknown
            },
            default_detail.to_string(),
            "lifecycle_inferred".to_string(),
        );
    }

    let lifecycle_rank = lifecycle_rank(lifecycle.state);
    let phase_rank = timeline_phase_rank(phase);
    let status = if phase_rank < lifecycle_rank {
        NodeApplyTimelineStatus::Ok
    } else if phase_rank == lifecycle_rank
        && !matches!(
            lifecycle.state,
            NodeApplyLifecycleState::Applied | NodeApplyLifecycleState::Unknown
        )
    {
        NodeApplyTimelineStatus::Active
    } else if matches!(lifecycle.state, NodeApplyLifecycleState::Unknown) {
        NodeApplyTimelineStatus::Unknown
    } else if matches!(lifecycle.state, NodeApplyLifecycleState::Applied) {
        NodeApplyTimelineStatus::Ok
    } else {
        NodeApplyTimelineStatus::Pending
    };

    (
        status,
        default_detail.to_string(),
        "lifecycle_inferred".to_string(),
    )
}

fn stage_matches_timeline_phase(stage: &str, phase: NodeApplyTimelineStage) -> bool {
    matches!(
        (stage, phase.as_str()),
        ("route_credentials", "fetch_route_credentials")
            | ("xray_render", "render_xray_config")
            | ("xray_external_validation", "validate_xray_config")
            | ("node_reported_apply", "report_sync")
            | ("local_applied_revision", "write_runtime_state")
            | ("xray_runtime", "restart_xray")
    ) || stage == phase.as_str()
}

fn lifecycle_rank(state: NodeApplyLifecycleState) -> usize {
    match state {
        NodeApplyLifecycleState::Unknown => 0,
        NodeApplyLifecycleState::Pending => 0,
        NodeApplyLifecycleState::Downloaded => 1,
        NodeApplyLifecycleState::Rendered => 2,
        NodeApplyLifecycleState::Validated => 3,
        NodeApplyLifecycleState::Applied => 8,
        NodeApplyLifecycleState::Failed => 4,
        NodeApplyLifecycleState::RolledBack => 8,
    }
}

/// Ordinal of a stage within the timeline.
///
/// The match is exhaustive: it used to carry a `_ => 0` arm, so an unknown stage
/// silently received the rank of the earliest one and counted as completed before
/// everything else. A new stage now requires an explicit rank.
fn timeline_phase_rank(phase: NodeApplyTimelineStage) -> usize {
    match phase {
        NodeApplyTimelineStage::FetchRuntimeConfig => 0,
        NodeApplyTimelineStage::FetchRouteCredentials => 1,
        NodeApplyTimelineStage::RenderXrayConfig => 2,
        NodeApplyTimelineStage::ValidateXrayConfig => 3,
        NodeApplyTimelineStage::WriteRuntimeState => 4,
        NodeApplyTimelineStage::RestartXray => 5,
        NodeApplyTimelineStage::ReportSync => 6,
        NodeApplyTimelineStage::ReportApplyResult => 7,
    }
}

fn build_node_health_center_recommendations(summary: &NodeHealthCenterSummary) -> Vec<String> {
    let mut recommendations = Vec::new();
    if summary.total == 0 {
        recommendations.push("No nodes are configured yet.".to_string());
    }
    if summary.offline > 0 || summary.stale_heartbeat > 0 {
        recommendations.push(
            "Prioritize offline or stale-heartbeat nodes before applying new cluster changes."
                .to_string(),
        );
    }
    if summary.drifted > 0 || summary.pending > 0 {
        recommendations
            .push("Some nodes are not synced with the current generated revision.".to_string());
    }
    if summary.provisioning_failed > 0 {
        recommendations.push(
            "Review failed provisioning tasks and retry only after the failing step is fixed."
                .to_string(),
        );
    }
    if summary.provisioning_stale > 0 {
        recommendations.push(
            "Some provisioning tasks are stale. Inspect executors before starting fresh installation work."
                .to_string(),
        );
    }
    if summary.reported_apply_failed > 0 {
        recommendations.push(
            "Some nodes reported failed apply stages or render issues. Inspect apply status before retrying."
                .to_string(),
        );
    }
    if summary.runtime_alerts_active > 0 {
        recommendations.push(
            "Some nodes reported active runtime alerts. Inspect node-side Xray, sidecar, validation, and poll-loop diagnostics."
                .to_string(),
        );
    }
    if recommendations.is_empty() {
        recommendations.push("Node fleet has no immediate health-center warnings.".to_string());
    }
    recommendations
}

fn timestamp_is_stale(timestamp: Option<u64>, now: u64, max_age_seconds: u64) -> bool {
    match timestamp {
        Some(value) => now.saturating_sub(value) > max_age_seconds,
        None => true,
    }
}

fn latest_provisioning_task_by_node(
    tasks: &[NodeProvisioningTask],
) -> HashMap<String, NodeProvisioningTask> {
    let mut latest = HashMap::new();
    for task in tasks {
        latest
            .entry(task.node_id.clone())
            .and_modify(|current: &mut NodeProvisioningTask| {
                if task.created_at_unix > current.created_at_unix {
                    *current = task.clone();
                }
            })
            .or_insert_with(|| task.clone());
    }
    latest
}

fn percent_used(used: Option<u64>, total: Option<u64>) -> Option<f64> {
    match (used, total) {
        (Some(used), Some(total)) if total > 0 => Some((used as f64 / total as f64) * 100.0),
        _ => None,
    }
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("system clock before unix epoch")
        .as_secs()
}

fn parse_xray_principal_counters(data: &[u8]) -> Result<HashMap<String, u64>, String> {
    let response = serde_json::from_slice::<XrayStatsResponse>(data)
        .map_err(|_| "Xray stats response is not valid JSON".to_string())?;
    let mut counters = HashMap::new();
    for stat in response.stat {
        let Some(principal) = stat
            .name
            .strip_prefix("user>>>")
            .and_then(|value| value.split_once(">>>traffic>>>"))
            .map(|(principal, _)| principal)
            .filter(|principal| !principal.is_empty() && principal.len() <= 256)
        else {
            continue;
        };
        let value = stat
            .value
            .as_u64()
            .or_else(|| stat.value.as_str().and_then(|value| value.parse().ok()))
            .ok_or_else(|| "Xray stats counter is not an unsigned integer".to_string())?;
        let counter = counters.entry(principal.to_string()).or_insert(0_u64);
        *counter = counter.saturating_add(value);
    }
    Ok(counters)
}

fn runtime_activity_session_id(source: &str, principal: &str) -> String {
    let mut material = Vec::with_capacity(source.len() + principal.len() + 1);
    material.extend_from_slice(source.as_bytes());
    material.push(0);
    material.extend_from_slice(principal.as_bytes());
    format!("activity-{}", sha256_hex(&material))
}

fn security_settings_from_config(config: &SecurityConfig) -> SecuritySettings {
    SecuritySettings {
        login_protection_enabled: config.login_protection_enabled,
        smart_ban_enabled: config.smart_ban_enabled,
        trust_x_forwarded_for: config.proxy_trust.trust_x_forwarded_for,
        trusted_proxy_ips: config.proxy_trust.trusted_proxy_ips.clone(),
        trusted_proxy_cidrs: config.proxy_trust.trusted_proxy_cidrs.clone(),
        max_failed_attempts: config.max_failed_attempts,
        attempt_window_seconds: config.attempt_window_seconds,
        block_for_seconds: config.block_for_seconds,
        session_ttl_seconds: config.session_ttl_seconds,
    }
}

fn security_preset_settings(
    preset: SecurityPreset,
    current: &SecurityConfig,
) -> UpdateSecuritySettingsRequest {
    let (max_failed_attempts, attempt_window_seconds, block_for_seconds, session_ttl_seconds) =
        match preset {
            SecurityPreset::Standard => (5, 300, 60, 86_400),
            SecurityPreset::Strict => (3, 300, 300, 43_200),
            SecurityPreset::Paranoid => (2, 600, 900, 14_400),
        };
    UpdateSecuritySettingsRequest {
        login_protection_enabled: true,
        smart_ban_enabled: preset != SecurityPreset::Standard,
        trust_x_forwarded_for: current.proxy_trust.trust_x_forwarded_for,
        trusted_proxy_ips: current.proxy_trust.trusted_proxy_ips.clone(),
        trusted_proxy_cidrs: current.proxy_trust.trusted_proxy_cidrs.clone(),
        max_failed_attempts,
        attempt_window_seconds,
        block_for_seconds,
        session_ttl_seconds,
    }
}

