fn secret_key_readiness_from_config(config: &AppConfig) -> SecretKeyReadinessView {
    let items = vec![
        inspect_secret_key(
            SecretKeyKind::Admin,
            "HYDRA_ADMIN_SECRETS_MASTER_KEY_B64",
            &config.security.admin_secrets_key_path,
        ),
        inspect_secret_key(
            SecretKeyKind::Node,
            "HYDRA_NODE_SECRETS_MASTER_KEY_B64",
            &config.node_secrets_key_path,
        ),
        inspect_secret_key(
            SecretKeyKind::Telegram,
            "HYDRA_TELEGRAM_SECRETS_MASTER_KEY_B64",
            &config.telegram_secrets_key_path,
        ),
        inspect_secret_key(
            SecretKeyKind::RouteMaterials,
            "HYDRA_ROUTE_MATERIALS_MASTER_KEY_B64",
            &config.route_materials_key_path,
        ),
    ];
    let ready = items
        .iter()
        .all(|item| item.status != SecretKeyReadinessStatus::Invalid);
    SecretKeyReadinessView {
        ready,
        generated_at_unix: now_unix(),
        items,
    }
}

fn inspect_secret_key(
    kind: SecretKeyKind,
    env_var_name: &str,
    key_path: &str,
) -> SecretKeyReadinessItem {
    if let Ok(value) = std::env::var(env_var_name) {
        let status = validate_secret_key_b64(value.trim());
        return SecretKeyReadinessItem {
            kind,
            env_var_name: env_var_name.to_string(),
            key_path: key_path.to_string(),
            source: SecretKeySource::Environment,
            status,
            detail: secret_key_readiness_detail(status, "environment variable"),
        };
    }

    let path = Path::new(key_path);
    if path.exists() {
        let status = fs::read_to_string(path)
            .map(|value| validate_secret_key_b64(value.trim()))
            .unwrap_or(SecretKeyReadinessStatus::Invalid);
        return SecretKeyReadinessItem {
            kind,
            env_var_name: env_var_name.to_string(),
            key_path: key_path.to_string(),
            source: SecretKeySource::KeyFile,
            status,
            detail: secret_key_readiness_detail(status, "key file"),
        };
    }

    SecretKeyReadinessItem {
        kind,
        env_var_name: env_var_name.to_string(),
        key_path: key_path.to_string(),
        source: SecretKeySource::KeyFilePending,
        status: SecretKeyReadinessStatus::Pending,
        detail: "key file does not exist yet; it will be generated on first use".to_string(),
    }
}

fn validate_secret_key_b64(value: &str) -> SecretKeyReadinessStatus {
    match BASE64.decode(value.as_bytes()) {
        Ok(decoded) if decoded.len() == 32 => SecretKeyReadinessStatus::Ready,
        _ => SecretKeyReadinessStatus::Invalid,
    }
}

fn secret_key_readiness_detail(status: SecretKeyReadinessStatus, source: &str) -> String {
    match status {
        SecretKeyReadinessStatus::Ready => format!("{source} contains a valid 32-byte master key"),
        SecretKeyReadinessStatus::Pending => format!("{source} is pending"),
        SecretKeyReadinessStatus::Invalid => {
            format!("{source} must contain base64-encoded 32-byte key material")
        }
    }
}

fn validate_system_thresholds(
    settings: &UpdateSystemThresholdsRequest,
) -> Result<(), SecurityError> {
    validate_threshold_pair(
        settings.disk_warning_percent,
        settings.disk_critical_percent,
        "disk",
    )?;
    validate_threshold_pair(
        settings.memory_warning_percent,
        settings.memory_critical_percent,
        "memory",
    )?;
    Ok(())
}

fn validate_threshold_pair(
    warning_percent: u8,
    critical_percent: u8,
    field_name: &'static str,
) -> Result<(), SecurityError> {
    if warning_percent == 0 || warning_percent > 100 {
        return Err(SecurityError::InvalidSecuritySettings(match field_name {
            "disk" => "disk_warning_percent must be between 1 and 100",
            _ => "memory_warning_percent must be between 1 and 100",
        }));
    }
    if critical_percent == 0 || critical_percent > 100 {
        return Err(SecurityError::InvalidSecuritySettings(match field_name {
            "disk" => "disk_critical_percent must be between 1 and 100",
            _ => "memory_critical_percent must be between 1 and 100",
        }));
    }
    if critical_percent <= warning_percent {
        return Err(SecurityError::InvalidSecuritySettings(match field_name {
            "disk" => "disk_critical_percent must be greater than disk_warning_percent",
            _ => "memory_critical_percent must be greater than memory_warning_percent",
        }));
    }
    Ok(())
}

