fn subscription_session_enforcement_view(
    action: &SubscriptionSessionEnforcementRecord,
) -> SubscriptionSessionEnforcementView {
    SubscriptionSessionEnforcementView {
        action_id: action.action_id.clone(),
        session_id: action.session_id.clone(),
        action: action.action,
        status: action.status,
        reason: action.reason.clone(),
        required_adapter: action.required_adapter,
        runtime_session_ref_present: action.runtime_session_ref_hmac_sha256.is_some(),
        requires_absence_verification: action.requires_absence_verification,
        issued_at_unix: action.issued_at_unix,
        updated_at_unix: action.updated_at_unix,
        detail: action.detail.clone(),
    }
}

fn validate_subscription_session_observation(
    observation: &SubscriptionSessionObservation,
) -> Result<(), SecurityError> {
    if observation.session_id.trim().is_empty() || observation.session_id.len() > 128 {
        return Err(SecurityError::InvalidSecuritySettings(
            "session id must be between 1 and 128 characters",
        ));
    }
    if observation.runtime_username.trim().is_empty() || observation.runtime_username.len() > 256 {
        return Err(SecurityError::InvalidSecuritySettings(
            "runtime username must be between 1 and 256 characters",
        ));
    }
    if observation
        .runtime_session_ref
        .as_deref()
        .is_some_and(|value| value.trim().is_empty() || value.len() > 256)
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "runtime session reference must not be empty or exceed 256 characters",
        ));
    }
    if observation
        .device_fingerprint
        .as_deref()
        .is_some_and(|value| value.trim().is_empty() || value.len() > 512)
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "device fingerprint must not be empty or exceed 512 characters",
        ));
    }
    if observation
        .source_ip
        .as_deref()
        .is_some_and(|value| value.trim().is_empty() || value.len() > 128)
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "source IP must not be empty or exceed 128 characters",
        ));
    }
    Ok(())
}

fn validate_subscription_session_report_capabilities(
    observation_source: SubscriptionSessionObservationSource,
    runtime_capabilities: &[SubscriptionSessionRuntimeCapability],
) -> Result<(), SecurityError> {
    if observation_source != SubscriptionSessionObservationSource::NodeManagedRuntimeTable {
        return Err(SecurityError::InvalidSecuritySettings(
            "unsupported session observation source",
        ));
    }
    if runtime_capabilities.len() > 8 {
        return Err(SecurityError::InvalidSecuritySettings(
            "session runtime capability list exceeds limit",
        ));
    }
    let unique: HashSet<_> = runtime_capabilities.iter().copied().collect();
    if unique.len() != runtime_capabilities.len() {
        return Err(SecurityError::InvalidSecuritySettings(
            "session runtime capability list contains duplicates",
        ));
    }
    if runtime_capabilities
        .contains(&SubscriptionSessionRuntimeCapability::PrincipalWideTerminationOnly)
        && runtime_capabilities
            .contains(&SubscriptionSessionRuntimeCapability::ExactSessionTermination)
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "principal-wide-only and exact termination capabilities conflict",
        ));
    }
    Ok(())
}

fn validate_subscription_session_enforcement_result(
    request: &ReportSubscriptionSessionEnforcementResultRequest,
) -> Result<(), SecurityError> {
    if request.action_id.trim().is_empty() || request.action_id.len() > 128 {
        return Err(SecurityError::InvalidSecuritySettings(
            "enforcement action id must be between 1 and 128 characters",
        ));
    }
    if request.session_id.trim().is_empty() || request.session_id.len() > 128 {
        return Err(SecurityError::InvalidSecuritySettings(
            "session id must be between 1 and 128 characters",
        ));
    }
    if request
        .detail
        .as_deref()
        .is_some_and(|detail| detail.len() > 512)
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "enforcement result detail must not exceed 512 characters",
        ));
    }
    if request
        .runtime_session_ref
        .as_deref()
        .is_some_and(|value| value.trim().is_empty() || value.len() > 256)
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "runtime session reference must not be empty or exceed 256 characters",
        ));
    }
    Ok(())
}

fn validate_subscription_access_policy_shape(
    policy: &SubscriptionClientNodeAccessPolicy,
) -> Result<(), SecurityError> {
    if policy.allow_all_nodes && (!policy.node_ids.is_empty() || !policy.cluster_ids.is_empty()) {
        return Err(SecurityError::InvalidSecuritySettings(
            "subscription access policy cannot allow all nodes and list explicit nodes or clusters",
        ));
    }
    if policy.allow_all_protocols && !policy.protocols.is_empty() {
        return Err(SecurityError::InvalidSecuritySettings(
            "subscription access policy cannot allow all protocols and list explicit protocols",
        ));
    }
    validate_resource_ids(&policy.node_ids, "node ids")?;
    validate_resource_ids(&policy.cluster_ids, "cluster ids")?;
    validate_resource_ids(&policy.protocols, "protocols")?;
    for protocol in &policy.protocols {
        validate_protocol(protocol)?;
    }
    if !policy.allow_all_nodes && policy.node_ids.is_empty() && policy.cluster_ids.is_empty() {
        return Err(SecurityError::InvalidSecuritySettings(
            "subscription access policy must include at least one node or cluster",
        ));
    }
    if !policy.allow_all_protocols && policy.protocols.is_empty() {
        return Err(SecurityError::InvalidSecuritySettings(
            "subscription access policy must include at least one protocol when protocol filtering is enabled",
        ));
    }
    Ok(())
}

fn resolve_subscription_usage_window(
    query: SubscriptionUsageQuery,
    now: u64,
) -> Result<(SubscriptionUsageWindowPreset, u64, u64), SecurityError> {
    let window = query.window.unwrap_or(SubscriptionUsageWindowPreset::Day1);
    let to_unix = query.to_unix.unwrap_or(now);
    let from_unix = match window {
        SubscriptionUsageWindowPreset::Hours12 => to_unix.saturating_sub(12 * 60 * 60),
        SubscriptionUsageWindowPreset::Day1 => to_unix.saturating_sub(24 * 60 * 60),
        SubscriptionUsageWindowPreset::Days3 => to_unix.saturating_sub(3 * 24 * 60 * 60),
        SubscriptionUsageWindowPreset::Week1 => to_unix.saturating_sub(7 * 24 * 60 * 60),
        SubscriptionUsageWindowPreset::Month1 => to_unix.saturating_sub(30 * 24 * 60 * 60),
        SubscriptionUsageWindowPreset::Months3 => to_unix.saturating_sub(90 * 24 * 60 * 60),
        SubscriptionUsageWindowPreset::Custom => {
            query
                .from_unix
                .ok_or(SecurityError::InvalidSecuritySettings(
                    "custom subscription usage window requires from_unix",
                ))?
        }
    };
    if from_unix > to_unix {
        return Err(SecurityError::InvalidSecuritySettings(
            "subscription usage window from_unix must be before to_unix",
        ));
    }
    Ok((window, from_unix, to_unix))
}

fn validate_subscription_client_public_state(
    client: &SubscriptionCatalogClient,
) -> Result<(), SecurityError> {
    if matches!(
        client.status,
        SubscriptionCatalogClientStatus::Disabled
            | SubscriptionCatalogClientStatus::Expired
            | SubscriptionCatalogClientStatus::Revoked
    ) || client.revoked_at_unix.is_some()
    {
        return Err(SecurityError::Unauthorized);
    }
    if let Some(expire_at_unix) = client.expire_at_unix
        && expire_at_unix <= now_unix()
    {
        return Err(SecurityError::Unauthorized);
    }
    Ok(())
}

fn subscription_client_runtime_username(client: &SubscriptionCatalogClient) -> String {
    format!("catalog/{}", client.id)
}

fn subscription_client_device_runtime_username(
    client: &SubscriptionCatalogClient,
    device: &SubscriptionClientDevice,
) -> String {
    format!("catalog/{}/device/{}", client.id, device.id)
}

fn parse_subscription_runtime_username(value: &str) -> Option<(&str, Option<&str>)> {
    let value = value.strip_prefix("catalog/")?;
    if let Some((client_id, device_id)) = value.split_once("/device/") {
        if client_id.is_empty()
            || device_id.is_empty()
            || client_id.contains('/')
            || device_id.contains('/')
        {
            return None;
        }
        Some((client_id, Some(device_id)))
    } else if !value.is_empty() && !value.contains('/') {
        Some((value, None))
    } else {
        None
    }
}

fn subscription_host_allowed(host: &Host, policy: &SubscriptionClientNodeAccessPolicy) -> bool {
    if policy.allow_all_nodes {
        return true;
    }
    host.node_id
        .as_ref()
        .is_some_and(|node_id| policy.node_ids.iter().any(|allowed| allowed == node_id))
        || host.cluster_id.as_ref().is_some_and(|cluster_id| {
            policy
                .cluster_ids
                .iter()
                .any(|allowed| allowed == cluster_id)
        })
}

fn subscription_inbound_allowed(
    inbound: &Inbound,
    policy: &SubscriptionClientNodeAccessPolicy,
) -> bool {
    subscription_protocol_allowed(&inbound.protocol, policy)
        && (policy.allow_all_nodes
            || inbound
                .node_id
                .as_ref()
                .is_some_and(|node_id| policy.node_ids.iter().any(|allowed| allowed == node_id))
            || inbound.cluster_id.as_ref().is_some_and(|cluster_id| {
                policy
                    .cluster_ids
                    .iter()
                    .any(|allowed| allowed == cluster_id)
            }))
}

fn subscription_protocol_allowed(
    protocol: &str,
    policy: &SubscriptionClientNodeAccessPolicy,
) -> bool {
    policy.allow_all_protocols || policy.protocols.iter().any(|allowed| allowed == protocol)
}

fn subscription_proxy_profile_allowed(
    profile: &ProxyProfile,
    policy: &SubscriptionClientNodeAccessPolicy,
) -> bool {
    subscription_protocol_allowed(proxy_type_protocol(profile.proxy_type), policy)
}

fn generated_subscription_proxy_profiles(
    profile: ProxyProfile,
    client: &SubscriptionCatalogClient,
    subscription_devices: &[SubscriptionClientDevice],
) -> Vec<GeneratedProxyProfile> {
    if profile.proxy_type != ProxyType::Wireguard {
        let generated = GeneratedProxyProfile {
            id: profile.id,
            name: profile.name,
            proxy_type: proxy_type_protocol(profile.proxy_type).to_string(),
            settings_json: profile.settings_json,
        };
        return vec![generated_runtime_proxy_profile(
            generated,
            &subscription_client_runtime_username(client),
            &client.subscription_token,
        )];
    }

    let mut devices = subscription_devices
        .iter()
        .filter(|device| {
            device.client_id == client.id
                && device.status == SubscriptionDeviceStatus::Active
                && device.wireguard_public_key.is_some()
                && !device.wireguard_allowed_ips.is_empty()
        })
        .collect::<Vec<_>>();
    devices.sort_by(|left, right| left.id.cmp(&right.id));
    devices
        .into_iter()
        .filter_map(|device| {
            generated_subscription_proxy_profile_for_device(profile.clone(), client, device)
        })
        .collect()
}

fn generated_subscription_proxy_profile_for_device(
    profile: ProxyProfile,
    client: &SubscriptionCatalogClient,
    device: &SubscriptionClientDevice,
) -> Option<GeneratedProxyProfile> {
    if device.client_id != client.id || device.status != SubscriptionDeviceStatus::Active {
        return None;
    }
    let serde_json::Value::Object(mut settings) =
        serde_json::from_str::<serde_json::Value>(&profile.settings_json).ok()?
    else {
        return None;
    };
    for key in [
        "id",
        "uuid",
        "password",
        "auth",
        "auth_password",
        "public_key",
        "peer_public_key",
        "allowed_ips",
        "device_fingerprint",
        "runtime_username",
        "device_id",
    ] {
        settings.remove(key);
    }
    let runtime_username = subscription_client_device_runtime_username(client, device);
    settings.insert(
        "runtime_username".to_string(),
        serde_json::Value::String(runtime_username.clone()),
    );
    settings.insert(
        "device_id".to_string(),
        serde_json::Value::String(device.id.clone()),
    );
    match profile.proxy_type {
        // VLESS is now the only protocol with a UUID identifier and Hysteria2 the
        // only one with a password. The arms are kept as arms rather than collapsed
        // into direct checks: they widen again naturally if protocols return.
        ProxyType::Vless => {
            settings.insert(
                "id".to_string(),
                serde_json::Value::String(runtime_client_uuid(
                    &runtime_username,
                    &client.subscription_token,
                )),
            );
        }
        ProxyType::Hysteria2 => {
            let protocol = proxy_type_protocol(profile.proxy_type);
            settings.insert(
                "password".to_string(),
                serde_json::Value::String(runtime_client_password(
                    protocol,
                    &runtime_username,
                    &client.subscription_token,
                )),
            );
        }
        ProxyType::Wireguard => {
            let public_key = device.wireguard_public_key.as_deref()?;
            if device.wireguard_allowed_ips.is_empty() {
                return None;
            }
            settings.insert(
                "peer_public_key".to_string(),
                serde_json::Value::String(public_key.to_string()),
            );
            settings.insert(
                "allowed_ips".to_string(),
                serde_json::Value::Array(
                    device
                        .wireguard_allowed_ips
                        .iter()
                        .cloned()
                        .map(serde_json::Value::String)
                        .collect(),
                ),
            );
            settings.insert(
                "device_fingerprint".to_string(),
                serde_json::Value::String(wireguard_device_fingerprint(public_key)),
            );
        }
    }
    Some(GeneratedProxyProfile {
        id: format!("{}:device:{}", profile.id, device.id),
        name: format!(
            "{} / {}",
            profile.name,
            device.label.as_deref().unwrap_or(device.id.as_str())
        ),
        proxy_type: proxy_type_protocol(profile.proxy_type).to_string(),
        settings_json: serde_json::Value::Object(settings).to_string(),
    })
}

fn generated_runtime_proxy_profile(
    profile: GeneratedProxyProfile,
    runtime_username: &str,
    subscription_token: &str,
) -> GeneratedProxyProfile {
    let Ok(serde_json::Value::Object(mut settings)) =
        serde_json::from_str::<serde_json::Value>(&profile.settings_json)
    else {
        return profile;
    };
    settings.insert(
        "runtime_username".to_string(),
        serde_json::Value::String(runtime_username.to_string()),
    );
    match profile.proxy_type.as_str() {
        "vless" => {
            settings.remove("uuid");
            settings.insert(
                "id".to_string(),
                serde_json::Value::String(runtime_client_uuid(
                    runtime_username,
                    subscription_token,
                )),
            );
        }
        "hysteria2" => {
            settings.insert(
                "password".to_string(),
                serde_json::Value::String(runtime_client_password(
                    &profile.proxy_type,
                    runtime_username,
                    subscription_token,
                )),
            );
        }
        _ => {}
    }
    GeneratedProxyProfile {
        settings_json: serde_json::Value::Object(settings).to_string(),
        ..profile
    }
}

fn proxy_type_protocol(proxy_type: ProxyType) -> &'static str {
    match proxy_type {
        ProxyType::Vless => "vless",
        ProxyType::Hysteria2 => "hysteria2",
        ProxyType::Wireguard => "wireguard",
    }
}

fn subscription_endpoint_reason(
    allowed: bool,
    node_id: Option<&str>,
    cluster_id: Option<&str>,
    protocol: Option<&str>,
    policy: &SubscriptionClientNodeAccessPolicy,
) -> String {
    if let Some(protocol) = protocol
        && !subscription_protocol_allowed(protocol, policy)
    {
        return format!(
            "denied because protocol is not allowed by subscription policy: {protocol}"
        );
    }
    if policy.allow_all_nodes {
        return "allowed because policy allows all nodes".to_string();
    }
    if let Some(node_id) = node_id
        && policy.node_ids.iter().any(|allowed| allowed == node_id)
    {
        return format!("allowed by node access policy: {node_id}");
    }
    if let Some(cluster_id) = cluster_id
        && policy
            .cluster_ids
            .iter()
            .any(|allowed| allowed == cluster_id)
    {
        return format!("allowed by cluster access policy: {cluster_id}");
    }
    if node_id.is_none() && cluster_id.is_none() {
        return if allowed {
            "allowed as unbound endpoint".to_string()
        } else {
            "denied because explicit policy excludes unbound endpoints".to_string()
        };
    }
    "denied because endpoint binding does not match access policy".to_string()
}

fn subscription_client_status_to_user_status(
    status: SubscriptionCatalogClientStatus,
) -> UserStatus {
    match status {
        SubscriptionCatalogClientStatus::Active => UserStatus::Active,
        SubscriptionCatalogClientStatus::Disabled => UserStatus::Disabled,
        SubscriptionCatalogClientStatus::Expired => UserStatus::Expired,
        SubscriptionCatalogClientStatus::Revoked => UserStatus::Disabled,
    }
}

fn validate_username(username: &str) -> Result<(), SecurityError> {
    if username.starts_with("catalog/") {
        return Err(SecurityError::InvalidSecuritySettings(
            "username prefix catalog/ is reserved for subscription runtime principals",
        ));
    }
    if username.is_empty() || username.len() > 64 {
        return Err(SecurityError::InvalidSecuritySettings(
            "username must be between 1 and 64 characters",
        ));
    }
    if !username
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-' | '.'))
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "username contains unsupported characters",
        ));
    }
    Ok(())
}

fn validate_note(note: Option<&str>) -> Result<(), SecurityError> {
    if let Some(note) = note
        && note.len() > 1024
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "note must be at most 1024 characters",
        ));
    }
    Ok(())
}

fn validate_create_inbound_request(request: &CreateInboundRequest) -> Result<(), SecurityError> {
    validate_tag(&request.tag, "inbound tag")?;
    validate_protocol(&request.protocol)?;
    validate_inbound_protocol_mode(&request.protocol, request.network, request.tls_enabled)?;
    validate_port(request.port)?;
    validate_optional_resource_id(request.node_id.as_deref(), "node id")?;
    validate_optional_resource_id(request.cluster_id.as_deref(), "cluster id")?;
    Ok(())
}

fn validate_update_inbound_request(request: &UpdateInboundRequest) -> Result<(), SecurityError> {
    if let Some(protocol) = request.protocol.as_deref() {
        validate_protocol(protocol)?;
    }
    if let Some(port) = request.port {
        validate_port(port)?;
    }
    if let (Some(protocol), Some(network), Some(tls_enabled)) = (
        request.protocol.as_deref(),
        request.network,
        request.tls_enabled,
    ) {
        validate_inbound_protocol_mode(protocol, network, tls_enabled)?;
    }
    validate_optional_resource_id(request.node_id.as_deref(), "node id")?;
    validate_optional_resource_id(request.cluster_id.as_deref(), "cluster id")?;
    Ok(())
}

fn validate_create_host_request(request: &CreateHostRequest) -> Result<(), SecurityError> {
    validate_resource_name(&request.remark, "host remark")?;
    validate_host_address(&request.address)?;
    validate_port(request.port)?;
    validate_optional_path(request.path.as_deref())?;
    validate_optional_sni(request.sni.as_deref())?;
    validate_optional_resource_id(request.node_id.as_deref(), "node id")?;
    validate_optional_resource_id(request.cluster_id.as_deref(), "cluster id")?;
    Ok(())
}

fn validate_update_host_request(request: &UpdateHostRequest) -> Result<(), SecurityError> {
    if let Some(remark) = request.remark.as_deref() {
        validate_resource_name(remark, "host remark")?;
    }
    if let Some(address) = request.address.as_deref() {
        validate_host_address(address)?;
    }
    if let Some(port) = request.port {
        validate_port(port)?;
    }
    validate_optional_path(request.path.as_deref())?;
    validate_optional_sni(request.sni.as_deref())?;
    validate_optional_resource_id(request.node_id.as_deref(), "node id")?;
    validate_optional_resource_id(request.cluster_id.as_deref(), "cluster id")?;
    Ok(())
}

fn validate_create_proxy_profile_request(
    request: &CreateProxyProfileRequest,
) -> Result<(), SecurityError> {
    validate_resource_name(&request.name, "proxy profile name")?;
    validate_json_blob(&request.settings_json, "proxy settings_json")?;
    validate_excluded_inbound_tags(&request.excluded_inbound_tags)?;
    Ok(())
}

fn validate_update_proxy_profile_request(
    request: &UpdateProxyProfileRequest,
) -> Result<(), SecurityError> {
    if let Some(name) = request.name.as_deref() {
        validate_resource_name(name, "proxy profile name")?;
    }
    if let Some(settings_json) = request.settings_json.as_deref() {
        validate_json_blob(settings_json, "proxy settings_json")?;
    }
    if let Some(tags) = request.excluded_inbound_tags.as_ref() {
        validate_excluded_inbound_tags(tags)?;
    }
    Ok(())
}

fn validate_tag(value: &str, field_name: &'static str) -> Result<(), SecurityError> {
    if value.is_empty() || value.len() > 64 {
        return Err(SecurityError::InvalidSecuritySettings(match field_name {
            "inbound tag" => "inbound tag must be between 1 and 64 characters",
            _ => "tag must be between 1 and 64 characters",
        }));
    }
    if !value
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-' | '.'))
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "tag contains unsupported characters",
        ));
    }
    Ok(())
}

fn validate_protocol(value: &str) -> Result<(), SecurityError> {
    let capabilities = protocol_capabilities_view();
    let Some(capability) = capabilities
        .capabilities
        .iter()
        .find(|capability| capability.protocol == value)
    else {
        return Err(SecurityError::InvalidSecuritySettings(
            "protocol is not supported",
        ));
    };
    if protocol_runtime_disabled_reason(capability).is_some() {
        return Err(SecurityError::InvalidSecuritySettings(
            "protocol runtime is not production-ready",
        ));
    }
    Ok(())
}

fn validate_inbound_protocol_mode(
    protocol: &str,
    network: InboundTransport,
    tls_enabled: bool,
) -> Result<(), SecurityError> {
    let security = if tls_enabled {
        ProtocolSecurityMode::Tls
    } else {
        ProtocolSecurityMode::None
    };
    let capabilities = protocol_capabilities_view();
    let Some(capability) = capabilities
        .capabilities
        .iter()
        .find(|capability| capability.protocol == protocol)
    else {
        return Err(SecurityError::InvalidSecuritySettings(
            "protocol is not supported",
        ));
    };
    if protocol_runtime_disabled_reason(capability).is_some() {
        return Err(SecurityError::InvalidSecuritySettings(
            "protocol runtime is not production-ready",
        ));
    }
    if capability
        .modes
        .iter()
        .any(|mode| mode.production_ready && mode.transport == network && mode.security == security)
    {
        return Ok(());
    }
    Err(SecurityError::InvalidSecuritySettings(
        "protocol, network, and TLS combination is not production-ready",
    ))
}

/// Typical deployment scenarios.
///
/// Each points at a capability matrix row rather than duplicating it. The test
/// `deployment_scenarios_reference_production_capability_rows` prevents a scenario
/// from advertising a combination the matrix does not have or has not marked
/// production-ready.
fn deployment_scenarios() -> Vec<DeploymentScenario> {
    vec![
        DeploymentScenario {
            id: DeploymentScenarioId::DirectMaxStealth,
            title: "Direct connection, maximum stealth".to_string(),
            protocol: "vless".to_string(),
            transport: InboundTransport::Xhttp,
            security: ProtocolSecurityMode::Reality,
            flow: Some(VlessFlow::XtlsRprxVision),
            xhttp_mode: Some(XhttpMode::StreamOne),
            cdn_compatible: false,
            recommended: true,
            rationale: "Reality hides the handshake and defeats active probing; \
                        XHTTP hides the connection profile that follows it. \
                        Cost: stream-one is the slowest XHTTP mode."
                .to_string(),
        },
        DeploymentScenario {
            id: DeploymentScenarioId::DirectMaxThroughput,
            title: "Direct connection, maximum throughput".to_string(),
            protocol: "vless".to_string(),
            transport: InboundTransport::Tcp,
            security: ProtocolSecurityMode::Reality,
            flow: Some(VlessFlow::XtlsRprxVision),
            xhttp_mode: None,
            cdn_compatible: false,
            recommended: false,
            rationale: "Vision over TCP splices on Linux and is markedly cheaper on \
                        CPU, which matters at 1 vCPU. Cost: the post-handshake \
                        connection profile is not disguised."
                .to_string(),
        },
        DeploymentScenario {
            id: DeploymentScenarioId::BehindCdn,
            title: "Behind a CDN".to_string(),
            protocol: "vless".to_string(),
            transport: InboundTransport::Xhttp,
            security: ProtocolSecurityMode::Tls,
            // Vision is incompatible with packet-up, which a CDN forces.
            flow: None,
            xhttp_mode: Some(XhttpMode::PacketUp),
            cdn_compatible: true,
            recommended: false,
            rationale: "packet-up is the only mode guaranteed to pass through a CDN \
                        or Nginx. Reality does not apply there because the \
                        intermediary terminates TLS, and Vision is incompatible \
                        with packet-up."
                .to_string(),
        },
    ]
}

fn protocol_capabilities_view() -> ProtocolCapabilitiesView {
    let mut capabilities = vec![
        protocol_capability(
            "vless",
            "VLESS",
            ProtocolSupportStatus::Production,
            true,
            ProtocolRuntimeOwner::Xray,
            vec!["xray"],
            Vec::new(),
            vec![
                protocol_mode(InboundTransport::Tcp, ProtocolSecurityMode::None, true),
                protocol_mode(InboundTransport::Tcp, ProtocolSecurityMode::Tls, true),
                // Reality over TCP: Vision splices on Linux here and is markedly
                // cheaper on CPU, which matters at 1 vCPU. This row was missing even
                // though it is the most common Reality deployment; the scenario
                // consistency test found the gap.
                protocol_mode(InboundTransport::Tcp, ProtocolSecurityMode::Reality, true)
                    .with_note(
                        "flow xtls-rprx-vision splices on Linux; cheapest CPU profile of the Reality options",
                    ),
                protocol_mode(InboundTransport::Ws, ProtocolSecurityMode::Tls, true)
                    .requires_domain()
                    .requires_path(),
                protocol_mode(InboundTransport::Grpc, ProtocolSecurityMode::Tls, true)
                    .requires_domain(),
                protocol_mode(
                    InboundTransport::HttpUpgrade,
                    ProtocolSecurityMode::Tls,
                    false,
                )
                .requires_domain()
                .requires_path()
                .with_note("renderer compatibility still needs production tests"),
                protocol_mode(InboundTransport::Quic, ProtocolSecurityMode::Tls, false)
                    .with_note("QUIC support remains renderer-gated"),
                // XHTTP covers the layer Reality does not: the connection profile
                // after the handshake. The two are complementary, not competing.
                protocol_mode(InboundTransport::Xhttp, ProtocolSecurityMode::Reality, true)
                    .requires_path()
                    .with_note(
                        "mode stream-one; auto resolves to it under Reality; the only mode compatible with flow xtls-rprx-vision",
                    ),
                protocol_mode(InboundTransport::Xhttp, ProtocolSecurityMode::Tls, true)
                    .requires_domain()
                    .requires_path()
                    .with_note(
                        "mode packet-up behind a CDN or Nginx; Reality and Vision are both unavailable there",
                    ),
            ],
        ),
        protocol_capability(
            "hysteria2",
            "Hysteria2",
            ProtocolSupportStatus::Production,
            false,
            ProtocolRuntimeOwner::Sidecar,
            vec!["hysteria"],
            vec!["tls_certificate", "hysteria_auth_secret"],
            vec![
                protocol_mode(InboundTransport::Quic, ProtocolSecurityMode::Tls, true)
                    .requires_domain()
                    .requires_secret_material()
                    .with_note(
                        "requires node-agent sidecar lifecycle and accepted executor session",
                    ),
            ],
        ),
        protocol_capability(
            "wireguard",
            "WireGuard",
            ProtocolSupportStatus::Production,
            false,
            ProtocolRuntimeOwner::NodeNative,
            vec!["wg", "wg-quick"],
            vec!["wireguard_private_key", "wireguard_peer_key"],
            vec![
                protocol_mode(InboundTransport::Udp, ProtocolSecurityMode::MutualTls, true)
                    .requires_secret_material()
                    .with_note(
                        "requires node-agent WireGuard lifecycle and accepted executor session",
                    ),
            ],
        ),
    ];
    for capability in &mut capabilities {
        capability.disabled_reason = protocol_runtime_disabled_reason(capability);
    }
    ProtocolCapabilitiesView {
        schema_version: SchemaId::ProtocolCapabilities.version(),
        deployment_scenarios: deployment_scenarios(),
        runtime_components: protocol_runtime_components_view(),
        capabilities,
    }
}

