/// A persisted-file read failure.
///
/// Carries the path and the cause: when startup is refused the operator must see
/// which file failed and where, rather than guess why the panel came up empty.
#[derive(Debug, Clone)]
pub struct PersistedFileError {
    pub path: String,
    pub kind: PersistedFileErrorKind,
}

#[derive(Debug, Clone)]
pub enum PersistedFileErrorKind {
    /// The file exists but does not read: permissions, bad media, a directory.
    Unreadable(String),
    /// The file was read but did not parse. The serde message carries line and column.
    Malformed(String),
}

impl std::fmt::Display for PersistedFileError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match &self.kind {
            PersistedFileErrorKind::Unreadable(detail) => {
                write!(formatter, "cannot read {}: {detail}", self.path)
            }
            PersistedFileErrorKind::Malformed(detail) => write!(
                formatter,
                "{} is corrupt or incompatible: {detail}. It will not be replaced \
                 with an empty file — repair or remove it deliberately",
                self.path
            ),
        }
    }
}

impl std::error::Error for PersistedFileError {}

/// Reads persisted JSON, keeping three cases apart.
///
/// - no file -> `Ok(None)`, a normal first run;
/// - unreadable file -> `Err(Unreadable)`;
/// - unparsable file -> `Err(Malformed)`, **never** a default.
///
/// All three used to collapse into an empty struct: one incompatible record
/// silently destroyed the whole file, including entries unrelated to it.
///
/// Returning `Result` leaves the decision to the caller. Today every call comes
/// from startup and decides "refuse to start"; if reload-without-restart appears,
/// its caller will handle the same error differently and nothing here changes.
fn read_persisted_json<T: serde::de::DeserializeOwned>(
    path: &str,
) -> Result<Option<T>, PersistedFileError> {
    let data = match fs::read(path) {
        Ok(data) => data,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => {
            return Err(PersistedFileError {
                path: path.to_string(),
                kind: PersistedFileErrorKind::Unreadable(error.to_string()),
            });
        }
    };

    serde_json::from_slice::<T>(&data)
        .map(Some)
        .map_err(|error| PersistedFileError {
            path: path.to_string(),
            kind: PersistedFileErrorKind::Malformed(error.to_string()),
        })
}

fn load_telegram_settings(
    path: &str,
    secrets_key_path: &str,
) -> Result<PersistedTelegramSettings, PersistedFileError> {
    let Some(mut settings) = read_persisted_json::<PersistedTelegramSettings>(path)? else {
        return Ok(default_telegram_settings());
    };
    if settings
        .bot_token
        .as_deref()
        .is_some_and(|value| !value.trim().is_empty())
    {
        settings.bot_token = normalize_optional_secret(settings.bot_token);
        return Ok(settings);
    }
    if settings.bot_token_ciphertext_b64.is_some() || settings.bot_token_nonce_b64.is_some() {
        // The token is encrypted but did not decrypt: silently returning settings
        // without it would quietly disable notifications.
        let master_key =
            load_or_create_telegram_secret_master_key(secrets_key_path).map_err(|_| {
                PersistedFileError {
                    path: secrets_key_path.to_string(),
                    kind: PersistedFileErrorKind::Unreadable(
                        "cannot obtain the Telegram secrets master key".to_string(),
                    ),
                }
            })?;
        let token = decrypt_persisted_secret(
            None,
            settings.bot_token_ciphertext_b64.as_deref(),
            settings.bot_token_nonce_b64.as_deref(),
            &master_key,
        )
        .map_err(|_| PersistedFileError {
            path: path.to_string(),
            kind: PersistedFileErrorKind::Malformed("cannot decrypt the bot token".to_string()),
        })?;
        settings.bot_token = normalize_optional_secret(Some(token));
    }
    Ok(settings)
}

fn compact_telegram_events(events: Vec<TelegramEvent>) -> Vec<TelegramEvent> {
    let mut compacted = Vec::<TelegramEvent>::new();
    for event in events {
        if let Some(existing) = compacted
            .iter_mut()
            .find(|existing| !existing.id.is_empty() && existing.id == event.id)
        {
            *existing = event;
        } else {
            compacted.push(event);
        }
    }
    compacted
}

fn persist_telegram_settings(
    path: &str,
    secrets_key_path: &str,
    settings: &PersistedTelegramSettings,
) -> Result<(), SecurityError> {
    let master_key = load_or_create_telegram_secret_master_key(secrets_key_path)?;
    let path = PathBuf::from(path);
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        create_secret_dir_all(parent)?;
    }

    let temp_path = temp_settings_path(&path);
    let mut persisted = settings.clone();
    if let Some(token) = normalize_optional_secret(persisted.bot_token.take()) {
        let encrypted = encrypt_persisted_secret(&token, &master_key)?;
        persisted.bot_token_ciphertext_b64 = Some(encrypted.ciphertext_b64);
        persisted.bot_token_nonce_b64 = Some(encrypted.nonce_b64);
    } else {
        persisted.bot_token_ciphertext_b64 = None;
        persisted.bot_token_nonce_b64 = None;
    }
    let data =
        serde_json::to_vec_pretty(&persisted).map_err(|_| SecurityError::PersistenceFailure)?;
    replace_file_durably(&temp_path, &path, &data)?;
    secure_route_material_permissions(&path)?;
    Ok(())
}

