fn persist_subscription_catalog(
    path: &str,
    runtime: &SubscriptionCatalogRuntime,
) -> Result<(), SecurityError> {
    let path = PathBuf::from(path);
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        create_secret_dir_all(parent)?;
    }

    let mut plans: Vec<_> = runtime.plans.values().cloned().collect();
    plans.sort_by(|left, right| left.name.cmp(&right.name).then(left.id.cmp(&right.id)));
    let mut clients: Vec<_> = runtime.clients.values().cloned().collect();
    clients.sort_by(|left, right| left.name.cmp(&right.name).then(left.id.cmp(&right.id)));
    let mut devices: Vec<_> = runtime.devices.values().cloned().collect();
    devices.sort_by(|left, right| {
        left.client_id
            .cmp(&right.client_id)
            .then(left.id.cmp(&right.id))
    });
    let mut enrollment_grants: Vec<_> = runtime.enrollment_grants.values().cloned().collect();
    enrollment_grants.sort_by(|left, right| {
        left.client_id
            .cmp(&right.client_id)
            .then(right.created_at_unix.cmp(&left.created_at_unix))
            .then(left.id.cmp(&right.id))
    });
    let payload = PersistedSubscriptionCatalog {
        plans,
        clients,
        devices,
        enrollment_grants,
    };

    let temp_path = temp_settings_path(&path);
    let data =
        serde_json::to_vec_pretty(&payload).map_err(|_| SecurityError::PersistenceFailure)?;
    replace_file_durably(&temp_path, &path, &data)?;
    Ok(())
}

fn load_subscription_usage(
    path: &str,
    max_usage_points: usize,
) -> Result<PersistedSubscriptionUsage, PersistedFileError> {
    let mut usage = read_persisted_json::<PersistedSubscriptionUsage>(path)?
        .unwrap_or(PersistedSubscriptionUsage { points: Vec::new() });
    compact_subscription_usage_points(&mut usage.points, max_usage_points);
    Ok(usage)
}

fn persist_subscription_usage(
    path: &str,
    runtime: &SubscriptionCatalogRuntime,
) -> Result<(), SecurityError> {
    let path = PathBuf::from(path);
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        create_secret_dir_all(parent)?;
    }

    let mut points = runtime
        .usage_points
        .iter()
        .map(|record| PersistedSubscriptionUsagePoint {
            client_id: record.client_id.clone(),
            point: record.point.clone(),
        })
        .collect::<Vec<_>>();
    points.sort_by(|left, right| {
        left.point
            .at_unix
            .cmp(&right.point.at_unix)
            .then(left.client_id.cmp(&right.client_id))
    });
    let payload = PersistedSubscriptionUsage { points };

    let temp_path = temp_settings_path(&path);
    let data =
        serde_json::to_vec_pretty(&payload).map_err(|_| SecurityError::PersistenceFailure)?;
    write_secret_temp_file(&temp_path, &data)?;
    fs::rename(&temp_path, &path).map_err(|_| SecurityError::PersistenceFailure)?;
    Ok(())
}

fn compact_subscription_usage_points(
    points: &mut Vec<PersistedSubscriptionUsagePoint>,
    max_usage_points: usize,
) {
    points.sort_by(|left, right| {
        left.point
            .at_unix
            .cmp(&right.point.at_unix)
            .then(left.client_id.cmp(&right.client_id))
    });
    let max_items = max_usage_points.max(1);
    if points.len() > max_items {
        let overflow = points.len().saturating_sub(max_items);
        points.drain(0..overflow);
    }
}

