#[derive(Debug, serde::Serialize, serde::Deserialize)]
struct PersistedNodesFile {
    nodes: Vec<serde_json::Value>,
}

fn load_nodes(path: &str, node_secrets_key_path: &str) -> Result<Vec<Node>, PersistedFileError> {
    let Some(mut nodes) = read_persisted_json::<PersistedNodesFile>(path)? else {
        return Ok(Vec::new());
    };
    // The master key is created when absent, so a failure here is a real access
    // problem rather than a first run.
    let master_key =
        load_or_create_node_secret_master_key(node_secrets_key_path).map_err(|_| {
            PersistedFileError {
                path: node_secrets_key_path.to_string(),
                kind: PersistedFileErrorKind::Unreadable(
                    "cannot obtain the node secrets master key".to_string(),
                ),
            }
        })?;
    Ok(nodes
        .nodes
        .iter_mut()
        .filter_map(|node| persisted_node_value_to_node(node, &master_key).ok())
        .collect())
}

fn persisted_node_value_to_node(
    value: &mut serde_json::Value,
    master_key: &[u8; 32],
) -> Result<Node, SecurityError> {
    let object = value
        .as_object_mut()
        .ok_or(SecurityError::PersistenceFailure)?;
    if !object.contains_key("auth_token_hash") {
        object.insert(
            "auth_token_hash".to_string(),
            serde_json::Value::String(hash_node_auth_token(&generate_token())),
        );
    }

    let legacy_token = object
        .remove("local_api_token")
        .and_then(|value| value.as_str().map(str::to_string));
    let ciphertext = object
        .remove("local_api_token_ciphertext_b64")
        .and_then(|value| value.as_str().map(str::to_string));
    let nonce = object
        .remove("local_api_token_nonce_b64")
        .and_then(|value| value.as_str().map(str::to_string));
    let local_api_token = if legacy_token
        .as_deref()
        .is_some_and(|value| !value.trim().is_empty())
    {
        normalize_optional_secret(legacy_token)
    } else if ciphertext.is_some() || nonce.is_some() {
        normalize_optional_secret(Some(decrypt_persisted_secret(
            None,
            ciphertext.as_deref(),
            nonce.as_deref(),
            master_key,
        )?))
    } else {
        None
    };
    object.insert(
        "local_api_token".to_string(),
        local_api_token
            .clone()
            .map(serde_json::Value::String)
            .unwrap_or(serde_json::Value::Null),
    );
    object.insert(
        "local_api_token_configured".to_string(),
        serde_json::Value::Bool(local_api_token.is_some()),
    );

    serde_json::from_value::<Node>(value.clone()).map_err(|_| SecurityError::PersistenceFailure)
}

fn persisted_node_value_from_node(
    node: &Node,
    master_key: &[u8; 32],
) -> Result<serde_json::Value, SecurityError> {
    let mut value = serde_json::to_value(node).map_err(|_| SecurityError::PersistenceFailure)?;
    let object = value
        .as_object_mut()
        .ok_or(SecurityError::PersistenceFailure)?;
    object.insert(
        "auth_token_hash".to_string(),
        serde_json::Value::String(node.auth_token_hash.clone()),
    );
    object.remove("local_api_token");
    if let Some(token) = node.local_api_token.as_deref() {
        let encrypted = encrypt_persisted_secret(token, master_key)?;
        object.insert(
            "local_api_token_ciphertext_b64".to_string(),
            serde_json::Value::String(encrypted.ciphertext_b64),
        );
        object.insert(
            "local_api_token_nonce_b64".to_string(),
            serde_json::Value::String(encrypted.nonce_b64),
        );
        object.insert(
            "local_api_token_configured".to_string(),
            serde_json::Value::Bool(true),
        );
    } else {
        object.insert(
            "local_api_token_configured".to_string(),
            serde_json::Value::Bool(false),
        );
    }
    Ok(value)
}

