fn persist_node_provisioning_tasks(
    path: &str,
    runtime: &ProvisioningRuntime,
    max_tasks: usize,
) -> Result<(), SecurityError> {
    let path = PathBuf::from(path);
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        create_secret_dir_all(parent)?;
    }

    let mut tasks: Vec<_> = runtime.tasks.values().cloned().collect();
    tasks.sort_by(|left, right| {
        let left_active = node_provisioning_task_is_active(left);
        let right_active = node_provisioning_task_is_active(right);
        right_active
            .cmp(&left_active)
            .then(right.updated_at_unix.cmp(&left.updated_at_unix))
            .then(left.task_id.cmp(&right.task_id))
    });
    tasks.truncate(max_tasks.max(1));
    tasks.sort_by_key(|task| std::cmp::Reverse(task.created_at_unix));
    let mut executors: Vec<_> = runtime.executors.values().cloned().collect();
    executors.sort_by(|left, right| left.executor_id.cmp(&right.executor_id));
    let payload = PersistedNodeProvisioningTasks {
        tasks,
        executors,
        executor_submissions: runtime.executor_submissions.clone(),
    };

    let temp_path = temp_settings_path(&path);
    let data =
        serde_json::to_vec_pretty(&payload).map_err(|_| SecurityError::PersistenceFailure)?;
    replace_file_durably(&temp_path, &path, &data)?;
    Ok(())
}

fn apply_persisted_admin(mut config: AppConfig) -> AppConfig {
    let path = Path::new(&config.security.admin_path);
    if let Ok(data) = fs::read(path)
        && let Ok(admin) = serde_json::from_slice::<PersistedAdmin>(&data)
    {
        let two_factor_secret = decrypt_persisted_admin_two_factor_secret(
            &admin,
            &config.security.admin_secrets_key_path,
        );
        config.security.bootstrap_admin.username = Some(admin.username);
        config.security.bootstrap_admin.password = None;
        config.security.bootstrap_admin.password_hash = Some(admin.password_hash);
        config.security.bootstrap_admin.two_factor_secret_base32 = two_factor_secret;
        config.security.bootstrap_admin.two_factor_enabled = admin.two_factor_enabled;
        config.security.bootstrap_admin.two_factor_two_step_enabled =
            admin.two_factor_two_step_enabled;
        config.security.bootstrap_admin.two_factor_confirmed_at_unix =
            admin.two_factor_confirmed_at_unix;
        return config;
    }

    let Some(username) = config.security.bootstrap_admin.username.clone() else {
        return config;
    };

    if config.security.bootstrap_admin.password_hash.is_none() {
        let Some(password) = config.security.bootstrap_admin.password.clone() else {
            return config;
        };
        let Some(hash) = hash_password(&password) else {
            return config;
        };
        config.security.bootstrap_admin.password_hash = Some(hash);
        config.security.bootstrap_admin.password = None;
    }

    if let Some(password_hash) = config.security.bootstrap_admin.password_hash.clone() {
        let admin = PersistedAdmin {
            username,
            password_hash,
            created_at_unix: now_unix(),
            two_factor_secret_base32: config
                .security
                .bootstrap_admin
                .two_factor_secret_base32
                .clone(),
            two_factor_secret_ciphertext_b64: None,
            two_factor_secret_nonce_b64: None,
            two_factor_enabled: config.security.bootstrap_admin.two_factor_enabled,
            two_factor_two_step_enabled: config
                .security
                .bootstrap_admin
                .two_factor_two_step_enabled,
            two_factor_confirmed_at_unix: config
                .security
                .bootstrap_admin
                .two_factor_confirmed_at_unix,
        };
        let _ = persist_admin(
            &config.security.admin_path,
            &config.security.admin_secrets_key_path,
            &admin,
        );
    }

    config
}

fn temp_settings_path(path: &Path) -> PathBuf {
    let mut temp = path.to_path_buf();
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .map(|name| format!("{name}.tmp"))
        .unwrap_or_else(|| "security-settings.tmp".to_string());
    temp.set_file_name(file_name);
    temp
}

fn decrypt_persisted_admin_two_factor_secret(
    admin: &PersistedAdmin,
    secrets_key_path: &str,
) -> Option<String> {
    if admin
        .two_factor_secret_base32
        .as_deref()
        .is_some_and(|value| !value.trim().is_empty())
    {
        return normalize_optional_secret(admin.two_factor_secret_base32.clone());
    }
    if admin.two_factor_secret_ciphertext_b64.is_none()
        && admin.two_factor_secret_nonce_b64.is_none()
    {
        return None;
    }
    let master_key = load_or_create_admin_secret_master_key(secrets_key_path).ok()?;
    decrypt_persisted_secret(
        None,
        admin.two_factor_secret_ciphertext_b64.as_deref(),
        admin.two_factor_secret_nonce_b64.as_deref(),
        &master_key,
    )
    .ok()
    .and_then(|secret| normalize_optional_secret(Some(secret)))
}

fn persist_admin(
    path: &str,
    secrets_key_path: &str,
    admin: &PersistedAdmin,
) -> Result<(), SecurityError> {
    let master_key = load_or_create_admin_secret_master_key(secrets_key_path)?;
    let path = PathBuf::from(path);
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        create_secret_dir_all(parent)?;
    }

    let temp_path = temp_settings_path(&path);
    let mut persisted = admin.clone();
    if let Some(secret) = normalize_optional_secret(persisted.two_factor_secret_base32.take()) {
        let encrypted = encrypt_persisted_secret(&secret, &master_key)?;
        persisted.two_factor_secret_ciphertext_b64 = Some(encrypted.ciphertext_b64);
        persisted.two_factor_secret_nonce_b64 = Some(encrypted.nonce_b64);
    } else {
        persisted.two_factor_secret_ciphertext_b64 = None;
        persisted.two_factor_secret_nonce_b64 = None;
    }
    let data =
        serde_json::to_vec_pretty(&persisted).map_err(|_| SecurityError::PersistenceFailure)?;
    replace_file_durably(&temp_path, &path, &data)?;
    Ok(())
}

fn build_persisted_admin(config: &SecurityConfig) -> Result<PersistedAdmin, SecurityError> {
    Ok(PersistedAdmin {
        username: config
            .bootstrap_admin
            .username
            .clone()
            .ok_or(SecurityError::AdminNotConfigured)?,
        password_hash: config
            .bootstrap_admin
            .password_hash
            .clone()
            .ok_or(SecurityError::AdminNotConfigured)?,
        created_at_unix: now_unix(),
        two_factor_secret_base32: config.bootstrap_admin.two_factor_secret_base32.clone(),
        two_factor_secret_ciphertext_b64: None,
        two_factor_secret_nonce_b64: None,
        two_factor_enabled: config.bootstrap_admin.two_factor_enabled,
        two_factor_two_step_enabled: config.bootstrap_admin.two_factor_two_step_enabled,
        two_factor_confirmed_at_unix: config.bootstrap_admin.two_factor_confirmed_at_unix,
    })
}

fn append_audit_event_to_file(path: &str, event: &AuditEvent) -> Result<(), SecurityError> {
    append_ndjson_line(path, event)
}

fn append_ndjson_line<T: serde::Serialize>(path: &str, value: &T) -> Result<(), SecurityError> {
    let path = PathBuf::from(path);
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        create_secret_dir_all(parent)?;
    }

    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .map_err(|_| SecurityError::PersistenceFailure)?;
    let line = serde_json::to_string(value).map_err(|_| SecurityError::PersistenceFailure)?;
    writeln!(file, "{line}").map_err(|_| SecurityError::PersistenceFailure)?;
    Ok(())
}

fn read_ndjson_lines<T>(path: &str, max_items: usize) -> Vec<T>
where
    T: serde::de::DeserializeOwned,
{
    let Ok(content) = fs::read_to_string(path) else {
        return Vec::new();
    };

    let mut items: Vec<T> = content
        .lines()
        .filter(|line| !line.trim().is_empty())
        .filter_map(|line| serde_json::from_str::<T>(line).ok())
        .collect();

    if items.len() > max_items {
        items = items.split_off(items.len() - max_items);
    }

    items
}

fn persist_core_config(path: &str, config_text: &str) -> Result<(), SecurityError> {
    let path = PathBuf::from(path);
    if let Some(parent) = path.parent()
        && !parent.as_os_str().is_empty()
    {
        create_secret_dir_all(parent)?;
    }
    let temp_path = temp_settings_path(&path);
    replace_file_durably(&temp_path, &path, config_text.as_bytes())?;
    Ok(())
}

fn validate_core_config_json(config_text: &str) -> Result<(), SecurityError> {
    serde_json::from_str::<serde_json::Value>(config_text)
        .map(|_| ())
        .map_err(|_| SecurityError::InvalidSecuritySettings("core config must be valid JSON"))
}

async fn attempt_telegram_delivery(event: &mut TelegramEvent, bot_token: &str, chat_id: &str) {
    event.attempt_count = event.attempt_count.saturating_add(1);
    event.target_chat_id = Some(chat_id.to_string());
    event.next_retry_at_unix = None;
    match send_telegram_message(bot_token, chat_id, &event.message).await {
        Ok(()) => {
            event.status = TelegramEventStatus::Delivered;
            event.last_error = None;
            event.delivered_at_unix = Some(now_unix());
        }
        Err(error) => {
            event.last_error = Some(sanitize_telegram_event_text(&error));
            event.delivered_at_unix = None;
            if event.attempt_count >= TELEGRAM_MAX_DELIVERY_ATTEMPTS {
                event.status = TelegramEventStatus::Failed;
                event.next_retry_at_unix = None;
            } else {
                event.status = TelegramEventStatus::RetryScheduled;
                event.next_retry_at_unix =
                    Some(now_unix() + telegram_retry_delay_seconds(event.attempt_count));
            }
        }
    }
}

fn telegram_retry_delay_seconds(attempt_count: u8) -> u64 {
    match attempt_count {
        0 | 1 => 30,
        2 => 120,
        3 => 600,
        _ => 1_800,
    }
}

fn telegram_alert_policy_blocker(
    settings: &PersistedTelegramSettings,
    events: &[TelegramEvent],
    context: TelegramAlertContext,
    now: u64,
) -> Option<String> {
    let policy = &settings.alert_policy;
    if !policy.enabled {
        return Some("alert delivery is disabled by alert policy".to_string());
    }
    if context.status == AlertEventStatus::Activated && !policy.notify_on_activation {
        return Some("alert activation delivery is disabled by alert policy".to_string());
    }
    if context.status == AlertEventStatus::Resolved && !policy.notify_on_resolution {
        return Some("alert resolution delivery is disabled by alert policy".to_string());
    }
    if severity_rank(context.severity) < severity_rank(policy.min_severity) {
        return Some("alert severity is below alert policy minimum".to_string());
    }
    if !policy.included_alert_kinds.contains(&context.kind) {
        return Some("alert kind is excluded by alert policy".to_string());
    }
    if let Some(last_sent_at) = latest_matching_alert_notification_at(events, context)
        && now.saturating_sub(last_sent_at) < policy.cooldown_seconds
    {
        return Some("alert delivery suppressed by alert policy cooldown".to_string());
    }
    None
}

fn latest_matching_alert_notification_at(
    events: &[TelegramEvent],
    context: TelegramAlertContext,
) -> Option<u64> {
    events
        .iter()
        .rev()
        .find(|event| {
            event.alert_kind == Some(context.kind)
                && event.alert_status == Some(context.status)
                && event.status != TelegramEventStatus::Skipped
        })
        .map(|event| event.created_at_unix)
}

fn severity_rank(severity: AlertSeverity) -> u8 {
    match severity {
        AlertSeverity::Warning => 1,
        AlertSeverity::Critical => 2,
    }
}

fn validate_alert_notification_policy(
    policy: &AlertNotificationPolicy,
) -> Result<(), SecurityError> {
    if policy.cooldown_seconds > 86_400 {
        return Err(SecurityError::InvalidSecuritySettings(
            "telegram alert policy cooldown_seconds must be <= 86400",
        ));
    }
    Ok(())
}

async fn send_telegram_message(
    bot_token: &str,
    chat_id: &str,
    message: &str,
) -> Result<(), String> {
    let url = format!("https://api.telegram.org/bot{bot_token}/sendMessage");
    let response = reqwest::Client::new()
        .post(url)
        .json(&serde_json::json!({
            "chat_id": chat_id,
            "text": message,
            "disable_web_page_preview": true
        }))
        .send()
        .await
        .map_err(|error| format!("telegram request failed: {error}"))?;
    let status = response.status();
    if status.is_success() {
        Ok(())
    } else {
        Err(format!("telegram api returned HTTP {status}"))
    }
}

fn build_xray_config_document(generated: &GeneratedCoreConfigPreview) -> XrayConfigDocument {
    let inbounds: Vec<XrayInboundDocument> = generated
        .inbounds
        .iter()
        .map(|inbound| {
            let clients = generated
                .users
                .iter()
                .filter(|user| {
                    user.inbounds
                        .iter()
                        .any(|candidate| candidate.tag == inbound.tag)
                })
                .map(|user| {
                    let material = generated_profile_client_material(user, inbound);
                    XrayInboundClientDocument {
                        username: user.username.clone(),
                        data_limit_bytes: user.data_limit_bytes,
                        expire_at_unix: user.expire_at_unix,
                        subscription_token: user.subscription_token.clone(),
                        credential_id: material
                            .as_ref()
                            .and_then(|settings| string_json_setting(settings, &["id", "uuid"])),
                        credential_password: material.as_ref().and_then(|settings| {
                            string_json_setting(settings, &["password", "auth", "auth_password"])
                        }),
                        credential_method: material
                            .as_ref()
                            .and_then(|settings| string_json_setting(settings, &["method"])),
                    }
                })
                .collect();

            XrayInboundDocument {
                tag: inbound.tag.clone(),
                port: inbound.port,
                protocol: inbound.protocol.clone(),
                network: format!("{:?}", inbound.network).to_ascii_lowercase(),
                tls_enabled: inbound.tls_enabled,
                stream_settings: xray_stream_settings_for_inbound(inbound, generated),
                security_settings: xray_security_settings_for_inbound(inbound, generated),
                clients,
            }
        })
        .collect();

    let hosts = generated
        .hosts
        .iter()
        .map(|host| XrayHostDocument {
            id: host.id.clone(),
            remark: host.remark.clone(),
            address: host.address.clone(),
            port: host.port,
            path: host.path.clone(),
            sni: host.sni.clone(),
            security: host.security.clone(),
        })
        .collect::<Vec<_>>();

    let outbounds = generated
        .users
        .iter()
        .flat_map(|user| user.proxy_profiles.iter())
        .map(|profile| XrayOutboundDocument {
            tag: format!("proxy-{}", profile.id),
            protocol: profile.proxy_type.clone(),
            transport: "proxy_profile".to_string(),
            settings_json: profile.settings_json.clone(),
        })
        .collect::<Vec<_>>();

    let user_bindings = generated
        .users
        .iter()
        .map(|user| XrayUserBindingDocument {
            username: user.username.clone(),
            inbound_tags: user
                .inbounds
                .iter()
                .map(|inbound| inbound.tag.clone())
                .collect(),
            host_ids: user.hosts.iter().map(|host| host.id.clone()).collect(),
            outbound_tags: user
                .proxy_profiles
                .iter()
                .map(|profile| format!("proxy-{}", profile.id))
                .collect(),
            policy_level: 0,
        })
        .collect::<Vec<_>>();

    let dns = XrayDnsConfigDocument {
        strategy: "prefer_ipv4".to_string(),
        hosts: hosts
            .iter()
            .map(|host| XrayDnsHostOverride {
                domain: host.sni.clone().unwrap_or_else(|| host.address.clone()),
                address: host.address.clone(),
            })
            .collect(),
        servers: vec![
            XrayDnsServer {
                address: "1.1.1.1".to_string(),
                domains: vec!["geosite:geolocation-!cn".to_string()],
            },
            XrayDnsServer {
                address: "8.8.8.8".to_string(),
                domains: vec!["geosite:global".to_string()],
            },
        ],
    };

    let routing = XrayRoutingConfigDocument {
        domain_strategy: "AsIs".to_string(),
        rules: vec![
            XrayRoutingRule {
                name: "block-private".to_string(),
                rule_type: "field".to_string(),
                domains: vec!["geoip:private".to_string()],
                outbound_tag: "block".to_string(),
            },
            XrayRoutingRule {
                name: "default-direct".to_string(),
                rule_type: "field".to_string(),
                domains: vec!["geosite:geolocation-!cn".to_string()],
                outbound_tag: "direct".to_string(),
            },
        ],
    };

    let policy = XrayPolicyConfigDocument {
        levels: vec![XrayPolicyLevel {
            level: 0,
            handshake_seconds: 4,
            conn_idle_seconds: 300,
            uplink_only_seconds: 2,
            downlink_only_seconds: 5,
        }],
        system: XrayPolicySystem {
            stats_inbound_uplink: true,
            stats_inbound_downlink: true,
            stats_outbound_uplink: true,
            stats_outbound_downlink: true,
        },
    };

    let nodes = generated
        .nodes
        .iter()
        .map(|node| XrayNodeDocument {
            id: node.id.clone(),
            name: node.name.clone(),
            address: node.address.clone(),
            api_port: node.api_port,
            enabled: node.enabled,
            usage_coefficient: node.usage_coefficient,
        })
        .collect();

    let clusters = generated
        .clusters
        .iter()
        .map(|cluster| XrayClusterDocument {
            id: cluster.id.clone(),
            name: cluster.name.clone(),
            status: cluster.status.clone(),
            revision: cluster.revision.clone(),
            controlled_egress: cluster.controlled_egress,
            failover_enabled: cluster.failover_enabled,
            paths: cluster
                .paths
                .iter()
                .map(|path| XrayClusterPathDocument {
                    hops: path
                        .hops
                        .iter()
                        .map(|hop| XrayClusterHopDocument {
                            cluster_node_id: hop.cluster_node_id.clone(),
                            node_id: hop.node_id.clone(),
                            role: format!("{:?}", hop.role).to_ascii_lowercase(),
                        })
                        .collect(),
                })
                .collect(),
        })
        .collect();

    let cluster_node_targets = generated
        .cluster_node_targets
        .iter()
        .map(|target| XrayClusterNodeTargetDocument {
            node_id: target.node_id.clone(),
            cluster_id: target.cluster_id.clone(),
            cluster_name: target.cluster_name.clone(),
            cluster_revision: target.cluster_revision.clone(),
            cluster_node_id: target.cluster_node_id.clone(),
            role: format!("{:?}", target.role).to_ascii_lowercase(),
            upstream_node_ids: target.upstream_node_ids.clone(),
            downstream_node_ids: target.downstream_node_ids.clone(),
            route_edge_ids: target.route_edge_ids.clone(),
        })
        .collect();

    let raw_config = build_raw_xray_config(&inbounds, &outbounds, &routing, &policy);
    let raw_config_validation =
        validate_raw_xray_config(&raw_config, &cdn_fronted_inbound_tags(generated));

    XrayConfigDocument {
        generated_at_unix: generated.generated_at_unix,
        revision: generated.revision.clone(),
        raw_config_validation,
        raw_config,
        dns,
        routing,
        policy,
        inbounds,
        outbounds,
        hosts,
        user_bindings,
        nodes,
        clusters,
        cluster_node_targets,
    }
}

fn generated_profile_client_material(
    user: &GeneratedUserConfig,
    inbound: &Inbound,
) -> Option<serde_json::Value> {
    user.proxy_profiles
        .iter()
        .filter(|profile| profile.proxy_type.eq_ignore_ascii_case(&inbound.protocol))
        .filter_map(|profile| {
            let settings =
                serde_json::from_str::<serde_json::Value>(&profile.settings_json).ok()?;
            generated_profile_allows_inbound(&settings, &inbound.tag).then_some(settings)
        })
        .next()
}

fn generated_profile_allows_inbound(settings: &serde_json::Value, inbound_tag: &str) -> bool {
    if let Some(inbounds) = settings
        .get("inbounds")
        .and_then(serde_json::Value::as_array)
    {
        let configured = inbounds
            .iter()
            .filter_map(serde_json::Value::as_str)
            .collect::<Vec<_>>();
        if !configured.is_empty() {
            return configured.contains(&inbound_tag);
        }
    }
    settings
        .get("inbound")
        .and_then(serde_json::Value::as_str)
        .is_none_or(|candidate| candidate == inbound_tag)
}

fn string_json_setting(settings: &serde_json::Value, names: &[&str]) -> Option<String> {
    names.iter().find_map(|name| {
        settings
            .get(*name)
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
    })
}

fn build_xray_config_document_from_runtime_config_document(
    runtime_config: &NodeRuntimeConfigDocument,
) -> XrayConfigDocument {
    let generated_at_unix = runtime_config.generated_at_unix;
    let generated = GeneratedCoreConfigPreview {
        generated_at_unix,
        revision: runtime_config.revision.clone(),
        users: runtime_config.config.users.clone(),
        inbounds: runtime_config.config.inbounds.clone(),
        hosts: runtime_config.config.hosts.clone(),
        nodes: runtime_config
            .config
            .nodes
            .iter()
            .map(|node| Node {
                id: node.node_id.clone(),
                name: node.name.clone(),
                address: node.address.clone(),
                port: node.port.unwrap_or_default(),
                api_port: node.api_port.unwrap_or_default(),
                usage_coefficient: 1.0,
                enabled: node.enabled,
                auth_token_hash: String::new(),
                auth_token_issued_at_unix: None,
                local_api_token: None,
                local_api_token_configured: false,
                xray_version: None,
                node_version: None,
                status: NodeStatus::Unknown,
                sync_status: NodeSyncStatus::Unknown,
                provisioning_status: NodeProvisioningStatus::None,
                last_applied_revision: None,
                last_registered_at_unix: None,
                last_heartbeat_at_unix: None,
                last_agent_heartbeat_at_unix: None,
                last_metrics_at_unix: None,
                reported_memory_used_bytes: None,
                reported_memory_total_bytes: None,
                reported_disk_used_bytes: None,
                reported_disk_total_bytes: None,
                last_sync_at_unix: None,
                created_at_unix: generated_at_unix,
                updated_at_unix: generated_at_unix,
            })
            .collect(),
        clusters: Vec::new(),
        cluster_node_targets: Vec::new(),
        node_route_assignments: runtime_config.route_assignments.clone(),
    };
    let mut document = build_xray_config_document(&generated);
    if !runtime_config.contract.valid {
        for issue in &runtime_config.contract.issues {
            push_xray_validation_issue(
                &mut document.raw_config_validation.issues,
                &format!("runtime_config.{}", issue.scope),
                &issue.severity,
                &issue.reason,
            );
        }
        document.raw_config_validation.issue_count = document.raw_config_validation.issues.len();
        document.raw_config_validation.valid = document
            .raw_config_validation
            .issues
            .iter()
            .all(|issue| issue.severity != "error");
    }
    document
}

fn build_node_runtime_xray_render_summary(
    runtime_config: &NodeRuntimeConfigDocument,
    xray_config: &XrayConfigDocument,
) -> XrayRenderSummaryView {
    let mut feature_flags = vec![
        format!("runtime_config_schema_v{}", runtime_config.schema_version),
        "least_knowledge".to_string(),
    ];
    if !runtime_config.route_assignments.is_empty() {
        feature_flags.push("route_assignments".to_string());
    }
    if !runtime_config.credential_refs.is_empty() {
        feature_flags.push("credential_refs".to_string());
    }

    let mut issues = runtime_config
        .contract
        .issues
        .iter()
        .map(|issue| XrayRenderIssueView {
            route_id: "runtime_config".to_string(),
            scope: issue.scope.clone(),
            severity: issue.severity.clone(),
            reason: issue.reason.clone(),
        })
        .collect::<Vec<_>>();
    issues.extend(
        xray_config
            .raw_config_validation
            .issues
            .iter()
            .map(|issue| build_xray_render_issue_from_raw_validation(issue, xray_config))
            .collect::<Vec<_>>(),
    );

    XrayRenderSummaryView {
        renderer_version: 1,
        source_revision: runtime_config.revision.clone(),
        xray_detected_version: None,
        feature_flags,
        inbound_count: xray_config.inbounds.len(),
        outbound_count: xray_config.outbounds.len(),
        routing_rule_count: xray_config.routing.rules.len(),
        fail_closed: true,
        issue_count: issues.len(),
        issues,
        created_at_unix: now_unix(),
    }
}

fn build_node_runtime_validation_report(
    apply_plan: &NodeAgentApplyPlan,
    route_credential_status: &NodeRouteCredentialStatusView,
    render_summary: &XrayRenderSummaryView,
    xray_config: &XrayConfigDocument,
    external_validation: Option<&XrayExternalValidationReport>,
) -> NodeRuntimeValidationReport {
    let mut issues = Vec::new();
    for component in &apply_plan.runtime_components {
        if !component.production_ready || component.disabled_reason.is_some() {
            issues.push(NodeRuntimeValidationIssue {
                scope: format!("runtime_components.{}", component.component.as_str()),
                severity: "error".to_string(),
                reason: component
                    .disabled_reason
                    .clone()
                    .unwrap_or_else(|| "runtime component is not production-ready".to_string()),
            });
        }
    }
    if !route_credential_status.safe_to_apply {
        issues.push(NodeRuntimeValidationIssue {
            scope: "route_credentials".to_string(),
            severity: "error".to_string(),
            reason: route_credential_status.detail.clone(),
        });
    }
    for issue in &render_summary.issues {
        issues.push(NodeRuntimeValidationIssue {
            scope: format!("render.{}.{}", issue.route_id, issue.scope),
            severity: issue.severity.clone(),
            reason: issue.reason.clone(),
        });
    }
    if !xray_config.raw_config_validation.valid {
        for issue in &xray_config.raw_config_validation.issues {
            issues.push(NodeRuntimeValidationIssue {
                scope: format!("xray_raw.{}", issue.path),
                severity: issue.severity.clone(),
                reason: issue.reason.clone(),
            });
        }
    }
    match external_validation {
        Some(report) if report.status == XrayExternalValidationStatus::Failed => {
            issues.push(NodeRuntimeValidationIssue {
                scope: "xray_external_validation".to_string(),
                severity: "error".to_string(),
                reason: report.detail.clone(),
            });
        }
        Some(report) if report.status == XrayExternalValidationStatus::Skipped => {
            issues.push(NodeRuntimeValidationIssue {
                scope: "xray_external_validation".to_string(),
                severity: "warning".to_string(),
                reason: report.detail.clone(),
            });
        }
        Some(_) => {}
        None => {
            issues.push(NodeRuntimeValidationIssue {
                scope: "xray_external_validation".to_string(),
                severity: "warning".to_string(),
                reason:
                    "node-agent has not reported external Xray validation for this runtime config"
                        .to_string(),
            });
        }
    }
    let valid = issues.iter().all(|issue| issue.severity != "error");
    NodeRuntimeValidationReport {
        schema_version: SchemaId::NodeRuntimeValidation.version(),
        generated_at_unix: now_unix(),
        valid,
        fail_closed: true,
        safe_to_restart: valid
            && apply_plan.safe_restart_after_successful_validation
            && route_credential_status.safe_to_apply
            && xray_config.raw_config_validation.valid
            && external_validation
                .is_some_and(|report| report.status == XrayExternalValidationStatus::Passed),
        issue_count: issues.len(),
        issues,
    }
}

fn build_xray_render_issue_from_raw_validation(
    issue: &XrayRawConfigValidationIssue,
    xray_config: &XrayConfigDocument,
) -> XrayRenderIssueView {
    if let Some(index) = parse_raw_xray_inbound_index(&issue.path)
        && let Some(inbound) = xray_config.inbounds.get(index)
    {
        return XrayRenderIssueView {
            route_id: inbound.tag.clone(),
            scope: format!(
                "xray.inbound[{index}].{}.{}",
                inbound.protocol,
                raw_xray_path_tail(&issue.path, index)
            ),
            severity: issue.severity.clone(),
            reason: issue.reason.clone(),
        };
    }

    XrayRenderIssueView {
        route_id: "xray".to_string(),
        scope: issue
            .path
            .strip_prefix("$.")
            .unwrap_or(&issue.path)
            .to_string(),
        severity: issue.severity.clone(),
        reason: issue.reason.clone(),
    }
}

fn parse_raw_xray_inbound_index(path: &str) -> Option<usize> {
    let rest = path.strip_prefix("$.inbounds[")?;
    let index = rest.split_once(']')?.0;
    index.parse().ok()
}

fn raw_xray_path_tail(path: &str, inbound_index: usize) -> String {
    let prefix = format!("$.inbounds[{inbound_index}].");
    path.strip_prefix(&prefix)
        .unwrap_or(path)
        .trim_start_matches('.')
        .to_string()
}

/// Enum values for the contract: exactly what serde puts on the wire.
///
/// The list comes from `T::ALL` and the string from the serialization itself, so
/// the declared value and the actual one agree by construction rather than by the
/// discipline of editing two lists.
fn enum_values<T: Serialize>(all: &'static [T]) -> Vec<String> {
    all.iter()
        .map(|variant| match serde_json::to_value(variant) {
            Ok(serde_json::Value::String(value)) => value,
            other => unreachable!("a unit enum variant must serialize to a string, got {other:?}"),
        })
        .collect()
}

impl SubscriptionCatalogRuntime {
    /// Catalog summary: counters only, no collections leave the process.
    ///
    /// One linear pass over each of the four maps. No allocations: the counts go
    /// into a struct on the stack.
    fn ui_summary(&self, now: u64) -> UiSubscriptionsSummary {
        let mut summary = UiSubscriptionsSummary {
            plans_total: self.plans.len(),
            clients_total: self.clients.len(),
            devices_total: self.devices.len(),
            ..UiSubscriptionsSummary::default()
        };

        for client in self.clients.values() {
            match client.status {
                SubscriptionCatalogClientStatus::Active => summary.clients_active += 1,
                SubscriptionCatalogClientStatus::Disabled => summary.clients_disabled += 1,
                SubscriptionCatalogClientStatus::Expired => summary.clients_expired += 1,
                SubscriptionCatalogClientStatus::Revoked => summary.clients_revoked += 1,
            }

            if client.status != SubscriptionCatalogClientStatus::Active {
                continue;
            }

            if let Some(expire_at) = client.expire_at_unix
                && expire_at > now
                && expire_at - now <= SUBSCRIPTION_EXPIRY_WARNING_WINDOW_SECONDS
            {
                summary.clients_expiring_within_day += 1;
            }

            if let Some(limit) = client.data_limit_bytes
                && limit > 0
                && client.used_traffic_bytes >= limit
            {
                summary.clients_data_limit_reached += 1;
            }
        }

        for device in self.devices.values() {
            match device.status {
                SubscriptionDeviceStatus::Active => summary.devices_active += 1,
                SubscriptionDeviceStatus::Revoked => summary.devices_revoked += 1,
            }
        }

        for grant in self.enrollment_grants.values() {
            match grant.status {
                SubscriptionDeviceEnrollmentStatus::Active => summary.enrollment_grants_active += 1,
                SubscriptionDeviceEnrollmentStatus::Consumed => {
                    summary.enrollment_grants_consumed += 1
                }
                SubscriptionDeviceEnrollmentStatus::Expired => {
                    summary.enrollment_grants_expired += 1
                }
                SubscriptionDeviceEnrollmentStatus::Revoked => {
                    summary.enrollment_grants_revoked += 1
                }
            }
        }

        summary
    }
}

impl InstallerRuntime {
    fn ui_summary(&self, config: &AppConfig) -> UiInstallerSummary {
        let mut summary = UiInstallerSummary {
            tls_configured: config.tls_certificate_path.is_some()
                && config.tls_private_key_path.is_some(),
            available_access_modes: PanelAccessMode::ALL.to_vec(),
            recommended_access_mode: build_panel_access_modes_view()
                .options
                .iter()
                .find(|option| option.recommended)
                .map(|option| option.mode),
            jobs_total: self.jobs.len(),
            ..UiInstallerSummary::default()
        };

        for record in self.jobs.values() {
            match record.view.status {
                PanelInstallerJobStatus::Pending => summary.jobs_pending += 1,
                PanelInstallerJobStatus::Running => summary.jobs_running += 1,
                PanelInstallerJobStatus::Succeeded => summary.jobs_succeeded += 1,
                PanelInstallerJobStatus::Failed => summary.jobs_failed += 1,
                PanelInstallerJobStatus::Rejected => summary.jobs_rejected += 1,
                PanelInstallerJobStatus::Expired => summary.jobs_expired += 1,
            }
            summary.latest_job_at_unix = summary
                .latest_job_at_unix
                .max(Some(record.view.updated_at_unix));
        }

        summary
    }
}

/// A compact projection of the capability matrix.
///
/// The size is bounded at compile time: there are as many protocols as matrix
/// rows, and the list does not grow with data.
fn build_ui_protocols_summary(xray_version: Option<String>) -> UiProtocolsSummary {
    let capabilities = protocol_capabilities_view();
    UiProtocolsSummary {
        capabilities_schema_version: capabilities.schema_version,
        xray_version,
        protocols: capabilities
            .capabilities
            .into_iter()
            .map(|capability| UiProtocolOption {
                available: capability.status == ProtocolSupportStatus::Production
                    && capability.disabled_reason.is_none(),
                protocol: capability.protocol,
                display_name: capability.display_name,
                status: capability.status,
                recommended_default: capability.recommended_default,
                disabled_reason: capability.disabled_reason,
                supported_transports: capability.supported_transports,
                supported_security_modes: capability.supported_security_modes,
            })
            .collect(),
    }
}

/// The single place `?limit=` is applied.
///
/// The contract is the same for every list route:
///
/// - parameter omitted -> the limit from config is used;
/// - more requested than the limit -> clamped to the limit. `limit` cannot widen
///   a response, or it would stop being bounded;
/// - `0` is meaningless and is raised to `1`.
///
/// `offset` is deliberately absent. Within a 512 MB budget deep pagination is
/// unreachable anyway, and offering `offset` would suggest it is supported.
/// Narrowing a response is the job of filters (`search`, `status`, time windows),
/// not of an offset.
fn resolve_limit(requested: Option<usize>, max_limit: usize) -> usize {
    let max_limit = max_limit.max(1);
    requested.unwrap_or(max_limit).clamp(1, max_limit)
}

