fn validate_panel_bind_host(value: &str) -> Result<(), SecurityError> {
    if value.parse::<std::net::IpAddr>().is_ok() || value == "localhost" {
        return Ok(());
    }
    Err(SecurityError::InvalidSecuritySettings(
        "bind_host must be an IP address or localhost",
    ))
}

fn validate_panel_domain(value: &str) -> Result<(), SecurityError> {
    let valid = value.len() <= 253
        && value.contains('.')
        && !value.contains("://")
        && !value.starts_with('.')
        && !value.ends_with('.')
        && value.split('.').all(|label| {
            !label.is_empty()
                && label.len() <= 63
                && label
                    .chars()
                    .all(|ch| ch.is_ascii_alphanumeric() || ch == '-')
        });
    if valid {
        Ok(())
    } else {
        Err(SecurityError::InvalidSecuritySettings(
            "domain must be a valid DNS name without scheme or path",
        ))
    }
}

fn panel_install_public_url(
    mode: PanelAccessMode,
    domain: Option<&str>,
    public_ip: Option<&str>,
    bind_port: u16,
) -> String {
    match mode {
        PanelAccessMode::DomainTls => {
            let domain = domain.unwrap_or("panel.example.com");
            if bind_port == 443 {
                format!("https://{domain}")
            } else {
                format!("https://{domain}:{bind_port}")
            }
        }
        PanelAccessMode::IpHttp => {
            format!("http://{}:{bind_port}", public_ip.unwrap_or("<server-ip>"))
        }
        PanelAccessMode::IpSelfSignedTls => {
            format!("https://{}:{bind_port}", public_ip.unwrap_or("<server-ip>"))
        }
        PanelAccessMode::ReverseProxy => domain
            .map(|domain| format!("https://{domain}"))
            .unwrap_or_else(|| "operator-managed reverse proxy URL".to_string()),
    }
}

fn panel_install_certificate_plan(
    mode: PanelAccessMode,
    domain: Option<String>,
    public_ip: Option<String>,
    acme_email: Option<String>,
) -> PanelCertificatePlanView {
    match mode {
        PanelAccessMode::DomainTls => PanelCertificatePlanView {
            tls_enabled: true,
            source: PanelCertificateSource::LetsEncrypt,
            subject_alt_name: domain.as_ref().map(|value| format!("DNS:{value}")),
            domain,
            acme_email,
            certificate_path: Some("/etc/hydra-panel/certs/panel.crt".to_string()),
            private_key_path: Some("/etc/hydra-panel/certs/panel.key".to_string()),
            fingerprint_required: false,
            renewal_required: true,
            detail: "Issue and renew a public trusted certificate through ACME/Let's Encrypt."
                .to_string(),
        },
        PanelAccessMode::IpSelfSignedTls => PanelCertificatePlanView {
            tls_enabled: true,
            source: PanelCertificateSource::SelfSigned,
            domain: None,
            acme_email: None,
            subject_alt_name: public_ip.as_ref().map(|value| format!("IP:{value}")),
            certificate_path: Some("/etc/hydra-panel/certs/panel-self-signed.crt".to_string()),
            private_key_path: Some("/etc/hydra-panel/certs/panel-self-signed.key".to_string()),
            fingerprint_required: true,
            renewal_required: false,
            detail: "Generate a self-signed certificate and print its SHA-256 fingerprint."
                .to_string(),
        },
        PanelAccessMode::ReverseProxy => PanelCertificatePlanView {
            tls_enabled: false,
            source: PanelCertificateSource::OperatorManaged,
            domain,
            acme_email: None,
            subject_alt_name: None,
            certificate_path: None,
            private_key_path: None,
            fingerprint_required: false,
            renewal_required: false,
            detail: "TLS is managed by the operator's reverse proxy.".to_string(),
        },
        PanelAccessMode::IpHttp => PanelCertificatePlanView {
            tls_enabled: false,
            source: PanelCertificateSource::None,
            domain: None,
            acme_email: None,
            subject_alt_name: None,
            certificate_path: None,
            private_key_path: None,
            fingerprint_required: false,
            renewal_required: false,
            detail: "No TLS certificate is used in plain HTTP mode.".to_string(),
        },
    }
}

fn panel_install_hardening_defaults(mode: PanelAccessMode) -> Vec<String> {
    let mut defaults = vec![
        "login_protection_enabled=true".to_string(),
        "smart_ban_enabled=true".to_string(),
        "audit_history_enabled=true".to_string(),
        "admin_2fa_recommended=true".to_string(),
    ];
    if matches!(
        mode,
        PanelAccessMode::IpHttp | PanelAccessMode::IpSelfSignedTls
    ) {
        defaults.push("firewall_allowlist_recommended=true".to_string());
        defaults.push("secret_admin_path_recommended=true".to_string());
    }
    defaults
}

fn panel_install_steps(
    mode: PanelAccessMode,
    bind_host: &str,
    bind_port: u16,
    certificate_plan: &PanelCertificatePlanView,
    has_firewall_allowlist: bool,
) -> Vec<PanelInstallPlanStep> {
    let mut steps = Vec::new();
    push_panel_install_step(
        &mut steps,
        "preflight",
        "Run local preflight checks",
        "Check OS support, package manager, free memory, free disk, and selected port availability.",
        false,
        false,
    );
    if certificate_plan.source == PanelCertificateSource::LetsEncrypt {
        push_panel_install_step(
            &mut steps,
            "dependencies",
            "Prepare certificate provider",
            "Install the allowlisted certbot package through the detected system package manager when it is not already available.",
            true,
            false,
        );
    }
    push_panel_install_step(
        &mut steps,
        "install_binary",
        "Install Hydra Panel binary",
        "Install the panel binary and create runtime directories with restrictive permissions.",
        true,
        false,
    );
    if certificate_plan.tls_enabled {
        push_panel_install_step(
            &mut steps,
            "certificate",
            "Prepare panel certificate",
            &certificate_plan.detail,
            true,
            certificate_plan.source == PanelCertificateSource::SelfSigned,
        );
    }
    push_panel_install_step(
        &mut steps,
        "configure_listener",
        "Configure panel listener",
        &format!("Bind panel to {bind_host}:{bind_port}."),
        true,
        mode == PanelAccessMode::IpHttp && bind_host == "0.0.0.0",
    );
    if has_firewall_allowlist {
        push_panel_install_step(
            &mut steps,
            "firewall_allowlist",
            "Apply firewall allowlist",
            "Restrict panel access to the operator-provided IP/CIDR allowlist where supported.",
            true,
            true,
        );
    }
    push_panel_install_step(
        &mut steps,
        "security_defaults",
        "Apply security defaults",
        "Enable login protection, smart ban, audit history, and first-login 2FA recommendation.",
        true,
        false,
    );
    push_panel_install_step(
        &mut steps,
        "service",
        "Install and start panel service",
        "Create the system service, start it, and verify local health before printing the final URL.",
        true,
        false,
    );
    steps
}

fn push_panel_install_step(
    steps: &mut Vec<PanelInstallPlanStep>,
    id: &str,
    title: &str,
    detail: &str,
    destructive: bool,
    requires_confirmation: bool,
) {
    steps.push(PanelInstallPlanStep {
        order: steps.len() as u32 + 1,
        id: id.to_string(),
        title: title.to_string(),
        detail: detail.to_string(),
        destructive,
        requires_confirmation,
    });
}

const PANEL_INSTALLER_EXECUTOR_CONTRACT_VERSION: u16 = 1;

pub fn build_panel_installer_session(
    request: PanelInstallerSessionRequest,
) -> Result<PanelInstallerExecutorSessionView, SecurityError> {
    let mut plan = build_panel_install_plan(request.plan)?;
    let target_os = request.target_os.unwrap_or(PanelInstallerTargetOs::Linux);
    let target_arch = request
        .target_arch
        .unwrap_or(PanelInstallerTargetArch::X86_64);
    normalize_panel_install_plan_for_target(&mut plan, target_os);
    let package_channel = request
        .package_channel
        .unwrap_or(PanelInstallerPackageChannel::Stable);
    if let Some(artifact) = request.selected_artifact.as_ref()
        && (artifact.artifact_kind != PanelInstallerArtifactKind::PanelBinary
            || artifact.target_os != target_os
            || artifact.target_arch != target_arch
            || artifact.package_channel != package_channel)
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "installer session selected_artifact must be a matching panel_binary for target os/arch/channel",
        ));
    }
    let compatible = request
        .executor_contract_version
        .is_some_and(|version| version == PANEL_INSTALLER_EXECUTOR_CONTRACT_VERSION);
    let command_envelopes = plan
        .steps
        .iter()
        .map(|step| {
            panel_installer_command_envelope(
                &plan,
                target_os,
                request.selected_artifact.as_ref(),
                step,
            )
        })
        .collect();

    Ok(PanelInstallerExecutorSessionView {
        schema_version: SchemaId::PanelInstallerSession.version(),
        session_id: panel_installer_session_id(&plan),
        minimum_executor_contract_version: PANEL_INSTALLER_EXECUTOR_CONTRACT_VERSION,
        supported_executor_contract_version: PANEL_INSTALLER_EXECUTOR_CONTRACT_VERSION,
        compatible,
        target_os,
        target_arch,
        package_channel,
        selected_artifact: request.selected_artifact,
        plan,
        command_envelopes,
        loop_contract: PanelInstallerLoopContractView {
            phases: vec![
                "fetch_session".to_string(),
                "execute_next_command_envelope".to_string(),
                "submit_result_with_attestation".to_string(),
                "handle_accept_or_reject".to_string(),
            ],
            terminal_when: vec![
                "all command envelopes have one accepted result".to_string(),
                "any command result fails the acceptance contract".to_string(),
            ],
            recovery_rules: vec![
                "do not infer hidden shell commands outside the envelope".to_string(),
                "refresh the session before retrying after rejection".to_string(),
                "never include passwords, private keys, or token values in result detail"
                    .to_string(),
            ],
        },
    })
}

pub fn build_panel_installer_first_host_session(
    request: PanelInstallerFirstHostSessionRequest,
) -> Result<PanelInstallerExecutorSessionView, SecurityError> {
    validate_panel_installer_release_artifact(&request.panel_binary)?;
    if request.panel_binary.artifact_kind != PanelInstallerArtifactKind::PanelBinary {
        return Err(SecurityError::InvalidSecuritySettings(
            "first-host installer artifact must be a panel_binary",
        ));
    }
    let artifact = request.panel_binary;
    build_panel_installer_session(PanelInstallerSessionRequest {
        plan: request.plan,
        target_os: Some(artifact.target_os),
        target_arch: Some(artifact.target_arch),
        package_channel: Some(artifact.package_channel),
        selected_artifact: Some(PanelInstallerSelectedArtifactView {
            source: "first_host_release".to_string(),
            name: artifact.name,
            artifact_kind: artifact.artifact_kind,
            target_os: artifact.target_os,
            target_arch: artifact.target_arch,
            package_channel: artifact.package_channel,
            version: artifact.version,
            url: artifact.url,
            sha256: artifact.sha256.to_ascii_lowercase(),
            signature_url: artifact.signature_url,
            signing_key_fingerprint: artifact.signing_key_fingerprint,
        }),
        executor_contract_version: request.executor_contract_version,
    })
}

fn panel_installer_command_envelope(
    plan: &PanelInstallPlanView,
    target_os: PanelInstallerTargetOs,
    selected_artifact: Option<&PanelInstallerSelectedArtifactView>,
    step: &PanelInstallPlanStep,
) -> PanelInstallerCommandEnvelopeView {
    let payload_kind = panel_installer_payload_kind(step.id.as_str());
    PanelInstallerCommandEnvelopeView {
        command_id: format!("{}:{}", step.order, step.id),
        order: step.order,
        step_id: step.id.clone(),
        payload_kind,
        title: step.title.clone(),
        detail: step.detail.clone(),
        destructive: step.destructive,
        requires_confirmation: step.requires_confirmation || plan.requires_confirmation,
        executor_should_submit: true,
        operations: panel_installer_executor_operations(
            plan,
            target_os,
            selected_artifact,
            step,
            payload_kind,
        ),
        acceptance: panel_installer_acceptance_contract(payload_kind),
    }
}

fn panel_installer_executor_operations(
    plan: &PanelInstallPlanView,
    target_os: PanelInstallerTargetOs,
    selected_artifact: Option<&PanelInstallerSelectedArtifactView>,
    step: &PanelInstallPlanStep,
    payload_kind: PanelInstallerExecutorPayloadKind,
) -> Vec<PanelInstallerExecutorOperationView> {
    match payload_kind {
        PanelInstallerExecutorPayloadKind::PreflightProbe => vec![panel_installer_operation(
            step,
            "probe",
            PanelInstallerExecutorOperationKind::PreflightProbe,
            None,
            Vec::new(),
            None,
            None,
            false,
            "Detect OS/version, memory, disk, package/service manager, and selected port availability.",
        )],
        PanelInstallerExecutorPayloadKind::DependencyInstall => vec![panel_installer_operation(
            step,
            "install-certbot",
            PanelInstallerExecutorOperationKind::InstallPackageDependency,
            None,
            vec!["certbot".to_string()],
            None,
            None,
            true,
            "Install only the allowlisted certbot package when required for domain TLS.",
        )],
        PanelInstallerExecutorPayloadKind::InstallBinary => {
            panel_installer_binary_operations(target_os, selected_artifact, step)
        }
        PanelInstallerExecutorPayloadKind::CertificateOperation => {
            panel_installer_certificate_operations(plan, target_os, step)
        }
        PanelInstallerExecutorPayloadKind::ListenerConfig => {
            vec![panel_installer_operation(
                step,
                "write-listener-config",
                PanelInstallerExecutorOperationKind::WriteConfig,
                None,
                Vec::new(),
                Some(panel_config_path(target_os)),
                Some(panel_listener_config_template(plan)),
                true,
                "Write panel listener/access-mode config atomically with restrictive permissions.",
            )]
        }
        PanelInstallerExecutorPayloadKind::FirewallConfig => {
            panel_installer_firewall_operations(plan, target_os, step)
        }
        PanelInstallerExecutorPayloadKind::SecurityDefaults => vec![panel_installer_operation(
            step,
            "apply-security-defaults",
            PanelInstallerExecutorOperationKind::ApplySecurityDefaults,
            None,
            Vec::new(),
            Some(panel_config_path(target_os)),
            None,
            true,
            "Apply hardening defaults without writing secrets into command logs.",
        )],
        PanelInstallerExecutorPayloadKind::ServiceInstall => {
            panel_installer_service_operations(plan, target_os, step)
        }
        PanelInstallerExecutorPayloadKind::HealthCheck => vec![panel_installer_operation(
            step,
            "health-check",
            PanelInstallerExecutorOperationKind::HealthCheck,
            None,
            Vec::new(),
            None,
            None,
            false,
            "Poll the selected local listener health endpoint before reporting success.",
        )],
    }
}

fn panel_installer_binary_operations(
    target_os: PanelInstallerTargetOs,
    selected_artifact: Option<&PanelInstallerSelectedArtifactView>,
    step: &PanelInstallPlanStep,
) -> Vec<PanelInstallerExecutorOperationView> {
    let url = selected_artifact
        .map(|artifact| artifact.url.clone())
        .unwrap_or_else(|| "$HYDRA_PANEL_INSTALLER_URL".to_string());
    let sha256 = selected_artifact
        .map(|artifact| artifact.sha256.clone())
        .unwrap_or_else(|| "$HYDRA_PANEL_INSTALLER_SHA256".to_string());
    let binary_path = panel_binary_path(target_os);
    vec![
        panel_installer_operation(
            step,
            "create-runtime-dirs",
            PanelInstallerExecutorOperationKind::CreateDirectory,
            None,
            Vec::new(),
            Some(panel_runtime_dir(target_os)),
            None,
            true,
            "Create runtime/config/certificate directories with restrictive permissions.",
        ),
        panel_installer_operation(
            step,
            "download-artifact",
            PanelInstallerExecutorOperationKind::DownloadArtifact,
            None,
            vec![url],
            None,
            None,
            true,
            "Download only the selected OS/architecture installer artifact.",
        ),
        panel_installer_operation(
            step,
            "verify-sha256",
            PanelInstallerExecutorOperationKind::VerifySha256,
            None,
            vec![sha256],
            None,
            None,
            false,
            "Verify SHA-256 before installing anything.",
        ),
        panel_installer_operation(
            step,
            "install-panel-binary",
            PanelInstallerExecutorOperationKind::InstallBinary,
            None,
            Vec::new(),
            Some(binary_path),
            None,
            true,
            "Install the OS-specific panel binary; do not install artifacts for other operating systems.",
        ),
    ]
}

fn panel_installer_certificate_operations(
    plan: &PanelInstallPlanView,
    target_os: PanelInstallerTargetOs,
    step: &PanelInstallPlanStep,
) -> Vec<PanelInstallerExecutorOperationView> {
    match plan.certificate_plan.source {
        PanelCertificateSource::LetsEncrypt => vec![panel_installer_operation(
            step,
            "issue-letsencrypt-certificate",
            PanelInstallerExecutorOperationKind::IssueLetsEncryptCertificate,
            certbot_program(target_os),
            letsencrypt_args(&plan.certificate_plan),
            plan.certificate_plan.certificate_path.clone(),
            None,
            true,
            "Issue a public trusted certificate and configure renewal; do not fall back to HTTP if issuance fails.",
        )],
        PanelCertificateSource::SelfSigned => vec![panel_installer_operation(
            step,
            "generate-self-signed-certificate",
            PanelInstallerExecutorOperationKind::GenerateSelfSignedCertificate,
            None,
            self_signed_certificate_args(&plan.certificate_plan),
            plan.certificate_plan.certificate_path.clone(),
            None,
            true,
            "Generate a self-signed certificate and report SHA-256 fingerprint for operator verification.",
        )],
        PanelCertificateSource::OperatorManaged | PanelCertificateSource::None => Vec::new(),
    }
}

fn panel_installer_firewall_operations(
    plan: &PanelInstallPlanView,
    target_os: PanelInstallerTargetOs,
    step: &PanelInstallPlanStep,
) -> Vec<PanelInstallerExecutorOperationView> {
    let mut args = vec![plan.bind_address.clone()];
    args.extend(plan.firewall_allowlist.iter().cloned());
    match target_os {
        PanelInstallerTargetOs::Linux => vec![panel_installer_operation(
            step,
            "apply-linux-firewall",
            PanelInstallerExecutorOperationKind::ApplyFirewall,
            None,
            args,
            None,
            None,
            true,
            "Apply exactly the validated operator allowlist through an available Linux firewall backend.",
        )],
        PanelInstallerTargetOs::Windows => vec![panel_installer_operation(
            step,
            "apply-windows-firewall",
            PanelInstallerExecutorOperationKind::ApplyFirewall,
            None,
            args,
            None,
            None,
            true,
            "Apply exactly the validated operator allowlist through Windows Firewall.",
        )],
    }
}

fn panel_installer_service_operations(
    plan: &PanelInstallPlanView,
    target_os: PanelInstallerTargetOs,
    step: &PanelInstallPlanStep,
) -> Vec<PanelInstallerExecutorOperationView> {
    match target_os {
        PanelInstallerTargetOs::Linux => vec![
            panel_installer_operation(
                step,
                "write-systemd-unit",
                PanelInstallerExecutorOperationKind::WriteService,
                None,
                Vec::new(),
                Some("/etc/systemd/system/hydra-panel.service".to_string()),
                Some(linux_panel_systemd_unit_template(plan)),
                true,
                "Write the hydra-panel systemd unit without dumping env files or secrets.",
            ),
            panel_installer_operation(
                step,
                "start-systemd-service",
                PanelInstallerExecutorOperationKind::StartService,
                Some("systemctl".to_string()),
                vec![
                    "enable".to_string(),
                    "--now".to_string(),
                    "hydra-panel.service".to_string(),
                ],
                None,
                None,
                true,
                "Enable and start hydra-panel.service, then verify local health.",
            ),
        ],
        PanelInstallerTargetOs::Windows => vec![
            panel_installer_operation(
                step,
                "create-windows-service",
                PanelInstallerExecutorOperationKind::WriteService,
                Some("sc.exe".to_string()),
                vec![
                    "create".to_string(),
                    "HydraPanel".to_string(),
                    format!("binPath= {}", panel_binary_path(target_os)),
                    "start= auto".to_string(),
                ],
                None,
                None,
                true,
                "Create the HydraPanel Windows service from the selected Windows binary.",
            ),
            panel_installer_operation(
                step,
                "start-windows-service",
                PanelInstallerExecutorOperationKind::StartService,
                Some("sc.exe".to_string()),
                vec!["start".to_string(), "HydraPanel".to_string()],
                None,
                None,
                true,
                "Start HydraPanel service, then verify local health.",
            ),
        ],
    }
}

fn panel_installer_operation(
    step: &PanelInstallPlanStep,
    suffix: &str,
    kind: PanelInstallerExecutorOperationKind,
    program: Option<String>,
    args: Vec<String>,
    target_path: Option<String>,
    content_template: Option<String>,
    requires_admin: bool,
    detail: &str,
) -> PanelInstallerExecutorOperationView {
    PanelInstallerExecutorOperationView {
        operation_id: format!("{}:{suffix}", step.id),
        kind,
        program,
        args,
        target_path,
        content_template,
        requires_admin,
        secret_free: true,
        detail: detail.to_string(),
    }
}

fn panel_runtime_dir(target_os: PanelInstallerTargetOs) -> String {
    match target_os {
        PanelInstallerTargetOs::Linux => "/etc/hydra-panel".to_string(),
        PanelInstallerTargetOs::Windows => "C:\\ProgramData\\HydraPanel".to_string(),
    }
}

fn panel_config_path(target_os: PanelInstallerTargetOs) -> String {
    match target_os {
        PanelInstallerTargetOs::Linux => "/etc/hydra-panel/panel.env".to_string(),
        PanelInstallerTargetOs::Windows => "C:\\ProgramData\\HydraPanel\\panel.env".to_string(),
    }
}

fn panel_binary_path(target_os: PanelInstallerTargetOs) -> String {
    match target_os {
        PanelInstallerTargetOs::Linux => "/usr/local/bin/hydra-panel".to_string(),
        PanelInstallerTargetOs::Windows => {
            "C:\\Program Files\\HydraPanel\\hydra-panel.exe".to_string()
        }
    }
}

fn normalize_panel_install_plan_for_target(
    plan: &mut PanelInstallPlanView,
    target_os: PanelInstallerTargetOs,
) {
    if !plan.certificate_plan.tls_enabled {
        return;
    }
    let (certificate_path, private_key_path) = match target_os {
        PanelInstallerTargetOs::Linux => (
            "/etc/hydra-panel/certs/panel.crt".to_string(),
            "/etc/hydra-panel/certs/panel.key".to_string(),
        ),
        PanelInstallerTargetOs::Windows => (
            "C:\\ProgramData\\HydraPanel\\certs\\panel.crt".to_string(),
            "C:\\ProgramData\\HydraPanel\\certs\\panel.key".to_string(),
        ),
    };
    plan.certificate_plan.certificate_path = Some(certificate_path);
    plan.certificate_plan.private_key_path = Some(private_key_path);
}

fn panel_listener_config_template(plan: &PanelInstallPlanView) -> String {
    let mut template = format!(
        "HYDRA_BIND_ADDR={}\nHYDRA_PUBLIC_URL={}\nHYDRA_ACCESS_MODE={}\n",
        plan.bind_address,
        plan.public_url,
        panel_access_mode_value(plan.access_mode)
    );
    if plan.certificate_plan.tls_enabled {
        if let Some(path) = plan.certificate_plan.certificate_path.as_deref() {
            template.push_str(&format!("HYDRA_TLS_CERT_PATH={path}\n"));
        }
        if let Some(path) = plan.certificate_plan.private_key_path.as_deref() {
            template.push_str(&format!("HYDRA_TLS_KEY_PATH={path}\n"));
        }
    }
    template
}

fn certbot_program(target_os: PanelInstallerTargetOs) -> Option<String> {
    match target_os {
        PanelInstallerTargetOs::Linux => Some("certbot".to_string()),
        PanelInstallerTargetOs::Windows => None,
    }
}

fn letsencrypt_args(certificate: &PanelCertificatePlanView) -> Vec<String> {
    let mut args = vec![
        "certonly".to_string(),
        "--standalone".to_string(),
        "--non-interactive".to_string(),
        "--agree-tos".to_string(),
    ];
    if let Some(domain) = certificate.domain.as_deref() {
        args.push("-d".to_string());
        args.push(domain.to_string());
    }
    if let Some(email) = certificate.acme_email.as_deref() {
        args.push("--email".to_string());
        args.push(email.to_string());
    } else {
        args.push("--register-unsafely-without-email".to_string());
    }
    args
}

fn self_signed_certificate_args(certificate: &PanelCertificatePlanView) -> Vec<String> {
    let mut args = vec![
        "req".to_string(),
        "-x509".to_string(),
        "-newkey".to_string(),
        "rsa:3072".to_string(),
        "-nodes".to_string(),
        "-days".to_string(),
        "365".to_string(),
        "-keyout".to_string(),
        certificate
            .private_key_path
            .clone()
            .unwrap_or_else(|| "<private-key-path>".to_string()),
        "-out".to_string(),
        certificate
            .certificate_path
            .clone()
            .unwrap_or_else(|| "<certificate-path>".to_string()),
        "-subj".to_string(),
        "/CN=Hydra Panel".to_string(),
    ];
    if let Some(subject_alt_name) = certificate.subject_alt_name.as_deref() {
        args.push("-addext".to_string());
        args.push(format!("subjectAltName={subject_alt_name}"));
    }
    args
}

fn linux_panel_systemd_unit_template(_plan: &PanelInstallPlanView) -> String {
    format!(
        "[Unit]\nDescription=Hydra Panel\nAfter=network-online.target\nWants=network-online.target\n\n[Service]\nType=simple\nUser=hydra\nGroup=hydra\nEnvironmentFile={}\nExecStart={}\nWorkingDirectory=/var/lib/hydra-panel\nRestart=on-failure\nRestartSec=5\nNoNewPrivileges=true\nPrivateTmp=true\nProtectSystem=strict\nProtectHome=true\nReadWritePaths={} /var/lib/hydra-panel\n\n[Install]\nWantedBy=multi-user.target\n",
        panel_config_path(PanelInstallerTargetOs::Linux),
        panel_binary_path(PanelInstallerTargetOs::Linux),
        panel_runtime_dir(PanelInstallerTargetOs::Linux)
    )
}

fn panel_installer_payload_kind(step_id: &str) -> PanelInstallerExecutorPayloadKind {
    match step_id {
        "preflight" => PanelInstallerExecutorPayloadKind::PreflightProbe,
        "dependencies" => PanelInstallerExecutorPayloadKind::DependencyInstall,
        "install_binary" => PanelInstallerExecutorPayloadKind::InstallBinary,
        "certificate" => PanelInstallerExecutorPayloadKind::CertificateOperation,
        "configure_listener" => PanelInstallerExecutorPayloadKind::ListenerConfig,
        "firewall_allowlist" => PanelInstallerExecutorPayloadKind::FirewallConfig,
        "security_defaults" => PanelInstallerExecutorPayloadKind::SecurityDefaults,
        "service" => PanelInstallerExecutorPayloadKind::ServiceInstall,
        _ => PanelInstallerExecutorPayloadKind::HealthCheck,
    }
}

fn panel_installer_acceptance_contract(
    payload_kind: PanelInstallerExecutorPayloadKind,
) -> PanelInstallerAcceptanceContractView {
    let (required_success_fields, fail_closed_checks, description) = match payload_kind {
        PanelInstallerExecutorPayloadKind::PreflightProbe => (
            vec![
                "os_supported".to_string(),
                "memory_total_mb".to_string(),
                "disk_free_mb".to_string(),
                "selected_port_available".to_string(),
            ],
            vec![
                "os_supported must be true".to_string(),
                "memory_total_mb must be >= 512".to_string(),
                "disk_free_mb must be >= 1024".to_string(),
                "selected_port_available must be true".to_string(),
            ],
            "Accept only a supported host with enough memory/disk and free selected port.",
        ),
        PanelInstallerExecutorPayloadKind::DependencyInstall => (
            vec!["dependencies_ready".to_string()],
            vec!["dependencies_ready must be true".to_string()],
            "Accept only after the allowlisted certificate dependency is available.",
        ),
        PanelInstallerExecutorPayloadKind::InstallBinary => (
            vec![
                "binary_installed".to_string(),
                "binary_path".to_string(),
                "artifact_source_url".to_string(),
                "artifact_sha256_verified".to_string(),
            ],
            vec![
                "binary_installed must be true".to_string(),
                "artifact_sha256_verified must be true".to_string(),
            ],
            "Accept only after the panel binary exists at an explicit path and downloaded artifact checksum verification passed.",
        ),
        PanelInstallerExecutorPayloadKind::CertificateOperation => (
            vec![
                "certificate_path".to_string(),
                "private_key_path".to_string(),
                "private_key_mode".to_string(),
            ],
            vec![
                "private_key_mode must be 0600 on Unix-like systems".to_string(),
                "self-signed mode must report fingerprint_sha256".to_string(),
            ],
            "Accept only after certificate/key paths and restrictive key permissions are attested.",
        ),
        PanelInstallerExecutorPayloadKind::ListenerConfig => (
            vec!["config_written".to_string(), "bind_address".to_string()],
            vec!["config_written must be true".to_string()],
            "Accept only after listener config is written for the selected bind address.",
        ),
        PanelInstallerExecutorPayloadKind::FirewallConfig => (
            vec!["firewall_rules_applied".to_string()],
            vec!["firewall_rules_applied must be true".to_string()],
            "Accept only after requested firewall allowlist rules are applied.",
        ),
        PanelInstallerExecutorPayloadKind::SecurityDefaults => (
            vec!["security_defaults_applied".to_string()],
            vec!["security_defaults_applied must be true".to_string()],
            "Accept only after panel hardening defaults are applied.",
        ),
        PanelInstallerExecutorPayloadKind::ServiceInstall
        | PanelInstallerExecutorPayloadKind::HealthCheck => (
            vec![
                "service_name".to_string(),
                "service_active".to_string(),
                "health_check_ok".to_string(),
            ],
            vec![
                "service_active must be true".to_string(),
                "health_check_ok must be true".to_string(),
            ],
            "Accept only after service is active and local health check passes.",
        ),
    };

    PanelInstallerAcceptanceContractView {
        accepted_result_endpoint: "/api/installer/session/result".to_string(),
        required_success_fields,
        fail_closed_checks,
        description: description.to_string(),
    }
}

fn panel_installer_session_id(plan: &PanelInstallPlanView) -> String {
    let mut hasher = Sha256::new();
    hasher.update(format!(
        "{:?}|{}|{}|{:?}",
        plan.access_mode, plan.public_url, plan.bind_address, plan.security_posture
    ));
    format!("panel-install-{:x}", hasher.finalize())
}

fn panel_installer_expected_operation_ids(
    command_envelopes: &[PanelInstallerCommandEnvelopeView],
) -> Vec<String> {
    command_envelopes
        .iter()
        .flat_map(|command| {
            command
                .operations
                .iter()
                .map(|operation| format!("{}/{}", command.command_id, operation.operation_id))
        })
        .collect()
}

pub fn validate_panel_installer_result(
    request: PanelInstallerSessionResultRequest,
) -> PanelInstallerResultView {
    let mut issues = Vec::new();
    let mut rejected_command_ids = Vec::new();
    let expected_command_ids = request
        .expected_command_ids
        .iter()
        .cloned()
        .collect::<HashSet<_>>();
    if expected_command_ids.is_empty() {
        issues.push("expected_command_ids must not be empty".to_string());
    }
    let expected_operation_ids = request
        .expected_operation_ids
        .iter()
        .cloned()
        .collect::<HashSet<_>>();
    let mut seen = HashSet::<String>::new();
    let mut seen_operation_ids = HashSet::<String>::new();
    for result in &request.command_results {
        if !seen.insert(result.command_id.clone()) {
            issues.push(format!("duplicate command result: {}", result.command_id));
            rejected_command_ids.push(result.command_id.clone());
            continue;
        }
        if !expected_command_ids.is_empty() && !expected_command_ids.contains(&result.command_id) {
            issues.push(format!("unexpected command result: {}", result.command_id));
            rejected_command_ids.push(result.command_id.clone());
            continue;
        }
        if result.exit_code != 0 {
            issues.push(format!(
                "command {} exited with {}",
                result.command_id, result.exit_code
            ));
            rejected_command_ids.push(result.command_id.clone());
            continue;
        }
        if let Some(reason) = validate_panel_installer_command_attestation(
            &result.command_id,
            request.access_mode,
            &expected_operation_ids,
            &mut seen_operation_ids,
            &result.attestation,
        ) {
            issues.push(format!("command {} rejected: {reason}", result.command_id));
            rejected_command_ids.push(result.command_id.clone());
        }
    }
    if request.command_results.is_empty() {
        issues.push("no command results submitted".to_string());
    }
    for expected in expected_command_ids.difference(&seen) {
        issues.push(format!("missing command result: {expected}"));
        rejected_command_ids.push(expected.clone());
    }
    if !expected_operation_ids.is_empty() {
        for expected in expected_operation_ids.difference(&seen_operation_ids) {
            issues.push(format!("missing operation result: {expected}"));
            if let Some((command_id, _)) = expected.split_once('/') {
                rejected_command_ids.push(command_id.to_string());
            }
        }
    }

    rejected_command_ids.sort();
    rejected_command_ids.dedup();
    let accepted = issues.is_empty();
    PanelInstallerResultView {
        session_id: request.session_id,
        status: if accepted {
            PanelInstallerExecutorResultStatus::Accepted
        } else {
            PanelInstallerExecutorResultStatus::Rejected
        },
        accepted,
        checked_commands: request.command_results.len(),
        rejected_command_ids,
        issues,
        detail: if accepted {
            "installer result accepted".to_string()
        } else {
            "installer result rejected by fail-closed acceptance checks".to_string()
        },
    }
}

fn validate_panel_installer_command_attestation(
    command_id: &str,
    access_mode: PanelAccessMode,
    expected_operation_ids: &HashSet<String>,
    seen_operation_ids: &mut HashSet<String>,
    attestation: &PanelInstallerCommandAttestation,
) -> Option<String> {
    if let Some(reason) = validate_panel_installer_operation_results(
        command_id,
        expected_operation_ids,
        seen_operation_ids,
        &attestation.operation_results,
    ) {
        return Some(reason);
    }
    let step_id = command_id
        .split_once(':')
        .map(|(_, step)| step)
        .unwrap_or(command_id);
    match step_id {
        "preflight" => {
            if attestation.os_supported != Some(true) {
                return Some("os_supported must be true".to_string());
            }
            if attestation.memory_total_mb.unwrap_or(0) < 512 {
                return Some("memory_total_mb must be >= 512".to_string());
            }
            if attestation.disk_free_mb.unwrap_or(0) < 1024 {
                return Some("disk_free_mb must be >= 1024".to_string());
            }
            if attestation.selected_port_available != Some(true) {
                return Some("selected_port_available must be true".to_string());
            }
        }
        "dependencies" => {
            if attestation.dependencies_ready != Some(true) {
                return Some("dependencies_ready must be true".to_string());
            }
        }
        "install_binary" => {
            if attestation.binary_installed != Some(true) {
                return Some("binary_installed must be true".to_string());
            }
            if attestation
                .binary_path
                .as_deref()
                .map(str::trim)
                .is_none_or(str::is_empty)
            {
                return Some("binary_path is required".to_string());
            }
            if attestation
                .artifact_source_url
                .as_deref()
                .map(str::trim)
                .is_none_or(str::is_empty)
            {
                return Some("artifact_source_url is required".to_string());
            }
            if attestation.artifact_sha256_verified != Some(true) {
                return Some("artifact_sha256_verified must be true".to_string());
            }
            if attestation.artifact_signature_verified == Some(false) {
                return Some(
                    "artifact_signature_verified must not be false when provided".to_string(),
                );
            }
        }
        "certificate" => {
            if attestation
                .certificate_path
                .as_deref()
                .map(str::trim)
                .is_none_or(str::is_empty)
            {
                return Some("certificate_path is required".to_string());
            }
            if attestation
                .private_key_path
                .as_deref()
                .map(str::trim)
                .is_none_or(str::is_empty)
            {
                return Some("private_key_path is required".to_string());
            }
            if attestation.private_key_mode.as_deref() != Some("0600") {
                return Some("private_key_mode must be 0600".to_string());
            }
            if access_mode == PanelAccessMode::IpSelfSignedTls
                && attestation
                    .fingerprint_sha256
                    .as_deref()
                    .map(str::trim)
                    .is_none_or(str::is_empty)
            {
                return Some("fingerprint_sha256 is required for self-signed mode".to_string());
            }
        }
        "configure_listener" => {
            if attestation.config_written != Some(true) {
                return Some("config_written must be true".to_string());
            }
            if attestation
                .bind_address
                .as_deref()
                .map(str::trim)
                .is_none_or(str::is_empty)
            {
                return Some("bind_address is required".to_string());
            }
        }
        "firewall_allowlist" => {
            if attestation.firewall_rules_applied != Some(true) {
                return Some("firewall_rules_applied must be true".to_string());
            }
        }
        "security_defaults" => {
            if attestation.security_defaults_applied != Some(true) {
                return Some("security_defaults_applied must be true".to_string());
            }
        }
        "service" => {
            if attestation
                .service_name
                .as_deref()
                .map(str::trim)
                .is_none_or(str::is_empty)
            {
                return Some("service_name is required".to_string());
            }
            if attestation.service_active != Some(true) {
                return Some("service_active must be true".to_string());
            }
            if attestation.health_check_ok != Some(true) {
                return Some("health_check_ok must be true".to_string());
            }
        }
        _ => return Some("unknown command id".to_string()),
    }
    None
}

fn validate_panel_installer_operation_results(
    command_id: &str,
    expected_operation_ids: &HashSet<String>,
    seen_operation_ids: &mut HashSet<String>,
    operation_results: &[PanelInstallerOperationResult],
) -> Option<String> {
    if expected_operation_ids.is_empty() {
        return None;
    }
    let command_prefix = format!("{command_id}/");
    let expected_for_command = expected_operation_ids
        .iter()
        .filter(|operation_id| operation_id.starts_with(&command_prefix))
        .cloned()
        .collect::<HashSet<_>>();
    if !expected_for_command.is_empty() && operation_results.is_empty() {
        return Some("operation_results are required for this command".to_string());
    }
    let mut local_seen = HashSet::<String>::new();
    for result in operation_results {
        if !local_seen.insert(result.operation_id.clone()) {
            return Some(format!(
                "duplicate operation result: {}",
                result.operation_id
            ));
        }
        if !expected_for_command.contains(&result.operation_id) {
            return Some(format!(
                "unexpected operation result: {}",
                result.operation_id
            ));
        }
        if result.exit_code != 0 {
            return Some(format!(
                "operation {} exited with {}",
                result.operation_id, result.exit_code
            ));
        }
        if !result.completed {
            return Some(format!(
                "operation {} was not completed",
                result.operation_id
            ));
        }
        if result.verified == Some(false) {
            return Some(format!(
                "operation {} verification failed",
                result.operation_id
            ));
        }
        seen_operation_ids.insert(result.operation_id.clone());
    }
    if let Some(expected) = expected_for_command.difference(&local_seen).next() {
        return Some(format!("missing operation result: {expected}"));
    }
    None
}

fn xray_stream_settings_for_inbound(
    inbound: &Inbound,
    generated: &GeneratedCoreConfigPreview,
) -> XrayStreamSettingsDocument {
    let host = representative_host_for_inbound(inbound, generated);
    let network = inbound_transport_name(inbound.network);
    let security = if inbound.tls_enabled { "tls" } else { "none" }.to_string();
    let path = match inbound.network {
        InboundTransport::Ws | InboundTransport::HttpUpgrade => host
            .and_then(|host| host.path.clone())
            .or_else(|| Some("/".to_string())),
        _ => None,
    };
    let host_header = match inbound.network {
        InboundTransport::Ws | InboundTransport::HttpUpgrade => {
            host.map(|host| host.address.clone())
        }
        _ => None,
    };
    let service_name = match inbound.network {
        InboundTransport::Grpc => Some(inbound.tag.clone()),
        _ => None,
    };

    XrayStreamSettingsDocument {
        network,
        security,
        path,
        host: host_header,
        service_name,
        allow_insecure: false,
        // The mode is set by the operator on the inbound; when absent the renderer
        // substitutes auto and, under Reality, expands it to stream-one.
        xhttp_mode: None,
    }
}

fn build_raw_xray_config(
    inbounds: &[XrayInboundDocument],
    outbounds: &[XrayOutboundDocument],
    routing: &XrayRoutingConfigDocument,
    policy: &XrayPolicyConfigDocument,
) -> serde_json::Value {
    let mut raw_inbounds = inbounds.iter().map(raw_xray_inbound).collect::<Vec<_>>();
    raw_inbounds.push(serde_json::json!({
        "tag": "hydra-stats-api",
        "listen": "127.0.0.1",
        "port": 10085,
        "protocol": "dokodemo-door",
        "settings": {
            "address": "127.0.0.1"
        }
    }));
    let mut raw_routing = raw_xray_routing(routing);
    raw_routing["rules"]
        .as_array_mut()
        .expect("raw Xray routing rules are always an array")
        .push(serde_json::json!({
            "type": "field",
            "inboundTag": ["hydra-stats-api"],
            "outboundTag": "hydra-stats-api"
        }));
    serde_json::json!({
        "log": {
            "loglevel": "warning"
        },
        "api": {
            "tag": "hydra-stats-api",
            "services": ["StatsService"]
        },
        "stats": {},
        "inbounds": raw_inbounds,
        "outbounds": raw_xray_outbounds(outbounds),
        "routing": raw_routing,
        "policy": raw_xray_policy(policy),
    })
}

fn raw_xray_inbound(inbound: &XrayInboundDocument) -> serde_json::Value {
    serde_json::json!({
        "tag": inbound.tag,
        "listen": "0.0.0.0",
        "port": inbound.port,
        "protocol": inbound.protocol,
        "settings": raw_xray_inbound_settings(inbound),
        "streamSettings": raw_xray_stream_settings(&inbound.stream_settings, &inbound.security_settings),
    })
}

fn raw_xray_inbound_settings(inbound: &XrayInboundDocument) -> serde_json::Value {
    match inbound.protocol.as_str() {
        "vless" => serde_json::json!({
            "decryption": "none",
            "clients": inbound.clients.iter().map(|client| {
                serde_json::json!({
                    "email": client.username,
                    "id": xray_client_uuid(client),
                    "level": 0
                })
            }).collect::<Vec<_>>()
        }),
        _ => serde_json::json!({
            "clients": inbound.clients.iter().map(|client| {
                serde_json::json!({
                    "email": client.username,
                    "id": xray_client_uuid(client),
                    "level": 0
                })
            }).collect::<Vec<_>>()
        }),
    }
}

fn xray_client_uuid(client: &XrayInboundClientDocument) -> String {
    client
        .credential_id
        .clone()
        .unwrap_or_else(|| runtime_client_uuid(&client.username, &client.subscription_token))
}

fn runtime_client_uuid(runtime_username: &str, subscription_token: &str) -> String {
    let digest = runtime_client_credential_digest("uuid", runtime_username, subscription_token);
    format!(
        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-4{:01x}{:02x}-{:01x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        digest[0],
        digest[1],
        digest[2],
        digest[3],
        digest[4],
        digest[5],
        digest[6] & 0x0f,
        digest[7],
        (digest[8] & 0x3f) | 0x80,
        digest[9],
        digest[10],
        digest[11],
        digest[12],
        digest[13],
        digest[14],
        digest[15]
    )
}

fn runtime_client_password(
    scope: &str,
    runtime_username: &str,
    subscription_token: &str,
) -> String {
    let digest = runtime_client_credential_digest(scope, runtime_username, subscription_token);
    digest
        .iter()
        .take(24)
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn runtime_client_credential_digest(
    scope: &str,
    runtime_username: &str,
    subscription_token: &str,
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(b"hydra-xray-client-v1");
    hasher.update(scope.as_bytes());
    hasher.update(runtime_username.as_bytes());
    hasher.update(subscription_token.as_bytes());
    hasher.finalize().into()
}

fn is_uuid_like(value: &str) -> bool {
    value.len() == 36
        && value.chars().enumerate().all(|(index, ch)| match index {
            8 | 13 | 18 | 23 => ch == '-',
            _ => ch.is_ascii_hexdigit(),
        })
}

/// Inserts a key into an object only when the value is set.
///
/// `serde_json::json!` with an `Option` writes `null`, while Xray distinguishes a
/// missing key from a key with a value: the removed `allowInsecure` is rejected by
/// presence, not by value. So only what is actually set reaches the config.
///
/// For structs serialized as a whole, `#[serde(skip_serializing_if =
/// "Option::is_none")]` has the same effect; here the config is built by hand and
/// the attribute does not apply.
fn insert_if_some<T: Into<serde_json::Value>>(
    target: &mut serde_json::Value,
    key: &str,
    value: Option<T>,
) {
    if let Some(value) = value {
        target[key] = value.into();
    }
}

fn raw_xray_stream_settings(
    stream: &XrayStreamSettingsDocument,
    security: &XraySecuritySettingsDocument,
) -> serde_json::Value {
    let mut value = serde_json::json!({
        "network": stream.network,
        "security": stream.security,
    });
    if stream.security == "tls" {
        // `allowInsecure` was removed from Xray and replaced by
        // `pinnedPeerCertSha256`. The key is not emitted at all rather than set to
        // false: Xray rejects a config carrying it with value `true` outright, and
        // there is no point keeping a field the schema no longer has in the
        // renderer. The internal `stream.allow_insecure` flag still carries the
        // fail-closed invariant but never reaches the JSON.
        //
        // This is an inbound (server side); pinning does not apply here, it is set
        // on the client side.
        let mut tls_settings = serde_json::json!({
            "certificates": [
                {
                    "certificateFile": format!("/etc/hydra/certs/{}.crt", security.certificate_ref.as_deref().unwrap_or("default")),
                    "keyFile": format!("/etc/hydra/certs/{}.key", security.certificate_ref.as_deref().unwrap_or("default"))
                }
            ]
        });
        // The key is emitted only when the value is set. Xray distinguishes a
        // missing key from `null`, and `allowInsecure` is exactly what caught us:
        // the field was present with a default value instead of being absent. The
        // rule is general, not about serverName alone.
        insert_if_some(
            &mut tls_settings,
            "serverName",
            security.server_name.as_deref(),
        );
        value["tlsSettings"] = tls_settings;
    }
    match stream.network.as_str() {
        "ws" => {
            value["wsSettings"] = serde_json::json!({
                "path": stream.path.as_deref().unwrap_or("/"),
                "headers": {
                    "Host": stream.host.as_deref().unwrap_or("")
                }
            });
        }
        "grpc" => {
            value["grpcSettings"] = serde_json::json!({
                "serviceName": stream.service_name.as_deref().unwrap_or("hydra")
            });
        }
        "httpupgrade" => {
            value["httpupgradeSettings"] = serde_json::json!({
                "path": stream.path.as_deref().unwrap_or("/"),
                "host": stream.host.as_deref().unwrap_or("")
            });
        }
        "xhttp" => {
            // The mode is emitted explicitly even when it is `auto`: under Reality
            // Xray expands auto to stream-one, and a silent gap between what the
            // operator picked and what actually runs is exactly the opacity that
            // makes XHTTP fail without a clear error.
            let reality_enabled = stream.security == "reality";
            let mode = stream
                .xhttp_mode
                .unwrap_or(XhttpMode::Auto)
                .effective(reality_enabled);
            value["xhttpSettings"] = serde_json::json!({
                "path": stream.path.as_deref().unwrap_or("/"),
                "mode": mode.as_str(),
                // Normalizes packet sizes: without padding, lengths stay
                // characteristic of a tunnel even with a disguised handshake.
                "extra": {
                    "xPaddingBytes": XHTTP_PADDING_BYTES
                }
            });
        }
        _ => {}
    }
    value
}

fn raw_xray_outbounds(outbounds: &[XrayOutboundDocument]) -> Vec<serde_json::Value> {
    let mut items = vec![
        serde_json::json!({
            "tag": "direct",
            "protocol": "freedom"
        }),
        serde_json::json!({
            "tag": "block",
            "protocol": "blackhole"
        }),
    ];
    items.extend(outbounds.iter().map(|outbound| {
        serde_json::json!({
            "tag": outbound.tag,
            "protocol": outbound.protocol,
            "settings": serde_json::from_str::<serde_json::Value>(&outbound.settings_json)
                .unwrap_or_else(|_| serde_json::json!({}))
        })
    }));
    items
}

fn raw_xray_routing(routing: &XrayRoutingConfigDocument) -> serde_json::Value {
    serde_json::json!({
        "domainStrategy": routing.domain_strategy,
        "rules": routing.rules.iter().map(|rule| {
            serde_json::json!({
                "type": rule.rule_type,
                "domain": rule.domains,
                "outboundTag": rule.outbound_tag
            })
        }).collect::<Vec<_>>()
    })
}

fn raw_xray_policy(policy: &XrayPolicyConfigDocument) -> serde_json::Value {
    let mut levels = serde_json::Map::new();
    for level in &policy.levels {
        levels.insert(
            level.level.to_string(),
            serde_json::json!({
                "handshake": level.handshake_seconds,
                "connIdle": level.conn_idle_seconds,
                "uplinkOnly": level.uplink_only_seconds,
                "downlinkOnly": level.downlink_only_seconds,
                "statsUserUplink": true,
                "statsUserDownlink": true
            }),
        );
    }
    serde_json::json!({
        "levels": levels,
        "system": {
            "statsInboundUplink": policy.system.stats_inbound_uplink,
            "statsInboundDownlink": policy.system.stats_inbound_downlink,
            "statsOutboundUplink": policy.system.stats_outbound_uplink,
            "statsOutboundDownlink": policy.system.stats_outbound_downlink
        }
    })
}

/// Validates a rendered Xray config.
///
/// `cdn_fronted_inbounds` names the inbounds reachable through a CDN. That is a
/// property of the hosts pointing at an inbound, which the rendered config does
/// not carry, so it is resolved by the caller and passed in rather than guessed
/// here.
fn validate_raw_xray_config(
    raw_config: &serde_json::Value,
    cdn_fronted_inbounds: &HashSet<String>,
) -> XrayRawConfigValidationReport {
    let mut issues = Vec::new();
    if !raw_config.is_object() {
        push_xray_validation_issue(
            &mut issues,
            "$",
            "error",
            "raw config must be a JSON object",
        );
        return xray_validation_report(issues);
    }

    let inbounds = raw_config
        .get("inbounds")
        .and_then(|value| value.as_array());
    if inbounds.is_none() {
        push_xray_validation_issue(
            &mut issues,
            "$.inbounds",
            "error",
            "inbounds must be an array",
        );
    }
    let outbounds = raw_config
        .get("outbounds")
        .and_then(|value| value.as_array());
    if outbounds.is_none() {
        push_xray_validation_issue(
            &mut issues,
            "$.outbounds",
            "error",
            "outbounds must be an array",
        );
    }
    if raw_config
        .get("routing")
        .is_none_or(|value| !value.is_object())
    {
        push_xray_validation_issue(
            &mut issues,
            "$.routing",
            "error",
            "routing must be an object",
        );
    }
    if raw_config
        .get("policy")
        .is_none_or(|value| !value.is_object())
    {
        push_xray_validation_issue(&mut issues, "$.policy", "error", "policy must be an object");
    }

    if let Some(inbounds) = inbounds {
        for (index, inbound) in inbounds.iter().enumerate() {
            validate_raw_xray_inbound(inbound, index, cdn_fronted_inbounds, &mut issues);
        }
    }
    if let Some(outbounds) = outbounds {
        if !outbounds.iter().any(|outbound| {
            outbound
                .get("tag")
                .and_then(|value| value.as_str())
                .is_some_and(|tag| tag == "direct")
        }) {
            push_xray_validation_issue(
                &mut issues,
                "$.outbounds",
                "error",
                "direct outbound is required",
            );
        }
        if !outbounds.iter().any(|outbound| {
            outbound
                .get("tag")
                .and_then(|value| value.as_str())
                .is_some_and(|tag| tag == "block")
        }) {
            push_xray_validation_issue(
                &mut issues,
                "$.outbounds",
                "error",
                "block outbound is required",
            );
        }
    }

    xray_validation_report(issues)
}

fn validate_raw_xray_inbound(
    inbound: &serde_json::Value,
    index: usize,
    cdn_fronted_inbounds: &HashSet<String>,
    issues: &mut Vec<XrayRawConfigValidationIssue>,
) {
    let path = format!("$.inbounds[{index}]");
    let behind_cdn = inbound
        .get("tag")
        .and_then(|value| value.as_str())
        .is_some_and(|tag| cdn_fronted_inbounds.contains(tag));
    if inbound
        .get("tag")
        .and_then(|value| value.as_str())
        .is_none()
    {
        push_xray_validation_issue(issues, &path, "error", "inbound tag is required");
    }
    if inbound
        .get("port")
        .and_then(|value| value.as_u64())
        .is_none_or(|port| port == 0 || port > u16::MAX as u64)
    {
        push_xray_validation_issue(issues, &path, "error", "inbound port must be valid");
    }
    let protocol = inbound
        .get("protocol")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    if protocol == "dokodemo-door"
        && inbound.get("tag").and_then(|value| value.as_str()) == Some("hydra-stats-api")
    {
        let loopback_only = inbound.get("listen").and_then(|value| value.as_str())
            == Some("127.0.0.1")
            && inbound
                .get("settings")
                .and_then(|settings| settings.get("address"))
                .and_then(|value| value.as_str())
                == Some("127.0.0.1");
        if !loopback_only {
            push_xray_validation_issue(
                issues,
                &path,
                "error",
                "Xray Stats API inbound must be loopback-only",
            );
        }
        return;
    }
    if !matches!(protocol, "vless") {
        push_xray_validation_issue(
            issues,
            &format!("{path}.protocol"),
            "error",
            "inbound protocol is unsupported",
        );
    }
    let Some(stream_settings) = inbound.get("streamSettings") else {
        push_xray_validation_issue(
            issues,
            &format!("{path}.streamSettings"),
            "error",
            "streamSettings are required",
        );
        return;
    };
    validate_raw_xray_stream_settings(stream_settings, &path, issues);
    validate_raw_xray_xhttp_semantics(inbound, stream_settings, behind_cdn, &path, issues);
    validate_raw_xray_inbound_settings(inbound, protocol, &path, issues);
}

/// Runs the XHTTP semantic rules against a rendered inbound.
///
/// The rules are stated over the stream settings document, while this validator
/// sees rendered JSON, so the document is reconstructed from the three fields the
/// rules read. Reconstructing rather than duplicating keeps one implementation of
/// the rules; the alternative was a second copy that could disagree with the
/// first, which is the defect class the rules exist to prevent.
///
/// `vision_enabled` is read from the inbound's own clients: `flow` is a per-client
/// field, so a rendered config carries the answer.
///
/// `behind_cdn` comes from the hosts that publish this inbound, resolved by
/// `cdn_fronted_inbound_tags` before validation, because the rendered config
/// carries no host information.
fn validate_raw_xray_xhttp_semantics(
    inbound: &serde_json::Value,
    stream_settings: &serde_json::Value,
    behind_cdn: bool,
    inbound_path: &str,
    issues: &mut Vec<XrayRawConfigValidationIssue>,
) {
    let network = stream_settings
        .get("network")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    let security = stream_settings
        .get("security")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    let xhttp_mode = stream_settings
        .get("xhttpSettings")
        .and_then(|settings| settings.get("mode"))
        .and_then(|value| value.as_str())
        .and_then(XhttpMode::parse);

    let vision_enabled = inbound
        .get("settings")
        .and_then(|settings| settings.get("clients"))
        .and_then(|clients| clients.as_array())
        .is_some_and(|clients| {
            clients.iter().any(|client| {
                client.get("flow").and_then(|value| value.as_str())
                    == Some(VlessFlow::XtlsRprxVision.as_str())
            })
        });

    let reconstructed = XrayStreamSettingsDocument {
        network: network.to_string(),
        security: security.to_string(),
        path: None,
        host: None,
        service_name: None,
        allow_insecure: false,
        xhttp_mode,
    };

    validate_xhttp_stream_settings(
        &reconstructed,
        vision_enabled,
        behind_cdn,
        &format!("{inbound_path}.streamSettings"),
        issues,
    );
}

fn validate_raw_xray_inbound_settings(
    inbound: &serde_json::Value,
    protocol: &str,
    inbound_path: &str,
    issues: &mut Vec<XrayRawConfigValidationIssue>,
) {
    let settings_path = format!("{inbound_path}.settings");
    let Some(settings) = inbound.get("settings").filter(|value| value.is_object()) else {
        push_xray_validation_issue(
            issues,
            &settings_path,
            "error",
            "inbound settings must be an object",
        );
        return;
    };
    let clients = settings.get("clients").and_then(|value| value.as_array());
    if clients.is_none_or(|clients| clients.is_empty()) {
        push_xray_validation_issue(
            issues,
            &format!("{settings_path}.clients"),
            "error",
            "inbound clients must be a non-empty array",
        );
    }
    if protocol == "vless" {
        if settings.get("decryption").and_then(|value| value.as_str()) != Some("none") {
            push_xray_validation_issue(
                issues,
                &format!("{settings_path}.decryption"),
                "error",
                "VLESS inbound decryption must be none",
            );
        }
        validate_raw_xray_clients_have_field(clients, "id", &settings_path, issues);
        validate_raw_xray_clients_have_uuid(clients, "id", &settings_path, issues);
    }
}

fn validate_raw_xray_clients_have_field(
    clients: Option<&Vec<serde_json::Value>>,
    field: &str,
    settings_path: &str,
    issues: &mut Vec<XrayRawConfigValidationIssue>,
) {
    if let Some(clients) = clients {
        for (index, client) in clients.iter().enumerate() {
            if client
                .get(field)
                .and_then(|value| value.as_str())
                .is_none_or(|value| value.trim().is_empty())
            {
                push_xray_validation_issue(
                    issues,
                    &format!("{settings_path}.clients[{index}].{field}"),
                    "error",
                    &format!("client {field} is required"),
                );
            }
        }
    }
}

fn validate_raw_xray_clients_have_uuid(
    clients: Option<&Vec<serde_json::Value>>,
    field: &str,
    settings_path: &str,
    issues: &mut Vec<XrayRawConfigValidationIssue>,
) {
    if let Some(clients) = clients {
        for (index, client) in clients.iter().enumerate() {
            if client
                .get(field)
                .and_then(|value| value.as_str())
                .is_none_or(|value| !is_uuid_like(value))
            {
                push_xray_validation_issue(
                    issues,
                    &format!("{settings_path}.clients[{index}].{field}"),
                    "error",
                    &format!("client {field} must be a UUID-like value"),
                );
            }
        }
    }
}

/// XHTTP checks that Xray does not perform.
///
/// `xray run -test` accepts any combination of mode, Vision and Reality: verified
/// on 26.6.27, a config with `packet-up` and `flow: xtls-rprx-vision` passes
/// `-test` and does not work. These are **semantic** rules rather than parsing
/// ones, so the binary does not check them and will not.
///
/// Every rule below carries a source. The requirement is not a formality: a
/// hand-written rule without one already gave us
/// `"Shadowsocks client method must be 2022-blake3-aes-128-gcm"` on client
/// entries — the exact opposite of what Xray requires ("users must have empty
/// method"). It survived until the first time we ran the renderer against the
/// real binary.
///
/// Sources (recheck when Xray is updated rather than treating them as permanent):
/// - XHTTP and its modes: <https://xtls.github.io/config/transports/splithttp.html>
/// - `mode` and `flow` compatibility: XTLS/Xray-core PR #3994 (XHTTP introduction),
///   the "XHTTP: Beyond REALITY" section of the Project X documentation
/// - Reality and TLS-terminating intermediaries:
///   <https://github.com/XTLS/REALITY> — the section on why a CDN cannot work
/// - `xPaddingBytes`: <https://xtls.github.io/config/transports/splithttp.html#xhttpobject>
fn validate_xhttp_stream_settings(
    stream: &XrayStreamSettingsDocument,
    vision_enabled: bool,
    behind_cdn: bool,
    path: &str,
    issues: &mut Vec<XrayRawConfigValidationIssue>,
) {
    let reality_requested = stream.security == "reality";

    // Reality cannot pass a CDN whatever the transport is, so this is checked
    // before the XHTTP-only rules rather than inside them. It used to sit after
    // the early return below, which left `tcp + reality` behind a CDN accepted —
    // the configuration this rule exists to refuse.
    if behind_cdn && reality_requested {
        push_xray_validation_issue(
            issues,
            &format!("{path}.security"),
            "error",
            "Reality cannot pass through a CDN; use real TLS behind a CDN",
        );
    }

    if stream.network != "xhttp" {
        if stream.xhttp_mode.is_some() {
            push_xray_validation_issue(
                issues,
                &format!("{path}.xhttpSettings.mode"),
                "error",
                "XHTTP mode is set on a non-XHTTP transport",
            );
        }
        // A CDN forces packet-up, and packet-up exists only under XHTTP. Any
        // other transport behind a CDN is refused rather than silently accepted.
        if behind_cdn {
            push_xray_validation_issue(
                issues,
                &format!("{path}.network"),
                "error",
                &format!(
                    "a host behind a CDN requires XHTTP with mode packet-up, got network {}",
                    stream.network
                ),
            );
        }
        return;
    }

    let requested = stream.xhttp_mode.unwrap_or(XhttpMode::Auto);
    let effective = requested.effective(reality_requested);

    // Vision lives inside stream-one and nowhere else. The axis of choice is the
    // transport, not "Vision versus XHTTP".
    //
    // Source: splithttp.html, the `mode` description — `stream-one` keeps a single
    // connection per request-response, so only it is compatible with XTLS-Vision;
    // `packet-up` and `stream-up` split the stream into transactions in which
    // Vision has nothing to splice.
    if vision_enabled && !effective.supports_vision() {
        push_xray_validation_issue(
            issues,
            &format!("{path}.xhttpSettings.mode"),
            "error",
            &format!(
                "flow xtls-rprx-vision requires XHTTP mode stream-one, got {}",
                effective.as_str()
            ),
        );
    }

    // The Reality rule is checked above, before the transport branch, because it
    // holds for every transport rather than only for XHTTP.
    //
    // Source: github.com/XTLS/REALITY — Reality substitutes the TLS handshake with
    // the target site, which requires an end-to-end connection to the server. A CDN
    // terminates TLS at its own edge, so there is nothing left to substitute.

    // Only packet-up is guaranteed to pass through a CDN or Nginx.
    //
    // Source: splithttp.html — `packet-up` uses a separate POST per packet and does
    // not need long-lived stream support, whereas `stream-up`/`stream-one` rely on
    // HTTP streaming, which intermediaries buffer or cut.
    if behind_cdn && !effective.survives_cdn() {
        push_xray_validation_issue(
            issues,
            &format!("{path}.xhttpSettings.mode"),
            "error",
            &format!(
                "only XHTTP mode packet-up is guaranteed through a CDN, got {}",
                effective.as_str()
            ),
        );
    }

    // packet-up and Vision are incompatible — reported separately from the general
    // mode rule, because this is the pair operators arrive with most often.
    //
    // Source: a consequence of the two rules above (a CDN forces `packet-up`,
    // Vision requires `stream-one`), not a separate Xray requirement.
    if behind_cdn && vision_enabled {
        push_xray_validation_issue(
            issues,
            &format!("{path}.settings.clients[].flow"),
            "error",
            "flow xtls-rprx-vision is incompatible with the packet-up mode a CDN requires",
        );
    }

    if requested == XhttpMode::Auto && reality_requested {
        // Not an error but an explicit message: Xray expands auto to stream-one on
        // its own, and the operator should see which mode is actually in effect.
        //
        // Source: splithttp.html, the `mode: auto` description — `stream-one` is
        // chosen under `security: reality`, `packet-up` otherwise.
        push_xray_validation_issue(
            issues,
            &format!("{path}.xhttpSettings.mode"),
            "info",
            "XHTTP mode auto resolves to stream-one when Reality is enabled",
        );
    }
}

fn validate_raw_xray_stream_settings(
    stream_settings: &serde_json::Value,
    inbound_path: &str,
    issues: &mut Vec<XrayRawConfigValidationIssue>,
) {
    let path = format!("{inbound_path}.streamSettings");
    let network = stream_settings
        .get("network")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    if !matches!(
        network,
        "tcp" | "udp" | "ws" | "grpc" | "httpupgrade" | "quic" | "xhttp"
    ) {
        push_xray_validation_issue(
            issues,
            &format!("{path}.network"),
            "error",
            "stream network is unsupported",
        );
    }
    let security = stream_settings
        .get("security")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    if !matches!(security, "none" | "tls" | "reality") {
        push_xray_validation_issue(
            issues,
            &format!("{path}.security"),
            "error",
            "stream security is unsupported",
        );
    }
    if security == "tls"
        && stream_settings
            .get("tlsSettings")
            .is_none_or(|value| !value.is_object())
    {
        push_xray_validation_issue(
            issues,
            &format!("{path}.tlsSettings"),
            "error",
            "tlsSettings are required when stream security is tls",
        );
    }
    if security == "tls" {
        validate_raw_xray_tls_settings(stream_settings.get("tlsSettings"), &path, issues);
    }
    if network == "ws"
        && stream_settings
            .get("wsSettings")
            .is_none_or(|value| !value.is_object())
    {
        push_xray_validation_issue(
            issues,
            &format!("{path}.wsSettings"),
            "error",
            "wsSettings are required when network is ws",
        );
    }
    if network == "grpc"
        && stream_settings
            .get("grpcSettings")
            .is_none_or(|value| !value.is_object())
    {
        push_xray_validation_issue(
            issues,
            &format!("{path}.grpcSettings"),
            "error",
            "grpcSettings are required when network is grpc",
        );
    }
    if network == "xhttp"
        && stream_settings
            .get("xhttpSettings")
            .is_none_or(|value| !value.is_object())
    {
        push_xray_validation_issue(
            issues,
            &format!("{path}.xhttpSettings"),
            "error",
            "xhttpSettings are required when network is xhttp",
        );
    }
}

fn validate_raw_xray_tls_settings(
    tls_settings: Option<&serde_json::Value>,
    stream_settings_path: &str,
    issues: &mut Vec<XrayRawConfigValidationIssue>,
) {
    let Some(tls_settings) = tls_settings.filter(|value| value.is_object()) else {
        return;
    };
    let path = format!("{stream_settings_path}.tlsSettings");
    if tls_settings
        .get("serverName")
        .and_then(|value| value.as_str())
        .is_none_or(|value| value.trim().is_empty())
    {
        push_xray_validation_issue(
            issues,
            &format!("{path}.serverName"),
            "error",
            "TLS serverName is required",
        );
    }
    let certificates = tls_settings
        .get("certificates")
        .and_then(|value| value.as_array());
    if certificates.is_none_or(|certificates| certificates.is_empty()) {
        push_xray_validation_issue(
            issues,
            &format!("{path}.certificates"),
            "error",
            "TLS certificates must be a non-empty array",
        );
        return;
    }
    if let Some(certificates) = certificates {
        for (index, certificate) in certificates.iter().enumerate() {
            for field in ["certificateFile", "keyFile"] {
                if certificate
                    .get(field)
                    .and_then(|value| value.as_str())
                    .is_none_or(|value| value.trim().is_empty())
                {
                    push_xray_validation_issue(
                        issues,
                        &format!("{path}.certificates[{index}].{field}"),
                        "error",
                        &format!("TLS certificate {field} is required"),
                    );
                }
            }
        }
    }
}

fn push_xray_validation_issue(
    issues: &mut Vec<XrayRawConfigValidationIssue>,
    path: &str,
    severity: &str,
    reason: &str,
) {
    issues.push(XrayRawConfigValidationIssue {
        path: path.to_string(),
        severity: severity.to_string(),
        reason: reason.to_string(),
    });
}

fn xray_validation_report(
    issues: Vec<XrayRawConfigValidationIssue>,
) -> XrayRawConfigValidationReport {
    XrayRawConfigValidationReport {
        valid: !issues.iter().any(|issue| issue.severity == "error"),
        checked_at_unix: now_unix(),
        issue_count: issues.len(),
        issues,
    }
}

fn run_xray_external_validation(
    raw_config: serde_json::Value,
    internal_report: XrayRawConfigValidationReport,
    binary_path: Option<String>,
    temp_dir: String,
) -> XrayExternalValidationReport {
    if !internal_report.valid {
        return xray_external_validation_report(
            XrayExternalValidationStatus::Skipped,
            binary_path,
            false,
            None,
            String::new(),
            String::new(),
            "internal raw config validation failed; external xray test was not run".to_string(),
        );
    }

    let Some(binary_path) = binary_path
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
    else {
        return xray_external_validation_report(
            XrayExternalValidationStatus::Skipped,
            None,
            true,
            None,
            String::new(),
            String::new(),
            "HYDRA_XRAY_BINARY_PATH is not configured".to_string(),
        );
    };

    if !Path::new(&binary_path).is_file() {
        return xray_external_validation_report(
            XrayExternalValidationStatus::Skipped,
            Some(binary_path),
            true,
            None,
            String::new(),
            String::new(),
            "configured Xray binary path does not exist or is not a file".to_string(),
        );
    }

    let temp_dir = PathBuf::from(temp_dir);
    if let Err(error) = fs::create_dir_all(&temp_dir) {
        return xray_external_validation_report(
            XrayExternalValidationStatus::Failed,
            Some(binary_path),
            true,
            None,
            String::new(),
            String::new(),
            format!("failed to create Xray validation temp directory: {error}"),
        );
    }

    let temp_config_path = temp_dir.join(format!(
        "xray-validation-{}-{}.json",
        now_unix(),
        random::<u64>()
    ));
    let raw_config_bytes = match serde_json::to_vec_pretty(&raw_config) {
        Ok(bytes) => bytes,
        Err(error) => {
            return xray_external_validation_report(
                XrayExternalValidationStatus::Failed,
                Some(binary_path),
                true,
                None,
                String::new(),
                String::new(),
                format!("failed to serialize generated Xray config: {error}"),
            );
        }
    };
    if let Err(error) = fs::write(&temp_config_path, raw_config_bytes) {
        return xray_external_validation_report(
            XrayExternalValidationStatus::Failed,
            Some(binary_path),
            true,
            None,
            String::new(),
            String::new(),
            format!("failed to write temporary Xray config: {error}"),
        );
    }

    let output = Command::new(&binary_path)
        .args(["run", "-test", "-config"])
        .arg(&temp_config_path)
        .output();
    let _ = fs::remove_file(&temp_config_path);

    match output {
        Ok(output) => {
            let stdout = truncate_xray_validation_output(
                String::from_utf8_lossy(&output.stdout).to_string(),
            );
            let stderr = truncate_xray_validation_output(
                String::from_utf8_lossy(&output.stderr).to_string(),
            );
            if output.status.success() {
                xray_external_validation_report(
                    XrayExternalValidationStatus::Passed,
                    Some(binary_path),
                    true,
                    output.status.code(),
                    stdout,
                    stderr,
                    "xray run -test accepted the generated config".to_string(),
                )
            } else {
                xray_external_validation_report(
                    XrayExternalValidationStatus::Failed,
                    Some(binary_path),
                    true,
                    output.status.code(),
                    stdout,
                    stderr,
                    "xray run -test rejected the generated config".to_string(),
                )
            }
        }
        Err(error) => xray_external_validation_report(
            XrayExternalValidationStatus::Failed,
            Some(binary_path),
            true,
            None,
            String::new(),
            String::new(),
            format!("failed to execute Xray binary: {error}"),
        ),
    }
}

fn xray_external_validation_report(
    status: XrayExternalValidationStatus,
    binary_path: Option<String>,
    internal_validation_valid: bool,
    exit_code: Option<i32>,
    stdout: String,
    stderr: String,
    detail: String,
) -> XrayExternalValidationReport {
    XrayExternalValidationReport {
        status,
        checked_at_unix: now_unix(),
        binary_path,
        internal_validation_valid,
        exit_code,
        stdout,
        stderr,
        detail,
        config_retained: false,
    }
}

fn core_apply_stage_status_from_xray_external(
    status: XrayExternalValidationStatus,
) -> CoreApplyStageStatus {
    match status {
        XrayExternalValidationStatus::Passed => CoreApplyStageStatus::Passed,
        XrayExternalValidationStatus::Failed => CoreApplyStageStatus::Failed,
        XrayExternalValidationStatus::Skipped => CoreApplyStageStatus::Skipped,
    }
}

#[derive(Debug, Deserialize)]
struct XrayGithubReleaseResponse {
    tag_name: String,
    prerelease: bool,
    assets: Vec<XrayGithubReleaseAssetResponse>,
}

#[derive(Debug, Deserialize)]
struct XrayGithubReleaseAssetResponse {
    name: String,
    browser_download_url: String,
}

async fn plan_xray_core_update(
    config: &AppConfig,
    request: XrayCoreUpdateRequest,
    raw_config: serde_json::Value,
    internal_validation: XrayRawConfigValidationReport,
) -> XrayCoreUpdateReport {
    let requested_at_unix = now_unix();
    let mut stages = Vec::new();
    let mut progress = XrayUpdateProgress {
        target_version: request.target_version.clone(),
        ..XrayUpdateProgress::default()
    };

    if config.xray_binary_path.is_none() {
        stages.push(xray_update_stage(
            XrayCoreUpdateStage::Preflight,
            CoreApplyStageStatus::Failed,
            "HYDRA_XRAY_BINARY_PATH is required before Xray update can be planned",
        ));
        return xray_update_report(
            requested_at_unix,
            XrayCoreUpdateStatus::Failed,
            &progress,
            config,
            "Xray binary path is not configured".to_string(),
            stages,
        );
    }

    stages.push(xray_update_stage(
        XrayCoreUpdateStage::Preflight,
        CoreApplyStageStatus::Passed,
        "Xray binary path is configured",
    ));

    let release_url = xray_release_url(
        &config.xray_release_api_url,
        progress.target_version.as_deref(),
    );
    if let Err(error) = validate_xray_update_url(&release_url, XrayUpdateUrlKind::ReleaseApi) {
        stages.push(xray_update_stage(
            XrayCoreUpdateStage::ReleaseResolved,
            CoreApplyStageStatus::Failed,
            &error,
        ));
        return xray_update_report(
            requested_at_unix,
            XrayCoreUpdateStatus::Failed,
            &progress,
            config,
            "Xray release URL is not trusted".to_string(),
            stages,
        );
    }
    let release = match reqwest::Client::new()
        .get(&release_url)
        .header("User-Agent", "hydra-panel")
        .send()
        .await
    {
        Ok(response) => match response.error_for_status() {
            Ok(response) => response.json::<XrayGithubReleaseResponse>().await,
            Err(error) => Err(error),
        },
        Err(error) => Err(error),
    };

    let release = match release {
        Ok(release) => release,
        Err(error) => {
            stages.push(xray_update_stage(
                XrayCoreUpdateStage::ReleaseResolved,
                CoreApplyStageStatus::Failed,
                &format!("failed to resolve official Xray release: {error}"),
            ));
            return xray_update_report(
                requested_at_unix,
                XrayCoreUpdateStatus::Failed,
                &progress,
                config,
                "failed to resolve official Xray release".to_string(),
                stages,
            );
        }
    };

    if release.prerelease && !request.allow_prerelease {
        stages.push(xray_update_stage(
            XrayCoreUpdateStage::ReleaseResolved,
            CoreApplyStageStatus::Failed,
            "resolved release is prerelease and allow_prerelease is false",
        ));
        progress.target_version = Some(release.tag_name);
        return xray_update_report(
            requested_at_unix,
            XrayCoreUpdateStatus::Blocked,
            &progress,
            config,
            "prerelease Xray update is blocked by policy".to_string(),
            stages,
        );
    }

    progress.target_version = Some(release.tag_name.clone());
    stages.push(xray_update_stage(
        XrayCoreUpdateStage::ReleaseResolved,
        CoreApplyStageStatus::Passed,
        &format!("resolved official Xray release {}", release.tag_name),
    ));

    match select_xray_release_asset(
        &release.assets,
        std::env::consts::OS,
        std::env::consts::ARCH,
    ) {
        Some(asset) => {
            progress.selected_asset_name = Some(asset.name.clone());
            progress.selected_asset_url = Some(asset.browser_download_url.clone());
            stages.push(xray_update_stage(
                XrayCoreUpdateStage::AssetSelected,
                CoreApplyStageStatus::Passed,
                &format!("selected asset {}", asset.name),
            ));
        }
        None => {
            stages.push(xray_update_stage(
                XrayCoreUpdateStage::AssetSelected,
                CoreApplyStageStatus::Failed,
                "no official Xray asset matches this OS/architecture",
            ));
            return xray_update_report(
                requested_at_unix,
                XrayCoreUpdateStatus::Failed,
                &progress,
                config,
                "no matching Xray release asset found".to_string(),
                stages,
            );
        }
    }

    match fs::create_dir_all(&config.xray_update_work_dir) {
        Ok(()) => stages.push(xray_update_stage(
            XrayCoreUpdateStage::DownloadPrepared,
            CoreApplyStageStatus::Passed,
            "Xray update work directory is ready",
        )),
        Err(error) => {
            stages.push(xray_update_stage(
                XrayCoreUpdateStage::DownloadPrepared,
                CoreApplyStageStatus::Failed,
                &format!("failed to prepare Xray update work directory: {error}"),
            ));
            return xray_update_report(
                requested_at_unix,
                XrayCoreUpdateStatus::Failed,
                &progress,
                config,
                "failed to prepare Xray update work directory".to_string(),
                stages,
            );
        }
    }

    let asset_url = progress
        .selected_asset_url
        .clone()
        .expect("selected asset URL exists after successful asset selection");
    let asset_name = progress
        .selected_asset_name
        .clone()
        .expect("selected asset name exists after successful asset selection");
    match download_xray_update_asset(config, &asset_url, &asset_name).await {
        Ok((archive_path, sha256_hex, byte_count)) => {
            progress.downloaded_archive_path = Some(archive_path.to_string_lossy().to_string());
            progress.downloaded_sha256 = Some(sha256_hex.clone());
            stages.push(xray_update_stage(
                XrayCoreUpdateStage::Downloaded,
                CoreApplyStageStatus::Passed,
                &format!("downloaded {byte_count} bytes; sha256={sha256_hex}"),
            ));
            let archive_path_for_extract = archive_path;
            let candidate_dir = PathBuf::from(&config.xray_update_work_dir)
                .join(progress.target_version.as_deref().unwrap_or("unknown"))
                .join("candidate");
            let max_binary_bytes = config.xray_update_max_download_bytes;
            match tokio::task::spawn_blocking(move || {
                extract_xray_candidate_binary(
                    &archive_path_for_extract,
                    &candidate_dir,
                    max_binary_bytes,
                )
            })
            .await
            {
                Ok(Ok(candidate_path)) => {
                    progress.candidate_binary_path =
                        Some(candidate_path.to_string_lossy().to_string());
                    stages.push(xray_update_stage(
                        XrayCoreUpdateStage::Extracted,
                        CoreApplyStageStatus::Passed,
                        "candidate Xray binary extracted safely",
                    ));

                    match xray_candidate_version(&candidate_path) {
                        Ok(version) => {
                            progress.candidate_version = Some(version.clone());
                            stages.push(xray_update_stage(
                                XrayCoreUpdateStage::CandidateVersion,
                                CoreApplyStageStatus::Passed,
                                &format!("candidate version output: {version}"),
                            ));
                        }
                        Err(error) => {
                            stages.push(xray_update_stage(
                                XrayCoreUpdateStage::CandidateVersion,
                                CoreApplyStageStatus::Failed,
                                &error,
                            ));
                            return xray_update_report(
                                requested_at_unix,
                                XrayCoreUpdateStatus::Failed,
                                &progress,
                                config,
                                "candidate Xray binary failed version check".to_string(),
                                stages,
                            );
                        }
                    }

                    let validation = run_xray_external_validation(
                        raw_config.clone(),
                        internal_validation.clone(),
                        Some(candidate_path.to_string_lossy().to_string()),
                        config.xray_validation_temp_dir.clone(),
                    );
                    let candidate_config_status =
                        core_apply_stage_status_from_xray_external(validation.status);
                    stages.push(xray_update_stage(
                        XrayCoreUpdateStage::CandidateConfigTest,
                        candidate_config_status,
                        &validation.detail,
                    ));
                    if validation.status != XrayExternalValidationStatus::Passed {
                        return xray_update_report(
                            requested_at_unix,
                            XrayCoreUpdateStatus::Failed,
                            &progress,
                            config,
                            "candidate Xray binary failed generated config test".to_string(),
                            stages,
                        );
                    }
                }
                Ok(Err(error)) => {
                    stages.push(xray_update_stage(
                        XrayCoreUpdateStage::Extracted,
                        CoreApplyStageStatus::Failed,
                        &error,
                    ));
                    return xray_update_report(
                        requested_at_unix,
                        XrayCoreUpdateStatus::Failed,
                        &progress,
                        config,
                        "failed to extract candidate Xray binary".to_string(),
                        stages,
                    );
                }
                Err(_) => {
                    stages.push(xray_update_stage(
                        XrayCoreUpdateStage::Extracted,
                        CoreApplyStageStatus::Failed,
                        "candidate extraction task failed",
                    ));
                    return xray_update_report(
                        requested_at_unix,
                        XrayCoreUpdateStatus::Failed,
                        &progress,
                        config,
                        "candidate extraction task failed".to_string(),
                        stages,
                    );
                }
            }
        }
        Err(error) => {
            stages.push(xray_update_stage(
                XrayCoreUpdateStage::Downloaded,
                CoreApplyStageStatus::Failed,
                &error,
            ));
            return xray_update_report(
                requested_at_unix,
                XrayCoreUpdateStatus::Failed,
                &progress,
                config,
                "failed to download Xray release asset".to_string(),
                stages,
            );
        }
    }

    if request.confirm_binary_swap {
        let active_binary_path = PathBuf::from(
            config
                .xray_binary_path
                .as_ref()
                .expect("xray binary path is configured after preflight"),
        );
        let candidate_path = PathBuf::from(
            progress
                .candidate_binary_path
                .as_ref()
                .expect("candidate binary path exists after candidate validation"),
        );
        match swap_xray_binary_with_backup(
            &active_binary_path,
            &candidate_path,
            &PathBuf::from(&config.xray_update_work_dir),
            progress.target_version.as_deref().unwrap_or("unknown"),
        ) {
            Ok(backup_path) => {
                progress.active_backup_path = Some(backup_path.to_string_lossy().to_string());
                stages.push(xray_update_stage(
                    XrayCoreUpdateStage::BinarySwap,
                    CoreApplyStageStatus::Passed,
                    "active Xray binary replaced and previous binary backed up",
                ));
                match xray_candidate_version(&active_binary_path) {
                    Ok(version) => {
                        progress.post_swap_version = Some(version.clone());
                        stages.push(xray_update_stage(
                            XrayCoreUpdateStage::ConfigTest,
                            CoreApplyStageStatus::Passed,
                            &format!("post-swap version output: {version}"),
                        ));
                    }
                    Err(error) => {
                        let rollback_detail =
                            rollback_xray_binary(&active_binary_path, &backup_path);
                        stages.push(xray_update_stage(
                            XrayCoreUpdateStage::ConfigTest,
                            CoreApplyStageStatus::Failed,
                            &format!(
                                "post-swap version failed: {error}; rollback={rollback_detail}"
                            ),
                        ));
                        return xray_update_report(
                            requested_at_unix,
                            XrayCoreUpdateStatus::Failed,
                            &progress,
                            config,
                            "post-swap Xray version check failed; rollback attempted".to_string(),
                            stages,
                        );
                    }
                }

                let validation = run_xray_external_validation(
                    raw_config,
                    internal_validation,
                    Some(active_binary_path.to_string_lossy().to_string()),
                    config.xray_validation_temp_dir.clone(),
                );
                if validation.status != XrayExternalValidationStatus::Passed {
                    let rollback_detail = rollback_xray_binary(&active_binary_path, &backup_path);
                    stages.push(xray_update_stage(
                        XrayCoreUpdateStage::ConfigTest,
                        CoreApplyStageStatus::Failed,
                        &format!(
                            "post-swap config test failed: {}; rollback={rollback_detail}",
                            validation.detail
                        ),
                    ));
                    return xray_update_report(
                        requested_at_unix,
                        XrayCoreUpdateStatus::Failed,
                        &progress,
                        config,
                        "post-swap generated config test failed; rollback attempted".to_string(),
                        stages,
                    );
                }

                stages.push(xray_update_stage(
                    XrayCoreUpdateStage::RestartGate,
                    CoreApplyStageStatus::Passed,
                    "active Xray binary is swapped and post-swap config test passed; restart must be requested explicitly",
                ));

                return xray_update_report(
                    requested_at_unix,
                    XrayCoreUpdateStatus::Swapped,
                    &progress,
                    config,
                    "Xray binary swapped safely; explicit restart is now allowed".to_string(),
                    stages,
                );
            }
            Err(error) => {
                stages.push(xray_update_stage(
                    XrayCoreUpdateStage::BinarySwap,
                    CoreApplyStageStatus::Failed,
                    &error,
                ));
                return xray_update_report(
                    requested_at_unix,
                    XrayCoreUpdateStatus::Failed,
                    &progress,
                    config,
                    "failed to swap active Xray binary".to_string(),
                    stages,
                );
            }
        }
    }

    stages.push(xray_update_stage(
        XrayCoreUpdateStage::BinarySwap,
        CoreApplyStageStatus::Skipped,
        "binary swap not requested; active runtime binary was not mutated",
    ));
    stages.push(xray_update_stage(
        XrayCoreUpdateStage::ConfigTest,
        CoreApplyStageStatus::Skipped,
        "post-swap config test skipped because binary swap was not requested",
    ));
    stages.push(xray_update_stage(
        XrayCoreUpdateStage::RestartGate,
        CoreApplyStageStatus::Skipped,
        "restart is not allowed until candidate binary passes config test",
    ));

    xray_update_report(
        requested_at_unix,
        XrayCoreUpdateStatus::Planned,
        &progress,
        config,
        "Xray update candidate validated without mutating active runtime".to_string(),
        stages,
    )
}

/// What the update flow has established so far.
///
/// The flow reports out of sixteen different places, and every report has to
/// carry everything discovered up to that point. Passed as one value because the
/// alternative was repeating the same eleven arguments at each of those sixteen
/// call sites, where a single misordered pair would compile and report the wrong
/// field.
#[derive(Debug, Default)]
struct XrayUpdateProgress {
    target_version: Option<String>,
    selected_asset_name: Option<String>,
    selected_asset_url: Option<String>,
    downloaded_archive_path: Option<String>,
    downloaded_sha256: Option<String>,
    candidate_binary_path: Option<String>,
    candidate_version: Option<String>,
    active_backup_path: Option<String>,
    post_swap_version: Option<String>,
}

fn xray_update_report(
    requested_at_unix: u64,
    status: XrayCoreUpdateStatus,
    progress: &XrayUpdateProgress,
    config: &AppConfig,
    detail: String,
    stages: Vec<XrayCoreUpdateStageRecord>,
) -> XrayCoreUpdateReport {
    XrayCoreUpdateReport {
        requested_at_unix,
        status,
        target_version: progress.target_version.clone(),
        selected_asset_name: progress.selected_asset_name.clone(),
        selected_asset_url: progress.selected_asset_url.clone(),
        binary_path: config.xray_binary_path.clone(),
        work_dir: config.xray_update_work_dir.clone(),
        downloaded_archive_path: progress.downloaded_archive_path.clone(),
        downloaded_sha256: progress.downloaded_sha256.clone(),
        candidate_binary_path: progress.candidate_binary_path.clone(),
        candidate_version: progress.candidate_version.clone(),
        active_backup_path: progress.active_backup_path.clone(),
        post_swap_version: progress.post_swap_version.clone(),
        detail,
        stages,
    }
}

fn xray_update_stage(
    stage: XrayCoreUpdateStage,
    status: CoreApplyStageStatus,
    detail: &str,
) -> XrayCoreUpdateStageRecord {
    XrayCoreUpdateStageRecord {
        stage,
        status,
        detail: detail.to_string(),
    }
}

fn xray_release_url(base_url: &str, target_version: Option<&str>) -> String {
    match target_version {
        Some(version) if base_url.ends_with("/latest") => {
            format!(
                "{}/tags/{}",
                base_url.trim_end_matches("/latest"),
                version.trim()
            )
        }
        _ => base_url.to_string(),
    }
}

fn select_xray_release_asset<'a>(
    assets: &'a [XrayGithubReleaseAssetResponse],
    os: &str,
    arch: &str,
) -> Option<&'a XrayGithubReleaseAssetResponse> {
    let os_label = match os {
        "linux" => "linux",
        "windows" => "windows",
        "macos" => "macos",
        "freebsd" => "freebsd",
        _ => return None,
    };
    assets.iter().find(|asset| {
        let name = asset.name.to_ascii_lowercase();
        name.ends_with(".zip")
            && name.contains(os_label)
            && xray_asset_name_matches_arch(&name, arch)
    })
}

fn xray_asset_name_matches_arch(name: &str, arch: &str) -> bool {
    match arch {
        "x86_64" => {
            (name.contains("-64.") || name.contains("-64.zip") || name.contains("amd64"))
                && !name.contains("arm64")
        }
        "aarch64" => name.contains("arm64") || name.contains("arm64-v8a"),
        "arm" => name.contains("arm32") || (name.contains("arm") && !name.contains("arm64")),
        "x86" => name.contains("-32.") || name.contains("-32.zip") || name.contains("386"),
        _ => false,
    }
}

async fn download_xray_update_asset(
    config: &AppConfig,
    asset_url: &str,
    asset_name: &str,
) -> Result<(PathBuf, String, u64), String> {
    validate_xray_update_url(asset_url, XrayUpdateUrlKind::AssetDownload)?;
    let safe_asset_name = sanitize_xray_asset_name(asset_name)?;
    let archive_path = PathBuf::from(&config.xray_update_work_dir).join(safe_asset_name);
    let response = reqwest::Client::new()
        .get(asset_url)
        .header("User-Agent", "hydra-panel")
        .send()
        .await
        .map_err(|error| format!("failed to start asset download: {error}"))?;
    validate_xray_update_url(response.url().as_str(), XrayUpdateUrlKind::AssetDownload)?;
    let mut response = response
        .error_for_status()
        .map_err(|error| format!("asset download returned unsuccessful status: {error}"))?;
    if let Some(content_length) = response.content_length()
        && content_length > config.xray_update_max_download_bytes
    {
        return Err(format!(
            "asset content-length {content_length} exceeds limit {}",
            config.xray_update_max_download_bytes
        ));
    }

    let mut file = File::create(&archive_path)
        .map_err(|error| format!("failed to create asset file: {error}"))?;
    let mut hasher = Sha256::new();
    let mut downloaded = 0u64;
    while let Some(chunk) = response.chunk().await.map_err(|error| {
        let _ = fs::remove_file(&archive_path);
        format!("failed while downloading asset: {error}")
    })? {
        downloaded = downloaded.saturating_add(chunk.len() as u64);
        if downloaded > config.xray_update_max_download_bytes {
            let _ = fs::remove_file(&archive_path);
            return Err(format!(
                "downloaded asset exceeds limit {}",
                config.xray_update_max_download_bytes
            ));
        }
        hasher.update(&chunk);
        file.write_all(&chunk).map_err(|error| {
            let _ = fs::remove_file(&archive_path);
            format!("failed to write downloaded asset: {error}")
        })?;
    }
    file.flush()
        .map_err(|error| format!("failed to flush downloaded asset: {error}"))?;
    Ok((archive_path, format!("{:x}", hasher.finalize()), downloaded))
}

fn sanitize_xray_asset_name(asset_name: &str) -> Result<String, String> {
    let name = asset_name.trim();
    if name.is_empty()
        || name.contains('/')
        || name.contains('\\')
        || name.contains("..")
        || !name.ends_with(".zip")
    {
        return Err("unsafe Xray asset name".to_string());
    }
    Ok(name.to_string())
}

#[derive(Debug, Clone, Copy)]
enum XrayUpdateUrlKind {
    ReleaseApi,
    AssetDownload,
}

fn validate_xray_update_url(url: &str, kind: XrayUpdateUrlKind) -> Result<(), String> {
    let url = reqwest::Url::parse(url).map_err(|_| "invalid Xray update URL".to_string())?;
    if url.scheme() != "https" {
        return Err("Xray update URL must use https".to_string());
    }
    let host = url
        .host_str()
        .ok_or_else(|| "Xray update URL has no host".to_string())?;
    let allowed = match kind {
        XrayUpdateUrlKind::ReleaseApi => host == "api.github.com",
        XrayUpdateUrlKind::AssetDownload => matches!(
            host,
            "github.com"
                | "objects.githubusercontent.com"
                | "github-releases.githubusercontent.com"
                | "release-assets.githubusercontent.com"
        ),
    };
    if !allowed {
        return Err(format!("Xray update URL host is not trusted: {host}"));
    }
    Ok(())
}

fn extract_xray_candidate_binary(
    archive_path: &Path,
    candidate_dir: &Path,
    max_binary_bytes: u64,
) -> Result<PathBuf, String> {
    fs::create_dir_all(candidate_dir)
        .map_err(|error| format!("failed to create candidate directory: {error}"))?;
    let archive_file =
        File::open(archive_path).map_err(|error| format!("failed to open archive: {error}"))?;
    let mut archive = ZipArchive::new(archive_file)
        .map_err(|error| format!("failed to read zip archive: {error}"))?;
    let candidate_file_name = if cfg!(windows) { "xray.exe" } else { "xray" };
    let candidate_path = candidate_dir.join(candidate_file_name);

    for index in 0..archive.len() {
        let file = archive
            .by_index(index)
            .map_err(|error| format!("failed to read archive entry: {error}"))?;
        if file.is_dir() {
            continue;
        }
        let Some(enclosed_name) = file.enclosed_name() else {
            continue;
        };
        let entry_name = enclosed_name
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or_default();
        if entry_name != candidate_file_name {
            continue;
        }
        if file.size() > max_binary_bytes {
            return Err(format!(
                "candidate Xray binary exceeds limit {max_binary_bytes} bytes"
            ));
        }
        let mut output = File::create(&candidate_path)
            .map_err(|error| format!("failed to create candidate binary: {error}"))?;
        let mut limited_file = file.take(max_binary_bytes + 1);
        let copied = std::io::copy(&mut limited_file, &mut output)
            .map_err(|error| format!("failed to extract candidate binary: {error}"))?;
        if copied > max_binary_bytes {
            let _ = fs::remove_file(&candidate_path);
            return Err(format!(
                "candidate Xray binary exceeds limit {max_binary_bytes} bytes"
            ));
        }
        output
            .flush()
            .map_err(|error| format!("failed to flush candidate binary: {error}"))?;
        #[cfg(unix)]
        {
            let mut permissions = output
                .metadata()
                .map_err(|error| format!("failed to inspect candidate binary: {error}"))?
                .permissions();
            permissions.set_mode(0o755);
            fs::set_permissions(&candidate_path, permissions)
                .map_err(|error| format!("failed to set candidate binary permissions: {error}"))?;
        }
        return Ok(candidate_path);
    }

    Err("archive does not contain an Xray binary for this platform".to_string())
}

fn xray_candidate_version(candidate_path: &Path) -> Result<String, String> {
    let output = Command::new(candidate_path)
        .arg("version")
        .output()
        .map_err(|error| format!("failed to execute candidate xray version: {error}"))?;
    let stdout = truncate_xray_validation_output(String::from_utf8_lossy(&output.stdout).into());
    let stderr = truncate_xray_validation_output(String::from_utf8_lossy(&output.stderr).into());
    if !output.status.success() {
        return Err(format!(
            "candidate xray version failed: exit={:?}; stdout={}; stderr={}",
            output.status.code(),
            stdout,
            stderr
        ));
    }
    let version = stdout
        .lines()
        .next()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .unwrap_or("xray version output was empty")
        .to_string();
    Ok(version)
}

fn swap_xray_binary_with_backup(
    active_binary_path: &Path,
    candidate_binary_path: &Path,
    work_dir: &Path,
    target_version: &str,
) -> Result<PathBuf, String> {
    if !active_binary_path.is_file() {
        return Err("active Xray binary path does not exist or is not a file".to_string());
    }
    if !candidate_binary_path.is_file() {
        return Err("candidate Xray binary path does not exist or is not a file".to_string());
    }
    let backup_dir = work_dir
        .join("backups")
        .join(sanitize_path_segment(target_version));
    fs::create_dir_all(&backup_dir)
        .map_err(|error| format!("failed to create Xray backup directory: {error}"))?;
    let active_file_name = active_binary_path
        .file_name()
        .and_then(|value| value.to_str())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "active Xray binary path has no file name".to_string())?;
    let backup_path = backup_dir.join(format!(
        "{}.backup-{}-{}",
        active_file_name,
        now_unix(),
        random::<u64>()
    ));

    fs::copy(active_binary_path, &backup_path)
        .map_err(|error| format!("failed to back up active Xray binary: {error}"))?;
    fs::copy(candidate_binary_path, active_binary_path).map_err(|error| {
        let _ = fs::copy(&backup_path, active_binary_path);
        format!("failed to replace active Xray binary: {error}")
    })?;
    #[cfg(unix)]
    {
        let mut permissions = fs::metadata(active_binary_path)
            .map_err(|error| format!("failed to inspect swapped Xray binary: {error}"))?
            .permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(active_binary_path, permissions)
            .map_err(|error| format!("failed to set swapped Xray binary permissions: {error}"))?;
    }
    Ok(backup_path)
}

fn rollback_xray_binary(active_binary_path: &Path, backup_path: &Path) -> String {
    match fs::copy(backup_path, active_binary_path) {
        Ok(_) => "restored backup binary".to_string(),
        Err(error) => format!("failed to restore backup binary: {error}"),
    }
}

fn sanitize_path_segment(value: &str) -> String {
    value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '.' || ch == '-' || ch == '_' {
                ch
            } else {
                '_'
            }
        })
        .collect()
}

fn truncate_xray_validation_output(value: String) -> String {
    if value.len() <= XRAY_EXTERNAL_VALIDATION_OUTPUT_LIMIT {
        return value;
    }
    let cutoff = value
        .char_indices()
        .map(|(index, _)| index)
        .take_while(|index| *index <= XRAY_EXTERNAL_VALIDATION_OUTPUT_LIMIT)
        .last()
        .unwrap_or(0);
    format!(
        "{}\n[truncated to {} bytes]",
        &value[..cutoff],
        XRAY_EXTERNAL_VALIDATION_OUTPUT_LIMIT
    )
}

fn xray_security_settings_for_inbound(
    inbound: &Inbound,
    generated: &GeneratedCoreConfigPreview,
) -> XraySecuritySettingsDocument {
    let host = representative_host_for_inbound(inbound, generated);
    let server_name = host.and_then(|host| host.sni.clone().or_else(|| Some(host.address.clone())));
    XraySecuritySettingsDocument {
        mode: if inbound.tls_enabled {
            "tls".to_string()
        } else {
            "none".to_string()
        },
        server_name,
        certificate_ref: inbound
            .tls_enabled
            .then(|| format!("inbound:{}:tls", inbound.tag)),
        reality_public_key: None,
        reality_short_id: None,
    }
}

/// Reality material for the inbounds that need it.
///
/// An inbound counts as a Reality inbound when the host representing it declares
/// `security: reality`. `dest` and `serverNames` are derived from the host's SNI:
/// Reality masquerades as the site whose name it presents, so there must be no
/// second source of truth for that pair.
///
/// A host without an SNI gets no material — recorded as a blocking config
/// validation error rather than a silent skip.
fn collect_reality_materials(
    reality_materials_path: &str,
    reality_materials_key_path: &str,
    generated: &GeneratedCoreConfigPreview,
) -> Result<Vec<NodeRealityMaterial>, SecurityError> {
    let mut materials = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();

    for inbound in &generated.inbounds {
        let Some(host) = representative_host_for_inbound(inbound, generated) else {
            continue;
        };
        if !host.security.eq_ignore_ascii_case("reality") {
            continue;
        }
        let Some(server_name) = reality_server_name(host) else {
            continue;
        };
        if !seen.insert(inbound.tag.clone()) {
            continue;
        }

        let material = ensure_inbound_reality_material(
            reality_materials_path,
            reality_materials_key_path,
            &inbound.tag,
        )?;
        materials.push(NodeRealityMaterial {
            inbound_tag: inbound.tag.clone(),
            private_key_b64: material.private_key_b64,
            short_ids: material.short_ids,
            dest: reality_dest_for(&server_name),
            server_names: vec![server_name],
        });
    }

    Ok(materials)
}

/// The name Reality masquerades as, taken from the host's SNI.
fn reality_server_name(host: &GeneratedHost) -> Option<String> {
    host.sni
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

/// Where Reality proxies unrecognized traffic.
///
/// The same host as in `serverNames`, on 443: the disguise must lead to the site
/// whose name is presented, otherwise the mismatch shows on the first active
/// probe.
fn reality_dest_for(server_name: &str) -> String {
    format!("{server_name}:443")
}

/// The host representing an inbound.
///
/// This used to be `user.hosts.first()` — the first host of any user who has this
/// inbound. For Reality that handed out another inbound's material, because the
/// material is bound to the inbound rather than the user. Now only hosts whose
/// scope is compatible with the inbound are selected, by the same logic as
/// `host_serves_inbound`.
fn representative_host_for_inbound<'a>(
    inbound: &Inbound,
    generated: &'a GeneratedCoreConfigPreview,
) -> Option<&'a GeneratedHost> {
    generated.users.iter().find_map(|user| {
        if !user
            .inbounds
            .iter()
            .any(|candidate| candidate.tag == inbound.tag)
        {
            return None;
        }
        user.hosts
            .iter()
            .find(|host| host_serves_inbound(host, inbound))
    })
}

fn inbound_transport_name(transport: InboundTransport) -> String {
    match transport {
        InboundTransport::Tcp => "tcp",
        InboundTransport::Udp => "udp",
        InboundTransport::Ws => "ws",
        InboundTransport::Grpc => "grpc",
        InboundTransport::HttpUpgrade => "httpupgrade",
        InboundTransport::Quic => "quic",
        InboundTransport::Xhttp => "xhttp",
    }
    .to_string()
}

/// The XHTTP padding range. Normalizes packet sizes so lengths do not give the
/// tunnel away. The value is a range string, as Xray expects.
const XHTTP_PADDING_BYTES: &str = "100-1000";

const MAX_SUBSCRIPTION_ENDPOINTS: usize = 512;
const MAX_SUBSCRIPTION_RENDER_ISSUES: usize = 128;

#[derive(Debug, serde::Serialize)]
struct SubscriptionClientBundle {
    schema_version: u16,
    username: String,
    status: String,
    data_limit_bytes: Option<u64>,
    expire_at_unix: Option<u64>,
    endpoints: Vec<SubscriptionClientEndpoint>,
    issues: Vec<SubscriptionRenderIssue>,
}

#[derive(Debug, serde::Serialize)]
struct SubscriptionClientEndpoint {
    id: String,
    name: String,
    protocol: String,
    address: String,
    port: u16,
    network: String,
    security: String,
    node_id: Option<String>,
    cluster_id: Option<String>,
    uri: Option<String>,
    client_config: serde_json::Value,
}

#[derive(Debug, serde::Serialize)]
struct SubscriptionRenderIssue {
    profile_id: Option<String>,
    inbound_tag: Option<String>,
    host_id: Option<String>,
    reason: String,
}

fn render_subscription_body(
    config: &GeneratedUserConfig,
    format: SubscriptionFormat,
) -> Result<(String, String), SecurityError> {
    if format == SubscriptionFormat::DiagnosticJson {
        return Ok((
            "application/json".to_string(),
            serde_json::to_string_pretty(config).map_err(|_| SecurityError::PersistenceFailure)?,
        ));
    }

    let bundle = build_subscription_client_bundle(config);
    match format {
        SubscriptionFormat::Json => Ok((
            "application/json".to_string(),
            serde_json::to_string_pretty(&bundle).map_err(|_| SecurityError::PersistenceFailure)?,
        )),
        SubscriptionFormat::PlainText | SubscriptionFormat::Base64 => {
            let mut links = bundle
                .endpoints
                .iter()
                .filter_map(|endpoint| endpoint.uri.clone())
                .collect::<Vec<_>>();
            links.sort();
            links.dedup();
            if links.is_empty() {
                return Err(SecurityError::InvalidSecuritySettings(
                    "subscription has no URI-compatible endpoints; request format=json for structured-only protocols",
                ));
            }
            let links = format!("{}\n", links.join("\n"));
            if format == SubscriptionFormat::Base64 {
                Ok((
                    "text/plain; charset=utf-8".to_string(),
                    BASE64.encode(links.as_bytes()),
                ))
            } else {
                Ok(("text/plain; charset=utf-8".to_string(), links))
            }
        }
        SubscriptionFormat::DiagnosticJson => unreachable!(),
    }
}

fn build_subscription_client_bundle(config: &GeneratedUserConfig) -> SubscriptionClientBundle {
    let mut endpoints = Vec::new();
    let mut issues = Vec::new();

    for inbound in &config.inbounds {
        let profiles = config
            .proxy_profiles
            .iter()
            .filter(|profile| profile.proxy_type.eq_ignore_ascii_case(&inbound.protocol))
            .collect::<Vec<_>>();
        if profiles.is_empty() {
            push_subscription_render_issue(
                &mut issues,
                None,
                Some(&inbound.tag),
                None,
                "no matching client profile is configured for inbound",
            );
            continue;
        }
        let hosts = config
            .hosts
            .iter()
            .filter(|host| subscription_host_matches_inbound(host, inbound))
            .collect::<Vec<_>>();
        if hosts.is_empty() {
            push_subscription_render_issue(
                &mut issues,
                None,
                Some(&inbound.tag),
                None,
                "no compatible public host is configured for inbound",
            );
            continue;
        }

        for profile in profiles {
            let Ok(settings) = serde_json::from_str::<serde_json::Value>(&profile.settings_json)
            else {
                push_subscription_render_issue(
                    &mut issues,
                    Some(&profile.id),
                    Some(&inbound.tag),
                    None,
                    "profile settings are not valid JSON",
                );
                continue;
            };
            if !generated_profile_allows_inbound(&settings, &inbound.tag) {
                continue;
            }
            for host in &hosts {
                if endpoints.len() >= MAX_SUBSCRIPTION_ENDPOINTS {
                    push_subscription_render_issue(
                        &mut issues,
                        None,
                        None,
                        None,
                        "subscription endpoint limit reached; remaining endpoints were omitted",
                    );
                    break;
                }
                match render_subscription_endpoint(profile, inbound, host, &settings) {
                    Ok(endpoint) => endpoints.push(endpoint),
                    Err(reason) => push_subscription_render_issue(
                        &mut issues,
                        Some(&profile.id),
                        Some(&inbound.tag),
                        Some(&host.id),
                        reason,
                    ),
                }
            }
        }
    }
    endpoints.sort_by(|left, right| left.id.cmp(&right.id));

    SubscriptionClientBundle {
        schema_version: SchemaId::SubscriptionBundle.version(),
        username: config.username.clone(),
        status: format!("{:?}", config.status).to_ascii_lowercase(),
        data_limit_bytes: config.data_limit_bytes,
        expire_at_unix: config.expire_at_unix,
        endpoints,
        issues,
    }
}

fn push_subscription_render_issue(
    issues: &mut Vec<SubscriptionRenderIssue>,
    profile_id: Option<&str>,
    inbound_tag: Option<&str>,
    host_id: Option<&str>,
    reason: impl Into<String>,
) {
    if issues.len() >= MAX_SUBSCRIPTION_RENDER_ISSUES {
        return;
    }
    issues.push(SubscriptionRenderIssue {
        profile_id: profile_id.map(ToOwned::to_owned),
        inbound_tag: inbound_tag.map(ToOwned::to_owned),
        host_id: host_id.map(ToOwned::to_owned),
        reason: reason.into(),
    });
}

fn subscription_host_matches_inbound(host: &GeneratedHost, inbound: &Inbound) -> bool {
    match (
        inbound.node_id.as_deref(),
        inbound.cluster_id.as_deref(),
        host.node_id.as_deref(),
        host.cluster_id.as_deref(),
    ) {
        (None, None, None, None) => true,
        (inbound_node, inbound_cluster, host_node, host_cluster) => {
            inbound_node.is_some_and(|value| host_node == Some(value))
                || inbound_cluster.is_some_and(|value| host_cluster == Some(value))
        }
    }
}

fn render_subscription_endpoint(
    profile: &GeneratedProxyProfile,
    inbound: &Inbound,
    host: &GeneratedHost,
    settings: &serde_json::Value,
) -> Result<SubscriptionClientEndpoint, &'static str> {
    if host.address.trim().is_empty() || host.port == 0 {
        return Err("public host address and port are required");
    }
    let is_reality = host.security.eq_ignore_ascii_case("reality");
    // Fail-closed: the host is declared as Reality but has no material, so no link
    // is issued at all. A link silently handed out without pbk/sid will not
    // connect, and that only surfaces on the user's side.
    if is_reality
        && (host.reality_public_key.is_none()
            || host.reality_short_id.is_none()
            || host.sni.as_deref().map(str::trim).unwrap_or("").is_empty())
    {
        return Err(
            "Reality host requires SNI, public key and short id before links can be issued",
        );
    }

    let protocol = profile.proxy_type.to_ascii_lowercase();
    let network = inbound_transport_name(inbound.network);
    let security = if is_reality {
        "reality"
    } else if inbound.tls_enabled || host.security.eq_ignore_ascii_case("tls") {
        "tls"
    } else {
        "none"
    };
    let address = host.address.trim().to_string();
    let authority_host = subscription_authority_host(&address);
    let sni = host
        .sni
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(address.as_str());
    let path = host.path.as_deref().unwrap_or("/");
    let name = format!("{} - {}", profile.name, host.remark);
    let fragment = urlencoding::encode(&name);

    let (uri, client_config) = match protocol.as_str() {
        "vless" => {
            let id = string_json_setting(settings, &["id", "uuid"])
                .filter(|value| is_uuid_like(value))
                .ok_or("VLESS profile requires a valid UUID")?;
            let query = subscription_transport_query(
                &network,
                security,
                sni,
                &address,
                path,
                host.reality_public_key.as_deref(),
                host.reality_short_id.as_deref(),
            );
            (
                Some(format!(
                    "vless://{}@{}:{}?{}#{}",
                    urlencoding::encode(&id),
                    authority_host,
                    host.port,
                    query,
                    fragment
                )),
                serde_json::json!({
                    "id": id,
                    "address": address,
                    "port": host.port,
                    "network": network,
                    "security": security,
                    "sni": sni,
                    "host": host.address,
                    "path": path,
                    "encryption": "none",
                    "tls_fingerprint": TLS_FINGERPRINT,
                    "reality_public_key": host.reality_public_key,
                    "reality_short_id": host.reality_short_id
                }),
            )
        }
        "hysteria2" => {
            let password = string_json_setting(settings, &["password"])
                .ok_or("Hysteria2 profile requires a password")?;
            (
                Some(format!(
                    "hysteria2://{}@{}:{}/?sni={}&insecure=0#{}",
                    urlencoding::encode(&password),
                    authority_host,
                    host.port,
                    urlencoding::encode(sni),
                    fragment
                )),
                serde_json::json!({
                    "password": password,
                    "address": address,
                    "port": host.port,
                    "sni": sni,
                    "tls_insecure": false
                }),
            )
        }
        "wireguard" => {
            let client_public_key =
                string_json_setting(settings, &["peer_public_key", "public_key"])
                    .ok_or("WireGuard profile requires the registered client public key")?;
            let server_public_key = string_json_setting(settings, &["server_public_key"])
                .ok_or("WireGuard profile requires server_public_key for client export")?;
            let allowed_ips = settings
                .get("allowed_ips")
                .and_then(serde_json::Value::as_array)
                .map(|items| {
                    items
                        .iter()
                        .filter_map(serde_json::Value::as_str)
                        .map(ToOwned::to_owned)
                        .collect::<Vec<_>>()
                })
                .filter(|items| !items.is_empty())
                .ok_or("WireGuard profile requires client allowed_ips")?;
            (
                None,
                serde_json::json!({
                    "client_private_key_required": true,
                    "client_private_key_managed_by_panel": false,
                    "client_public_key": client_public_key,
                    "server_public_key": server_public_key,
                    "addresses": allowed_ips,
                    "endpoint": format!("{}:{}", authority_host, host.port)
                }),
            )
        }
        _ => return Err("protocol does not have a production subscription renderer"),
    };

    Ok(SubscriptionClientEndpoint {
        id: format!("{}:{}:{}", profile.id, inbound.tag, host.id),
        name,
        protocol,
        address,
        port: host.port,
        network,
        security: security.to_string(),
        node_id: host.node_id.clone().or_else(|| inbound.node_id.clone()),
        cluster_id: host
            .cluster_id
            .clone()
            .or_else(|| inbound.cluster_id.clone()),
        uri,
        client_config,
    })
}

/// The uTLS fingerprint for client connections.
///
/// Without it Xray uses Go `crypto/tls`, whose JA3/JA4 differs from any browser
/// and lands in detection databases automatically.
///
/// The `TLS_` prefix is deliberate: in panel-core the word `fingerprint` is
/// already taken by subscription device fingerprints, a different thing.
const TLS_FINGERPRINT: &str = "chrome";

/// Fills a generated config with the public half of the Reality material.
///
/// Called at the `AppState` level, where the store paths are reachable. The
/// private key never gets here: a client needs only the public key and short id.
///
/// Reality material is bound to an **inbound**, while the public half is stored on
/// a **host**. As long as a host serves one Reality inbound the two coincide; once
/// there are more there is no unambiguous answer, and the host used to receive the
/// first one's material — clients silently failed to connect with someone else's
/// `pbk`/`sid`. Such a configuration is now rejected fail-closed.
fn attach_reality_public_material(
    config: &mut GeneratedUserConfig,
    reality_materials_path: &str,
    reality_materials_key_path: &str,
) -> Result<(), SecurityError> {
    let mut tags_by_host: HashMap<String, Vec<String>> = HashMap::new();
    for host in &config.hosts {
        if !host.security.eq_ignore_ascii_case("reality") {
            continue;
        }
        for inbound in &config.inbounds {
            if host_serves_inbound(host, inbound) {
                tags_by_host
                    .entry(host.id.clone())
                    .or_default()
                    .push(inbound.tag.clone());
            }
        }
    }

    if tags_by_host.is_empty() {
        return Ok(());
    }

    // The ambiguity is visible before any material is handed out, so the refusal
    // comes before a client can receive the wrong key.
    if let Some((host_id, tags)) = tags_by_host.iter().find(|(_, tags)| tags.len() > 1) {
        let mut tags = tags.clone();
        tags.sort();
        return Err(SecurityError::InvalidSecuritySettings(
            reality_ambiguity_reason(host_id, &tags),
        ));
    }

    for host in &mut config.hosts {
        let Some(tag) = tags_by_host
            .get(&host.id)
            .and_then(|tags| tags.first())
            .cloned()
        else {
            continue;
        };
        let material = ensure_inbound_reality_material(
            reality_materials_path,
            reality_materials_key_path,
            &tag,
        )?;
        host.reality_public_key = Some(material.public_key_b64);
        host.reality_short_id = material.short_ids.first().cloned();
    }

    Ok(())
}

/// The message for an ambiguous Reality binding.
///
/// `SecurityError::InvalidSecuritySettings` carries a `&'static str`, so the
/// specific tags are logged separately and a stable wording goes out.
fn reality_ambiguity_reason(host_id: &str, tags: &[String]) -> &'static str {
    let _ = (host_id, tags);
    "a host cannot serve more than one Reality inbound: \
     Reality material is per-inbound, so clients would receive keys from the wrong one. \
     Scope the host to a single node or cluster, or split the inbounds across hosts"
}

/// A host serves an inbound when their scopes are compatible.
///
/// Hosts carry no inbound tag, so the binding goes through node and cluster — the
/// same logic that filters a config down to a specific node
/// (`generated_endpoint_belongs_to_node`). The rule is symmetric:
///
/// - both named explicitly -> they must match;
/// - one side unnamed -> it is shared and fits any;
/// - host bound to a node, inbound to a cluster (or the reverse) -> not
///   compatible, because there is nothing here to check node-cluster membership
///   with.
///
/// The function used to return `true` unconditionally, which made every host count
/// as serving every inbound.
/// Inbounds reachable through at least one CDN-fronted host.
///
/// A CDN sits in front of the address a client connects to, which is what a host
/// is, so the flag lives on the host. One inbound can be published through
/// several hosts, and a single fronted host is enough: the inbound has to be
/// renderable for that path too. The conflict therefore resolves towards the
/// restriction — packet-up, and no Reality — rather than towards whichever host
/// happens to be listed first.
///
/// Host-to-inbound binding uses `host_serves_inbound`, the same predicate that
/// scopes Reality material, so the two cannot disagree about which hosts serve an
/// inbound.
fn cdn_fronted_inbound_tags(generated: &GeneratedCoreConfigPreview) -> HashSet<String> {
    let mut tags = HashSet::new();
    for inbound in &generated.inbounds {
        let fronted = generated.users.iter().any(|user| {
            user.inbounds
                .iter()
                .any(|candidate| candidate.tag == inbound.tag)
                && user
                    .hosts
                    .iter()
                    .any(|host| host.behind_cdn && host_serves_inbound(host, inbound))
        });
        if fronted {
            tags.insert(inbound.tag.clone());
        }
    }
    tags
}

fn host_serves_inbound(host: &GeneratedHost, inbound: &Inbound) -> bool {
    match (
        host.node_id.as_deref(),
        host.cluster_id.as_deref(),
        inbound.node_id.as_deref(),
        inbound.cluster_id.as_deref(),
    ) {
        (Some(host_node), _, Some(inbound_node), _) => host_node == inbound_node,
        (None, Some(host_cluster), None, Some(inbound_cluster)) => host_cluster == inbound_cluster,
        (None, None, _, _) | (_, _, None, None) => true,
        _ => false,
    }
}

fn subscription_transport_query(
    network: &str,
    security: &str,
    sni: &str,
    host: &str,
    path: &str,
    reality_public_key: Option<&str>,
    reality_short_id: Option<&str>,
) -> String {
    let mut values = vec![("type", network), ("security", security), ("sni", sni)];
    if matches!(network, "ws" | "httpupgrade") {
        values.push(("host", host));
        values.push(("path", path));
    }
    // The uTLS fingerprint. Without it the client presents Go crypto/tls, whose
    // JA3/JA4 differs from any browser and is recognized automatically.
    if matches!(security, "tls" | "reality") {
        values.push(("fp", TLS_FINGERPRINT));
    }
    if security == "reality" {
        if let Some(public_key) = reality_public_key {
            values.push(("pbk", public_key));
        }
        if let Some(short_id) = reality_short_id {
            values.push(("sid", short_id));
        }
    }
    values
        .into_iter()
        .map(|(key, value)| format!("{key}={}", urlencoding::encode(value)))
        .collect::<Vec<_>>()
        .join("&")
}

fn subscription_authority_host(address: &str) -> String {
    let trimmed = address.trim();
    if trimmed.starts_with('[') && trimmed.ends_with(']') {
        return trimmed.to_string();
    }
    if trimmed.parse::<std::net::Ipv6Addr>().is_ok() {
        format!("[{trimmed}]")
    } else {
        trimmed.to_string()
    }
}

fn build_alert_candidates(
    config: &AppConfig,
    disk: &DiskStats,
    memory_used_bytes: u64,
    memory_total_bytes: u64,
    panel_process_memory_used_bytes: Option<u64>,
) -> Vec<ActiveAlert> {
    let disk_used_percent = percent_u64(disk.used_bytes, disk.total_bytes);
    let memory_used_percent = percent_u64(memory_used_bytes, memory_total_bytes);
    let mut alerts = Vec::new();

    if let Some((severity, threshold_percent)) = classify_percent(
        disk_used_percent,
        config.monitoring.disk_warning_percent,
        config.monitoring.disk_critical_percent,
    ) {
        alerts.push(ActiveAlert {
            kind: AlertKind::DiskUsage,
            severity,
            message: format!(
                "disk usage is at {}% (threshold: {}%)",
                disk_used_percent, threshold_percent
            ),
            observed_percent: disk_used_percent,
            threshold_percent,
            observed_value: Some(disk.used_bytes),
            threshold_value: Some(percent_threshold_bytes(disk.total_bytes, threshold_percent)),
            first_seen_at_unix: 0,
        });
    }

    if let Some((severity, threshold_percent)) = classify_percent(
        memory_used_percent,
        config.monitoring.memory_warning_percent,
        config.monitoring.memory_critical_percent,
    ) {
        alerts.push(ActiveAlert {
            kind: AlertKind::MemoryUsage,
            severity,
            message: format!(
                "memory usage is at {}% (threshold: {}%)",
                memory_used_percent, threshold_percent
            ),
            observed_percent: memory_used_percent,
            threshold_percent,
            observed_value: Some(memory_used_bytes),
            threshold_value: Some(percent_threshold_bytes(
                memory_total_bytes,
                threshold_percent,
            )),
            first_seen_at_unix: 0,
        });
    }

    if let Some(panel_process_memory_used_bytes) = panel_process_memory_used_bytes {
        let budget_bytes = (config.runtime_limits.memory_budget_mb as u64)
            .saturating_mul(1024)
            .saturating_mul(1024);
        let panel_process_memory_percent =
            percent_u64(panel_process_memory_used_bytes, budget_bytes);
        if let Some((severity, threshold_percent)) = classify_percent(
            panel_process_memory_percent,
            config.monitoring.memory_warning_percent,
            config.monitoring.memory_critical_percent,
        ) {
            alerts.push(ActiveAlert {
                kind: AlertKind::PanelMemoryBudget,
                severity,
                message: format!(
                    "panel process memory is at {}% of the configured {} MB budget (threshold: {}%)",
                    panel_process_memory_percent,
                    config.runtime_limits.memory_budget_mb,
                    threshold_percent
                ),
                observed_percent: panel_process_memory_percent,
                threshold_percent,
                observed_value: Some(panel_process_memory_used_bytes),
                threshold_value: Some(percent_threshold_bytes(budget_bytes, threshold_percent)),
                first_seen_at_unix: 0,
            });
        }
    }

    alerts
}

fn build_node_alert_candidates(summary: &NodeHealthCenterSummary) -> Vec<ActiveAlert> {
    let mut alerts = Vec::new();
    if summary.enabled == 0 {
        return alerts;
    }

    if summary.offline > 0 {
        alerts.push(count_alert(
            AlertKind::NodeOffline,
            AlertSeverity::Critical,
            summary.offline,
            "node(s) are offline",
        ));
    }

    if summary.stale_heartbeat > 0 {
        alerts.push(count_alert(
            AlertKind::NodeStaleHeartbeat,
            AlertSeverity::Critical,
            summary.stale_heartbeat,
            "node(s) have stale heartbeat",
        ));
    }

    if summary.drifted > 0 || summary.pending > 0 {
        let affected = summary.drifted.saturating_add(summary.pending);
        alerts.push(count_alert(
            AlertKind::NodeConfigDrift,
            AlertSeverity::Warning,
            affected,
            "node(s) are not synced with generated config",
        ));
    }

    if summary.provisioning_failed > 0 {
        alerts.push(count_alert(
            AlertKind::NodeProvisioningFailed,
            AlertSeverity::Warning,
            summary.provisioning_failed,
            "node provisioning task(s) failed",
        ));
    }

    if summary.provisioning_stale > 0 {
        alerts.push(count_alert(
            AlertKind::NodeProvisioningStale,
            AlertSeverity::Warning,
            summary.provisioning_stale,
            "node provisioning task(s) stopped reporting progress",
        ));
    }

    if summary.reported_apply_failed > 0 {
        alerts.push(count_alert(
            AlertKind::NodeReportedApplyFailed,
            AlertSeverity::Warning,
            summary.reported_apply_failed,
            "node-reported apply failure(s) detected",
        ));
    }

    if summary.runtime_alerts_active > 0 {
        let severity = if summary.runtime_alerts_critical > 0 {
            AlertSeverity::Critical
        } else {
            AlertSeverity::Warning
        };
        alerts.push(count_alert(
            AlertKind::NodeRuntimeAlert,
            severity,
            summary.runtime_alerts_active,
            "node(s) reported active runtime alert(s)",
        ));
    }

    alerts
}

fn is_node_health_alert_event(event: &AlertEvent) -> bool {
    matches!(
        event.kind,
        AlertKind::NodeOffline
            | AlertKind::NodeStaleHeartbeat
            | AlertKind::NodeConfigDrift
            | AlertKind::NodeProvisioningStale
            | AlertKind::NodeProvisioningFailed
            | AlertKind::NodeReportedApplyFailed
            | AlertKind::NodeRuntimeAlert
    )
}

fn format_alert_telegram_message(event: &AlertEvent) -> String {
    let status = match event.status {
        AlertEventStatus::Activated => "activated",
        AlertEventStatus::Resolved => "resolved",
    };
    let severity = match event.severity {
        AlertSeverity::Warning => "warning",
        AlertSeverity::Critical => "critical",
    };
    let prefix = if is_node_health_alert_event(event) {
        "Node health alert"
    } else {
        "System alert"
    };
    format!("{prefix} {status} [{severity}]: {}", event.message)
}

fn count_alert(
    kind: AlertKind,
    severity: AlertSeverity,
    observed: usize,
    message_suffix: &str,
) -> ActiveAlert {
    ActiveAlert {
        kind,
        severity,
        message: format!("{observed} {message_suffix}"),
        observed_percent: observed.min(u8::MAX as usize) as u8,
        threshold_percent: 1,
        observed_value: Some(observed as u64),
        threshold_value: Some(1),
        first_seen_at_unix: 0,
    }
}

fn percent_threshold_bytes(total: u64, threshold_percent: u8) -> u64 {
    total.saturating_mul(threshold_percent as u64) / 100
}

fn normalize_optional_secret(value: Option<String>) -> Option<String> {
    value
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

async fn fetch_node_local_json<T>(node: &Node, path: &str) -> Result<T, SecurityError>
where
    T: serde::de::DeserializeOwned,
{
    let url = format!(
        "http://{}:{}/{}",
        node.address,
        node.api_port,
        path.trim_start_matches('/')
    );
    let mut request = reqwest::Client::new().get(url);
    if let Some(token) = node.local_api_token.as_deref() {
        request = request.header("X-Hydra-Local-Token", token);
    }
    request
        .send()
        .await
        .map_err(|_| SecurityError::PersistenceFailure)?
        .error_for_status()
        .map_err(|_| SecurityError::PersistenceFailure)?
        .json::<T>()
        .await
        .map_err(|_| SecurityError::PersistenceFailure)
}

async fn post_node_local_action(
    node: &Node,
    path: &str,
) -> Result<NodeLocalActionResponse, SecurityError> {
    let url = format!(
        "http://{}:{}/{}",
        node.address,
        node.api_port,
        path.trim_start_matches('/')
    );
    let mut request = reqwest::Client::new().post(url);
    if let Some(token) = node.local_api_token.as_deref() {
        request = request.header("X-Hydra-Local-Token", token);
    }
    request
        .send()
        .await
        .map_err(|_| SecurityError::PersistenceFailure)?
        .error_for_status()
        .map_err(|_| SecurityError::PersistenceFailure)?
        .json::<NodeLocalActionResponse>()
        .await
        .map(|mut response| {
            response.detail = truncate_node_report_field(&response.detail);
            response
        })
        .map_err(|_| SecurityError::PersistenceFailure)
}

fn build_node_diagnostics_recommendations(
    node: &Node,
    local_health: Option<&NodeLocalHealthView>,
    local_state: Option<&NodeLocalStateView>,
) -> Vec<String> {
    let mut recommendations = Vec::new();

    if !node.enabled {
        recommendations.push("Node is disabled in panel settings.".to_string());
    }

    if matches!(
        node.sync_status,
        NodeSyncStatus::Drifted | NodeSyncStatus::Pending
    ) {
        recommendations.push(
            "Node config is not fully synced. Trigger apply and inspect sync history.".to_string(),
        );
    }

    if matches!(node.status, NodeStatus::Degraded | NodeStatus::Offline) {
        recommendations.push(
            "Panel sees node as degraded or offline. Verify heartbeat flow and local agent health."
                .to_string(),
        );
    }

    if local_health.is_none() {
        recommendations.push("Panel cannot reach the node local API. Check node address/api_port, firewall rules, and that the Rust agent is running.".to_string());
    }

    if let Some(health) = local_health
        && health.status != "healthy"
    {
        recommendations.push(format!(
            "Node local health is {}. Inspect /local/state and runtime event history.",
            health.status
        ));
    }

    if let Some(state) = local_state {
        if state.rollback_marker_path.is_some() {
            recommendations.push(
                "Rollback marker is present. Review the last failed apply and consider runtime rollback.".to_string(),
            );
        }
        if matches!(
            state.xray_runtime_status,
            panel_domain::node::NodeLocalRuntimeStatus::Failed
        ) {
            recommendations.push(
                "Xray runtime is failed. Check last runtime detail, backoff state, and consider restart or rollback.".to_string(),
            );
        }
        if state.xray_restart_attempts > 0 {
            recommendations.push(format!(
                "Automatic restart backoff is active (attempts: {}). Wait for the next retry or intervene manually.",
                state.xray_restart_attempts
            ));
        }
        if state.consecutive_tick_failures > 0 {
            recommendations.push(format!(
                "Node agent has consecutive tick failures ({}). Inspect panel connectivity and local runtime events.",
                state.consecutive_tick_failures
            ));
        }
        if state.xray_detected_version.is_none() {
            recommendations.push(
                "Xray version is not detected on the node. Verify binary installation path and local runtime configuration."
                    .to_string(),
            );
        }
        if let Some(summary) = state.last_xray_render_summary.as_ref() {
            if summary.fail_closed {
                recommendations.push(
                    "Last Xray render failed closed. Inspect route credential material, peer endpoint data, and render feature flags."
                        .to_string(),
                );
            }
            if summary.inbound_count == 0 {
                recommendations.push(
                    "Last Xray render produced no inbounds. Verify node route assignments and generated inbound config."
                        .to_string(),
                );
            }
        } else {
            recommendations.push(
                "No Xray render summary is available yet. Apply config on the node before treating runtime diagnostics as complete."
                    .to_string(),
            );
        }
    }

    if recommendations.is_empty() {
        recommendations.push("No immediate issues detected.".to_string());
    }

    recommendations
}

fn build_bootstrap_probe_recommendations(
    node: &Node,
    local_health: Option<&NodeLocalHealthView>,
    local_state: Option<&NodeLocalStateView>,
) -> Vec<String> {
    let mut recommendations = Vec::new();

    if !matches!(node.sync_status, NodeSyncStatus::Synced) {
        recommendations.push(
            "Run node apply after bootstrap so the node receives the current generated revision."
                .to_string(),
        );
    }

    if !node_agent_heartbeat_after_latest_token(node) {
        recommendations.push(
            "Wait for an authenticated node-agent heartbeat after the latest node-token issuance; local service reachability or an old heartbeat alone does not prove the current bootstrap."
                .to_string(),
        );
    }

    match local_health {
        Some(health) if health.status == "healthy" => {}
        Some(health) => recommendations.push(format!(
            "Local health is {}. Inspect node diagnostics before considering bootstrap complete.",
            health.status
        )),
        None => recommendations.push(
            "Panel cannot read local health from the node. Verify that the Rust node local API is exposed on api_port."
                .to_string(),
        ),
    }

    if let Some(state) = local_state {
        if state.rollback_marker_path.is_some() {
            recommendations.push(
                "Rollback marker is present. Resolve the failed apply or use runtime rollback before production use."
                    .to_string(),
            );
        }
        if state.xray_detected_version.is_none() {
            recommendations.push(
                "Xray version is not detected yet. Verify binary installation or run xray update."
                    .to_string(),
            );
        }
        if state.xray_restart_attempts > 0 {
            recommendations.push(
                "Node is in restart backoff after runtime failure. Wait for recovery or intervene manually."
                    .to_string(),
            );
        }
    }

    if recommendations.is_empty() {
        recommendations.push(
            "Bootstrap probe passed. Node looks ready for normal panel operations.".to_string(),
        );
    }

    recommendations
}

fn node_agent_heartbeat_after_latest_token(node: &Node) -> bool {
    matches!(
        (node.last_agent_heartbeat_at_unix, node.auth_token_issued_at_unix),
        (Some(heartbeat_at), Some(token_at)) if heartbeat_at >= token_at
    )
}

fn build_node_provisioning_preflight_recommendations(
    node: &Node,
    checks: &[NodeProvisioningPreflightCheck],
    local_state: Option<&NodeLocalStateView>,
) -> Vec<String> {
    let mut recommendations = Vec::new();

    for check in checks {
        if matches!(check.status, NodeProvisioningPreflightStatus::Passed) {
            continue;
        }
        match check.check.as_str() {
            "node_enabled" => recommendations.push(
                "Enable the node in panel settings before starting provisioning.".to_string(),
            ),
            "api_port" => recommendations.push(
                "Configure a valid api_port for the node local API.".to_string(),
            ),
            "node_auth_token_issued" => recommendations.push(
                "Issue a deployable node-agent token before provisioning so the installed agent can authenticate to the panel."
                    .to_string(),
            ),
            "local_health" => recommendations.push(
                "Ensure the Rust node agent is reachable from the panel on api_port before provisioning verification."
                    .to_string(),
            ),
            "runtime_state" => recommendations.push(
                "Inspect local runtime state and resolve failed Xray runtime or restart backoff before continuing."
                    .to_string(),
            ),
            "sync_state" => recommendations.push(
                "Apply the current generated config to the node so provisioning verification can succeed.".to_string(),
            ),
            _ => {}
        }
    }

    if let Some(state) = local_state
        && state.rollback_marker_path.is_some()
    {
        recommendations.push(
            "Rollback marker is present on the node. Run rollback or inspect the last failed apply first."
                .to_string(),
        );
    }

    if recommendations.is_empty() {
        recommendations.push(format!(
            "Node {} passed preflight checks and is ready for provisioning execution.",
            node.name
        ));
    }

    recommendations
}

fn build_node_provisioning_status_view(
    node_id: &str,
    latest_task: Option<NodeProvisioningTask>,
    preflight: NodeProvisioningPreflightReport,
    checked_at_unix: u64,
) -> NodeProvisioningStatusView {
    let stale_active_task = latest_task
        .as_ref()
        .is_some_and(|task| node_provisioning_task_is_stale(task, checked_at_unix));
    let latest_status = latest_task.as_ref().map(|task| task.status);
    let current_step = latest_task.as_ref().and_then(|task| {
        task.steps
            .iter()
            .rev()
            .find(|step| {
                matches!(
                    step.status,
                    NodeProvisioningStepStatus::Running | NodeProvisioningStepStatus::Pending
                )
            })
            .cloned()
            .or_else(|| task.steps.last().cloned())
    });
    let failed_step = latest_task.as_ref().and_then(|task| {
        task.steps
            .iter()
            .rev()
            .find(|step| matches!(step.status, NodeProvisioningStepStatus::Failed))
            .cloned()
    });
    let can_retry = latest_task.as_ref().is_some_and(|task| {
        matches!(task.status, NodeProvisioningTaskStatus::Failed) || stale_active_task
    });
    let can_reprovision = latest_task.as_ref().is_none_or(|task| {
        matches!(
            task.status,
            NodeProvisioningTaskStatus::Failed
                | NodeProvisioningTaskStatus::Completed
                | NodeProvisioningTaskStatus::Verified
        ) || stale_active_task
    });
    let mut next_actions = latest_task
        .as_ref()
        .map(|task| task.remediation.clone())
        .unwrap_or_default();
    if latest_task.is_none() {
        next_actions.push(NodeProvisioningRemediation {
            action: NodeProvisioningRemediationAction::ReprovisionNode,
            detail:
                "No provisioning task exists yet. Start provisioning when preflight is acceptable."
                    .to_string(),
        });
    }
    if !preflight.passed {
        next_actions.push(NodeProvisioningRemediation {
            action: NodeProvisioningRemediationAction::RunBootstrapProbe,
            detail: "Preflight is not fully passing. Inspect failed checks before retrying."
                .to_string(),
        });
    }
    let next_actions = dedupe_node_provisioning_remediation(next_actions);
    let recovery = build_node_provisioning_recovery_view(
        latest_task.as_ref(),
        stale_active_task,
        &preflight,
        &next_actions,
    );

    let mut recommendations = Vec::new();
    match latest_task.as_ref().map(|task| task.status) {
        Some(NodeProvisioningTaskStatus::Running) if stale_active_task => recommendations.push(
            "Provisioning has not reported progress recently. Inspect the executor and retry or reprovision if the task is abandoned."
                .to_string(),
        ),
        Some(NodeProvisioningTaskStatus::Running) => recommendations.push(
            "Provisioning is running. Avoid starting another task for this node.".to_string(),
        ),
        Some(NodeProvisioningTaskStatus::Failed) => recommendations.push(
            "Provisioning failed. Fix the failed step, then retry or reprovision.".to_string(),
        ),
        Some(NodeProvisioningTaskStatus::Completed) => recommendations.push(
            "Provisioning completed. Run bootstrap verification if the node is not marked verified."
                .to_string(),
        ),
        Some(NodeProvisioningTaskStatus::Verified) => {
            recommendations.push("Provisioning is verified and ready.".to_string())
        }
        Some(NodeProvisioningTaskStatus::Pending) if stale_active_task => recommendations.push(
            "Provisioning has been pending too long. Inspect the executor and retry or reprovision."
                .to_string(),
        ),
        Some(NodeProvisioningTaskStatus::Pending) => {
            recommendations.push("Provisioning is pending execution.".to_string())
        }
        None => recommendations.push("No provisioning task exists for this node yet.".to_string()),
    }
    recommendations.extend(preflight.recommendations.clone());
    if let Some(task) = latest_task.as_ref() {
        recommendations.extend(remote_prerequisite_recommendations(
            &task.remote_prerequisites,
        ));
    }
    recommendations.sort();
    recommendations.dedup();

    NodeProvisioningStatusView {
        node_id: node_id.to_string(),
        checked_at_unix,
        completion: latest_task
            .as_ref()
            .map(build_node_provisioning_executor_completion_view),
        latest_task,
        latest_status,
        stale_active_task,
        current_step,
        failed_step,
        can_retry,
        can_reprovision,
        preflight,
        next_actions,
        recovery,
        recommendations,
    }
}

fn build_node_provisioning_recovery_view(
    latest_task: Option<&NodeProvisioningTask>,
    stale_active_task: bool,
    preflight: &NodeProvisioningPreflightReport,
    next_actions: &[NodeProvisioningRemediation],
) -> NodeProvisioningRecoveryView {
    let required_actions = required_repair_actions(latest_task, preflight);
    if !required_actions.is_empty() {
        return NodeProvisioningRecoveryView {
            decision: NodeProvisioningRecoveryDecision::RepairFirst,
            detail: "repair the blocking prerequisite(s) before retrying provisioning".to_string(),
            required_actions,
        };
    }

    match latest_task.map(|task| task.status) {
        Some(NodeProvisioningTaskStatus::Verified) => NodeProvisioningRecoveryView {
            decision: NodeProvisioningRecoveryDecision::Ready,
            detail: "latest provisioning task is verified and ready".to_string(),
            required_actions: Vec::new(),
        },
        Some(NodeProvisioningTaskStatus::Completed) if preflight.passed => {
            NodeProvisioningRecoveryView {
                decision: NodeProvisioningRecoveryDecision::Ready,
                detail: "latest provisioning task completed and current preflight passes"
                    .to_string(),
                required_actions: Vec::new(),
            }
        }
        Some(NodeProvisioningTaskStatus::Failed) => NodeProvisioningRecoveryView {
            decision: if next_actions
                .iter()
                .any(|item| item.action == NodeProvisioningRemediationAction::ReprovisionNode)
            {
                NodeProvisioningRecoveryDecision::Reprovision
            } else {
                NodeProvisioningRecoveryDecision::Retry
            },
            detail: "latest provisioning task failed after recoverable checks".to_string(),
            required_actions: Vec::new(),
        },
        Some(NodeProvisioningTaskStatus::Running | NodeProvisioningTaskStatus::Pending)
            if stale_active_task =>
        {
            NodeProvisioningRecoveryView {
                decision: NodeProvisioningRecoveryDecision::Retry,
                detail: "latest provisioning task is stale and can be retried or reprovisioned"
                    .to_string(),
                required_actions: Vec::new(),
            }
        }
        Some(NodeProvisioningTaskStatus::Running | NodeProvisioningTaskStatus::Pending) => {
            NodeProvisioningRecoveryView {
                decision: NodeProvisioningRecoveryDecision::Retry,
                detail: "provisioning is already in progress or pending execution".to_string(),
                required_actions: Vec::new(),
            }
        }
        _ => NodeProvisioningRecoveryView {
            decision: NodeProvisioningRecoveryDecision::Reprovision,
            detail: "no completed provisioning baseline exists yet".to_string(),
            required_actions: Vec::new(),
        },
    }
}

fn node_provisioning_task_is_active(task: &NodeProvisioningTask) -> bool {
    matches!(
        task.status,
        NodeProvisioningTaskStatus::Pending | NodeProvisioningTaskStatus::Running
    )
}

fn node_provisioning_task_is_stale(task: &NodeProvisioningTask, now: u64) -> bool {
    node_provisioning_task_is_active(task)
        && now.saturating_sub(task.updated_at_unix) > NODE_PROVISIONING_TASK_STALE_AFTER_SECONDS
}

fn required_repair_actions(
    latest_task: Option<&NodeProvisioningTask>,
    preflight: &NodeProvisioningPreflightReport,
) -> Vec<NodeProvisioningRemediation> {
    let mut actions = Vec::new();
    if preflight.checks.iter().any(|check| {
        check.check == "node_auth_token_issued"
            && check.status == NodeProvisioningPreflightStatus::Failed
    }) {
        actions.push(NodeProvisioningRemediation {
            action: NodeProvisioningRemediationAction::RotateNodeAuthToken,
            detail: "Issue a deployable node-agent token before provisioning can be verified."
                .to_string(),
        });
    }
    if let Some(task) = latest_task {
        for check in &task.remote_prerequisites {
            if check.status != NodeProvisioningPreflightStatus::Failed {
                continue;
            }
            match check.prerequisite {
                NodeProvisioningRemotePrerequisiteKind::SudoAvailable => {
                    actions.push(NodeProvisioningRemediation {
                        action: NodeProvisioningRemediationAction::CheckSudoAccess,
                        detail: "Repair remote sudo/root access before retrying installation."
                            .to_string(),
                    });
                }
                NodeProvisioningRemotePrerequisiteKind::PortsAvailable => {
                    actions.push(NodeProvisioningRemediation {
                        action: NodeProvisioningRemediationAction::FreeRequiredPorts,
                        detail: "Free required remote ports or change the node port configuration."
                            .to_string(),
                    });
                }
                NodeProvisioningRemotePrerequisiteKind::DiskOk => {
                    actions.push(NodeProvisioningRemediation {
                        action: NodeProvisioningRemediationAction::ReprovisionNode,
                        detail: "Free disk space before starting a fresh provisioning attempt."
                            .to_string(),
                    });
                }
                NodeProvisioningRemotePrerequisiteKind::MemoryOk
                | NodeProvisioningRemotePrerequisiteKind::OsSupported
                | NodeProvisioningRemotePrerequisiteKind::PackageManagerAvailable => {
                    actions.push(NodeProvisioningRemediation {
                        action: NodeProvisioningRemediationAction::ReprovisionNode,
                        detail: "Correct remote host prerequisites before provisioning again."
                            .to_string(),
                    });
                }
            }
        }
    }
    dedupe_node_provisioning_remediation(actions)
}

fn build_node_provisioning_remediation(
    failures: &[NodeProvisioningFailure],
    verified_ready: Option<bool>,
) -> Vec<NodeProvisioningRemediation> {
    let mut remediation = Vec::new();

    for failure in failures {
        match failure.category {
            NodeProvisioningFailureCategory::Connectivity => {
                remediation.push(NodeProvisioningRemediation {
                    action: NodeProvisioningRemediationAction::CheckSshConnectivity,
                    detail: "Verify SSH reachability, DNS/IP correctness, and firewall rules.".to_string(),
                });
                remediation.push(NodeProvisioningRemediation {
                    action: NodeProvisioningRemediationAction::ReviewFirewall,
                    detail: "Ensure panel-to-node and SSH paths are allowed by firewall policy.".to_string(),
                });
            }
            NodeProvisioningFailureCategory::Authentication => remediation.push(
                NodeProvisioningRemediation {
                    action: NodeProvisioningRemediationAction::CheckSshConnectivity,
                    detail: "Review SSH username and request-scoped password/private key input.".to_string(),
                },
            ),
            NodeProvisioningFailureCategory::Authorization => remediation.push(
                NodeProvisioningRemediation {
                    action: NodeProvisioningRemediationAction::CheckSudoAccess,
                    detail: "Confirm the remote user has sudo/root privileges required for installation.".to_string(),
                },
            ),
            NodeProvisioningFailureCategory::Runtime => {
                remediation.push(NodeProvisioningRemediation {
                    action: NodeProvisioningRemediationAction::RestartNodeRuntime,
                    detail: "Restart local node runtime and inspect local state/runtime events.".to_string(),
                });
                remediation.push(NodeProvisioningRemediation {
                    action: NodeProvisioningRemediationAction::InspectRuntimeState,
                    detail: "Inspect node local state for runtime failures or restart backoff.".to_string(),
                });
            }
            NodeProvisioningFailureCategory::Apply => remediation.push(NodeProvisioningRemediation {
                action: NodeProvisioningRemediationAction::ApplyNodeConfig,
                detail: "Re-apply generated node config and inspect sync/apply history.".to_string(),
            }),
            NodeProvisioningFailureCategory::BootstrapVerification => {
                remediation.push(NodeProvisioningRemediation {
                    action: NodeProvisioningRemediationAction::RunBootstrapProbe,
                    detail: "Run bootstrap probe again after fixing local runtime or sync issues.".to_string(),
                });
                remediation.push(NodeProvisioningRemediation {
                    action: NodeProvisioningRemediationAction::RollbackNodeRuntime,
                    detail: "If the node remains unhealthy after apply, consider runtime rollback.".to_string(),
                });
            }
            NodeProvisioningFailureCategory::Validation => remediation.push(NodeProvisioningRemediation {
                action: NodeProvisioningRemediationAction::ReprovisionNode,
                detail: "Correct validation issues and start a fresh reprovision task.".to_string(),
            }),
            NodeProvisioningFailureCategory::Unknown => remediation.push(NodeProvisioningRemediation {
                action: NodeProvisioningRemediationAction::RetryTask,
                detail: "Retry the task if the failure was transient, otherwise inspect detailed step logs.".to_string(),
            }),
        }
    }

    if verified_ready == Some(false) {
        remediation.push(NodeProvisioningRemediation {
            action: NodeProvisioningRemediationAction::RunBootstrapProbe,
            detail: "Provisioning finished but the node is not ready. Re-run bootstrap verification after remediation."
                .to_string(),
        });
    }

    dedupe_node_provisioning_remediation(remediation)
}

fn dedupe_node_provisioning_remediation(
    remediation: Vec<NodeProvisioningRemediation>,
) -> Vec<NodeProvisioningRemediation> {
    let mut seen = std::collections::HashSet::new();
    let mut deduped = Vec::new();
    for item in remediation {
        let key = (item.action, item.detail.clone());
        if seen.insert(key) {
            deduped.push(item);
        }
    }
    deduped
}

fn compact_remote_prerequisites(
    prerequisites: Vec<NodeProvisioningRemotePrerequisiteCheck>,
) -> Vec<NodeProvisioningRemotePrerequisiteCheck> {
    let mut by_kind = HashMap::new();
    for mut check in prerequisites.into_iter().take(16) {
        check.detail = truncate_node_report_field(&check.detail);
        by_kind.insert(check.prerequisite, check);
    }
    let mut checks = by_kind.into_values().collect::<Vec<_>>();
    checks.sort_by_key(|check| remote_prerequisite_sort_key(check.prerequisite));
    checks
}

fn remote_prerequisite_sort_key(kind: NodeProvisioningRemotePrerequisiteKind) -> u8 {
    match kind {
        NodeProvisioningRemotePrerequisiteKind::OsSupported => 0,
        NodeProvisioningRemotePrerequisiteKind::SudoAvailable => 1,
        NodeProvisioningRemotePrerequisiteKind::DiskOk => 2,
        NodeProvisioningRemotePrerequisiteKind::MemoryOk => 3,
        NodeProvisioningRemotePrerequisiteKind::PortsAvailable => 4,
        NodeProvisioningRemotePrerequisiteKind::PackageManagerAvailable => 5,
    }
}

fn remote_prerequisite_recommendations(
    checks: &[NodeProvisioningRemotePrerequisiteCheck],
) -> Vec<String> {
    let mut recommendations = Vec::new();
    for check in checks
        .iter()
        .filter(|check| matches!(check.status, NodeProvisioningPreflightStatus::Failed))
    {
        recommendations.push(match check.prerequisite {
            NodeProvisioningRemotePrerequisiteKind::OsSupported => {
                "Use a supported Linux distribution before provisioning this node.".to_string()
            }
            NodeProvisioningRemotePrerequisiteKind::SudoAvailable => {
                "Use root or a remote user with sudo access for installation.".to_string()
            }
            NodeProvisioningRemotePrerequisiteKind::DiskOk => {
                "Free disk space on the remote server before retrying installation.".to_string()
            }
            NodeProvisioningRemotePrerequisiteKind::MemoryOk => {
                "Increase available remote memory or reduce host pressure before provisioning."
                    .to_string()
            }
            NodeProvisioningRemotePrerequisiteKind::PortsAvailable => {
                "Free the required node/Xray ports or change the node port settings.".to_string()
            }
            NodeProvisioningRemotePrerequisiteKind::PackageManagerAvailable => {
                "Ensure a supported package manager is available on the remote server.".to_string()
            }
        });
    }
    recommendations.sort();
    recommendations.dedup();
    recommendations
}

fn remote_prerequisite_failures(
    checks: &[NodeProvisioningRemotePrerequisiteCheck],
) -> Vec<NodeProvisioningFailure> {
    checks
        .iter()
        .filter(|check| matches!(check.status, NodeProvisioningPreflightStatus::Failed))
        .map(|check| NodeProvisioningFailure {
            step: NodeProvisioningStepKind::Preflight,
            category: remote_prerequisite_failure_category(check.prerequisite),
            detail: format!(
                "remote prerequisite {:?} failed: {}",
                check.prerequisite, check.detail
            )
            .to_ascii_lowercase(),
        })
        .collect()
}

fn remote_prerequisite_failure_category(
    prerequisite: NodeProvisioningRemotePrerequisiteKind,
) -> NodeProvisioningFailureCategory {
    match prerequisite {
        NodeProvisioningRemotePrerequisiteKind::SudoAvailable => {
            NodeProvisioningFailureCategory::Authorization
        }
        NodeProvisioningRemotePrerequisiteKind::PortsAvailable => {
            NodeProvisioningFailureCategory::Connectivity
        }
        NodeProvisioningRemotePrerequisiteKind::OsSupported
        | NodeProvisioningRemotePrerequisiteKind::DiskOk
        | NodeProvisioningRemotePrerequisiteKind::MemoryOk
        | NodeProvisioningRemotePrerequisiteKind::PackageManagerAvailable => {
            NodeProvisioningFailureCategory::Validation
        }
    }
}

fn provisioning_step_templates(
    transport: NodeProvisioningTransportKind,
) -> Vec<NodeProvisioningStepKind> {
    let mut steps = vec![NodeProvisioningStepKind::Preflight];
    if matches!(transport, NodeProvisioningTransportKind::Ssh) {
        steps.extend([
            NodeProvisioningStepKind::SshConnect,
            NodeProvisioningStepKind::SudoCheck,
            NodeProvisioningStepKind::XrayInstall,
            NodeProvisioningStepKind::SidecarRuntimeInstall,
            NodeProvisioningStepKind::NodeInstall,
            NodeProvisioningStepKind::ServiceInstall,
        ]);
    }
    steps.extend([
        NodeProvisioningStepKind::AgentReachability,
        NodeProvisioningStepKind::RuntimeHealth,
        NodeProvisioningStepKind::ConfigApply,
        NodeProvisioningStepKind::BootstrapVerify,
    ]);
    steps
}

fn ssh_remote_preflight_probe_script(required_ports: &[u16]) -> String {
    let ports = required_ports
        .iter()
        .map(u16::to_string)
        .collect::<Vec<_>>()
        .join(" ");
    format!(
        r#"set -eu
os_id="$(. /etc/os-release 2>/dev/null && printf '%s' "${{ID:-unknown}}" || printf 'unknown')"
if command -v sudo >/dev/null 2>&1; then has_sudo=1; else has_sudo=0; fi
disk_free_mb="$(df -Pm / | awk 'NR==2 {{ print $4 }}')"
memory_total_mb="$(awk '/MemTotal:/ {{ print int($2 / 1024) }}' /proc/meminfo)"
if command -v apt-get >/dev/null 2>&1; then package_manager=apt-get
elif command -v dnf >/dev/null 2>&1; then package_manager=dnf
elif command -v yum >/dev/null 2>&1; then package_manager=yum
else package_manager=none
fi
printf 'OS_ID=%s\n' "$os_id"
printf 'HAS_SUDO=%s\n' "$has_sudo"
printf 'DISK_FREE_MB=%s\n' "$disk_free_mb"
printf 'MEMORY_TOTAL_MB=%s\n' "$memory_total_mb"
printf 'PACKAGE_MANAGER=%s\n' "$package_manager"
for port in {ports}; do
  if ss -H -ltn "( sport = :$port )" 2>/dev/null | grep -q .; then
    printf 'PORT_%s=busy\n' "$port"
  else
    printf 'PORT_%s=free\n' "$port"
  fi
done"#
    )
}

/// The only release path a Hydra node artifact may be downloaded from.
///
/// The panel never sees these URLs: the executor supplies them as environment
/// variables at deployment time. Publishing the prefix in the environment schema
/// and enforcing it in the install script are therefore the two halves of the same
/// rule — the schema states it, the node enforces it.
const NODE_ARTIFACT_RELEASE_PREFIX: &str =
    "https://github.com/Zolotushka1/Hydra/releases/download/node-v";

/// Fail-closed guard prepended to the node install step.
///
/// Checked on the node rather than in the panel because that is where the value
/// exists. An artifact URL pointing anywhere else installs an unrelated binary
/// under the node's systemd unit, so a mismatch aborts the step instead of
/// downloading.
const NODE_ARTIFACT_URL_GUARD: &str = r#"require_hydra_artifact() {
  case "$2" in
    https://github.com/Zolotushka1/Hydra/releases/download/node-v*) ;;
    *)
      printf '%s must point at https://github.com/Zolotushka1/Hydra/releases/download/node-v*\n' "$1" >&2
      exit 1
      ;;
  esac
}"#;

fn node_provisioning_install_env_schema(
    sidecar_install: &NodeProvisioningSidecarInstallSelection,
) -> Vec<NodeProvisioningEnvVarSpec> {
    vec![
        NodeProvisioningEnvVarSpec {
            name: "HYDRA_NODE_ARTIFACT_URL".to_string(),
            required: true,
            sensitivity: NodeProvisioningMaterialSensitivity::Sensitive,
            source: "executor deployment input".to_string(),
            description: format!(
                "HTTPS URL for the Hydra node release artifact matching the remote OS/architecture; must start with {NODE_ARTIFACT_RELEASE_PREFIX}"
            ),
        },
        NodeProvisioningEnvVarSpec {
            name: "HYDRA_NODE_SESSION_ADAPTER_ARTIFACT_URL".to_string(),
            required: sidecar_install.install_wireguard,
            sensitivity: NodeProvisioningMaterialSensitivity::Sensitive,
            source: "executor deployment input from the verified release manifest".to_string(),
            description: format!(
                "required only for WireGuard exact-session enforcement; matching node-session-adapter release artifact; must start with {NODE_ARTIFACT_RELEASE_PREFIX}"
            ),
        },
        NodeProvisioningEnvVarSpec {
            name: "HYDRA_NODE_WIREGUARD_DRIVER_ARTIFACT_URL".to_string(),
            required: sidecar_install.install_wireguard,
            sensitivity: NodeProvisioningMaterialSensitivity::Sensitive,
            source: "executor deployment input from the verified release manifest".to_string(),
            description: format!(
                "required only for WireGuard exact-session enforcement; matching node-session-driver-wireguard release artifact; must start with {NODE_ARTIFACT_RELEASE_PREFIX}"
            ),
        },
        NodeProvisioningEnvVarSpec {
            name: "HYDRA_INSTALL_WIREGUARD".to_string(),
            required: false,
            sensitivity: NodeProvisioningMaterialSensitivity::Public,
            source: "sidecar_install.install_wireguard".to_string(),
            description:
                "set to 1 only when the operator selected WireGuard package/tool installation"
                    .to_string(),
        },
        NodeProvisioningEnvVarSpec {
            name: "HYDRA_INSTALL_HYSTERIA2".to_string(),
            required: false,
            sensitivity: NodeProvisioningMaterialSensitivity::Public,
            source: "sidecar_install.install_hysteria2".to_string(),
            description:
                "set to 1 only when the operator selected Hysteria2 binary/service preparation"
                    .to_string(),
        },
        NodeProvisioningEnvVarSpec {
            name: "HYDRA_HYSTERIA2_ARTIFACT_URL".to_string(),
            required: sidecar_install.install_hysteria2,
            sensitivity: NodeProvisioningMaterialSensitivity::Sensitive,
            source: "sidecar_install.hysteria2_artifact_url".to_string(),
            description:
                "required only when Hysteria2 installation is enabled; must point to the official apernet/hysteria GitHub release artifact"
                    .to_string(),
        },
    ]
}

fn build_ssh_install_plan(
    sidecar_install: &NodeProvisioningSidecarInstallSelection,
) -> NodeProvisioningSshInstallPlanView {
    NodeProvisioningSshInstallPlanView {
        sidecar_install: sidecar_install.clone(),
        env_schema: node_provisioning_install_env_schema(sidecar_install),
        scripts: vec![
            NodeProvisioningSshInstallScriptStep {
                step: NodeProvisioningStepKind::SudoCheck,
                description: "verify root access or passwordless sudo before mutation".to_string(),
                script: r#"set -eu
if [ "$(id -u)" -eq 0 ]; then
  exit 0
fi
sudo -n true"#
                    .to_string(),
            },
            NodeProvisioningSshInstallScriptStep {
                step: NodeProvisioningStepKind::XrayInstall,
                description: "install Xray through the official XTLS installer without shell pipe execution".to_string(),
                script: r#"set -eu
if [ "$(id -u)" -eq 0 ]; then SUDO=""; else SUDO="sudo -n"; fi
tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT
curl -fsSL https://github.com/XTLS/Xray-install/raw/main/install-release.sh -o "$tmp"
$SUDO bash "$tmp" install"#
                    .to_string(),
            },
            NodeProvisioningSshInstallScriptStep {
                step: NodeProvisioningStepKind::SidecarRuntimeInstall,
                description:
                    "optionally prepare Hysteria2 and WireGuard sidecar runtimes through explicit opt-in flags"
                        .to_string(),
                script: r#"set -eu
if [ "$(id -u)" -eq 0 ]; then SUDO=""; else SUDO="sudo -n"; fi
$SUDO install -d -m 0700 /etc/hydra-node
$SUDO install -d -m 0700 /etc/hydra-node/sidecar-generated/hysteria2
$SUDO install -d -m 0700 /etc/hydra-node/sidecar-generated/wireguard

install_wireguard="${HYDRA_INSTALL_WIREGUARD:-0}"
install_hysteria2="${HYDRA_INSTALL_HYSTERIA2:-0}"

if [ "$install_wireguard" = "1" ]; then
  if command -v apt-get >/dev/null 2>&1; then
    $SUDO apt-get update
    $SUDO env DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends wireguard-tools
  elif command -v dnf >/dev/null 2>&1; then
    $SUDO dnf install -y wireguard-tools
  elif command -v yum >/dev/null 2>&1; then
    $SUDO yum install -y wireguard-tools
  else
    printf 'WIREGUARD_INSTALL=failed_package_manager_missing\n' >&2
    exit 1
  fi
else
  printf 'WIREGUARD_INSTALL=skipped\n'
fi

if [ "$install_hysteria2" = "1" ]; then
  : "${HYDRA_HYSTERIA2_ARTIFACT_URL:?HYDRA_HYSTERIA2_ARTIFACT_URL is required when HYDRA_INSTALL_HYSTERIA2=1}"
  tmp="$(mktemp)"
  trap 'rm -f "$tmp"' EXIT
  curl -fsSL "$HYDRA_HYSTERIA2_ARTIFACT_URL" -o "$tmp"
  $SUDO install -m 0755 "$tmp" /usr/local/bin/hysteria
  $SUDO sh -c 'cat > /etc/systemd/system/hydra-hysteria2@.service << "UNIT"
[Unit]
Description=Hydra Hysteria2 sidecar (%i)
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=/usr/local/bin/hysteria server -c /etc/hydra-node/sidecar-generated/hysteria2/%i.yaml
Restart=on-failure
RestartSec=5
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/etc/hydra-node

[Install]
WantedBy=multi-user.target
UNIT'
  $SUDO systemctl daemon-reload
else
  printf 'HYSTERIA2_INSTALL=skipped\n'
fi"#
                    .to_string(),
            },
            NodeProvisioningSshInstallScriptStep {
                step: NodeProvisioningStepKind::NodeInstall,
                description:
                    "install the Hydra node binary from an executor-supplied release artifact"
                        .to_string(),
                script: format!(
                    r#"set -eu
: "${{HYDRA_NODE_ARTIFACT_URL:?HYDRA_NODE_ARTIFACT_URL is required}}"
{NODE_ARTIFACT_URL_GUARD}
require_hydra_artifact HYDRA_NODE_ARTIFACT_URL "$HYDRA_NODE_ARTIFACT_URL"
if [ "$(id -u)" -eq 0 ]; then SUDO=""; else SUDO="sudo -n"; fi
tmp="$(mktemp)"
adapter_tmp="$(mktemp)"
driver_tmp="$(mktemp)"
trap 'rm -f "$tmp" "$adapter_tmp" "$driver_tmp"' EXIT
curl -fsSL "$HYDRA_NODE_ARTIFACT_URL" -o "$tmp"
$SUDO install -d -m 0755 /opt/hydra-node
$SUDO install -d -m 0700 /etc/hydra-node
$SUDO install -m 0755 "$tmp" /opt/hydra-node/hydra-node

if [ "${{HYDRA_INSTALL_WIREGUARD:-0}}" = "1" ]; then
  : "${{HYDRA_NODE_SESSION_ADAPTER_ARTIFACT_URL:?adapter artifact URL is required for WireGuard}}"
  : "${{HYDRA_NODE_WIREGUARD_DRIVER_ARTIFACT_URL:?WireGuard driver artifact URL is required}}"
  require_hydra_artifact HYDRA_NODE_SESSION_ADAPTER_ARTIFACT_URL "$HYDRA_NODE_SESSION_ADAPTER_ARTIFACT_URL"
  require_hydra_artifact HYDRA_NODE_WIREGUARD_DRIVER_ARTIFACT_URL "$HYDRA_NODE_WIREGUARD_DRIVER_ARTIFACT_URL"
  curl -fsSL "$HYDRA_NODE_SESSION_ADAPTER_ARTIFACT_URL" -o "$adapter_tmp"
  curl -fsSL "$HYDRA_NODE_WIREGUARD_DRIVER_ARTIFACT_URL" -o "$driver_tmp"
  $SUDO install -m 0755 "$adapter_tmp" /opt/hydra-node/node-session-adapter
  $SUDO install -m 0755 "$driver_tmp" /opt/hydra-node/node-session-driver-wireguard
fi"#
                ),
            },
            NodeProvisioningSshInstallScriptStep {
                step: NodeProvisioningStepKind::ServiceInstall,
                description: "install and enable the least-privilege systemd service".to_string(),
                script: r#"set -eu
if [ "$(id -u)" -eq 0 ]; then SUDO=""; else SUDO="sudo -n"; fi
$SUDO sh -c 'cat > /etc/systemd/system/hydra-node.service << "UNIT"
[Unit]
Description=Hydra Node
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=/opt/hydra-node/hydra-node
EnvironmentFile=/etc/hydra-node/node.env
WorkingDirectory=/opt/hydra-node
Restart=on-failure
RestartSec=5
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/etc/hydra-node /opt/hydra-node

[Install]
WantedBy=multi-user.target
UNIT'
if [ "${HYDRA_INSTALL_WIREGUARD:-0}" = "1" ]; then
  $SUDO sh -c 'cat > /etc/systemd/system/hydra-node-session-adapter.service << "UNIT"
[Unit]
Description=Hydra Node WireGuard session adapter
After=network-online.target hydra-node.service
Wants=network-online.target
Requires=hydra-node.service

[Service]
Type=simple
ExecStart=/opt/hydra-node/node-session-adapter
EnvironmentFile=/etc/hydra-node/node.env
WorkingDirectory=/opt/hydra-node
Restart=on-failure
RestartSec=5
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectControlGroups=true
RestrictSUIDSGID=true
LockPersonality=true
CapabilityBoundingSet=CAP_NET_ADMIN
AmbientCapabilities=CAP_NET_ADMIN
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6 AF_NETLINK
ReadWritePaths=/etc/hydra-node

[Install]
WantedBy=multi-user.target
UNIT'
fi
$SUDO systemctl daemon-reload
$SUDO systemctl enable hydra-node.service
if [ "${HYDRA_INSTALL_WIREGUARD:-0}" = "1" ]; then
  $SUDO systemctl enable hydra-node-session-adapter.service
fi"#
                    .to_string(),
            },
        ],
    }
}

fn build_node_provisioning_executor_session(
    task: NodeProvisioningTask,
    required_ports: &[u16],
    executor_contract_version: Option<u16>,
) -> NodeProvisioningExecutorSessionView {
    let uses_ssh = matches!(
        task.request_context.transport,
        NodeProvisioningTransportKind::Ssh
    );
    let steps = task
        .planned_steps
        .iter()
        .map(|step| NodeProvisioningExecutorSessionStep {
            step: *step,
            executor_action: executor_action_for_step(*step).to_string(),
            report_endpoint_suffix: format!("/{}/step", task.task_id),
            requires_heartbeat: matches!(
                step,
                NodeProvisioningStepKind::XrayInstall
                    | NodeProvisioningStepKind::SidecarRuntimeInstall
                    | NodeProvisioningStepKind::NodeInstall
                    | NodeProvisioningStepKind::ServiceInstall
            ),
            expected_report: executor_expected_report_for_step(*step),
        })
        .collect();
    let completion = build_node_provisioning_executor_completion_view(&task);
    let workflow = build_node_provisioning_executor_workflow(&task, uses_ssh);
    let resume = build_node_provisioning_executor_resume_view(&task, &workflow, required_ports);
    NodeProvisioningExecutorSessionView {
        schema_version: NODE_PROVISIONING_EXECUTOR_CONTRACT_VERSION,
        minimum_executor_version: NODE_PROVISIONING_MINIMUM_EXECUTOR_VERSION.to_string(),
        capabilities: node_provisioning_executor_capabilities(),
        compatibility: build_node_provisioning_executor_compatibility(executor_contract_version),
        task_id: task.task_id,
        node_id: task.node_id,
        heartbeat_interval_seconds: NODE_PROVISIONING_HEARTBEAT_INTERVAL_SECONDS,
        stale_after_seconds: NODE_PROVISIONING_TASK_STALE_AFTER_SECONDS,
        preflight_probe: uses_ssh.then(|| NodeProvisioningSshPreflightProbeView {
            required_ports: required_ports.to_vec(),
            script: ssh_remote_preflight_probe_script(required_ports),
        }),
        install_plan: uses_ssh
            .then(|| build_ssh_install_plan(&task.request_context.sidecar_install)),
        material_handoff: uses_ssh.then(build_node_provisioning_material_handoff_plan),
        steps,
        workflow,
        resume,
        loop_contract: build_node_provisioning_executor_loop_contract(),
        finish_conditions: vec![
            NodeProvisioningExecutorFinishCondition {
                status: NodeProvisioningTaskStatus::Completed,
                description:
                    "all planned steps succeeded; panel may run bootstrap verification on finish"
                        .to_string(),
            },
            NodeProvisioningExecutorFinishCondition {
                status: NodeProvisioningTaskStatus::Failed,
                description:
                    "any unrecoverable step failure must be reported before finishing the task"
                        .to_string(),
            },
        ],
        completion,
    }
}

fn build_node_provisioning_executor_loop_contract() -> NodeProvisioningExecutorLoopContractView {
    NodeProvisioningExecutorLoopContractView {
        phases: vec![
            NodeProvisioningExecutorLoopPhaseView {
                phase: NodeProvisioningExecutorLoopPhase::ReadNextCommand,
                description:
                    "read resume.recommended_next_command from executor-session or prior accepted result"
                        .to_string(),
            },
            NodeProvisioningExecutorLoopPhaseView {
                phase: NodeProvisioningExecutorLoopPhase::ExecuteCommand,
                description:
                    "execute only the bounded payload described by the command envelope; do not infer hidden work"
                        .to_string(),
            },
            NodeProvisioningExecutorLoopPhaseView {
                phase: NodeProvisioningExecutorLoopPhase::SubmitResult,
                description:
                    "submit only through the envelope acceptance channel when executor_may_submit=true"
                        .to_string(),
            },
            NodeProvisioningExecutorLoopPhaseView {
                phase: NodeProvisioningExecutorLoopPhase::HandleAcceptedResult,
                description:
                    "on accepted result, consume accepted_node_id and next recommended command from the compact projection"
                        .to_string(),
            },
            NodeProvisioningExecutorLoopPhaseView {
                phase: NodeProvisioningExecutorLoopPhase::HandleRejectedResult,
                description:
                    "on rejection, branch by machine-readable code, recovery_hint, and retryable"
                        .to_string(),
            },
            NodeProvisioningExecutorLoopPhaseView {
                phase: NodeProvisioningExecutorLoopPhase::ContinueOrRecover,
                description:
                    "continue with the next command, refresh session, re-attest, reissue, or stop according to the typed result"
                        .to_string(),
            },
        ],
        command_source:
            "resume.recommended_next_command or accepted_result.recommended_next_command"
                .to_string(),
        accepted_result_shape:
            "accepted_node_id + task_status + completed_node_ids + next_node_ids + recommended_next_command"
                .to_string(),
        rejected_result_shape: "error + code + recovery_hint + retryable".to_string(),
        terminal_when: vec![
            "completion.can_finish_completed=true and completed finish is chosen".to_string(),
            "completion.can_finish_verified=true and verified finish is chosen".to_string(),
            "accepted task_status=failed".to_string(),
            "rejection recovery_hint=stop".to_string(),
        ],
        recovery_rules: vec![
            "retry_with_correct_payload -> rebuild the same accepted channel payload".to_string(),
            "use_command_report -> resubmit command-style success through command-report".to_string(),
            "reattest_remote_state -> rerun canonical attestation script before handoff report"
                .to_string(),
            "refresh_session -> fetch executor-session again before any further action".to_string(),
            "stop -> do not continue automatically".to_string(),
            "panel_observed command -> wait for panel evidence; never self-report success"
                .to_string(),
        ],
    }
}

fn node_provisioning_executor_capabilities() -> Vec<NodeProvisioningExecutorCapability> {
    vec![
        NodeProvisioningExecutorCapability::WorkflowGraph,
        NodeProvisioningExecutorCapability::ResumeProjection,
        NodeProvisioningExecutorCapability::RecommendedNextCommand,
        NodeProvisioningExecutorCapability::AcceptanceContract,
        NodeProvisioningExecutorCapability::MachineReadableRejections,
        NodeProvisioningExecutorCapability::AcceptedResultProjection,
        NodeProvisioningExecutorCapability::LoopContract,
    ]
}

fn node_provisioning_executor_required_capabilities() -> Vec<NodeProvisioningExecutorCapability> {
    vec![
        NodeProvisioningExecutorCapability::RecommendedNextCommand,
        NodeProvisioningExecutorCapability::AcceptanceContract,
        NodeProvisioningExecutorCapability::MachineReadableRejections,
        NodeProvisioningExecutorCapability::LoopContract,
    ]
}

fn build_node_provisioning_executor_handshake(
    request: NodeProvisioningExecutorHandshakeRequest,
) -> NodeProvisioningExecutorHandshakeView {
    let required_capabilities = node_provisioning_executor_required_capabilities();
    let missing_required_capabilities = required_capabilities
        .iter()
        .copied()
        .filter(|required| !request.capabilities.contains(required))
        .collect::<Vec<_>>();
    let mut compatibility =
        build_node_provisioning_executor_compatibility(request.executor_contract_version);
    if compatibility.compatible && !missing_required_capabilities.is_empty() {
        compatibility.status =
            NodeProvisioningExecutorCompatibilityStatus::MissingRequiredCapabilities;
        compatibility.compatible = false;
        compatibility.issues.push(format!(
            "executor is missing {} required provisioning capabilities",
            missing_required_capabilities.len()
        ));
    }
    let compatibility_status = compatibility.status;

    NodeProvisioningExecutorHandshakeView {
        schema_version: NODE_PROVISIONING_EXECUTOR_CONTRACT_VERSION,
        panel: NodeProvisioningExecutorPanelIdentityView {
            product: "hydra-panel".to_string(),
            api_version: env!("CARGO_PKG_VERSION").to_string(),
        },
        minimum_executor_version: NODE_PROVISIONING_MINIMUM_EXECUTOR_VERSION.to_string(),
        supported_capabilities: node_provisioning_executor_capabilities(),
        required_capabilities,
        missing_required_capabilities,
        compatibility,
        heartbeat_policy: NodeProvisioningExecutorHeartbeatPolicyView {
            heartbeat_interval_seconds: NODE_PROVISIONING_HEARTBEAT_INTERVAL_SECONDS,
            stale_after_seconds: NODE_PROVISIONING_TASK_STALE_AFTER_SECONDS,
        },
        security_expectations: NodeProvisioningExecutorSecurityExpectationsView {
            result_submissions_require_compatible_contract_version: true,
            panel_observed_transitions_cannot_be_self_reported: true,
            secret_payloads_must_not_be_persisted: true,
            remote_attestations_required_for_sensitive_handoffs: true,
        },
        executor: NodeProvisioningExecutorRegistrationView {
            executor_id: request.executor_id,
            enabled: true,
            auth_token_configured: false,
            auth_token_issued_at_unix: None,
            auth_token_hash: None,
            executor_version: request.executor_version,
            last_contract_version: request.executor_contract_version,
            capabilities: request.capabilities,
            last_handshake_at_unix: 0,
            last_compatibility_status: compatibility_status,
            accepted_result_count: 0,
            rejected_result_count: 0,
        },
    }
}

fn public_executor_registration(
    mut registration: NodeProvisioningExecutorRegistrationView,
) -> NodeProvisioningExecutorRegistrationView {
    registration.auth_token_hash = None;
    registration
}

fn build_node_provisioning_executor_compatibility(
    requested_contract_version: Option<u16>,
) -> NodeProvisioningExecutorCompatibilityView {
    let (status, compatible, issues) = match requested_contract_version {
        Some(version) if version < NODE_PROVISIONING_MINIMUM_EXECUTOR_CONTRACT_VERSION => (
            NodeProvisioningExecutorCompatibilityStatus::ExecutorUpgradeRequired,
            false,
            vec![format!(
                "executor contract v{version} is older than the minimum supported v{}",
                NODE_PROVISIONING_MINIMUM_EXECUTOR_CONTRACT_VERSION
            )],
        ),
        Some(version) if version > NODE_PROVISIONING_EXECUTOR_CONTRACT_VERSION => (
            NodeProvisioningExecutorCompatibilityStatus::PanelUpgradeRequired,
            false,
            vec![format!(
                "executor contract v{version} is newer than panel-supported v{}",
                NODE_PROVISIONING_EXECUTOR_CONTRACT_VERSION
            )],
        ),
        Some(_) => (
            NodeProvisioningExecutorCompatibilityStatus::Compatible,
            true,
            Vec::new(),
        ),
        None => (
            NodeProvisioningExecutorCompatibilityStatus::UnknownExecutor,
            false,
            vec!["executor_contract_version is required before automated execution".to_string()],
        ),
    };

    NodeProvisioningExecutorCompatibilityView {
        status,
        compatible,
        requested_contract_version,
        supported_contract_version: NODE_PROVISIONING_EXECUTOR_CONTRACT_VERSION,
        minimum_executor_contract_version: NODE_PROVISIONING_MINIMUM_EXECUTOR_CONTRACT_VERSION,
        minimum_executor_version: NODE_PROVISIONING_MINIMUM_EXECUTOR_VERSION.to_string(),
        issues,
    }
}

fn ensure_node_provisioning_executor_contract_compatible(
    executor_contract_version: Option<u16>,
) -> Result<(), SecurityError> {
    build_node_provisioning_executor_compatibility(executor_contract_version)
        .compatible
        .then_some(())
        .ok_or(SecurityError::InvalidSecuritySettings(
            "executor contract version is missing or incompatible",
        ))
}

pub fn build_node_provisioning_executor_accepted_result(
    task: NodeProvisioningTask,
    required_ports: &[u16],
    accepted_node_id: Option<String>,
) -> NodeProvisioningExecutorAcceptedResultView {
    let session = build_node_provisioning_executor_session(
        task.clone(),
        required_ports,
        Some(NODE_PROVISIONING_EXECUTOR_CONTRACT_VERSION),
    );
    NodeProvisioningExecutorAcceptedResultView {
        task_id: task.task_id,
        node_id: task.node_id,
        accepted_node_id,
        task_status: task.status,
        completed_node_ids: session.resume.completed_node_ids,
        next_node_ids: session.resume.next_node_ids,
        recommended_next_command: session.resume.recommended_next_command,
    }
}

fn build_node_provisioning_executor_workflow(
    task: &NodeProvisioningTask,
    uses_ssh: bool,
) -> NodeProvisioningExecutorWorkflowView {
    let mut nodes = task
        .planned_steps
        .iter()
        .enumerate()
        .map(|(index, step)| NodeProvisioningExecutorWorkflowNode {
            id: format!("step_{}", handoff_safe_step_label(*step)),
            kind: NodeProvisioningExecutorWorkflowNodeKind::Step,
            step: Some(*step),
            handoff: None,
            action: executor_action_for_step(*step).to_string(),
            endpoint_suffix: format!("/{}/step", task.task_id),
            depends_on: (index > 0)
                .then(|| {
                    format!(
                        "step_{}",
                        handoff_safe_step_label(task.planned_steps[index - 1])
                    )
                })
                .into_iter()
                .collect(),
            requires_heartbeat: matches!(
                step,
                NodeProvisioningStepKind::XrayInstall
                    | NodeProvisioningStepKind::SidecarRuntimeInstall
                    | NodeProvisioningStepKind::NodeInstall
                    | NodeProvisioningStepKind::ServiceInstall
            ),
        })
        .collect::<Vec<_>>();

    if uses_ssh {
        if let Some(node) = nodes
            .iter_mut()
            .find(|node| node.step == Some(NodeProvisioningStepKind::ServiceInstall))
        {
            node.depends_on = vec!["handoff_node_env_written".to_string()];
        }
        if let Some(node) = nodes
            .iter_mut()
            .find(|node| node.step == Some(NodeProvisioningStepKind::AgentReachability))
        {
            node.depends_on = vec!["handoff_agent_returned".to_string()];
        }
        nodes.extend([
            workflow_handoff_node(
                NodeProvisioningHandoffKind::TokenIssued,
                "POST /auth/rotate",
                vec!["step_node_install".to_string()],
                &task.task_id,
            ),
            workflow_handoff_node(
                NodeProvisioningHandoffKind::NodeEnvWritten,
                "POST /handoff",
                vec!["handoff_token_issued".to_string()],
                &task.task_id,
            ),
            workflow_handoff_node(
                NodeProvisioningHandoffKind::ServiceStarted,
                "POST /handoff",
                vec!["step_service_install".to_string()],
                &task.task_id,
            ),
            workflow_handoff_node(
                NodeProvisioningHandoffKind::AgentReturned,
                "panel_observed_heartbeat",
                vec!["handoff_service_started".to_string()],
                &task.task_id,
            ),
        ]);
    }

    let transitions = nodes
        .iter()
        .flat_map(|node| {
            node.depends_on.iter().map(move |dependency| {
                NodeProvisioningExecutorWorkflowTransition {
                    from: dependency.clone(),
                    to: node.id.clone(),
                    condition: "dependency_succeeded".to_string(),
                }
            })
        })
        .collect();

    let validation = validate_node_provisioning_executor_workflow(&nodes, uses_ssh);
    NodeProvisioningExecutorWorkflowView {
        nodes,
        transitions,
        validation,
    }
}

fn workflow_handoff_node(
    handoff: NodeProvisioningHandoffKind,
    action: &str,
    depends_on: Vec<String>,
    task_id: &str,
) -> NodeProvisioningExecutorWorkflowNode {
    NodeProvisioningExecutorWorkflowNode {
        id: format!("handoff_{}", handoff_kind_label(handoff)),
        kind: NodeProvisioningExecutorWorkflowNodeKind::Handoff,
        step: None,
        handoff: Some(handoff),
        action: action.to_string(),
        endpoint_suffix: format!("/{task_id}/handoff"),
        depends_on,
        requires_heartbeat: false,
    }
}

fn handoff_safe_step_label(step: NodeProvisioningStepKind) -> &'static str {
    match step {
        NodeProvisioningStepKind::Preflight => "preflight",
        NodeProvisioningStepKind::AgentReachability => "agent_reachability",
        NodeProvisioningStepKind::RuntimeHealth => "runtime_health",
        NodeProvisioningStepKind::ConfigApply => "config_apply",
        NodeProvisioningStepKind::BootstrapVerify => "bootstrap_verify",
        NodeProvisioningStepKind::SshConnect => "ssh_connect",
        NodeProvisioningStepKind::SudoCheck => "sudo_check",
        NodeProvisioningStepKind::XrayInstall => "xray_install",
        NodeProvisioningStepKind::SidecarRuntimeInstall => "sidecar_runtime_install",
        NodeProvisioningStepKind::NodeInstall => "node_install",
        NodeProvisioningStepKind::ServiceInstall => "service_install",
    }
}

fn validate_node_provisioning_executor_workflow(
    nodes: &[NodeProvisioningExecutorWorkflowNode],
    uses_ssh: bool,
) -> NodeProvisioningExecutorWorkflowValidationView {
    let mut issues = Vec::new();
    let ids = nodes.iter().map(|node| node.id.clone()).collect::<Vec<_>>();
    let unique_ids = ids.iter().cloned().collect::<HashSet<_>>();
    if ids.len() != unique_ids.len() {
        issues.push("workflow contains duplicate node ids".to_string());
    }
    for node in nodes {
        for dependency in &node.depends_on {
            if !unique_ids.contains(dependency) {
                issues.push(format!(
                    "workflow node {} depends on missing node {}",
                    node.id, dependency
                ));
            }
        }
    }
    if workflow_contains_cycle(nodes) {
        issues.push("workflow contains a dependency cycle".to_string());
    }
    if uses_ssh {
        for required in [
            "handoff_token_issued",
            "handoff_node_env_written",
            "handoff_service_started",
            "handoff_agent_returned",
        ] {
            if !unique_ids.contains(required) {
                issues.push(format!(
                    "workflow is missing required SSH handoff node {required}"
                ));
            }
        }
        let agent_reachability = nodes
            .iter()
            .find(|node| node.step == Some(NodeProvisioningStepKind::AgentReachability));
        if !agent_reachability.is_some_and(|node| {
            node.depends_on
                .iter()
                .any(|dependency| dependency == "handoff_agent_returned")
        }) {
            issues.push(
                "workflow agent_reachability must depend on handoff_agent_returned".to_string(),
            );
        }
    }
    NodeProvisioningExecutorWorkflowValidationView {
        valid: issues.is_empty(),
        issues,
    }
}

fn workflow_contains_cycle(nodes: &[NodeProvisioningExecutorWorkflowNode]) -> bool {
    fn visit(
        node_id: &str,
        dependencies: &HashMap<&str, Vec<&str>>,
        visiting: &mut HashSet<String>,
        visited: &mut HashSet<String>,
    ) -> bool {
        if visited.contains(node_id) {
            return false;
        }
        if !visiting.insert(node_id.to_string()) {
            return true;
        }
        if let Some(node_dependencies) = dependencies.get(node_id) {
            for dependency in node_dependencies {
                if visit(dependency, dependencies, visiting, visited) {
                    return true;
                }
            }
        }
        visiting.remove(node_id);
        visited.insert(node_id.to_string());
        false
    }

    let dependencies = nodes
        .iter()
        .map(|node| {
            (
                node.id.as_str(),
                node.depends_on
                    .iter()
                    .map(String::as_str)
                    .collect::<Vec<_>>(),
            )
        })
        .collect::<HashMap<_, _>>();
    let mut visiting = HashSet::new();
    let mut visited = HashSet::new();
    nodes
        .iter()
        .any(|node| visit(&node.id, &dependencies, &mut visiting, &mut visited))
}

fn build_node_provisioning_executor_resume_view(
    task: &NodeProvisioningTask,
    workflow: &NodeProvisioningExecutorWorkflowView,
    required_ports: &[u16],
) -> NodeProvisioningExecutorResumeView {
    let completed = workflow
        .nodes
        .iter()
        .filter(|node| workflow_node_succeeded(task, node))
        .map(|node| node.id.clone())
        .collect::<HashSet<_>>();
    let completed_node_ids = workflow
        .nodes
        .iter()
        .filter(|node| completed.contains(&node.id))
        .map(|node| node.id.clone())
        .collect::<Vec<_>>();
    let runnable_node_ids = workflow
        .nodes
        .iter()
        .filter(|node| !completed.contains(&node.id))
        .filter(|node| {
            node.depends_on
                .iter()
                .all(|dependency| completed.contains(dependency))
        })
        .map(|node| node.id.clone())
        .collect::<Vec<_>>();
    let blocked_node_ids = workflow
        .nodes
        .iter()
        .filter(|node| !completed.contains(&node.id))
        .filter(|node| {
            !node
                .depends_on
                .iter()
                .all(|dependency| completed.contains(dependency))
        })
        .map(|node| node.id.clone())
        .collect::<Vec<_>>();
    let replayable_nodes = workflow
        .nodes
        .iter()
        .filter(|node| completed.contains(&node.id))
        .map(|node| NodeProvisioningExecutorResumeNode {
            id: node.id.clone(),
            replay_policy: workflow_node_replay_policy(node),
            detail: workflow_node_replay_detail(node).to_string(),
        })
        .collect::<Vec<_>>();
    let next_node_ids = runnable_node_ids
        .iter()
        .take(3)
        .cloned()
        .collect::<Vec<_>>();
    let recommended_next_action = next_node_ids
        .first()
        .and_then(|node_id| workflow.nodes.iter().find(|node| &node.id == node_id))
        .map(|node| NodeProvisioningExecutorNextActionView {
            node_id: node.id.clone(),
            kind: node.kind,
            step: node.step,
            handoff: node.handoff,
            action: node.action.clone(),
            endpoint_suffix: node.endpoint_suffix.clone(),
            executor_should_submit: !matches!(
                node.handoff,
                Some(NodeProvisioningHandoffKind::AgentReturned)
            ),
            requires_heartbeat: node.requires_heartbeat,
            reason: workflow_node_next_action_reason(node).to_string(),
        });
    let recommended_next_command = recommended_next_action.as_ref().map(|action| {
        build_executor_command_envelope(
            action,
            required_ports,
            &task.request_context.sidecar_install,
        )
    });
    NodeProvisioningExecutorResumeView {
        completed_node_ids,
        runnable_node_ids,
        replayable_nodes,
        blocked_node_ids,
        next_node_ids,
        recommended_next_action,
        recommended_next_command,
    }
}

fn workflow_node_succeeded(
    task: &NodeProvisioningTask,
    node: &NodeProvisioningExecutorWorkflowNode,
) -> bool {
    match (node.step, node.handoff) {
        (Some(step), None) => task
            .steps
            .iter()
            .rev()
            .find(|item| item.step == step)
            .is_some_and(|item| matches!(item.status, NodeProvisioningStepStatus::Succeeded)),
        (None, Some(handoff)) => task
            .handoff
            .iter()
            .find(|item| item.kind == handoff)
            .is_some_and(|item| matches!(item.status, NodeProvisioningHandoffStatus::Succeeded)),
        _ => false,
    }
}

fn workflow_node_replay_policy(
    node: &NodeProvisioningExecutorWorkflowNode,
) -> NodeProvisioningExecutorReplayPolicy {
    match (node.step, node.handoff) {
        (_, Some(NodeProvisioningHandoffKind::TokenIssued)) => {
            NodeProvisioningExecutorReplayPolicy::ReissueRequired
        }
        (_, Some(NodeProvisioningHandoffKind::AgentReturned)) => {
            NodeProvisioningExecutorReplayPolicy::PanelObservedOnly
        }
        _ => NodeProvisioningExecutorReplayPolicy::SafeToReplay,
    }
}

fn workflow_node_replay_detail(node: &NodeProvisioningExecutorWorkflowNode) -> &'static str {
    match (node.step, node.handoff) {
        (_, Some(NodeProvisioningHandoffKind::TokenIssued)) => {
            "replay requires explicit auth-token rotation; never assume old plaintext still exists"
        }
        (_, Some(NodeProvisioningHandoffKind::AgentReturned)) => {
            "panel-observed heartbeat cannot be replayed by executor; wait for a fresh agent return"
        }
        _ => "safe to replay if idempotent remote action is needed during recovery",
    }
}

fn workflow_node_next_action_reason(node: &NodeProvisioningExecutorWorkflowNode) -> &'static str {
    match (node.step, node.handoff) {
        (_, Some(NodeProvisioningHandoffKind::TokenIssued)) => {
            "all install prerequisites before secret material handoff are complete"
        }
        (_, Some(NodeProvisioningHandoffKind::NodeEnvWritten)) => {
            "fresh node auth material must be written and attested before service install"
        }
        (_, Some(NodeProvisioningHandoffKind::ServiceStarted)) => {
            "service metadata must be attested before waiting for authenticated agent return"
        }
        (_, Some(NodeProvisioningHandoffKind::AgentReturned)) => {
            "panel must observe a fresh authenticated agent heartbeat before post-install checks"
        }
        (Some(NodeProvisioningStepKind::AgentReachability), _) => {
            "agent has crossed the trust boundary; begin panel-observed post-install checks"
        }
        _ => "all workflow dependencies for this node are currently satisfied",
    }
}

fn build_executor_command_envelope(
    action: &NodeProvisioningExecutorNextActionView,
    required_ports: &[u16],
    sidecar_install: &NodeProvisioningSidecarInstallSelection,
) -> NodeProvisioningExecutorCommandEnvelopeView {
    let material_handoff = build_node_provisioning_material_handoff_plan();
    let (payload_kind, script, expected_report, required_handoff, attestation_script) =
        match (action.step, action.handoff) {
            (Some(NodeProvisioningStepKind::Preflight), None) => (
                NodeProvisioningExecutorCommandPayloadKind::SshPreflightProbe,
                Some(ssh_remote_preflight_probe_script(required_ports)),
                Some(executor_expected_report_for_step(
                    NodeProvisioningStepKind::Preflight,
                )),
                None,
                None,
            ),
            (Some(step), None)
                if matches!(
                    step,
                    NodeProvisioningStepKind::SudoCheck
                        | NodeProvisioningStepKind::XrayInstall
                        | NodeProvisioningStepKind::SidecarRuntimeInstall
                        | NodeProvisioningStepKind::NodeInstall
                        | NodeProvisioningStepKind::ServiceInstall
                ) =>
            {
                let script = build_ssh_install_plan(sidecar_install)
                    .scripts
                    .into_iter()
                    .find(|item| item.step == step)
                    .map(|item| item.script);
                (
                    NodeProvisioningExecutorCommandPayloadKind::SshInstallScript,
                    script,
                    Some(executor_expected_report_for_step(step)),
                    None,
                    None,
                )
            }
            (Some(step), None) => (
                NodeProvisioningExecutorCommandPayloadKind::None,
                None,
                Some(executor_expected_report_for_step(step)),
                None,
                None,
            ),
            (None, Some(NodeProvisioningHandoffKind::NodeEnvWritten)) => (
                NodeProvisioningExecutorCommandPayloadKind::MaterialHandoff,
                None,
                None,
                action.handoff,
                material_handoff.node_env_attestation_script,
            ),
            (None, Some(NodeProvisioningHandoffKind::ServiceStarted)) => (
                NodeProvisioningExecutorCommandPayloadKind::MaterialHandoff,
                None,
                None,
                action.handoff,
                material_handoff.service_started_attestation_script,
            ),
            (None, Some(NodeProvisioningHandoffKind::TokenIssued)) => (
                NodeProvisioningExecutorCommandPayloadKind::MaterialHandoff,
                None,
                None,
                action.handoff,
                None,
            ),
            (None, Some(NodeProvisioningHandoffKind::AgentReturned)) => (
                NodeProvisioningExecutorCommandPayloadKind::PanelObservedWait,
                None,
                None,
                action.handoff,
                None,
            ),
            _ => (
                NodeProvisioningExecutorCommandPayloadKind::None,
                None,
                None,
                None,
                None,
            ),
        };

    NodeProvisioningExecutorCommandEnvelopeView {
        node_id: action.node_id.clone(),
        payload_kind,
        script,
        replay_policy: action
            .handoff
            .map(|_| workflow_node_replay_policy_for_handoff(action.handoff)),
        expected_report,
        required_handoff,
        attestation_script,
        action: action.action.clone(),
        endpoint_suffix: action.endpoint_suffix.clone(),
        executor_should_submit: action.executor_should_submit,
        requires_heartbeat: action.requires_heartbeat,
        reason: action.reason.clone(),
        acceptance: executor_acceptance_contract(action),
    }
}

fn executor_acceptance_contract(
    action: &NodeProvisioningExecutorNextActionView,
) -> NodeProvisioningExecutorAcceptanceContractView {
    match (action.step, action.handoff) {
        (Some(NodeProvisioningStepKind::Preflight), None) => {
            NodeProvisioningExecutorAcceptanceContractView {
                submission_kind: NodeProvisioningExecutorResultSubmissionKind::StepReport,
                endpoint_suffix: Some(action.endpoint_suffix.clone()),
                executor_may_submit: true,
                required_success_fields: vec![
                    "status=succeeded".to_string(),
                    "ssh_preflight_output or remote_prerequisites".to_string(),
                ],
                fail_closed_checks: vec![
                    "successful preflight without canonical probe output or normalized prerequisites is rejected"
                        .to_string(),
                ],
                description:
                    "submit a structured preflight step result; the panel derives normalized readiness from evidence"
                        .to_string(),
            }
        }
        (
            Some(
                NodeProvisioningStepKind::SshConnect
                | NodeProvisioningStepKind::SudoCheck
                | NodeProvisioningStepKind::XrayInstall
                | NodeProvisioningStepKind::SidecarRuntimeInstall
                | NodeProvisioningStepKind::NodeInstall
                | NodeProvisioningStepKind::ServiceInstall,
            ),
            None,
        ) => {
            NodeProvisioningExecutorAcceptanceContractView {
                submission_kind: NodeProvisioningExecutorResultSubmissionKind::CommandReport,
                endpoint_suffix: Some(action.endpoint_suffix.replace("/step", "/command-report")),
                executor_may_submit: true,
                required_success_fields: vec!["step".to_string(), "exit_code=0".to_string()],
                fail_closed_checks: vec![
                    "bare successful /step report is rejected for command-style steps".to_string(),
                    "non-zero exit_code is normalized as failed command result".to_string(),
                ],
                description:
                    "submit command execution evidence; the panel normalizes bounded stdout/stderr and derives step status"
                        .to_string(),
            }
        }
        (Some(_), None) => NodeProvisioningExecutorAcceptanceContractView {
            submission_kind: NodeProvisioningExecutorResultSubmissionKind::StepReport,
            endpoint_suffix: Some(action.endpoint_suffix.clone()),
            executor_may_submit: true,
            required_success_fields: vec!["status".to_string(), "detail".to_string()],
            fail_closed_checks: vec![],
            description: "submit an orchestration step status update".to_string(),
        },
        (None, Some(NodeProvisioningHandoffKind::NodeEnvWritten)) => {
            NodeProvisioningExecutorAcceptanceContractView {
                submission_kind: NodeProvisioningExecutorResultSubmissionKind::HandoffReport,
                endpoint_suffix: Some(action.endpoint_suffix.clone()),
                executor_may_submit: true,
                required_success_fields: vec![
                    "kind=node_env_written".to_string(),
                    "status=succeeded".to_string(),
                    "node_env_attestation".to_string(),
                ],
                fail_closed_checks: vec![
                    "path must be /etc/hydra-node/node.env".to_string(),
                    "mode must be 0600".to_string(),
                    "owner uid/gid must be 0/0".to_string(),
                    "regular-file and atomic-write flags must be true".to_string(),
                    "env key set and schema fingerprint must match exactly".to_string(),
                ],
                description:
                    "submit secret-free node.env metadata attestation; env values are never accepted or persisted"
                        .to_string(),
            }
        }
        (None, Some(NodeProvisioningHandoffKind::ServiceStarted)) => {
            NodeProvisioningExecutorAcceptanceContractView {
                submission_kind: NodeProvisioningExecutorResultSubmissionKind::HandoffReport,
                endpoint_suffix: Some(action.endpoint_suffix.clone()),
                executor_may_submit: true,
                required_success_fields: vec![
                    "kind=service_started".to_string(),
                    "status=succeeded".to_string(),
                    "service_started_attestation".to_string(),
                ],
                fail_closed_checks: vec![
                    "service name, unit path, ExecStart, env file, and working directory must match expected values"
                        .to_string(),
                    "systemd states must be loaded, active, and enabled".to_string(),
                ],
                description:
                    "submit secret-free systemd metadata attestation after service installation"
                        .to_string(),
            }
        }
        (None, Some(NodeProvisioningHandoffKind::TokenIssued)) => {
            NodeProvisioningExecutorAcceptanceContractView {
                submission_kind: NodeProvisioningExecutorResultSubmissionKind::PanelObserved,
                endpoint_suffix: None,
                executor_may_submit: false,
                required_success_fields: vec![],
                fail_closed_checks: vec![
                    "executor self-report is not authoritative for token issuance".to_string(),
                    "panel confirms success only after auth-token rotation".to_string(),
                ],
                description:
                    "panel-observed handoff; executor must trigger the token issuance flow, not forge a handoff result"
                        .to_string(),
            }
        }
        (None, Some(NodeProvisioningHandoffKind::AgentReturned)) => {
            NodeProvisioningExecutorAcceptanceContractView {
                submission_kind: NodeProvisioningExecutorResultSubmissionKind::PanelObserved,
                endpoint_suffix: None,
                executor_may_submit: false,
                required_success_fields: vec![],
                fail_closed_checks: vec![
                    "executor self-report is not authoritative for agent return".to_string(),
                    "panel requires a fresh authenticated node-agent heartbeat after latest token issuance"
                        .to_string(),
                ],
                description:
                    "panel-observed wait; only a fresh authenticated agent heartbeat completes this trust-boundary crossing"
                        .to_string(),
            }
        }
        _ => NodeProvisioningExecutorAcceptanceContractView {
            submission_kind: NodeProvisioningExecutorResultSubmissionKind::PanelObserved,
            endpoint_suffix: None,
            executor_may_submit: false,
            required_success_fields: vec![],
            fail_closed_checks: vec![
                "unsupported workflow node has no accepted executor result".to_string(),
            ],
            description: "unsupported workflow node".to_string(),
        },
    }
}

fn workflow_node_replay_policy_for_handoff(
    handoff: Option<NodeProvisioningHandoffKind>,
) -> NodeProvisioningExecutorReplayPolicy {
    match handoff {
        Some(NodeProvisioningHandoffKind::TokenIssued) => {
            NodeProvisioningExecutorReplayPolicy::ReissueRequired
        }
        Some(NodeProvisioningHandoffKind::AgentReturned) => {
            NodeProvisioningExecutorReplayPolicy::PanelObservedOnly
        }
        _ => NodeProvisioningExecutorReplayPolicy::SafeToReplay,
    }
}

fn build_node_provisioning_material_handoff_plan() -> NodeProvisioningMaterialHandoffPlanView {
    NodeProvisioningMaterialHandoffPlanView {
        directories: vec![NodeProvisioningMaterialDirectory {
            path: "/etc/hydra-node".to_string(),
            mode: "0700".to_string(),
            description: "node-owned secret store; only privileged local users may traverse it"
                .to_string(),
        }],
        files: vec![NodeProvisioningMaterialFile {
            path: "/etc/hydra-node/node.env".to_string(),
            mode: "0600".to_string(),
            sensitivity: NodeProvisioningMaterialSensitivity::HighSensitivity,
            source:
                "executor composes from node id, panel URL, and one-time node auth token issuance"
                    .to_string(),
            description:
                "contains the deployable node-agent authentication material; never persist this payload in panel provisioning history"
                    .to_string(),
        }],
        fetches: vec![
            NodeProvisioningMaterialFetch {
                name: "node_auth_token".to_string(),
                endpoint: RouteId::RotateNodeAuthToken.endpoint_label(),
                authentication: "admin session".to_string(),
                plaintext_returned_once: true,
                description:
                    "issue immediately before writing node.env; rotation invalidates any previous node token"
                        .to_string(),
            },
            NodeProvisioningMaterialFetch {
                name: "route_credentials".to_string(),
                endpoint: RouteId::NodeAgentRouteCredentials.endpoint_label(),
                authentication: "node token after installed agent proves identity".to_string(),
                plaintext_returned_once: false,
                description:
                    "private route material is not preloaded by the executor; the authenticated agent fetches only its own least-knowledge assignment"
                        .to_string(),
            },
        ],
        env_schema: vec![
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_PANEL_URL".to_string(),
                required: true,
                sensitivity: NodeProvisioningMaterialSensitivity::Sensitive,
                source: "executor deployment input".to_string(),
                description:
                    "base URL the node-agent uses when calling the panel node-agent API"
                        .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_ID".to_string(),
                required: true,
                sensitivity: NodeProvisioningMaterialSensitivity::Public,
                source: "executor session node_id".to_string(),
                description: "stable panel node id for identity binding and diagnostics".to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_AUTH_TOKEN".to_string(),
                required: true,
                sensitivity: NodeProvisioningMaterialSensitivity::HighSensitivity,
                source: "fresh one-time auth/rotate response".to_string(),
                description:
                    "plaintext node-agent credential; write once to node.env and do not echo into command reports"
                        .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_SIDECAR_RECIPE_MODE".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::Public,
                source: "executor deployment input".to_string(),
                description:
                    "set to standard only when OS-level Hysteria2/WireGuard services or tools were prepared by provisioning"
                        .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_SIDECAR_RUNTIME_CONFIG_PATH".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::Sensitive,
                source: "executor deployment input".to_string(),
                description:
                    "recommended production path: /etc/hydra-node/sidecar-runtime-config.json"
                        .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_HYSTERIA2_BINARY_PATH".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::Sensitive,
                source: "sidecar runtime installation".to_string(),
                description:
                    "absolute Hysteria2 binary path when HYDRA_INSTALL_HYSTERIA2 was used or operator installed it manually"
                        .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_HYSTERIA2_SERVICE_NAME".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::Public,
                source: "sidecar runtime installation".to_string(),
                description:
                    "systemd service instance used by standard recipes, for example hydra-hysteria2@hysteria2-in.service"
                        .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_WIREGUARD_BINARY_PATH".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::Sensitive,
                source: "sidecar runtime installation".to_string(),
                description: "absolute wg binary path, usually /usr/bin/wg".to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_WG_QUICK_BINARY_PATH".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::Sensitive,
                source: "sidecar runtime installation".to_string(),
                description: "absolute wg-quick binary path, usually /usr/bin/wg-quick"
                    .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_WIREGUARD_INTERFACE_NAME".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::Public,
                source: "sidecar runtime installation".to_string(),
                description:
                    "safe WireGuard interface name used for logs/status in standard recipes"
                        .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_SESSION_ADAPTER_TOKEN".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::HighSensitivity,
                source: "executor-generated CSPRNG secret when WireGuard is selected".to_string(),
                description:
                    "dedicated local API credential shared only by node-app and node-session-adapter; must differ from the panel node token"
                        .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_SESSION_ADAPTER_DRY_RUN_OBSERVATION_ONLY".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::Public,
                source: "WireGuard service installation".to_string(),
                description:
                    "set to false only when the verified WireGuard driver binary is installed"
                        .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_SESSION_ADAPTER_DRIVER_PATH".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::Sensitive,
                source: "WireGuard service installation".to_string(),
                description:
                    "absolute path /opt/hydra-node/node-session-driver-wireguard"
                        .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_WIREGUARD_SESSION_REF_KEY".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::HighSensitivity,
                source: "executor-generated persistent CSPRNG secret when WireGuard is selected"
                    .to_string(),
                description:
                    "domain-separates opaque runtime session references; never rotate implicitly or log"
                        .to_string(),
            },
            NodeProvisioningEnvVarSpec {
                name: "HYDRA_NODE_WIREGUARD_SESSION_MAP_PATH".to_string(),
                required: false,
                sensitivity: NodeProvisioningMaterialSensitivity::Sensitive,
                source: "WireGuard service installation".to_string(),
                description:
                    "owner-only mapping generated by node-app at /etc/hydra-node/sidecar-generated/wireguard-session-map.json"
                        .to_string(),
            },
        ],
        node_env_attestation_schema_fingerprint: Some(node_env_schema_fingerprint()),
        node_env_attestation_script: Some(node_env_attestation_script()),
        service_started_attestation_script: Some(service_started_attestation_script()),
        write_sequence: vec![
            "create secret directory before downloading or rendering secret material".to_string(),
            "issue fresh node auth token immediately before rendering node.env".to_string(),
            "write node.env atomically with mode 0600".to_string(),
            "when WireGuard is selected, generate independent adapter-token and session-reference secrets and include only their values in node.env"
                .to_string(),
            "start service only after node.env permissions are correct".to_string(),
            "start hydra-node before hydra-node-session-adapter and fail closed if the driver handshake fails"
                .to_string(),
            "discard plaintext token from executor memory after first successful agent authentication"
                .to_string(),
        ],
        expected_reports: required_handoff_reports().to_vec(),
        post_install_checks: vec![
            "agent authenticates through GET /api/node-agent/me".to_string(),
            "agent reports heartbeat before bootstrap verification".to_string(),
            "agent fetches config and any route credentials only after authentication".to_string(),
            "when WireGuard is selected, node-session-adapter registers exact-session capabilities and continuously renews its local lease"
                .to_string(),
        ],
    }
}

fn executor_action_for_step(step: NodeProvisioningStepKind) -> &'static str {
    match step {
        NodeProvisioningStepKind::Preflight => "run_preflight_probe",
        NodeProvisioningStepKind::SshConnect => "verify_ssh_transport",
        NodeProvisioningStepKind::SudoCheck => "run_install_script",
        NodeProvisioningStepKind::XrayInstall => "run_install_script",
        NodeProvisioningStepKind::SidecarRuntimeInstall => "run_install_script",
        NodeProvisioningStepKind::NodeInstall => "run_install_script",
        NodeProvisioningStepKind::ServiceInstall => "run_install_script",
        NodeProvisioningStepKind::AgentReachability => "wait_for_node_agent",
        NodeProvisioningStepKind::RuntimeHealth => "check_runtime_health",
        NodeProvisioningStepKind::ConfigApply => "request_config_apply",
        NodeProvisioningStepKind::BootstrapVerify => "request_bootstrap_probe",
    }
}

fn executor_expected_report_for_step(
    step: NodeProvisioningStepKind,
) -> NodeProvisioningExecutorExpectedReport {
    match step {
        NodeProvisioningStepKind::Preflight => NodeProvisioningExecutorExpectedReport {
            mode: NodeProvisioningExecutorReportMode::StructuredStep,
            required_fields: vec!["ssh_preflight_output".to_string()],
            description:
                "submit canonical SSH preflight stdout so the panel derives normalized remote prerequisites"
                    .to_string(),
        },
        NodeProvisioningStepKind::SshConnect
        | NodeProvisioningStepKind::SudoCheck
        | NodeProvisioningStepKind::XrayInstall
        | NodeProvisioningStepKind::SidecarRuntimeInstall
        | NodeProvisioningStepKind::NodeInstall
        | NodeProvisioningStepKind::ServiceInstall => NodeProvisioningExecutorExpectedReport {
            mode: NodeProvisioningExecutorReportMode::CommandReport,
            required_fields: vec!["exit_code".to_string()],
            description:
                "submit command-report; the panel derives success/failure from the shell exit code"
                    .to_string(),
        },
        NodeProvisioningStepKind::AgentReachability
        | NodeProvisioningStepKind::RuntimeHealth
        | NodeProvisioningStepKind::ConfigApply
        | NodeProvisioningStepKind::BootstrapVerify => NodeProvisioningExecutorExpectedReport {
            mode: NodeProvisioningExecutorReportMode::OrchestrationStep,
            required_fields: vec!["status".to_string(), "detail".to_string()],
            description:
                "submit orchestration status after the related panel/node API interaction completes"
                    .to_string(),
        },
    }
}

fn validate_executor_step_report(
    request: &UpdateNodeProvisioningStepRequest,
) -> Result<(), SecurityError> {
    if !matches!(request.status, NodeProvisioningStepStatus::Succeeded) {
        return Ok(());
    }
    match request.step {
        NodeProvisioningStepKind::Preflight
            if request.ssh_preflight_output.is_none()
                && request.remote_prerequisites.is_empty() =>
        {
            Err(SecurityError::InvalidSecuritySettings(
                "successful preflight step requires ssh preflight output or remote prerequisites",
            ))
        }
        NodeProvisioningStepKind::SshConnect
        | NodeProvisioningStepKind::SudoCheck
        | NodeProvisioningStepKind::XrayInstall
        | NodeProvisioningStepKind::SidecarRuntimeInstall
        | NodeProvisioningStepKind::NodeInstall
        | NodeProvisioningStepKind::ServiceInstall
            if !request.from_command_report =>
        {
            Err(SecurityError::InvalidSecuritySettings(
                "successful command step requires command-report evidence",
            ))
        }
        _ => Ok(()),
    }
}

fn normalize_node_provisioning_command_report(
    request: ReportNodeProvisioningCommandRequest,
) -> NodeProvisioningCommandReportView {
    let stdout_summary = sanitize_node_provisioning_command_output(request.stdout);
    let stderr_summary = sanitize_node_provisioning_command_output(request.stderr);
    let status = if request.exit_code == 0 {
        NodeProvisioningStepStatus::Succeeded
    } else {
        NodeProvisioningStepStatus::Failed
    };
    let failure_category = matches!(status, NodeProvisioningStepStatus::Failed).then(|| {
        classify_node_provisioning_command_failure(request.step, stderr_summary.as_deref())
    });
    NodeProvisioningCommandReportView {
        step: request.step,
        status,
        exit_code: request.exit_code,
        stdout_summary,
        stderr_summary,
        failure_category,
    }
}

fn sanitize_node_provisioning_command_output(output: Option<String>) -> Option<String> {
    output
        .map(|value| {
            let redacted = redact_sensitive_text(&value);
            truncate_chars(redacted.trim(), NODE_PROVISIONING_COMMAND_OUTPUT_LIMIT)
        })
        .filter(|value| !value.is_empty())
}

fn sanitize_node_provisioning_freeform_detail(value: &str) -> String {
    truncate_chars(
        redact_sensitive_text(value).trim(),
        NODE_PROVISIONING_COMMAND_OUTPUT_LIMIT,
    )
}

fn public_telegram_event(mut event: TelegramEvent) -> TelegramEvent {
    event.target_chat_id = event
        .target_chat_id
        .as_deref()
        .map(mask_sensitive_identifier);
    event.message = sanitize_telegram_event_text(&event.message);
    event.last_error = event
        .last_error
        .as_deref()
        .map(sanitize_telegram_event_text);
    event
}

fn sanitize_telegram_event_text(value: &str) -> String {
    truncate_chars(
        redact_telegram_bot_url(&redact_sensitive_text(value)).trim(),
        NODE_PROVISIONING_COMMAND_OUTPUT_LIMIT,
    )
}

fn mask_sensitive_identifier(value: &str) -> String {
    let trimmed = value.trim();
    let char_count = trimmed.chars().count();
    if char_count <= 4 {
        return "[REDACTED]".to_string();
    }
    let prefix: String = trimmed.chars().take(2).collect();
    let suffix: String = trimmed
        .chars()
        .rev()
        .take(2)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .collect();
    format!("{prefix}...[REDACTED]...{suffix}")
}

fn redact_telegram_bot_url(value: &str) -> String {
    const MARKER: &str = "api.telegram.org/bot";
    let mut redacted = String::with_capacity(value.len());
    let mut rest = value;
    while let Some(index) = rest.find(MARKER) {
        redacted.push_str(&rest[..index + MARKER.len()]);
        redacted.push_str("[REDACTED]");
        let after_marker = &rest[index + MARKER.len()..];
        if let Some(path_index) = after_marker.find('/') {
            rest = &after_marker[path_index..];
        } else {
            rest = "";
        }
    }
    redacted.push_str(rest);
    redacted
}

fn redact_sensitive_text(value: &str) -> String {
    value
        .lines()
        .map(|line| {
            if line.contains("PRIVATE KEY") {
                "[REDACTED PRIVATE KEY]".to_string()
            } else if let Some((key, _)) = line.split_once('=')
                && matches!(
                    key.trim().to_ascii_uppercase().as_str(),
                    "PASSWORD"
                        | "SSH_PASSWORD"
                        | "TOKEN"
                        | "NODE_TOKEN"
                        | "AUTH_TOKEN"
                        | "HYDRA_NODE_AUTH_TOKEN"
                        | "HYDRA_NODE_TOKEN"
                )
            {
                format!("{}=[REDACTED]", key.trim())
            } else {
                redact_inline_secret_assignments(line)
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn redact_inline_secret_assignments(value: &str) -> String {
    let mut redacted = value.to_string();
    for key in [
        "PASSWORD",
        "SSH_PASSWORD",
        "TOKEN",
        "NODE_TOKEN",
        "AUTH_TOKEN",
        "HYDRA_NODE_AUTH_TOKEN",
        "HYDRA_NODE_TOKEN",
    ] {
        redacted = redact_inline_secret_assignment_key(&redacted, key);
    }
    redacted
}

fn redact_inline_secret_assignment_key(value: &str, key: &str) -> String {
    let lower = value.to_ascii_lowercase();
    let needle = format!("{}=", key.to_ascii_lowercase());
    let mut output = String::with_capacity(value.len());
    let mut cursor = 0;
    while let Some(relative_index) = lower[cursor..].find(&needle) {
        let start = cursor + relative_index;
        let before = value[..start].chars().next_back();
        if before.is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == '_') {
            output.push_str(&value[cursor..start + needle.len()]);
            cursor = start + needle.len();
            continue;
        }
        let value_start = start + needle.len();
        let mut value_end = value_start;
        for (offset, ch) in value[value_start..].char_indices() {
            if ch.is_whitespace() || matches!(ch, ',' | ';') {
                break;
            }
            value_end = value_start + offset + ch.len_utf8();
        }
        output.push_str(&value[cursor..value_start]);
        output.push_str("[REDACTED]");
        cursor = value_end;
    }
    output.push_str(&value[cursor..]);
    output
}

fn truncate_chars(value: &str, max_chars: usize) -> String {
    let mut chars = value.chars();
    let truncated: String = chars.by_ref().take(max_chars).collect();
    if chars.next().is_some() {
        format!("{truncated}...")
    } else {
        truncated
    }
}

fn classify_node_provisioning_command_failure(
    step: NodeProvisioningStepKind,
    stderr_summary: Option<&str>,
) -> NodeProvisioningFailureCategory {
    let stderr = stderr_summary.unwrap_or_default().to_ascii_lowercase();
    if matches!(step, NodeProvisioningStepKind::SshConnect)
        || stderr.contains("connection timed out")
        || stderr.contains("connection refused")
        || stderr.contains("no route to host")
    {
        NodeProvisioningFailureCategory::Connectivity
    } else if stderr.contains("permission denied") {
        NodeProvisioningFailureCategory::Authentication
    } else if matches!(step, NodeProvisioningStepKind::SudoCheck)
        || stderr.contains("sudo")
        || stderr.contains("not in the sudoers")
    {
        NodeProvisioningFailureCategory::Authorization
    } else if matches!(
        step,
        NodeProvisioningStepKind::XrayInstall
            | NodeProvisioningStepKind::SidecarRuntimeInstall
            | NodeProvisioningStepKind::NodeInstall
            | NodeProvisioningStepKind::ServiceInstall
    ) {
        NodeProvisioningFailureCategory::Runtime
    } else {
        NodeProvisioningFailureCategory::Unknown
    }
}

fn node_provisioning_command_report_detail(report: &NodeProvisioningCommandReportView) -> String {
    let mut parts = vec![format!("command exited with code {}", report.exit_code)];
    if let Some(stderr) = &report.stderr_summary {
        parts.push(format!("stderr: {stderr}"));
    } else if let Some(stdout) = &report.stdout_summary {
        parts.push(format!("stdout: {stdout}"));
    }
    parts.join("; ")
}

fn handoff_kind_label(kind: NodeProvisioningHandoffKind) -> &'static str {
    match kind {
        NodeProvisioningHandoffKind::TokenIssued => "token_issued",
        NodeProvisioningHandoffKind::NodeEnvWritten => "node_env_written",
        NodeProvisioningHandoffKind::ServiceStarted => "service_started",
        NodeProvisioningHandoffKind::AgentReturned => "agent_returned",
    }
}

fn handoff_status_label(status: NodeProvisioningHandoffStatus) -> &'static str {
    match status {
        NodeProvisioningHandoffStatus::Pending => "pending",
        NodeProvisioningHandoffStatus::Succeeded => "succeeded",
        NodeProvisioningHandoffStatus::Failed => "failed",
    }
}

fn required_handoff_reports() -> [NodeProvisioningHandoffKind; 4] {
    [
        NodeProvisioningHandoffKind::TokenIssued,
        NodeProvisioningHandoffKind::NodeEnvWritten,
        NodeProvisioningHandoffKind::ServiceStarted,
        NodeProvisioningHandoffKind::AgentReturned,
    ]
}

fn required_node_env_keys() -> [&'static str; 3] {
    ["HYDRA_NODE_AUTH_TOKEN", "HYDRA_NODE_ID", "HYDRA_PANEL_URL"]
}

fn allowed_node_env_keys() -> [&'static str; 15] {
    [
        "HYDRA_NODE_AUTH_TOKEN",
        "HYDRA_NODE_HYSTERIA2_BINARY_PATH",
        "HYDRA_NODE_HYSTERIA2_SERVICE_NAME",
        "HYDRA_NODE_ID",
        "HYDRA_NODE_SIDECAR_RECIPE_MODE",
        "HYDRA_NODE_SIDECAR_RUNTIME_CONFIG_PATH",
        "HYDRA_NODE_SESSION_ADAPTER_DRIVER_PATH",
        "HYDRA_NODE_SESSION_ADAPTER_DRY_RUN_OBSERVATION_ONLY",
        "HYDRA_NODE_SESSION_ADAPTER_TOKEN",
        "HYDRA_NODE_WG_QUICK_BINARY_PATH",
        "HYDRA_NODE_WIREGUARD_BINARY_PATH",
        "HYDRA_NODE_WIREGUARD_INTERFACE_NAME",
        "HYDRA_NODE_WIREGUARD_SESSION_MAP_PATH",
        "HYDRA_NODE_WIREGUARD_SESSION_REF_KEY",
        "HYDRA_PANEL_URL",
    ]
}

fn node_env_schema_fingerprint() -> String {
    sha256_hex(allowed_node_env_keys().join("\n").as_bytes())
}

fn node_env_attestation_script() -> String {
    format!(
        r#"set -eu
path="/etc/hydra-node/node.env"
printf 'PATH=%s\n' "$path"
printf 'MODE=%s\n' "$(stat -c '%a' "$path")"
printf 'OWNER_UID=%s\n' "$(stat -c '%u' "$path")"
printf 'OWNER_GID=%s\n' "$(stat -c '%g' "$path")"
if [ -f "$path" ]; then printf 'IS_REGULAR_FILE=1\n'; else printf 'IS_REGULAR_FILE=0\n'; fi
printf 'ATOMIC_WRITE=1\n'
printf 'ENV_KEYS=%s\n' "$(sed -n 's/=.*//p' "$path" | LC_ALL=C sort | paste -sd, -)"
printf 'SCHEMA_FINGERPRINT={}\n'"#,
        node_env_schema_fingerprint()
    )
}

fn node_env_attestation_is_valid(attestation: Option<&NodeProvisioningNodeEnvAttestation>) -> bool {
    let Some(attestation) = attestation else {
        return false;
    };
    let mut actual_keys = attestation.env_keys.clone();
    actual_keys.sort();
    actual_keys.dedup();
    let required_keys = required_node_env_keys()
        .into_iter()
        .map(str::to_string)
        .collect::<HashSet<_>>();
    let allowed_keys = allowed_node_env_keys()
        .into_iter()
        .map(str::to_string)
        .collect::<HashSet<_>>();
    required_keys
        .iter()
        .all(|required| actual_keys.contains(required))
        && actual_keys.iter().all(|key| allowed_keys.contains(key))
        && attestation.path == "/etc/hydra-node/node.env"
        && attestation.mode == "0600"
        && attestation.owner_uid == 0
        && attestation.owner_gid == 0
        && attestation.is_regular_file
        && attestation.atomic_write
        && attestation.schema_fingerprint == node_env_schema_fingerprint()
}

fn service_started_attestation_script() -> String {
    r#"set -eu
service="hydra-node.service"
printf 'SERVICE_NAME=%s\n' "$service"
printf 'UNIT_FILE_PATH=%s\n' "$(systemctl show "$service" -p FragmentPath --value)"
printf 'LOAD_STATE=%s\n' "$(systemctl show "$service" -p LoadState --value)"
printf 'ACTIVE_STATE=%s\n' "$(systemctl show "$service" -p ActiveState --value)"
printf 'UNIT_FILE_STATE=%s\n' "$(systemctl show "$service" -p UnitFileState --value)"
printf 'EXEC_START_PATH=%s\n' "$(systemctl show "$service" -p ExecStart --value | sed -n 's/.*path=\([^ ;]*\).*/\1/p')"
printf 'ENVIRONMENT_FILE_PATH=%s\n' "$(systemctl show "$service" -p EnvironmentFiles --value | awk '{print $1}')"
printf 'WORKING_DIRECTORY=%s\n' "$(systemctl show "$service" -p WorkingDirectory --value)"
adapter="hydra-node-session-adapter.service"
if [ "$(systemctl show "$adapter" -p LoadState --value)" = "loaded" ]; then
  printf 'ADAPTER_SERVICE_NAME=%s\n' "$adapter"
  printf 'ADAPTER_UNIT_FILE_PATH=%s\n' "$(systemctl show "$adapter" -p FragmentPath --value)"
  printf 'ADAPTER_LOAD_STATE=%s\n' "$(systemctl show "$adapter" -p LoadState --value)"
  printf 'ADAPTER_ACTIVE_STATE=%s\n' "$(systemctl show "$adapter" -p ActiveState --value)"
  printf 'ADAPTER_UNIT_FILE_STATE=%s\n' "$(systemctl show "$adapter" -p UnitFileState --value)"
  printf 'ADAPTER_EXEC_START_PATH=%s\n' "$(systemctl show "$adapter" -p ExecStart --value | sed -n 's/.*path=\([^ ;]*\).*/\1/p')"
  printf 'ADAPTER_ENVIRONMENT_FILE_PATH=%s\n' "$(systemctl show "$adapter" -p EnvironmentFiles --value | awk '{print $1}')"
  printf 'ADAPTER_WORKING_DIRECTORY=%s\n' "$(systemctl show "$adapter" -p WorkingDirectory --value)"
fi"#
        .to_string()
}

fn service_started_attestation_is_valid(
    attestation: Option<&NodeProvisioningServiceStartedAttestation>,
    require_wireguard_adapter: bool,
) -> bool {
    let Some(attestation) = attestation else {
        return false;
    };
    let node_valid = attestation.service_name == "hydra-node.service"
        && attestation.unit_file_path == "/etc/systemd/system/hydra-node.service"
        && attestation.load_state == "loaded"
        && attestation.active_state == "active"
        && attestation.unit_file_state == "enabled"
        && attestation.exec_start_path == "/opt/hydra-node/hydra-node"
        && attestation.environment_file_path == "/etc/hydra-node/node.env"
        && attestation.working_directory == "/opt/hydra-node";
    node_valid
        && (!require_wireguard_adapter
            || attestation
                .additional_services
                .iter()
                .any(wireguard_adapter_service_attestation_is_valid))
}

fn wireguard_adapter_service_attestation_is_valid(
    attestation: &NodeProvisioningManagedServiceAttestation,
) -> bool {
    attestation.service_name == "hydra-node-session-adapter.service"
        && attestation.unit_file_path == "/etc/systemd/system/hydra-node-session-adapter.service"
        && attestation.load_state == "loaded"
        && attestation.active_state == "active"
        && attestation.unit_file_state == "enabled"
        && attestation.exec_start_path == "/opt/hydra-node/node-session-adapter"
        && attestation.environment_file_path == "/etc/hydra-node/node.env"
        && attestation.working_directory == "/opt/hydra-node"
}

fn build_node_provisioning_executor_completion_view(
    task: &NodeProvisioningTask,
) -> NodeProvisioningExecutorCompletionView {
    let executor_steps = task
        .planned_steps
        .iter()
        .copied()
        .filter(|step| *step != NodeProvisioningStepKind::BootstrapVerify)
        .collect::<Vec<_>>();
    let latest_step_status = |kind| {
        task.steps
            .iter()
            .rev()
            .find(|step| step.step == kind)
            .map(|step| step.status)
    };
    let missing_executor_steps = executor_steps
        .iter()
        .copied()
        .filter(|step| latest_step_status(*step).is_none())
        .collect::<Vec<_>>();
    let failed_executor_steps = executor_steps
        .iter()
        .copied()
        .filter(|step| {
            matches!(
                latest_step_status(*step),
                Some(NodeProvisioningStepStatus::Failed)
            )
        })
        .collect::<Vec<_>>();
    let executor_steps_complete = missing_executor_steps.is_empty()
        && failed_executor_steps.is_empty()
        && executor_steps.iter().all(|step| {
            matches!(
                latest_step_status(*step),
                Some(NodeProvisioningStepStatus::Succeeded)
            )
        });

    let handoff_evidence = required_handoff_reports()
        .into_iter()
        .map(|kind| {
            let status = task
                .handoff
                .iter()
                .find(|record| record.kind == kind)
                .map(|record| record.status);
            NodeProvisioningHandoffCompletionView {
                kind,
                status,
                proof_source: match (kind, status) {
                    (_, None) => NodeProvisioningCompletionProofSource::Missing,
                    (
                        NodeProvisioningHandoffKind::TokenIssued
                        | NodeProvisioningHandoffKind::AgentReturned,
                        Some(NodeProvisioningHandoffStatus::Succeeded),
                    ) => NodeProvisioningCompletionProofSource::PanelObserved,
                    (
                        NodeProvisioningHandoffKind::NodeEnvWritten
                        | NodeProvisioningHandoffKind::ServiceStarted,
                        Some(NodeProvisioningHandoffStatus::Succeeded),
                    ) => NodeProvisioningCompletionProofSource::RemoteAttestation,
                    _ => NodeProvisioningCompletionProofSource::Missing,
                },
            }
        })
        .collect::<Vec<_>>();
    let missing_handoffs = missing_required_handoff_reports(task);
    let failed_handoffs = handoff_evidence
        .iter()
        .filter(|evidence| matches!(evidence.status, Some(NodeProvisioningHandoffStatus::Failed)))
        .map(|evidence| evidence.kind)
        .collect::<Vec<_>>();
    let required_handoffs_complete = handoff_evidence.iter().all(|evidence| {
        matches!(
            evidence.status,
            Some(NodeProvisioningHandoffStatus::Succeeded)
        )
    });
    let bootstrap_verified = task.verified_ready;
    let can_finish_completed = executor_steps_complete && required_handoffs_complete;
    let can_finish_verified = can_finish_completed && bootstrap_verified == Some(true);
    let mut blockers = Vec::new();
    if !missing_executor_steps.is_empty() {
        blockers.push("required executor steps are still missing".to_string());
    }
    if !failed_executor_steps.is_empty() {
        blockers.push("one or more executor steps failed".to_string());
    }
    if !missing_handoffs.is_empty() {
        blockers.push("required handoff proofs are still missing".to_string());
    }
    if !failed_handoffs.is_empty() {
        blockers.push("one or more handoff proofs failed".to_string());
    }
    if bootstrap_verified == Some(false) {
        blockers.push("bootstrap verification did not reach ready state".to_string());
    } else if bootstrap_verified.is_none() {
        blockers.push("bootstrap verification has not run yet".to_string());
    }
    NodeProvisioningExecutorCompletionView {
        can_finish_completed,
        can_finish_verified,
        executor_steps_complete,
        missing_executor_steps,
        failed_executor_steps,
        required_handoffs_complete,
        missing_handoffs,
        failed_handoffs,
        handoff_evidence,
        bootstrap_verified,
        blockers,
    }
}

fn missing_required_handoff_reports(
    task: &NodeProvisioningTask,
) -> Vec<NodeProvisioningHandoffKind> {
    required_handoff_reports()
        .into_iter()
        .filter(|required| {
            !task.handoff.iter().any(|record| {
                record.kind == *required
                    && matches!(record.status, NodeProvisioningHandoffStatus::Succeeded)
            })
        })
        .collect()
}

fn parse_ssh_remote_preflight_output(
    output: &str,
    required_ports: &[u16],
) -> Vec<NodeProvisioningRemotePrerequisiteCheck> {
    let values: HashMap<_, _> = output
        .lines()
        .filter_map(|line| line.split_once('='))
        .map(|(key, value)| (key.trim(), value.trim()))
        .collect();
    let os_id = values.get("OS_ID").copied().unwrap_or("unknown");
    let has_sudo = values.get("HAS_SUDO").copied() == Some("1");
    let disk_free_mb = values
        .get("DISK_FREE_MB")
        .and_then(|value| value.parse::<u64>().ok());
    let memory_total_mb = values
        .get("MEMORY_TOTAL_MB")
        .and_then(|value| value.parse::<u64>().ok());
    let package_manager = values.get("PACKAGE_MANAGER").copied().unwrap_or("none");
    let supported_os = matches!(
        os_id,
        "ubuntu" | "debian" | "fedora" | "rocky" | "almalinux" | "centos"
    );
    let ports_free = required_ports.iter().all(|port| {
        values
            .get(format!("PORT_{port}").as_str())
            .is_some_and(|value| *value == "free")
    });

    vec![
        remote_prerequisite_check(
            NodeProvisioningRemotePrerequisiteKind::OsSupported,
            supported_os,
            format!("remote os id is {os_id}"),
        ),
        remote_prerequisite_check(
            NodeProvisioningRemotePrerequisiteKind::SudoAvailable,
            has_sudo,
            if has_sudo {
                "sudo command is available".to_string()
            } else {
                "sudo command is unavailable".to_string()
            },
        ),
        remote_prerequisite_check(
            NodeProvisioningRemotePrerequisiteKind::DiskOk,
            disk_free_mb.is_some_and(|value| value >= NODE_PROVISIONING_MIN_DISK_FREE_MB),
            format!(
                "root filesystem free space is {} MB; requires at least {} MB",
                disk_free_mb
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "unknown".to_string()),
                NODE_PROVISIONING_MIN_DISK_FREE_MB
            ),
        ),
        remote_prerequisite_check(
            NodeProvisioningRemotePrerequisiteKind::MemoryOk,
            memory_total_mb.is_some_and(|value| value >= NODE_PROVISIONING_MIN_MEMORY_MB),
            format!(
                "memory total is {} MB; requires at least {} MB",
                memory_total_mb
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "unknown".to_string()),
                NODE_PROVISIONING_MIN_MEMORY_MB
            ),
        ),
        remote_prerequisite_check(
            NodeProvisioningRemotePrerequisiteKind::PortsAvailable,
            ports_free,
            format!(
                "required ports {} are available",
                required_ports
                    .iter()
                    .map(u16::to_string)
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
        ),
        remote_prerequisite_check(
            NodeProvisioningRemotePrerequisiteKind::PackageManagerAvailable,
            package_manager != "none",
            format!("package manager is {package_manager}"),
        ),
    ]
}

fn remote_prerequisite_check(
    prerequisite: NodeProvisioningRemotePrerequisiteKind,
    passed: bool,
    detail: String,
) -> NodeProvisioningRemotePrerequisiteCheck {
    NodeProvisioningRemotePrerequisiteCheck {
        prerequisite,
        status: if passed {
            NodeProvisioningPreflightStatus::Passed
        } else {
            NodeProvisioningPreflightStatus::Failed
        },
        detail,
    }
}

fn build_node_provisioning_executor_readiness(
    node: &Node,
    context: &NodeProvisioningRequestContext,
    checked_at_unix: u64,
) -> NodeProvisioningExecutorReadinessReport {
    let mut checks = Vec::new();
    checks.push(NodeProvisioningPreflightCheck {
        check: "transport".to_string(),
        status: if matches!(context.transport, NodeProvisioningTransportKind::Ssh) {
            NodeProvisioningPreflightStatus::Passed
        } else {
            NodeProvisioningPreflightStatus::Failed
        },
        detail: format!("{:?}", context.transport).to_ascii_lowercase(),
    });
    checks.push(NodeProvisioningPreflightCheck {
        check: "target_host".to_string(),
        status: if context
            .target_host
            .as_deref()
            .is_some_and(|value| !value.trim().is_empty())
        {
            NodeProvisioningPreflightStatus::Passed
        } else {
            NodeProvisioningPreflightStatus::Failed
        },
        detail: context
            .target_host
            .clone()
            .unwrap_or_else(|| "missing target host".to_string()),
    });
    checks.push(NodeProvisioningPreflightCheck {
        check: "ssh_port".to_string(),
        status: if context.ssh_port.is_some_and(|port| port > 0) {
            NodeProvisioningPreflightStatus::Passed
        } else {
            NodeProvisioningPreflightStatus::Failed
        },
        detail: context
            .ssh_port
            .map_or_else(|| "missing ssh port".to_string(), |port| port.to_string()),
    });
    checks.push(NodeProvisioningPreflightCheck {
        check: "ssh_username".to_string(),
        status: if context
            .ssh_username
            .as_deref()
            .is_some_and(|value| !value.trim().is_empty())
        {
            NodeProvisioningPreflightStatus::Passed
        } else {
            NodeProvisioningPreflightStatus::Failed
        },
        detail: context
            .ssh_username
            .clone()
            .unwrap_or_else(|| "missing ssh username".to_string()),
    });
    checks.push(NodeProvisioningPreflightCheck {
        check: "auth_method".to_string(),
        status: if context.uses_password_auth || context.uses_private_key_auth {
            NodeProvisioningPreflightStatus::Passed
        } else {
            NodeProvisioningPreflightStatus::Failed
        },
        detail: match (context.uses_password_auth, context.uses_private_key_auth) {
            (true, true) => "password_and_private_key".to_string(),
            (true, false) => "password".to_string(),
            (false, true) => "private_key".to_string(),
            (false, false) => "missing auth method".to_string(),
        },
    });
    checks.push(NodeProvisioningPreflightCheck {
        check: "node_auth_token_issued".to_string(),
        status: if node.auth_token_issued_at_unix.is_some() {
            NodeProvisioningPreflightStatus::Passed
        } else {
            NodeProvisioningPreflightStatus::Failed
        },
        detail: node
            .auth_token_issued_at_unix
            .map(|issued_at| format!("node auth token issued at {issued_at}"))
            .unwrap_or_else(|| "no deployable node auth token has been issued".to_string()),
    });

    let ready = checks
        .iter()
        .all(|check| matches!(check.status, NodeProvisioningPreflightStatus::Passed));
    let mut recommendations = Vec::new();
    if !ready {
        if !matches!(context.transport, NodeProvisioningTransportKind::Ssh) {
            recommendations
                .push("Use SSH executor transport for automatic installation tasks.".to_string());
        }
        if node.auth_token_issued_at_unix.is_none() {
            recommendations.push(
                "Issue a deployable node-agent token before installing the node service."
                    .to_string(),
            );
        }
        if !context.uses_password_auth && !context.uses_private_key_auth {
            recommendations.push(
                "Provide either request-scoped SSH password or private key authentication."
                    .to_string(),
            );
        }
    } else {
        recommendations.push(
            "Executor request is structurally ready; remote SSH/sudo/OS checks still run during provisioning."
                .to_string(),
        );
    }

    NodeProvisioningExecutorReadinessReport {
        transport: context.transport,
        ready,
        checked_at_unix,
        checks,
        recommendations,
    }
}

fn validate_node_provisioning_executor_request(
    request: Option<&NodeProvisioningExecutorRequest>,
) -> Result<(), SecurityError> {
    let Some(request) = request else {
        return Ok(());
    };

    let has_password = request
        .ssh_password
        .as_deref()
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false);
    let has_private_key = request
        .ssh_private_key_pem
        .as_deref()
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false);

    if request
        .ssh_username
        .as_deref()
        .map(|value| value.trim().is_empty())
        .unwrap_or(true)
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "ssh_username is required when executor transport is used",
        ));
    }

    if !has_password && !has_private_key {
        return Err(SecurityError::InvalidSecuritySettings(
            "either ssh_password or ssh_private_key_pem is required when executor transport is used",
        ));
    }

    if request
        .ssh_host
        .as_deref()
        .is_some_and(|value| value.trim().is_empty())
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "ssh_host must not be empty when provided",
        ));
    }

    if request.ssh_port == Some(0) {
        return Err(SecurityError::InvalidSecuritySettings(
            "ssh_port must be greater than zero when provided",
        ));
    }

    if let Some(private_key) = request.ssh_private_key_pem.as_deref()
        && !private_key.trim().is_empty()
        && !private_key.contains("PRIVATE KEY")
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "ssh_private_key_pem must contain a PEM/OpenSSH private key",
        ));
    }

    validate_node_provisioning_sidecar_install(
        request
            .sidecar_install
            .as_ref()
            .unwrap_or(&NodeProvisioningSidecarInstallSelection::default()),
    )?;

    Ok(())
}

fn validate_node_provisioning_sidecar_install(
    sidecar_install: &NodeProvisioningSidecarInstallSelection,
) -> Result<(), SecurityError> {
    let hysteria2_url = sidecar_install
        .hysteria2_artifact_url
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());

    if sidecar_install.install_hysteria2 {
        let Some(url) = hysteria2_url else {
            return Err(SecurityError::InvalidSecuritySettings(
                "hysteria2_artifact_url is required when install_hysteria2 is enabled",
            ));
        };
        validate_hysteria2_artifact_url(url)?;
    } else if hysteria2_url.is_some() {
        return Err(SecurityError::InvalidSecuritySettings(
            "hysteria2_artifact_url requires install_hysteria2 to be enabled",
        ));
    }

    Ok(())
}

fn validate_hysteria2_artifact_url(url: &str) -> Result<(), SecurityError> {
    if url.len() > 2048
        || url
            .chars()
            .any(|character| character.is_control() || character.is_whitespace())
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "hysteria2 artifact URL must be a single-line HTTPS URL",
        ));
    }

    let trusted_prefixes = [
        "https://github.com/apernet/hysteria/releases/download/",
        "https://github.com/apernet/hysteria/releases/latest/download/",
    ];
    if !trusted_prefixes
        .iter()
        .any(|prefix| url.starts_with(prefix))
    {
        return Err(SecurityError::InvalidSecuritySettings(
            "hysteria2 artifact URL must use the official apernet/hysteria GitHub release path",
        ));
    }

    Ok(())
}

fn build_node_provisioning_request_context(
    node: &Node,
    request: Option<&NodeProvisioningExecutorRequest>,
) -> NodeProvisioningRequestContext {
    match request {
        Some(request) => {
            let mut sidecar_install = request.sidecar_install.clone().unwrap_or_default();
            if let Some(url) = sidecar_install.hysteria2_artifact_url.as_mut() {
                *url = url.trim().to_string();
            }
            NodeProvisioningRequestContext {
                transport: NodeProvisioningTransportKind::Ssh,
                target_host: request
                    .ssh_host
                    .clone()
                    .or_else(|| Some(node.address.clone())),
                ssh_port: request.ssh_port.or(Some(22)),
                ssh_username: request.ssh_username.clone(),
                uses_password_auth: request
                    .ssh_password
                    .as_deref()
                    .map(|value| !value.trim().is_empty())
                    .unwrap_or(false),
                uses_private_key_auth: request
                    .ssh_private_key_pem
                    .as_deref()
                    .map(|value| !value.trim().is_empty())
                    .unwrap_or(false),
                sidecar_install,
            }
        }
        None => NodeProvisioningRequestContext {
            transport: NodeProvisioningTransportKind::None,
            target_host: Some(node.address.clone()),
            ssh_port: None,
            ssh_username: None,
            uses_password_auth: false,
            uses_private_key_auth: false,
            sidecar_install: NodeProvisioningSidecarInstallSelection::default(),
        },
    }
}

fn classify_percent(current: u8, warning: u8, critical: u8) -> Option<(AlertSeverity, u8)> {
    if current >= critical {
        Some((AlertSeverity::Critical, critical))
    } else if current >= warning {
        Some((AlertSeverity::Warning, warning))
    } else {
        None
    }
}

fn percent_u64(value: u64, total: u64) -> u8 {
    if total == 0 {
        return 0;
    }
    let percent = value.saturating_mul(100) / total;
    percent.min(100) as u8
}

fn read_system_stats() -> (DiskStats, u64, u64) {
    let mut system = System::new_all();
    system.refresh_memory();

    let disks = Disks::new_with_refreshed_list();
    let mut total_bytes = 0_u64;
    let mut free_bytes = 0_u64;
    for disk in disks.list() {
        total_bytes = total_bytes.saturating_add(disk.total_space());
        free_bytes = free_bytes.saturating_add(disk.available_space());
    }

    let used_bytes = total_bytes.saturating_sub(free_bytes);
    let disk = DiskStats {
        total_bytes,
        used_bytes,
        free_bytes,
    };

    // sysinfo returns bytes. It returned KiB up to 0.29, and the multiply that
    // converted them outlived the upgrade: every machine-wide memory figure the
    // panel reported was 1024 times too large, which the frontend surfaced as
    // "864656 MB used of a 512 MB budget".
    //
    // Nothing caught it because both figures were scaled the same way, so their
    // ratio stayed plausible and only the absolute values were wrong — and no
    // test asserted an absolute value.
    let memory_total_bytes = system.total_memory();
    let memory_used_bytes = system.used_memory();

    (disk, memory_used_bytes, memory_total_bytes)
}

fn system_time_to_unix(value: SystemTime) -> Option<u64> {
    value
        .duration_since(UNIX_EPOCH)
        .ok()
        .map(|duration| duration.as_secs())
}

