    #[test]
    fn persisted_nodes_encrypt_local_api_token_and_keep_auth_hash() {
        let base =
            std::env::temp_dir().join(format!("hydra-panel-node-secret-test-{}", random::<u64>()));
        let nodes_path = base.with_extension("nodes.json");
        let key_path = base.with_extension("key");
        let _ = std::fs::remove_file(&nodes_path);
        let _ = std::fs::remove_file(&key_path);

        let mut node = test_node("node-a", "node-a");
        node.auth_token_hash = hash_node_auth_token("node-token");
        node.local_api_token = Some("local-secret".to_string());
        node.local_api_token_configured = true;
        let runtime = node_runtime_with_nodes(vec![node.clone()]);

        persist_nodes(
            nodes_path.to_str().expect("test path is utf-8"),
            key_path.to_str().expect("test path is utf-8"),
            &runtime,
        )
        .expect("nodes persist");

        let persisted = std::fs::read_to_string(&nodes_path).expect("nodes file exists");
        assert!(persisted.contains("auth_token_hash"));
        assert!(persisted.contains("local_api_token_ciphertext_b64"));
        assert!(!persisted.contains("local-secret"));
        assert!(!persisted.contains("\"local_api_token\""));

        let loaded = load_nodes(
            nodes_path.to_str().expect("test path is utf-8"),
            key_path.to_str().expect("test path is utf-8"),
        )
        .expect("persisted file is readable");

        assert_eq!(loaded.len(), 1);
        assert_eq!(loaded[0].auth_token_hash, node.auth_token_hash);
        assert_eq!(loaded[0].local_api_token.as_deref(), Some("local-secret"));
        assert!(loaded[0].local_api_token_configured);

        let _ = std::fs::remove_file(&nodes_path);
        let _ = std::fs::remove_file(&key_path);
    }

