    #[test]
    fn invalid_two_factor_codes_escalate_to_ip_ban() {
        let mut config = AppConfig::default();
        config.security.bootstrap_admin.username = Some("admin".to_string());
        config.security.bootstrap_admin.password = Some("password".to_string());
        config.security.bootstrap_admin.password_hash = None;
        config.security.bootstrap_admin.two_factor_enabled = true;
        config.security.bootstrap_admin.two_factor_secret_base32 =
            Some(generate_totp_secret_base32());
        config.security.max_failed_attempts = 2;
        config.security.attempt_window_seconds = 300;
        config.security.block_for_seconds = 30;

        let mut runtime = SecurityRuntime::new(&config.security);

        let first = runtime
            .login(
                &config,
                "203.0.113.10",
                "admin",
                "password",
                Some("000000"),
                None,
            )
            .expect_err("first invalid 2fa code should fail");
        assert_eq!(first.reason, "invalid_two_factor_code");

        let second = runtime
            .login(
                &config,
                "203.0.113.10",
                "admin",
                "password",
                Some("000000"),
                None,
            )
            .expect_err("second invalid 2fa code should trigger ban");
        assert_eq!(second.reason, "ip_banned");
        assert_eq!(second.ban_kind, Some(BanKind::Temporary));
    }

    #[test]
    fn node_privileged_actions_have_distinct_audit_event_types() {
        let mut runtime = SecurityRuntime::with_audit_events(Vec::new());
        runtime.push_audit_event(
            10,
            AuditEvent {
                event_type: AuditEventType::NodeLocalRuntimeActionRequested,
                username: Some("admin".to_string()),
                client_ip: Some("127.0.0.1".to_string()),
                created_at_unix: 1,
                detail: "node runtime action executed: node-a restart".to_string(),
            },
        );
        runtime.push_audit_event(
            10,
            AuditEvent {
                event_type: AuditEventType::NodeLocalXrayUpdateRequested,
                username: Some("admin".to_string()),
                client_ip: Some("127.0.0.1".to_string()),
                created_at_unix: 2,
                detail: "node xray update requested: node-a".to_string(),
            },
        );
        runtime.push_audit_event(
            10,
            AuditEvent {
                event_type: AuditEventType::NodeBootstrapProbeRequested,
                username: Some("admin".to_string()),
                client_ip: Some("127.0.0.1".to_string()),
                created_at_unix: 3,
                detail: "node bootstrap probe completed: node-a ready=false".to_string(),
            },
        );

        let events = runtime.audit_events(AuditEventsQuery::default(), 10);

        assert!(events.iter().any(|event| matches!(
            event.event_type,
            AuditEventType::NodeLocalRuntimeActionRequested
        )));
        assert!(events.iter().any(|event| matches!(
            event.event_type,
            AuditEventType::NodeLocalXrayUpdateRequested
        )));
        assert!(events.iter().any(|event| matches!(
            event.event_type,
            AuditEventType::NodeBootstrapProbeRequested
        )));
        assert!(!events.iter().any(|event| {
            event.event_type == AuditEventType::NodeUpdated
                && event.detail.contains("bootstrap probe")
        }));
    }

    #[test]
    fn audit_events_support_bounded_filters() {
        let runtime = SecurityRuntime::with_audit_events(vec![
            AuditEvent {
                event_type: AuditEventType::LoginSucceeded,
                username: Some("admin".to_string()),
                client_ip: Some("127.0.0.1".to_string()),
                created_at_unix: 10,
                detail: "admin login succeeded".to_string(),
            },
            AuditEvent {
                event_type: AuditEventType::NodeLocalXrayUpdateRequested,
                username: Some("operator".to_string()),
                client_ip: Some("192.0.2.1".to_string()),
                created_at_unix: 20,
                detail: "node xray update requested: node-a".to_string(),
            },
            AuditEvent {
                event_type: AuditEventType::BanCreated,
                username: Some("admin".to_string()),
                client_ip: Some("127.0.0.1".to_string()),
                created_at_unix: 30,
                detail: "ban created for 203.0.113.10".to_string(),
            },
        ]);

        let filtered = runtime.audit_events(
            AuditEventsQuery {
                event_type: Some(AuditEventType::NodeLocalXrayUpdateRequested),
                username: Some("oper".to_string()),
                client_ip: None,
                search: Some("node-a".to_string()),
                created_from_unix: Some(15),
                created_to_unix: Some(25),
                limit: Some(10),
            },
            100,
        );

        assert_eq!(filtered.len(), 1);
        assert!(matches!(
            filtered[0].event_type,
            AuditEventType::NodeLocalXrayUpdateRequested
        ));

        let bounded = runtime.audit_events(
            AuditEventsQuery {
                limit: Some(100),
                ..AuditEventsQuery::default()
            },
            2,
        );

        assert_eq!(bounded.len(), 2);
        assert_eq!(bounded[0].created_at_unix, 20);
        assert_eq!(bounded[1].created_at_unix, 30);
    }

