    #[test]
    fn telegram_alert_policy_filters_severity_kind_status_and_cooldown() {
        let mut settings = PersistedTelegramSettings {
            enabled: true,
            bot_token: Some("123:abc".to_string()),
            bot_token_ciphertext_b64: None,
            bot_token_nonce_b64: None,
            default_chat_id: Some("1".to_string()),
            notify_on_security_events: true,
            notify_on_system_alerts: true,
            notify_on_node_events: true,
            notify_on_node_health_alerts: true,
            alert_policy: AlertNotificationPolicy {
                enabled: true,
                notify_on_activation: true,
                notify_on_resolution: false,
                min_severity: AlertSeverity::Critical,
                included_alert_kinds: vec![AlertKind::NodeRuntimeAlert],
                cooldown_seconds: 300,
            },
        };
        let critical_runtime_activation = TelegramAlertContext {
            kind: AlertKind::NodeRuntimeAlert,
            severity: AlertSeverity::Critical,
            status: AlertEventStatus::Activated,
        };

        assert!(
            telegram_alert_policy_blocker(&settings, &[], critical_runtime_activation, 1_000)
                .is_none()
        );

        assert!(
            telegram_alert_policy_blocker(
                &settings,
                &[],
                TelegramAlertContext {
                    severity: AlertSeverity::Warning,
                    ..critical_runtime_activation
                },
                1_000
            )
            .is_some_and(|reason| reason.contains("severity"))
        );
        assert!(
            telegram_alert_policy_blocker(
                &settings,
                &[],
                TelegramAlertContext {
                    kind: AlertKind::NodeConfigDrift,
                    ..critical_runtime_activation
                },
                1_000
            )
            .is_some_and(|reason| reason.contains("excluded"))
        );
        assert!(
            telegram_alert_policy_blocker(
                &settings,
                &[],
                TelegramAlertContext {
                    status: AlertEventStatus::Resolved,
                    ..critical_runtime_activation
                },
                1_000
            )
            .is_some_and(|reason| reason.contains("resolution"))
        );

        settings.alert_policy.notify_on_resolution = true;
        let previous = TelegramEvent {
            id: "event-a".to_string(),
            kind: TelegramEventKind::NodeHealthAlert,
            status: TelegramEventStatus::Delivered,
            alert_kind: Some(AlertKind::NodeRuntimeAlert),
            alert_severity: Some(AlertSeverity::Critical),
            alert_status: Some(AlertEventStatus::Activated),
            message: "runtime alert".to_string(),
            target_chat_id: Some("1".to_string()),
            attempt_count: 1,
            last_error: None,
            next_retry_at_unix: None,
            delivered_at_unix: Some(900),
            created_at_unix: 900,
        };

        assert!(
            telegram_alert_policy_blocker(
                &settings,
                std::slice::from_ref(&previous),
                critical_runtime_activation,
                1_000
            )
            .is_some_and(|reason| reason.contains("cooldown"))
        );
        assert!(
            telegram_alert_policy_blocker(
                &settings,
                &[previous],
                critical_runtime_activation,
                1_300
            )
            .is_none()
        );
    }

