    #[test]
    fn active_admin_sessions_expose_stable_ids_without_tokens() {
        let mut runtime = SecurityRuntime::new(&SecurityConfig::default());
        runtime.sessions.insert(
            "secret-token-a".to_string(),
            SessionState {
                username: "admin".to_string(),
                client_ip: "127.0.0.1".to_string(),
                issued_at_unix: 10,
                expires_at_unix: now_unix() + 300,
            },
        );

        let sessions = runtime.active_sessions();

        assert_eq!(sessions.len(), 1);
        assert_eq!(sessions[0].session_id, session_public_id("secret-token-a"));
        assert_ne!(sessions[0].session_id, "secret-token-a");
        assert_eq!(sessions[0].username, "admin");
        assert_eq!(sessions[0].client_ip, "127.0.0.1");
    }

    #[test]
    fn admin_session_revoke_removes_only_target_session() {
        let mut runtime = SecurityRuntime::new(&SecurityConfig::default());
        runtime.sessions.insert(
            "secret-token-a".to_string(),
            SessionState {
                username: "admin".to_string(),
                client_ip: "127.0.0.1".to_string(),
                issued_at_unix: 10,
                expires_at_unix: now_unix() + 300,
            },
        );
        runtime.sessions.insert(
            "secret-token-b".to_string(),
            SessionState {
                username: "admin".to_string(),
                client_ip: "192.0.2.1".to_string(),
                issued_at_unix: 11,
                expires_at_unix: now_unix() + 300,
            },
        );

        let revoked = runtime
            .revoke_session(&session_public_id("secret-token-a"))
            .expect("session should be revoked");

        assert_eq!(revoked.session_id, session_public_id("secret-token-a"));
        assert!(!runtime.sessions.contains_key("secret-token-a"));
        assert!(runtime.sessions.contains_key("secret-token-b"));
    }

    #[test]
    fn security_presets_keep_proxy_trust_lists_and_escalate_limits() {
        let mut config = SecurityConfig::default();
        config.proxy_trust.trust_x_forwarded_for = true;
        config.proxy_trust.trusted_proxy_ips = vec!["127.0.0.1".to_string()];
        config.proxy_trust.trusted_proxy_cidrs = vec!["10.0.0.0/8".to_string()];

        let strict = security_preset_settings(SecurityPreset::Strict, &config);
        let paranoid = security_preset_settings(SecurityPreset::Paranoid, &config);

        assert!(strict.login_protection_enabled);
        assert!(strict.smart_ban_enabled);
        assert!(strict.trust_x_forwarded_for);
        assert_eq!(strict.trusted_proxy_ips, vec!["127.0.0.1".to_string()]);
        assert_eq!(strict.trusted_proxy_cidrs, vec!["10.0.0.0/8".to_string()]);
        assert!(paranoid.max_failed_attempts < strict.max_failed_attempts);
        assert!(paranoid.block_for_seconds > strict.block_for_seconds);
        assert!(paranoid.session_ttl_seconds < strict.session_ttl_seconds);
        validate_security_settings(&strict).unwrap();
        validate_security_settings(&paranoid).unwrap();
    }

