        let payload = bootstrap
            .selected_payload_artifact
            .expect("panel binary payload selected");
        assert_eq!(payload.name, "hydra-panel-linux-aarch64");
        assert_eq!(
            payload.artifact_kind,
            PanelInstallerArtifactKind::PanelBinary
        );
        assert_eq!(payload.target_os, PanelInstallerTargetOs::Linux);
