    #[test]
    fn panel_installer_job_record_uses_one_time_hashed_executor_token() {
        let (job, executor_token, executor_token_hash) = build_panel_installer_job_record(
            PanelInstallerCreateJobRequest {
                ttl_seconds: Some(9_999),
                ..test_panel_installer_create_job_request()
            },
            1_000,
        )
        .expect("job record builds");

        assert!(job.job_id.starts_with("panel-installer-job-"));
        assert_eq!(job.status, PanelInstallerJobStatus::Pending);
        assert_eq!(
            job.expires_at_unix,
            1_000 + PANEL_INSTALLER_JOB_MAX_TTL_SECONDS
        );
        assert!(!executor_token.is_empty());
        assert_ne!(executor_token, executor_token_hash);
        assert!(constant_time_str_eq(
            &executor_token_hash,
            &hash_node_auth_token(&executor_token)
        ));
        let serialized = serde_json::to_string(&job).expect("job serializes");
        assert!(!serialized.contains(&executor_token));

        let mut runtime = InstallerRuntime::default();
        runtime.jobs.insert(
            job.job_id.clone(),
            InstallerJobRecord {
                view: job.clone(),
                executor_token_hash,
            },
        );
        let record = runtime
            .authenticate_job_mut(&job.job_id, &executor_token, 1_001)
            .expect("executor token authenticates");
        record.view.status = PanelInstallerJobStatus::Running;
        assert_eq!(record.view.status, PanelInstallerJobStatus::Running);
        assert!(
            runtime
                .authenticate_job_mut(&job.job_id, "wrong-token", 1_002)
                .is_err()
        );
    }

