    #[test]
    fn panel_installer_job_creation_has_specific_audit_event() {
        tokio::runtime::Runtime::new().unwrap().block_on(async {
            let state = AppState::new(isolated_app_config("panel-installer-job-audit"))
                .expect("panel state loads");
            let login = state
                .login("127.0.0.1", "admin", "password", None, None)
                .await
                .expect("admin login succeeds");

            let created = state
                .create_panel_installer_job(&login.token, test_panel_installer_create_job_request())
                .await
                .expect("installer job is created");

            let events = state
                .recent_audit_events(&login.token, AuditEventsQuery::default())
                .await
                .expect("audit query succeeds");

            assert!(events.iter().any(|event| {
                event.event_type == AuditEventType::PanelInstallerJobCreated
                    && event.detail.contains(&created.job.job_id)
            }));
            assert!(!events.iter().any(|event| {
                event.event_type == AuditEventType::CoreConfigSaved
                    && event.detail.contains("panel installer job")
            }));
            assert!(
                !events
                    .iter()
                    .any(|event| event.detail.contains(&created.executor_token))
            );
        });
    }

    #[test]
    fn panel_standalone_core_apply_does_not_require_remote_node() {
        tokio::runtime::Runtime::new().unwrap().block_on(async {
            let state = AppState::new(isolated_app_config("panel-standalone-core-apply"))
                .expect("panel state loads");
            let login = state
                .login("127.0.0.1", "admin", "password", None, None)
                .await
                .expect("admin login succeeds");

            let generated = state
                .generated_xray_config(&login.token)
                .await
                .expect("panel renders standalone Xray config");
            assert!(
                generated.raw_config_validation.valid,
                "standalone panel Xray config must pass internal validation"
            );

            let apply = state
                .core_apply_generated(&login.token, CoreApplyRequest { revision: None })
                .await
                .expect("standalone panel core apply succeeds without nodes");
            assert_eq!(apply.result, CoreApplyResult::Applied);
            assert!(
                apply.stages.iter().any(|stage| {
                    stage.stage == CoreApplyStage::ExternalValidated
                        && stage.status == CoreApplyStageStatus::Skipped
                }),
                "missing Xray binary should skip external validation, not require a remote node"
            );
            assert!(apply.stages.iter().any(|stage| {
                stage.stage == CoreApplyStage::RuntimeStateUpdated
                    && stage.status == CoreApplyStageStatus::Passed
            }));

            let runtime = state
                .core_runtime_state(&login.token)
                .await
                .expect("runtime state is available");
            assert!(matches!(runtime.status, CoreStatus::Running));
            assert_eq!(
                runtime.applied_revision.as_deref(),
                Some(apply.revision.as_str())
            );

            let history = state
                .core_apply_history(
                    &login.token,
                    CoreApplyHistoryQuery {
                        result: None,
                        limit: None,
                    },
                )
                .await
                .expect("apply history is available");
            assert!(history.iter().any(|record| {
                record.revision == apply.revision && record.result == CoreApplyResult::Applied
            }));

            let events = state
                .recent_audit_events(&login.token, AuditEventsQuery::default())
                .await
                .expect("audit query succeeds");
            assert!(
                events
                    .iter()
                    .any(|event| event.event_type == AuditEventType::CoreApplyRequested)
            );
            assert!(!events.iter().any(|event| {
                matches!(
                    event.event_type,
                    AuditEventType::NodeApplyRequested
                        | AuditEventType::NodeApplyRetryRequested
                        | AuditEventType::NodeSyncUpdated
                )
            }));
        });
    }

    #[test]
    fn core_apply_restart_and_xray_update_have_specific_audit_events() {
        tokio::runtime::Runtime::new().unwrap().block_on(async {
            let state =
                AppState::new(isolated_app_config("core-action-audit")).expect("panel state loads");
            let login = state
                .login("127.0.0.1", "admin", "password", None, None)
                .await
                .expect("admin login succeeds");

            let apply = state
                .core_apply_generated(&login.token, CoreApplyRequest { revision: None })
                .await
                .expect("generated core config apply is recorded");

            let update = state
                .xray_core_update(
                    &login.token,
                    XrayCoreUpdateRequest {
                        target_version: None,
                        allow_prerelease: false,
                        confirm_binary_swap: false,
                    },
                )
                .await
                .expect("xray update preflight is recorded");
            assert_eq!(update.status, XrayCoreUpdateStatus::Failed);

            state
                .restart_core(&login.token)
                .await
                .expect("core restart action is recorded");
            state
                .execute_core_action(&login.token, CoreAction::Start)
                .await
                .expect("core start action is recorded");
            state
                .execute_core_action(&login.token, CoreAction::Stop)
                .await
                .expect("core stop action is recorded");

            let events = state
                .recent_audit_events(&login.token, AuditEventsQuery::default())
                .await
                .expect("audit query succeeds");

            assert!(events.iter().any(|event| {
                event.event_type == AuditEventType::CoreApplyRequested
                    && event.detail.contains(&format!(
                        "core generated config apply requested: {}",
                        apply.revision
                    ))
            }));
            assert!(events.iter().any(|event| {
                event.event_type == AuditEventType::CoreXrayUpdateRequested
                    && event
                        .detail
                        .contains("xray core update requested: Xray binary path is not configured")
            }));
            assert!(events.iter().any(|event| {
                event.event_type == AuditEventType::CoreRestartRequested
                    && event.detail.contains("core action requested: Restart")
            }));
            assert!(events.iter().any(|event| {
                event.event_type == AuditEventType::CoreStartRequested
                    && event.detail.contains("core action requested: Start")
            }));
            assert!(events.iter().any(|event| {
                event.event_type == AuditEventType::CoreStopRequested
                    && event.detail.contains("core action requested: Stop")
            }));
            assert!(!events.iter().any(|event| {
                event.event_type == AuditEventType::CoreActionRequested
                    && (event.detail.contains("xray core update")
                        || event.detail.contains("generated config apply")
                        || event.detail.contains("Restart")
                        || event.detail.contains("Start")
                        || event.detail.contains("Stop"))
            }));
        });
    }

    #[test]
    fn security_preset_and_user_usage_have_specific_audit_events() {
        tokio::runtime::Runtime::new().unwrap().block_on(async {
            let state = AppState::new(isolated_app_config("preset-user-usage-audit"))
                .expect("panel state loads");
            let login = state
                .login("127.0.0.1", "admin", "password", None, None)
                .await
                .expect("admin login succeeds");

            state
                .apply_security_preset(
                    &login.token,
                    ApplySecurityPresetRequest {
                        preset: SecurityPreset::Strict,
                    },
                )
                .await
                .expect("security preset applies");
            state
                .create_user(
                    &login.token,
                    CreateUserRequest {
                        username: "usage-audit-user".to_string(),
                        template_id: None,
                        next_template_id: None,
                        status: Some(UserStatus::Active),
                        data_limit_bytes: None,
                        expire_at_unix: None,
                        note: None,
                        proxy_profile_ids: None,
                        excluded_inbound_tags: None,
                    },
                )
                .await
                .expect("user is created");
            state
                .report_user_usage(
                    &login.token,
                    "usage-audit-user",
                    ReportUserUsageRequest { bytes_delta: 42 },
                )
                .await
                .expect("usage report is recorded");

            let events = state
                .recent_audit_events(&login.token, AuditEventsQuery::default())
                .await
                .expect("audit query succeeds");

            assert!(
                events
                    .iter()
                    .any(|event| event.event_type == AuditEventType::SecurityPresetApplied)
            );
            assert!(
                events
                    .iter()
                    .any(|event| event.event_type == AuditEventType::UserUsageReported)
            );
            assert!(!events.iter().any(|event| {
                event.event_type == AuditEventType::SecuritySettingsUpdated
                    && event.detail.contains("security preset")
            }));
            assert!(!events.iter().any(|event| {
                event.event_type == AuditEventType::UserUpdated
                    && event.detail.contains("usage reported")
            }));
        });
    }

