    #[test]
    fn panel_process_memory_budget_creates_system_alert() {
        let config = AppConfig::default();
        let disk = DiskStats {
            total_bytes: 1_000,
            used_bytes: 100,
            free_bytes: 900,
        };
        let panel_rss = 450_u64 * 1024 * 1024;
        let alerts = build_alert_candidates(&config, &disk, 100, 1_000, Some(panel_rss));
        let alert = alerts
            .iter()
            .find(|alert| alert.kind == AlertKind::PanelMemoryBudget)
            .expect("panel memory budget alert exists");

        assert_eq!(alert.severity, AlertSeverity::Warning);
        assert_eq!(alert.observed_value, Some(panel_rss));
        assert!(alert.message.contains("512 MB budget"));
        assert!(
            !alerts
                .iter()
                .any(|alert| alert.kind == AlertKind::MemoryUsage)
        );
    }

