    #[test]
    fn panel_installer_session_wraps_plan_in_command_envelopes() {
        let session = build_panel_installer_session(PanelInstallerSessionRequest {
            executor_contract_version: Some(1),
            target_os: Some(PanelInstallerTargetOs::Linux),
            target_arch: Some(PanelInstallerTargetArch::X86_64),
            package_channel: Some(PanelInstallerPackageChannel::Stable),
            selected_artifact: None,
            plan: PanelInstallPlanRequest {
                access_mode: PanelAccessMode::IpSelfSignedTls,
                domain: None,
                public_ip: Some("203.0.113.10".to_string()),
                bind_host: None,
                bind_port: Some(2053),
                acme_email: None,
                firewall_allowlist: vec!["198.51.100.7/32".to_string()],
                trusted_proxy_cidrs: Vec::new(),
                confirm_public_http: false,
            },
        })
        .expect("installer session builds");

        assert!(session.compatible);
        assert_eq!(session.schema_version, 1);
        assert_eq!(session.target_os, PanelInstallerTargetOs::Linux);
        assert_eq!(session.target_arch, PanelInstallerTargetArch::X86_64);
        assert_eq!(
            session.package_channel,
            PanelInstallerPackageChannel::Stable
        );
        assert!(session.selected_artifact.is_none());
        assert!(session.session_id.starts_with("panel-install-"));
        assert!(session.command_envelopes.iter().any(
            |command| command.payload_kind == PanelInstallerExecutorPayloadKind::PreflightProbe
        ));
        assert!(
            session
                .command_envelopes
                .iter()
                .any(|command| command.payload_kind
                    == PanelInstallerExecutorPayloadKind::CertificateOperation
                    && command.requires_confirmation)
        );
        let service = session
            .command_envelopes
            .iter()
            .find(|command| {
                command.payload_kind == PanelInstallerExecutorPayloadKind::ServiceInstall
            })
            .expect("service envelope exists");
        assert!(service.operations.iter().any(|operation| {
            operation.kind == PanelInstallerExecutorOperationKind::WriteService
                && operation
                    .target_path
                    .as_deref()
                    .is_some_and(|path| path == "/etc/systemd/system/hydra-panel.service")
                && operation
                    .content_template
                    .as_deref()
                    .is_some_and(|content| content.contains("ProtectSystem=strict"))
        }));
        assert!(service.operations.iter().any(|operation| {
            operation.kind == PanelInstallerExecutorOperationKind::StartService
                && operation.program.as_deref() == Some("systemctl")
                && operation.args.contains(&"hydra-panel.service".to_string())
        }));

        let incompatible = build_panel_installer_session(PanelInstallerSessionRequest {
            executor_contract_version: None,
            target_os: Some(PanelInstallerTargetOs::Linux),
            target_arch: Some(PanelInstallerTargetArch::X86_64),
            package_channel: Some(PanelInstallerPackageChannel::Stable),
            selected_artifact: None,
            plan: PanelInstallPlanRequest {
                access_mode: PanelAccessMode::IpHttp,
                domain: None,
                public_ip: Some("203.0.113.10".to_string()),
                bind_host: None,
                bind_port: None,
                acme_email: None,
                firewall_allowlist: Vec::new(),
                trusted_proxy_cidrs: Vec::new(),
                confirm_public_http: true,
            },
        })
        .expect("incompatible session still returns inspectable contract");
        assert!(!incompatible.compatible);
    }

