    #[test]
    fn panel_installer_result_rejects_missing_operation_attestation() {
        let rejected = validate_panel_installer_result(PanelInstallerSessionResultRequest {
            session_id: "panel-install-test".to_string(),
            access_mode: PanelAccessMode::DomainTls,
            expected_command_ids: vec!["2:install_binary".to_string()],
            expected_operation_ids: vec![
                "2:install_binary/2:install_binary:download-artifact".to_string(),
                "2:install_binary/2:install_binary:verify-sha256".to_string(),
            ],
            command_results: vec![PanelInstallerCommandResult {
                command_id: "2:install_binary".to_string(),
                exit_code: 0,
                detail: None,
                attestation: PanelInstallerCommandAttestation {
                    operation_results: vec![PanelInstallerOperationResult {
                        operation_id: "2:install_binary/2:install_binary:download-artifact"
                            .to_string(),
                        exit_code: 0,
                        completed: true,
                        verified: Some(true),
                        target_path: None,
                        detail: None,
                    }],
                    binary_installed: Some(true),
                    binary_path: Some("/usr/local/bin/hydra-panel".to_string()),
                    artifact_source_url: Some(
                        "https://downloads.example.test/hydra/panel".to_string(),
                    ),
                    artifact_sha256_verified: Some(true),
                    ..PanelInstallerCommandAttestation::default()
                },
            }],
        });

        assert!(!rejected.accepted);
        assert!(
            rejected
                .issues
                .iter()
                .any(|issue| issue.contains("missing operation result"))
        );
        assert!(
            rejected
                .rejected_command_ids
                .contains(&"2:install_binary".to_string())
        );
    }

