    #[test]
    fn active_bans_drop_expired_items_and_expose_remaining_seconds() {
        let mut runtime = SecurityRuntime::new(&SecurityConfig::default());
        let now = now_unix();
        runtime.bans.insert(
            "192.0.2.1".to_string(),
            BanState {
                kind: BanKind::Temporary,
                source: BanSource::Automatic,
                reason: "login protection triggered".to_string(),
                created_at_unix: now.saturating_sub(5),
                blocked_until_unix: now + 120,
                ban_level: 2,
            },
        );
        runtime.bans.insert(
            "192.0.2.2".to_string(),
            BanState {
                kind: BanKind::Temporary,
                source: BanSource::Automatic,
                reason: "expired".to_string(),
                created_at_unix: now.saturating_sub(120),
                blocked_until_unix: now.saturating_sub(1),
                ban_level: 1,
            },
        );
        runtime.bans.insert(
            "192.0.2.3".to_string(),
            BanState {
                kind: BanKind::Permanent,
                source: BanSource::Manual,
                reason: "manual operator ban".to_string(),
                created_at_unix: now.saturating_sub(60),
                blocked_until_unix: u64::MAX,
                ban_level: 0,
            },
        );

        let bans = runtime.active_bans();

        assert_eq!(bans.len(), 2);
        assert!(bans.iter().all(|ban| ban.client_ip != "192.0.2.2"));
        let temporary = bans
            .iter()
            .find(|ban| ban.client_ip == "192.0.2.1")
            .expect("temporary ban remains active");
        assert!(
            temporary
                .remaining_seconds
                .is_some_and(|seconds| seconds <= 120)
        );
        assert_eq!(temporary.source, BanSource::Automatic);
        assert_eq!(temporary.ban_level, 2);
        assert!(temporary.reason.contains("login protection"));
        let permanent = bans
            .iter()
            .find(|ban| ban.client_ip == "192.0.2.3")
            .expect("permanent ban remains active");
        assert_eq!(permanent.remaining_seconds, None);
        assert_eq!(permanent.source, BanSource::Manual);
        assert_eq!(permanent.reason, "manual operator ban");
    }

    #[test]
    fn manual_ban_view_preserves_safe_operator_context() {
        let mut runtime = SecurityRuntime::new(&SecurityConfig::default());
        let view = runtime.create_ban(
            "198.51.100.10".to_string(),
            BanKind::Temporary,
            Some(600),
            normalize_manual_ban_reason(Some(" repeated scanner ")).unwrap(),
        );

        assert_eq!(view.client_ip, "198.51.100.10");
        assert_eq!(view.ban_kind, BanKind::Temporary);
        assert_eq!(view.source, BanSource::Manual);
        assert_eq!(view.reason, "repeated scanner");
        assert_eq!(view.ban_level, 0);
        assert!(view.remaining_seconds.is_some_and(|seconds| seconds <= 600));
    }

    #[test]
    fn manual_ban_reason_rejects_control_characters_and_long_text() {
        assert!(normalize_manual_ban_reason(Some("bad\nreason")).is_err());
        assert!(normalize_manual_ban_reason(Some(&"x".repeat(257))).is_err());
        assert_eq!(
            normalize_manual_ban_reason(None).unwrap(),
            "manual operator ban"
        );
    }

    #[test]
    fn node_health_center_flags_stale_drifted_and_failed_nodes() {
        let checked_at = 1_000;
        let mut healthy = test_node("node-a", "healthy");
        healthy.status = NodeStatus::Healthy;
        healthy.last_applied_revision = Some("rev-a".to_string());
        healthy.last_heartbeat_at_unix = Some(950);
        healthy.last_metrics_at_unix = Some(950);
        healthy.reported_memory_used_bytes = Some(128);
        healthy.reported_memory_total_bytes = Some(512);
        healthy.reported_disk_used_bytes = Some(10);
        healthy.reported_disk_total_bytes = Some(100);
        healthy.sync_status = effective_node_sync_status(&healthy, "rev-a");

        let mut broken = test_node("node-b", "broken");
        broken.status = NodeStatus::Offline;
        broken.last_applied_revision = Some("old-rev".to_string());
        broken.last_heartbeat_at_unix = Some(700);
        broken.last_metrics_at_unix = None;
        broken.reported_memory_used_bytes = Some(950);
        broken.reported_memory_total_bytes = Some(1_000);
        broken.provisioning_status = NodeProvisioningStatus::Failed;
        broken.sync_status = effective_node_sync_status(&broken, "rev-a");

        let sync_history = vec![NodeSyncHistoryEntry {
            node_id: "node-b".to_string(),
            sync_status: NodeSyncStatus::Drifted,
            applied_revision: Some("old-rev".to_string()),
            expected_revision: "rev-a".to_string(),
            detail: Some("node render failed".to_string()),
            apply_lifecycle_state: Some(NodeApplyLifecycleState::Failed),
            last_good_revision: Some("old-rev".to_string()),
            rollback_available: true,
            apply_stages: vec![NodeApplyStageView {
                stage: "render_xray".to_string(),
                status: NodeApplyStageStatus::Failed,
                detail: "invalid outbound".to_string(),
            }],
            apply_issues: vec![XrayRenderIssueView {
                route_id: "route-a".to_string(),
                scope: "outbound".to_string(),
                severity: "error".to_string(),
                reason: "missing peer material".to_string(),
            }],
            retry_state: Some(NodeAgentRetryStateView {
                consecutive_failures: 3,
                retry_backoff_seconds: Some(120),
                next_retry_not_before_unix: Some(checked_at + 60),
                last_transport_error: Some("panel timeout".to_string()),
            }),
            runtime_components: Vec::new(),
            external_xray_validation: None,
            runtime_alerts: Vec::new(),
            created_at_unix: checked_at - 10,
        }];

        let apply_results = vec![
            NodeApplyResultEntry {
                node_id: "node-b".to_string(),
                attempt_id: "attempt-ok".to_string(),
                target_revision: "old-rev".to_string(),
                status: NodeApplyResultStatus::Applied,
                started_at_unix: Some(checked_at - 80),
                finished_at_unix: Some(checked_at - 70),
                applied_revision: Some("old-rev".to_string()),
                last_good_revision: Some("old-rev".to_string()),
                rollback_available: false,
                safe_to_restart: true,
                detail: Some("previous apply succeeded".to_string()),
                apply_stages: Vec::new(),
                apply_issues: Vec::new(),
                external_xray_validation: None,
                recorded_at_unix: checked_at - 70,
            },
            NodeApplyResultEntry {
                node_id: "node-b".to_string(),
                attempt_id: "attempt-failed".to_string(),
                target_revision: "rev-a".to_string(),
                status: NodeApplyResultStatus::Failed,
                started_at_unix: Some(checked_at - 20),
                finished_at_unix: Some(checked_at - 10),
                applied_revision: Some("old-rev".to_string()),
                last_good_revision: Some("old-rev".to_string()),
                rollback_available: true,
                safe_to_restart: false,
                detail: Some("render failed".to_string()),
                apply_stages: Vec::new(),
                apply_issues: Vec::new(),
                external_xray_validation: None,
                recorded_at_unix: checked_at - 10,
            },
        ];

        let view = build_node_health_center(
            vec![healthy, broken],
            "rev-a",
            checked_at,
            &sync_history,
            &apply_results,
            &[],
        );

        assert_eq!(view.summary.total, 2);
        assert_eq!(view.summary.healthy, 1);
        assert_eq!(view.summary.offline, 1);
        assert_eq!(view.summary.drifted, 1);
        assert_eq!(view.summary.stale_heartbeat, 1);
        assert_eq!(view.summary.stale_metrics, 1);
        assert_eq!(view.summary.provisioning_failed, 1);
        assert_eq!(view.summary.provisioning_stale, 0);
        assert_eq!(view.summary.reported_apply_failed, 1);
        assert_eq!(view.summary.retry_backoff_active, 1);
        assert_eq!(view.summary.apply_rollback_available, 1);
        assert_eq!(view.summary.attention_required, 1);

        let broken_item = view
            .nodes
            .iter()
            .find(|node| node.node_id == "node-b")
            .expect("broken node item exists");
        assert!(broken_item.health_flags.contains(&NodeHealthFlag::Offline));
        assert!(
            broken_item
                .health_flags
                .contains(&NodeHealthFlag::StaleHeartbeat)
        );
        assert!(
            broken_item
                .health_flags
                .contains(&NodeHealthFlag::ConfigDrift)
        );
        assert!(
            broken_item
                .health_flags
                .contains(&NodeHealthFlag::ProvisioningFailed)
        );
        assert!(
            broken_item
                .health_flags
                .contains(&NodeHealthFlag::MemoryHigh)
        );
        assert!(
            broken_item
                .health_flags
                .contains(&NodeHealthFlag::ReportedApplyFailed)
        );
        assert!(
            broken_item
                .health_flags
                .contains(&NodeHealthFlag::RetryBackoffActive)
        );
        assert!(broken_item.reported_apply_failed);
        assert!(broken_item.retry_backoff_active);
        assert_eq!(
            broken_item
                .latest_retry_state
                .as_ref()
                .map(|state| state.consecutive_failures),
            Some(3)
        );
        assert_eq!(broken_item.reported_apply_failed_stage_count, 1);
        assert_eq!(broken_item.reported_apply_error_issue_count, 1);
        assert_eq!(
            broken_item.latest_apply_status,
            Some(NodeApplyResultStatus::Failed)
        );
        assert_eq!(
            broken_item.latest_apply_target_revision.as_deref(),
            Some("rev-a")
        );
        assert_eq!(
            broken_item.latest_successful_apply_revision.as_deref(),
            Some("old-rev")
        );
        assert_eq!(
            broken_item.latest_failed_apply_revision.as_deref(),
            Some("rev-a")
        );
        assert!(broken_item.rollback_available);
        assert!(
            broken_item
                .reported_memory_percent
                .is_some_and(|value| value >= 95.0)
        );
    }

    #[test]
    fn node_health_center_surfaces_node_reported_runtime_alerts() {
        let checked_at = 1_000;
        let mut node = test_node("node-a", "node-a");
        node.status = NodeStatus::Healthy;
        node.last_applied_revision = Some("rev-a".to_string());
        node.last_heartbeat_at_unix = Some(990);
        node.last_metrics_at_unix = Some(990);
        node.sync_status = effective_node_sync_status(&node, "rev-a");

        let sync_history = vec![NodeSyncHistoryEntry {
            node_id: "node-a".to_string(),
            sync_status: NodeSyncStatus::Synced,
            applied_revision: Some("rev-a".to_string()),
            expected_revision: "rev-a".to_string(),
            detail: Some("node runtime alerts".to_string()),
            apply_lifecycle_state: Some(NodeApplyLifecycleState::Applied),
            last_good_revision: Some("rev-a".to_string()),
            rollback_available: false,
            apply_stages: Vec::new(),
            apply_issues: Vec::new(),
            retry_state: None,
            runtime_components: Vec::new(),
            external_xray_validation: None,
            runtime_alerts: vec![NodeRuntimeAlertView {
                alert_id: "xray_runtime_failed".to_string(),
                kind: NodeRuntimeAlertKind::XrayRuntimeFailed,
                severity: NodeRuntimeAlertSeverity::Critical,
                source: NodeRuntimeAlertSource::Xray,
                active: true,
                detail: "xray process exited".to_string(),
                observed_at_unix: checked_at - 5,
            }],
            created_at_unix: checked_at - 5,
        }];

        let view =
            build_node_health_center(vec![node], "rev-a", checked_at, &sync_history, &[], &[]);

        assert_eq!(view.summary.runtime_alerts_active, 1);
        assert_eq!(view.summary.runtime_alerts_critical, 1);
        assert!(
            view.recommendations
                .iter()
                .any(|item| item.contains("active runtime alerts"))
        );

        let item = view.nodes.first().expect("node health item exists");
        assert_eq!(item.runtime_alert_count, 1);
        assert_eq!(item.runtime_critical_alert_count, 1);
        assert!(
            item.health_flags
                .contains(&NodeHealthFlag::RuntimeAlertsActive)
        );
        assert_eq!(item.latest_runtime_alerts.len(), 1);

        let alerts = build_node_alert_candidates(&view.summary);
        let alert = alerts
            .iter()
            .find(|alert| alert.kind == AlertKind::NodeRuntimeAlert)
            .expect("runtime alert candidate exists");
        assert_eq!(alert.severity, AlertSeverity::Critical);
    }

    #[test]
    fn node_health_center_distinguishes_stale_provisioning_from_running_work() {
        let checked_at = NODE_PROVISIONING_TASK_STALE_AFTER_SECONDS + 100;
        let mut node = test_node("node-a", "node-a");
        node.provisioning_status = NodeProvisioningStatus::Running;
        let mut task = sample_provisioning_task(NodeProvisioningTaskStatus::Running);
        task.updated_at_unix = 1;

        let view = build_node_health_center(vec![node], "rev-a", checked_at, &[], &[], &[task]);

        assert_eq!(view.summary.provisioning_running, 1);
        assert_eq!(view.summary.provisioning_stale, 1);
        let item = view.nodes.first().expect("node item exists");
        assert!(
            item.health_flags
                .contains(&NodeHealthFlag::ProvisioningStale)
        );
        assert!(
            !item
                .health_flags
                .contains(&NodeHealthFlag::ProvisioningRunning)
        );
    }

    #[test]
    fn node_health_summary_activates_and_resolves_system_alerts() {
        let unique = format!("hydra-panel-alerts-{}", now_unix());
        let base = std::env::temp_dir().join(unique);
        let mut config = AppConfig::default();
        config.monitoring.alert_history_path = base
            .with_extension("alerts.ndjson")
            .to_string_lossy()
            .to_string();
        config.operational_log_path = base
            .with_extension("logs.ndjson")
            .to_string_lossy()
            .to_string();

        let mut runtime = SystemRuntime {
            config: "{}".to_string(),
            saved_at_unix: None,
            valid_json: true,
            status: CoreStatus::Running,
            applied_revision: None,
            last_xray_update: None,
            logs: Vec::new(),
            apply_history: Vec::new(),
            active_alerts: HashMap::new(),
            alert_events: Vec::new(),
            last_action: None,
        };
        let disk = DiskStats {
            total_bytes: 1_000,
            used_bytes: 100,
            free_bytes: 900,
        };
        let summary = NodeHealthCenterSummary {
            total: 3,
            enabled: 3,
            offline: 1,
            stale_heartbeat: 1,
            drifted: 1,
            provisioning_stale: 1,
            provisioning_failed: 1,
            reported_apply_failed: 1,
            ..NodeHealthCenterSummary::default()
        };

        let active = runtime.evaluate_alerts(&config, &disk, 100, 1_000, None, Some(&summary));

        assert_eq!(active.len(), 6);
        assert!(
            active
                .iter()
                .any(|alert| alert.kind == AlertKind::NodeOffline)
        );
        assert!(
            active
                .iter()
                .any(|alert| alert.kind == AlertKind::NodeStaleHeartbeat)
        );
        assert!(
            active
                .iter()
                .any(|alert| alert.kind == AlertKind::NodeConfigDrift)
        );
        assert!(
            active
                .iter()
                .any(|alert| alert.kind == AlertKind::NodeProvisioningStale)
        );
        assert!(
            active
                .iter()
                .any(|alert| alert.kind == AlertKind::NodeProvisioningFailed)
        );
        assert!(
            active
                .iter()
                .any(|alert| alert.kind == AlertKind::NodeReportedApplyFailed)
        );
        assert_eq!(
            runtime
                .alert_events
                .iter()
                .filter(|event| event.status == AlertEventStatus::Activated)
                .count(),
            6
        );

        let resolved_summary = NodeHealthCenterSummary {
            total: 3,
            enabled: 3,
            healthy: 3,
            synced: 3,
            ..NodeHealthCenterSummary::default()
        };
        let active =
            runtime.evaluate_alerts(&config, &disk, 100, 1_000, None, Some(&resolved_summary));

        assert!(active.is_empty());
        assert_eq!(
            runtime
                .alert_events
                .iter()
                .filter(|event| event.status == AlertEventStatus::Resolved)
                .count(),
            6
        );

        let _ = std::fs::remove_file(&config.monitoring.alert_history_path);
        let _ = std::fs::remove_file(&config.operational_log_path);
    }

