        assert_eq!(history[0].apply_issues.len(), 1);
        assert_eq!(history[0].runtime_components.len(), 1);
        assert_eq!(history[0].runtime_components[0].component, "xray");
        assert_eq!(history[0].runtime_alerts.len(), 1);
