    #[test]
    fn node_apply_status_surfaces_external_xray_validation_state() {
        let mut node = test_node("node-a", "node-a");
        node.status = NodeStatus::Healthy;
        node.last_heartbeat_at_unix = Some(990);
        node.last_applied_revision = Some("rev-a".to_string());
        node.sync_status = NodeSyncStatus::Synced;
        let runtime_components = node_agent_runtime_component_requirements_for_inbounds(&[]);

        let missing_view = build_node_apply_status_view(
            node.clone(),
            "rev-a".to_string(),
            Vec::new(),
            Vec::new(),
            None,
            None,
            runtime_components.clone(),
            1_000,
        );

        assert!(
            missing_view
                .stages
                .iter()
                .any(|stage| stage.stage == "xray_external_validation"
                    && stage.status == NodeApplyStageStatus::Unknown)
        );
        assert!(
            missing_view
                .blocking_issues
                .iter()
                .any(|issue| issue.contains("external Xray validation has not been reported"))
        );
        assert!(missing_view.timeline.iter().any(|item| item.phase
            == NodeApplyTimelineStage::ValidateXrayConfig
            && item.status == NodeApplyTimelineStatus::Unknown
            && item.source == "stage:xray_external_validation"));

        let passed_view = build_node_apply_status_view(
            node,
            "rev-a".to_string(),
            Vec::new(),
            vec![NodeApplyResultEntry {
                node_id: "node-a".to_string(),
                attempt_id: "attempt-a".to_string(),
                target_revision: "rev-a".to_string(),
                status: NodeApplyResultStatus::Applied,
                started_at_unix: Some(10),
                finished_at_unix: Some(20),
                applied_revision: Some("rev-a".to_string()),
                last_good_revision: Some("rev-a".to_string()),
                rollback_available: false,
                safe_to_restart: true,
                detail: Some("applied".to_string()),
                apply_stages: Vec::new(),
                apply_issues: Vec::new(),
                external_xray_validation: Some(XrayExternalValidationReport {
                    status: XrayExternalValidationStatus::Passed,
                    checked_at_unix: 20,
                    binary_path: Some("/usr/local/bin/xray".to_string()),
                    internal_validation_valid: true,
                    exit_code: Some(0),
                    stdout: String::new(),
                    stderr: String::new(),
                    detail: "xray run -test passed".to_string(),
                    config_retained: false,
                }),
                recorded_at_unix: 21,
            }],
            None,
            None,
            runtime_components,
            1_000,
        );

        assert!(
            passed_view
                .stages
                .iter()
                .any(|stage| stage.stage == "xray_external_validation"
                    && stage.status == NodeApplyStageStatus::Ok
                    && stage.detail.contains("passed"))
        );
        assert!(
            !passed_view
                .blocking_issues
                .iter()
                .any(|issue| issue.contains("external Xray validation"))
        );
    }

