    #[test]
    fn duplicate_node_apply_result_is_idempotent() {
        let unique = format!("hydra-node-apply-result-idempotent-{}", random::<u64>());
        let base = std::env::temp_dir().join(unique);
        fs::create_dir_all(&base).expect("test dir is created");
        let config = AppConfig {
            node_sync_history_path: base.join("sync.ndjson").to_string_lossy().to_string(),
            node_apply_results_path: base.join("apply.ndjson").to_string_lossy().to_string(),
            ..AppConfig::default()
        };
        let node = test_node("node-a", "node-a");
        let mut runtime = node_runtime_with_nodes(vec![node]);
        let request = NodeApplyResultRequest {
            attempt_id: "attempt-a".to_string(),
            target_revision: "rev-a".to_string(),
            status: NodeApplyResultStatus::Applied,
            started_at_unix: Some(10),
            finished_at_unix: Some(20),
            applied_revision: Some("rev-a".to_string()),
            last_good_revision: Some("rev-a".to_string()),
            rollback_available: false,
            safe_to_restart: true,
            detail: Some("applied".to_string()),
            apply_stages: Vec::new(),
            apply_issues: Vec::new(),
            runtime_components: Vec::new(),
            external_xray_validation: None,
        };

        let first = runtime
            .record_apply_result(&config, "node-a", request.clone(), "rev-a")
            .expect("first apply result is recorded");
        let second = runtime
            .record_apply_result(&config, "node-a", request, "rev-a")
            .expect("duplicate apply result is accepted idempotently");

        assert_eq!(first.recorded_at_unix, second.recorded_at_unix);
        assert_eq!(runtime.apply_results_for("node-a", 10).len(), 1);
        assert_eq!(runtime.sync_history_for("node-a", 10).len(), 1);

        let _ = fs::remove_dir_all(&base);
    }

    #[test]
    fn retry_and_rollback_requests_create_pending_lifecycle_entries() {
        let unique = format!("hydra-node-apply-retry-rollback-{}", random::<u64>());
        let base = std::env::temp_dir().join(unique);
        fs::create_dir_all(&base).expect("test dir is created");
        let config = AppConfig {
            node_sync_history_path: base.join("sync.ndjson").to_string_lossy().to_string(),
            node_apply_results_path: base.join("apply.ndjson").to_string_lossy().to_string(),
            ..AppConfig::default()
        };
        let mut node = test_node("node-a", "node-a");
        node.last_applied_revision = Some("old-rev".to_string());
        let mut runtime = node_runtime_with_nodes(vec![node]);

        runtime
            .request_apply_with_detail(
                &config,
                "node-a",
                "rev-a",
                "apply retry requested: test".to_string(),
            )
            .expect("retry apply request is recorded");
        let retry_history = runtime.sync_history_for("node-a", 10);
        assert_eq!(retry_history.len(), 1);
        assert_eq!(retry_history[0].sync_status, NodeSyncStatus::Pending);
        assert_eq!(
            retry_history[0].apply_lifecycle_state,
            Some(NodeApplyLifecycleState::Pending)
        );

        runtime
            .request_rollback(
                &config,
                "node-a",
                "old-rev",
                "rollback requested: test".to_string(),
            )
            .expect("rollback request is recorded");
        let history = runtime.sync_history_for("node-a", 10);
        assert_eq!(history.len(), 2);
        let rollback = history.last().expect("rollback entry exists");
        assert_eq!(rollback.sync_status, NodeSyncStatus::Pending);
        assert_eq!(rollback.last_good_revision.as_deref(), Some("old-rev"));
        assert!(rollback.rollback_available);
        assert!(rollback.apply_stages.iter().any(|stage| {
            stage.stage == "rollback" && stage.status == NodeApplyStageStatus::Warning
        }));

        let _ = fs::remove_dir_all(&base);
    }

