    #[test]
    fn provisioning_heartbeat_refreshes_active_task_without_fake_step() {
        let unique = format!("hydra-provisioning-touch-{}", random::<u64>());
        let base = std::env::temp_dir().join(unique);
        fs::create_dir_all(&base).expect("test dir is created");
        let config = AppConfig {
            node_provisioning_events_path: base.join("events.ndjson").to_string_lossy().to_string(),
            ..AppConfig::default()
        };
        let mut runtime = ProvisioningRuntime {
            tasks: HashMap::new(),
            events: Vec::new(),
            executors: HashMap::new(),
            executor_submissions: Vec::new(),
        };
        let mut task = sample_provisioning_task(NodeProvisioningTaskStatus::Running);
        task.updated_at_unix = 1;
        runtime.tasks.insert(task.task_id.clone(), task);

        let touched = runtime
            .touch_task(
                &config,
                "node-a",
                "task-a",
                TouchNodeProvisioningTaskRequest {
                    detail: Some("still installing packages".to_string()),
                },
            )
            .expect("active task is touched");

        assert!(touched.updated_at_unix > 1);
        assert!(touched.steps.is_empty());
        assert_eq!(runtime.events.len(), 1);
        assert_eq!(runtime.events[0].kind, "heartbeat");
        assert_eq!(runtime.events[0].detail, "still installing packages");

        let _ = fs::remove_dir_all(&base);
    }

