    #[test]
    fn executor_session_binds_probe_scripts_steps_and_finish_conditions() {
        let task = NodeProvisioningTask {
            request_context: NodeProvisioningRequestContext {
                transport: NodeProvisioningTransportKind::Ssh,
                target_host: Some("203.0.113.10".to_string()),
                ssh_port: Some(22),
                ssh_username: Some("root".to_string()),
                uses_password_auth: false,
                uses_private_key_auth: true,
                sidecar_install: NodeProvisioningSidecarInstallSelection::default(),
            },
            planned_steps: provisioning_step_templates(NodeProvisioningTransportKind::Ssh),
            ..sample_provisioning_task(NodeProvisioningTaskStatus::Running)
        };

        let session = build_node_provisioning_executor_session(task, &[62050, 62051], Some(1));

        assert_eq!(session.schema_version, 1);
        assert_eq!(session.minimum_executor_version, "0.1.0");
        assert_eq!(
            session.compatibility.status,
            NodeProvisioningExecutorCompatibilityStatus::Compatible
        );
        assert!(session.compatibility.compatible);
        assert!(
            session
                .capabilities
                .contains(&NodeProvisioningExecutorCapability::LoopContract)
        );
        assert_eq!(session.heartbeat_interval_seconds, 60);
        assert_eq!(session.stale_after_seconds, 1_800);
        assert!(session.preflight_probe.is_some());
        assert!(session.install_plan.is_some());
        assert!(session.material_handoff.is_some());
        assert_eq!(session.steps.len(), 11);
        assert!(session.steps.iter().any(|step| {
            step.step == NodeProvisioningStepKind::XrayInstall && step.requires_heartbeat
        }));
        assert!(session.steps.iter().any(|step| {
            step.step == NodeProvisioningStepKind::SidecarRuntimeInstall
                && step.requires_heartbeat
                && step.expected_report.mode == NodeProvisioningExecutorReportMode::CommandReport
        }));
        assert!(session.steps.iter().any(|step| {
            step.step == NodeProvisioningStepKind::Preflight
                && step.executor_action == "run_preflight_probe"
                && step.expected_report.mode == NodeProvisioningExecutorReportMode::StructuredStep
        }));
        assert!(session.steps.iter().any(|step| {
            step.step == NodeProvisioningStepKind::XrayInstall
                && step.expected_report.mode == NodeProvisioningExecutorReportMode::CommandReport
        }));
        assert!(session.workflow.nodes.iter().any(|node| {
            node.id == "handoff_token_issued"
                && node.depends_on == vec!["step_node_install".to_string()]
        }));
        assert!(session.workflow.nodes.iter().any(|node| {
            node.id == "step_service_install"
                && node.depends_on == vec!["handoff_node_env_written".to_string()]
        }));
        assert!(session.workflow.nodes.iter().any(|node| {
            node.id == "step_agent_reachability"
                && node.depends_on == vec!["handoff_agent_returned".to_string()]
        }));
        assert!(session.workflow.transitions.iter().any(|transition| {
            transition.from == "handoff_service_started"
                && transition.to == "handoff_agent_returned"
                && transition.condition == "dependency_succeeded"
        }));
        assert!(session.workflow.validation.valid);
        assert!(session.workflow.validation.issues.is_empty());
        assert_eq!(session.loop_contract.phases.len(), 6);
        assert_eq!(
            session.loop_contract.phases[0].phase,
            NodeProvisioningExecutorLoopPhase::ReadNextCommand
        );
        assert!(
            session
                .loop_contract
                .recovery_rules
                .iter()
                .any(|rule| rule.contains("panel_observed command"))
        );
        assert_eq!(session.finish_conditions.len(), 2);
        assert!(!session.completion.can_finish_completed);
        assert!(
            session
                .completion
                .missing_executor_steps
                .contains(&NodeProvisioningStepKind::Preflight)
        );
        let serialized = serde_json::to_string(&session).expect("session serializes");
        assert!(!serialized.contains("PRIVATE KEY"));
        assert!(!serialized.contains("ssh_password"));
    }

