    #[test]
    fn executor_handshake_reports_identity_policy_and_missing_capabilities() {
        let compatible =
            build_node_provisioning_executor_handshake(NodeProvisioningExecutorHandshakeRequest {
                executor_id: "executor-a".to_string(),
                executor_contract_version: Some(1),
                executor_version: Some("0.1.0".to_string()),
                capabilities: node_provisioning_executor_capabilities(),
            });
        assert_eq!(compatible.schema_version, 1);
        assert_eq!(compatible.panel.product, "hydra-panel");
        assert!(compatible.compatibility.compatible);
        assert!(compatible.missing_required_capabilities.is_empty());
        assert!(
            compatible
                .security_expectations
                .panel_observed_transitions_cannot_be_self_reported
        );

        let missing =
            build_node_provisioning_executor_handshake(NodeProvisioningExecutorHandshakeRequest {
                executor_id: "executor-b".to_string(),
                executor_contract_version: Some(1),
                executor_version: Some("0.1.0".to_string()),
                capabilities: vec![NodeProvisioningExecutorCapability::WorkflowGraph],
            });
        assert_eq!(
            missing.compatibility.status,
            NodeProvisioningExecutorCompatibilityStatus::MissingRequiredCapabilities
        );
        assert!(!missing.compatibility.compatible);
        assert!(!missing.missing_required_capabilities.is_empty());
    }

    #[test]
    fn material_handoff_keeps_secret_delivery_explicit_and_agent_scoped() {
        let handoff = build_node_provisioning_material_handoff_plan();

        assert_eq!(handoff.directories[0].path, "/etc/hydra-node");
        assert_eq!(handoff.directories[0].mode, "0700");
        assert_eq!(handoff.files[0].path, "/etc/hydra-node/node.env");
        assert_eq!(handoff.files[0].mode, "0600");
        assert_eq!(
            handoff.files[0].sensitivity,
            NodeProvisioningMaterialSensitivity::HighSensitivity
        );
        assert!(handoff.fetches.iter().any(|fetch| {
            fetch.name == "node_auth_token"
                && fetch.plaintext_returned_once
                && fetch.endpoint.contains("/auth/rotate")
        }));
        assert!(handoff.fetches.iter().any(|fetch| {
            fetch.name == "route_credentials"
                && !fetch.plaintext_returned_once
                && fetch.authentication.contains("node token")
        }));
        assert!(handoff.env_schema.iter().any(|field| {
            field.name == "HYDRA_NODE_AUTH_TOKEN"
                && field.required
                && field.sensitivity == NodeProvisioningMaterialSensitivity::HighSensitivity
        }));
        assert!(
            handoff
                .write_sequence
                .iter()
                .any(|step| step.contains("atomically"))
        );
        assert_eq!(
            handoff.expected_reports,
            vec![
                NodeProvisioningHandoffKind::TokenIssued,
                NodeProvisioningHandoffKind::NodeEnvWritten,
                NodeProvisioningHandoffKind::ServiceStarted,
                NodeProvisioningHandoffKind::AgentReturned,
            ]
        );
        let attestation_script = handoff
            .node_env_attestation_script
            .as_deref()
            .expect("attestation script exists");
        assert!(attestation_script.contains("stat -c '%a'"));
        assert!(attestation_script.contains("sed -n 's/=.*//p'"));
        assert!(!attestation_script.contains("HYDRA_NODE_AUTH_TOKEN="));
        let service_attestation_script = handoff
            .service_started_attestation_script
            .as_deref()
            .expect("service attestation script exists");
        assert!(service_attestation_script.contains("hydra-node.service"));
        assert!(service_attestation_script.contains("ActiveState"));
        assert!(service_attestation_script.contains("ExecStart"));
        assert!(!service_attestation_script.contains("cat /etc/systemd/system"));
        let serialized = serde_json::to_string(&handoff).expect("handoff serializes");
        assert!(!serialized.contains("actual-token"));
        assert!(!serialized.contains("PRIVATE KEY"));
    }

    #[test]
    fn command_report_redacts_output_and_classifies_failure() {
        let report =
            normalize_node_provisioning_command_report(ReportNodeProvisioningCommandRequest {
                step: NodeProvisioningStepKind::SudoCheck,
                exit_code: 1,
                stdout: Some("TOKEN=secret-value".to_string()),
                stderr: Some("sudo: user is not in the sudoers file".to_string()),
            });

        assert_eq!(report.status, NodeProvisioningStepStatus::Failed);
        assert_eq!(
            report.failure_category,
            Some(NodeProvisioningFailureCategory::Authorization)
        );
        assert_eq!(report.stdout_summary.as_deref(), Some("TOKEN=[REDACTED]"));
        assert_eq!(
            report.stderr_summary.as_deref(),
            Some("sudo: user is not in the sudoers file")
        );
    }

    #[test]
    fn command_report_output_is_bounded_and_private_keys_are_redacted() {
        let report =
            normalize_node_provisioning_command_report(ReportNodeProvisioningCommandRequest {
                step: NodeProvisioningStepKind::NodeInstall,
                exit_code: 0,
                stdout: Some(format!(
                    "-----BEGIN OPENSSH PRIVATE KEY-----\n{}\n-----END OPENSSH PRIVATE KEY-----",
                    "x".repeat(NODE_PROVISIONING_COMMAND_OUTPUT_LIMIT * 2)
                )),
                stderr: None,
            });

        let stdout = report.stdout_summary.expect("stdout summary exists");
        assert!(stdout.contains("[REDACTED PRIVATE KEY]"));
        assert!(!stdout.contains("BEGIN OPENSSH PRIVATE KEY"));
        assert!(stdout.chars().count() <= NODE_PROVISIONING_COMMAND_OUTPUT_LIMIT + 3);
    }

    #[test]
    fn provisioning_step_detail_is_redacted_and_bounded() {
        let unique = format!("hydra-step-redaction-{}", generate_resource_id());
        let base = std::env::temp_dir().join(unique);
        let config = AppConfig {
            node_provisioning_events_path: base.join("events.ndjson").to_string_lossy().to_string(),
            ..AppConfig::default()
        };
        let mut runtime = ProvisioningRuntime {
            tasks: HashMap::from([(
                "task-a".to_string(),
                sample_provisioning_task(NodeProvisioningTaskStatus::Running),
            )]),
            events: Vec::new(),
            executors: HashMap::new(),
            executor_submissions: Vec::new(),
        };

        let task = runtime
            .push_step(
                &config,
                "node-a",
                "task-a",
                UpdateNodeProvisioningStepRequest {
                    step: NodeProvisioningStepKind::BootstrapVerify,
                    status: NodeProvisioningStepStatus::Failed,
                    detail: format!(
                        "TOKEN=secret-value\n-----BEGIN OPENSSH PRIVATE KEY-----\n{}\n-----END OPENSSH PRIVATE KEY-----",
                        "x".repeat(NODE_PROVISIONING_COMMAND_OUTPUT_LIMIT * 2)
                    ),
                    failure_category: Some(NodeProvisioningFailureCategory::Runtime),
                    remote_prerequisites: Vec::new(),
                    ssh_preflight_output: None,
                    from_command_report: false,
                },
                &[],
            )
            .expect("failed orchestration step is recorded");

        let step_detail = &task.steps[0].detail;
        let failure_detail = &task.failures[0].detail;
        let event_detail = &runtime.events[0].detail;
        for detail in [step_detail, failure_detail, event_detail] {
            assert!(detail.contains("TOKEN=[REDACTED]"));
            assert!(detail.contains("[REDACTED PRIVATE KEY]"));
            assert!(!detail.contains("secret-value"));
            assert!(!detail.contains("BEGIN OPENSSH PRIVATE KEY"));
            assert!(detail.chars().count() <= NODE_PROVISIONING_COMMAND_OUTPUT_LIMIT + 3);
        }

        let _ = fs::remove_dir_all(&base);
    }

    #[test]
    fn handoff_reports_keep_latest_state_and_redact_secret_detail() {
        let unique = format!("hydra-handoff-reports-{}", generate_resource_id());
        let base = std::env::temp_dir().join(unique);
        let config = AppConfig {
            node_provisioning_events_path: base.join("events.ndjson").to_string_lossy().to_string(),
            ..AppConfig::default()
        };
        let mut runtime = ProvisioningRuntime {
            tasks: HashMap::from([(
                "task-a".to_string(),
                sample_provisioning_task(NodeProvisioningTaskStatus::Running),
            )]),
            events: Vec::new(),
            executors: HashMap::new(),
            executor_submissions: Vec::new(),
        };

        runtime
            .record_handoff(
                &config,
                "node-a",
                "task-a",
                ReportNodeProvisioningHandoffRequest {
                    kind: NodeProvisioningHandoffKind::TokenIssued,
                    status: NodeProvisioningHandoffStatus::Succeeded,
                    detail: format!(
                        "TOKEN=secret-value\n-----BEGIN OPENSSH PRIVATE KEY-----\n{}\n-----END OPENSSH PRIVATE KEY-----",
                        "x".repeat(NODE_PROVISIONING_COMMAND_OUTPUT_LIMIT * 2)
                    ),
                    node_env_attestation: None,
                    service_started_attestation: None,
                },
            )
            .expect("first handoff succeeds");
        let task = runtime
            .record_handoff(
                &config,
                "node-a",
                "task-a",
                ReportNodeProvisioningHandoffRequest {
                    kind: NodeProvisioningHandoffKind::TokenIssued,
                    status: NodeProvisioningHandoffStatus::Succeeded,
                    detail: "fresh token issued".to_string(),
                    node_env_attestation: None,
                    service_started_attestation: None,
                },
            )
            .expect("latest handoff replaces previous state");

        assert_eq!(task.handoff.len(), 1);
        assert_eq!(task.handoff[0].detail, "fresh token issued");
        assert_eq!(runtime.events.len(), 2);
        assert!(runtime.events[0].detail.contains("TOKEN=[REDACTED]"));
        assert!(runtime.events[0].detail.contains("[REDACTED PRIVATE KEY]"));
        assert!(!runtime.events[0].detail.contains("secret-value"));
        assert!(
            !runtime.events[0]
                .detail
                .contains("BEGIN OPENSSH PRIVATE KEY")
        );
        assert!(
            runtime.events[0].detail.chars().count()
                <= "succeeded: ".chars().count() + NODE_PROVISIONING_COMMAND_OUTPUT_LIMIT + 3
        );
        assert_eq!(runtime.events[1].kind, "handoff_token_issued");

        let _ = fs::remove_dir_all(&base);
    }

