    #[test]
    fn node_env_success_requires_secret_free_attestation_contract() {
        let attestation = NodeProvisioningNodeEnvAttestation {
            path: "/etc/hydra-node/node.env".to_string(),
            mode: "0600".to_string(),
            owner_uid: 0,
            owner_gid: 0,
            is_regular_file: true,
            atomic_write: true,
            env_keys: vec![
                "HYDRA_PANEL_URL".to_string(),
                "HYDRA_NODE_AUTH_TOKEN".to_string(),
                "HYDRA_NODE_ID".to_string(),
                "HYDRA_NODE_SIDECAR_RECIPE_MODE".to_string(),
                "HYDRA_NODE_HYSTERIA2_SERVICE_NAME".to_string(),
                "HYDRA_NODE_WIREGUARD_BINARY_PATH".to_string(),
                "HYDRA_NODE_WG_QUICK_BINARY_PATH".to_string(),
                "HYDRA_NODE_WIREGUARD_INTERFACE_NAME".to_string(),
            ],
            schema_fingerprint: node_env_schema_fingerprint(),
        };
        assert!(node_env_attestation_is_valid(Some(&attestation)));

        let mut weak = attestation.clone();
        weak.mode = "0644".to_string();
        assert!(!node_env_attestation_is_valid(Some(&weak)));

        weak = attestation;
        weak.env_keys.push("PLAINTEXT_VALUE".to_string());
        assert!(!node_env_attestation_is_valid(Some(&weak)));
    }

    #[test]
    fn node_env_handoff_rejects_self_report_without_valid_attestation() {
        let unique = format!("hydra-node-env-attestation-{}", generate_resource_id());
        let base = std::env::temp_dir().join(unique);
        let config = AppConfig {
            node_provisioning_events_path: base.join("events.ndjson").to_string_lossy().to_string(),
            ..AppConfig::default()
        };
        let mut runtime = ProvisioningRuntime {
            tasks: HashMap::from([(
                "task-a".to_string(),
                sample_provisioning_task(NodeProvisioningTaskStatus::Running),
            )]),
            events: Vec::new(),
            executors: HashMap::new(),
            executor_submissions: Vec::new(),
        };

        let missing_attestation = runtime.record_handoff(
            &config,
            "node-a",
            "task-a",
            ReportNodeProvisioningHandoffRequest {
                kind: NodeProvisioningHandoffKind::NodeEnvWritten,
                status: NodeProvisioningHandoffStatus::Succeeded,
                detail: "node env written".to_string(),
                node_env_attestation: None,
                service_started_attestation: None,
            },
        );
        assert!(matches!(
            missing_attestation,
            Err(SecurityError::InvalidSecuritySettings(
                "successful node_env_written handoff requires valid node env attestation"
            ))
        ));

        let accepted = runtime
            .record_handoff(
                &config,
                "node-a",
                "task-a",
                ReportNodeProvisioningHandoffRequest {
                    kind: NodeProvisioningHandoffKind::NodeEnvWritten,
                    status: NodeProvisioningHandoffStatus::Succeeded,
                    detail: "node env attested".to_string(),
                    node_env_attestation: Some(NodeProvisioningNodeEnvAttestation {
                        path: "/etc/hydra-node/node.env".to_string(),
                        mode: "0600".to_string(),
                        owner_uid: 0,
                        owner_gid: 0,
                        is_regular_file: true,
                        atomic_write: true,
                        env_keys: vec![
                            "HYDRA_PANEL_URL".to_string(),
                            "HYDRA_NODE_AUTH_TOKEN".to_string(),
                            "HYDRA_NODE_ID".to_string(),
                            "HYDRA_NODE_SIDECAR_RUNTIME_CONFIG_PATH".to_string(),
                        ],
                        schema_fingerprint: node_env_schema_fingerprint(),
                    }),
                    service_started_attestation: None,
                },
            )
            .expect("valid node env attestation is accepted");

        assert_eq!(accepted.handoff.len(), 1);
        assert_eq!(
            accepted.handoff[0].kind,
            NodeProvisioningHandoffKind::NodeEnvWritten
        );
        let _ = fs::remove_dir_all(&base);
    }

    #[test]
    fn service_started_success_requires_secret_free_attestation_contract() {
        let attestation = NodeProvisioningServiceStartedAttestation {
            service_name: "hydra-node.service".to_string(),
            unit_file_path: "/etc/systemd/system/hydra-node.service".to_string(),
            load_state: "loaded".to_string(),
            active_state: "active".to_string(),
            unit_file_state: "enabled".to_string(),
            exec_start_path: "/opt/hydra-node/hydra-node".to_string(),
            environment_file_path: "/etc/hydra-node/node.env".to_string(),
            working_directory: "/opt/hydra-node".to_string(),
            additional_services: Vec::new(),
        };
        assert!(service_started_attestation_is_valid(
            Some(&attestation),
            false
        ));
        assert!(!service_started_attestation_is_valid(
            Some(&attestation),
            true
        ));

        let mut weak = attestation.clone();
        weak.active_state = "inactive".to_string();
        assert!(!service_started_attestation_is_valid(Some(&weak), false));

        weak = attestation.clone();
        weak.exec_start_path = "/tmp/hydra-node".to_string();
        assert!(!service_started_attestation_is_valid(Some(&weak), false));

        let mut wireguard = attestation;
        wireguard
            .additional_services
            .push(NodeProvisioningManagedServiceAttestation {
                service_name: "hydra-node-session-adapter.service".to_string(),
                unit_file_path: "/etc/systemd/system/hydra-node-session-adapter.service"
                    .to_string(),
                load_state: "loaded".to_string(),
                active_state: "active".to_string(),
                unit_file_state: "enabled".to_string(),
                exec_start_path: "/opt/hydra-node/node-session-adapter".to_string(),
                environment_file_path: "/etc/hydra-node/node.env".to_string(),
                working_directory: "/opt/hydra-node".to_string(),
            });
        assert!(service_started_attestation_is_valid(Some(&wireguard), true));
    }

