    #[test]
    fn authenticated_agent_return_auto_confirms_latest_active_ssh_task() {
        let unique = format!("hydra-auto-agent-return-{}", generate_resource_id());
        let base = std::env::temp_dir().join(unique);
        let config = AppConfig {
            node_provisioning_events_path: base.join("events.ndjson").to_string_lossy().to_string(),
            ..AppConfig::default()
        };
        let mut old_task = sample_provisioning_task(NodeProvisioningTaskStatus::Running);
        old_task.task_id = "task-old".to_string();
        old_task.created_at_unix = 1;
        old_task.request_context.transport = NodeProvisioningTransportKind::Ssh;
        let mut latest_task = sample_provisioning_task(NodeProvisioningTaskStatus::Running);
        latest_task.task_id = "task-latest".to_string();
        latest_task.created_at_unix = 2;
        latest_task.updated_at_unix = now_unix();
        latest_task.request_context.transport = NodeProvisioningTransportKind::Ssh;
        let mut runtime = ProvisioningRuntime {
            tasks: HashMap::from([
                ("task-old".to_string(), old_task),
                ("task-latest".to_string(), latest_task),
            ]),
            events: Vec::new(),
            executors: HashMap::new(),
            executor_submissions: Vec::new(),
        };
        let mut node = test_node("node-a", "node-a");
        node.auth_token_issued_at_unix = Some(10);
        node.last_agent_heartbeat_at_unix = Some(11);

        assert!(
            runtime
                .confirm_agent_returned(&config, &node)
                .expect("auto confirmation succeeds")
        );
        assert!(runtime.tasks["task-old"].handoff.is_empty());
        assert!(runtime.tasks["task-latest"].handoff.iter().any(|record| {
            record.kind == NodeProvisioningHandoffKind::AgentReturned
                && record.status == NodeProvisioningHandoffStatus::Succeeded
        }));
        assert!(
            !runtime
                .confirm_agent_returned(&config, &node)
                .expect("second confirmation is idempotent")
        );

        let _ = fs::remove_dir_all(&base);
    }

