    #[test]
    fn recovery_requires_repair_before_retrying_blocked_prerequisites() {
        let task = NodeProvisioningTask {
            task_id: "task-a".to_string(),
            node_id: "node-a".to_string(),
            parent_task_id: None,
            reason: Some("manual".to_string()),
            status: NodeProvisioningTaskStatus::Failed,
            created_at_unix: 1,
            started_at_unix: Some(1),
            finished_at_unix: Some(2),
            updated_at_unix: 2,
            verify_after_finish: true,
            verified_ready: Some(false),
            verify_probe_id: None,
            recommendations: Vec::new(),
            failures: Vec::new(),
            remediation: Vec::new(),
            request_context: NodeProvisioningRequestContext {
                transport: NodeProvisioningTransportKind::Ssh,
                target_host: Some("203.0.113.10".to_string()),
                ssh_port: Some(22),
                ssh_username: Some("root".to_string()),
                uses_password_auth: false,
                uses_private_key_auth: true,
                sidecar_install: NodeProvisioningSidecarInstallSelection::default(),
            },
            executor_readiness: NodeProvisioningExecutorReadinessReport {
                transport: NodeProvisioningTransportKind::Ssh,
                ready: true,
                checked_at_unix: 1,
                checks: Vec::new(),
                recommendations: Vec::new(),
            },
            remote_prerequisites: vec![NodeProvisioningRemotePrerequisiteCheck {
                prerequisite: NodeProvisioningRemotePrerequisiteKind::PortsAvailable,
                status: NodeProvisioningPreflightStatus::Failed,
                detail: "62050 busy".to_string(),
            }],
            planned_steps: provisioning_step_templates(NodeProvisioningTransportKind::Ssh),
            steps: Vec::new(),
            handoff: Vec::new(),
        };
        let preflight = NodeProvisioningPreflightReport {
            node_id: "node-a".to_string(),
            passed: true,
            checked_at_unix: 3,
            checks: Vec::new(),
            recommendations: Vec::new(),
        };
        let recovery =
            build_node_provisioning_recovery_view(Some(&task), false, &preflight, &Vec::new());

        assert_eq!(
            recovery.decision,
            NodeProvisioningRecoveryDecision::RepairFirst
        );
        assert!(
            recovery.required_actions.iter().any(|item| {
                item.action == NodeProvisioningRemediationAction::FreeRequiredPorts
            })
        );
    }

    #[test]
    fn node_provisioning_events_are_filtered_and_bounded() {
        let runtime = ProvisioningRuntime {
            tasks: HashMap::new(),
            events: vec![
                NodeProvisioningEvent {
                    task_id: "task-a".to_string(),
                    node_id: "node-a".to_string(),
                    kind: "started".to_string(),
                    detail: "started".to_string(),
                    created_at_unix: 1,
                },
                NodeProvisioningEvent {
                    task_id: "task-a".to_string(),
                    node_id: "node-a".to_string(),
                    kind: "step".to_string(),
                    detail: "ssh connect".to_string(),
                    created_at_unix: 2,
                },
                NodeProvisioningEvent {
                    task_id: "task-b".to_string(),
                    node_id: "node-a".to_string(),
                    kind: "step".to_string(),
                    detail: "retry step".to_string(),
                    created_at_unix: 3,
                },
                NodeProvisioningEvent {
                    task_id: "task-c".to_string(),
                    node_id: "node-b".to_string(),
                    kind: "step".to_string(),
                    detail: "other node".to_string(),
                    created_at_unix: 4,
                },
            ],
            executors: HashMap::new(),
            executor_submissions: Vec::new(),
        };

        let events = runtime.events_for_node(
            "node-a",
            NodeProvisioningEventsQuery {
                task_id: None,
                kind: Some("STEP".to_string()),
                limit: Some(1),
            },
            100,
        );

        assert_eq!(events.len(), 1);
        assert_eq!(events[0].task_id, "task-b");
        assert_eq!(events[0].node_id, "node-a");
        assert_eq!(events[0].kind, "step");
    }

    #[test]
    fn executor_submission_journal_is_filtered_and_bounded() {
        let runtime = ProvisioningRuntime {
            tasks: HashMap::new(),
            events: Vec::new(),
            executors: HashMap::new(),
            executor_submissions: vec![
                NodeProvisioningExecutorSubmissionEntry {
                    executor_id: "executor-a".to_string(),
                    node_id: "node-a".to_string(),
                    task_id: "task-a".to_string(),
                    submission_kind: NodeProvisioningExecutorResultSubmissionKind::StepReport,
                    status: NodeProvisioningExecutorSubmissionStatus::Accepted,
                    accepted_node_id: Some("step_preflight".to_string()),
                    detail: "accepted".to_string(),
                    created_at_unix: 10,
                },
                NodeProvisioningExecutorSubmissionEntry {
                    executor_id: "executor-b".to_string(),
                    node_id: "node-b".to_string(),
                    task_id: "task-b".to_string(),
                    submission_kind: NodeProvisioningExecutorResultSubmissionKind::HandoffReport,
                    status: NodeProvisioningExecutorSubmissionStatus::Rejected,
                    accepted_node_id: None,
                    detail: "missing attestation".to_string(),
                    created_at_unix: 20,
                },
            ],
        };

        let rejected = runtime.executor_submissions(
            NodeProvisioningExecutorSubmissionsQuery {
                executor_id: Some("executor-b".to_string()),
                status: Some(NodeProvisioningExecutorSubmissionStatus::Rejected),
                ..NodeProvisioningExecutorSubmissionsQuery::default()
            },
            10,
        );
        assert_eq!(rejected.len(), 1);
        assert_eq!(rejected[0].task_id, "task-b");

        let bounded = runtime.executor_submissions(
            NodeProvisioningExecutorSubmissionsQuery {
                limit: Some(10),
                ..NodeProvisioningExecutorSubmissionsQuery::default()
            },
            1,
        );
        assert_eq!(bounded.len(), 1);
        assert_eq!(bounded[0].created_at_unix, 20);
    }

