    #[test]
    fn node_runtime_config_document_is_secret_free_least_knowledge_contract() {
        let projected = node_agent_generated_config(generated_cluster_config(), "node-relay");
        let node = projected.nodes[0].clone();
        let apply = NodeAgentApplyDirective {
            apply_required: true,
            target_revision: projected.revision.clone(),
            current_applied_revision: None,
            current_sync_status: NodeSyncStatus::Pending,
            requested_at_unix: Some(42),
            reason: "test apply".to_string(),
        };

        let document = build_node_runtime_config_document(&node, &projected, apply);

        assert_eq!(document.schema_version, 1);
        assert_eq!(document.node.node_id, "node-relay");
        assert_eq!(document.revision, projected.revision);
        assert!(document.runtime.least_knowledge);
        assert!(document.contract.valid);
        assert!(document.contract.fail_closed);
        assert_eq!(document.contract.node_id, "node-relay");
        assert_eq!(
            document.contract.projected_node_ids,
            vec!["node-relay".to_string()]
        );
        assert_eq!(document.contract.route_assignment_count, 1);
        assert_eq!(
            document.contract.credential_ref_count,
            document.credential_refs.len()
        );
        assert!(document.config.users.is_empty());
        assert!(document.config.inbounds.is_empty());
        assert!(document.config.hosts.is_empty());
        assert_eq!(document.config.nodes.len(), 1);
        assert_eq!(document.config.nodes[0].node_id, "node-relay");
        assert_eq!(document.route_assignments.len(), 1);
        assert_eq!(document.route_assignments[0].node_id, "node-relay");
        assert!(!document.credential_refs.is_empty());

        let serialized = serde_json::to_string(&document).expect("runtime config serializes");
        assert!(!serialized.contains("PRIVATE KEY"));
        assert!(!serialized.contains("auth_token_hash"));
        assert!(!serialized.contains("local_api_token"));
        assert!(!serialized.contains("node-entry"));
        assert!(!serialized.contains("node-exit"));
    }

    #[test]
    fn node_runtime_contract_diagnostics_fail_closed_on_leaked_topology() {
        let projected = node_agent_generated_config(generated_cluster_config(), "node-relay");
        let node = projected.nodes[0].clone();
        let apply = NodeAgentApplyDirective {
            apply_required: true,
            target_revision: projected.revision.clone(),
            current_applied_revision: None,
            current_sync_status: NodeSyncStatus::Pending,
            requested_at_unix: Some(42),
            reason: "test apply".to_string(),
        };
        let mut document = build_node_runtime_config_document(&node, &projected, apply);
        document.config.nodes.push(NodeRuntimeIdentity {
            node_id: "node-exit".to_string(),
            name: "exit".to_string(),
            address: "203.0.113.3".to_string(),
            port: Some(62000),
            api_port: Some(62001),
            enabled: true,
        });
        let mut leaked_assignment = document.route_assignments[0].clone();
        leaked_assignment.node_id = "node-exit".to_string();
        document.route_assignments.push(leaked_assignment);
        document.credential_refs.push("unrelated-ref".to_string());

        document.contract = build_node_runtime_contract_diagnostics(&document);
        let xray_config = build_xray_config_document_from_runtime_config_document(&document);
        let render_summary = build_node_runtime_xray_render_summary(&document, &xray_config);

        assert!(!document.contract.valid);
        assert!(!xray_config.raw_config_validation.valid);
        assert_eq!(
            xray_config.raw_config_validation.issue_count,
            document.contract.issue_count
        );
        assert!(
            xray_config
                .raw_config_validation
                .issues
                .iter()
                .any(|issue| {
                    issue.path == "runtime_config.config.nodes"
                        && issue.reason.contains("node-exit")
                })
        );
        assert!(document.contract.issue_count >= 3);
        assert_eq!(
            render_summary.issue_count,
            document.contract.issue_count + xray_config.raw_config_validation.issue_count
        );
        assert!(render_summary.issues.iter().any(|issue| {
            issue.route_id == "runtime_config"
                && issue.scope == "config.nodes"
                && issue.reason.contains("node-exit")
        }));
        assert!(render_summary.issues.iter().any(|issue| {
            issue.route_id == "runtime_config"
                && issue.scope == "route_assignments"
                && issue.reason.contains("node-exit")
        }));
        assert!(render_summary.issues.iter().any(|issue| {
            issue.route_id == "runtime_config" && issue.scope == "credential_refs"
        }));
    }

