    #[test]
    fn node_agent_apply_plan_is_secret_free_and_requires_safe_validation_sequence() {
        let projected = node_agent_generated_config(generated_cluster_config(), "node-entry");
        let node = projected.nodes[0].clone();
        let apply = NodeAgentApplyDirective {
            apply_required: true,
            target_revision: projected.revision.clone(),
            current_applied_revision: None,
            current_sync_status: NodeSyncStatus::Pending,
            requested_at_unix: Some(42),
            reason: "test apply".to_string(),
        };
        let runtime_config = build_node_runtime_config_document(&node, &projected, apply);

        let plan = build_node_agent_apply_plan(&runtime_config);

        assert_eq!(plan.schema_version, 2);
        assert_eq!(plan.target_revision, runtime_config.revision);
        assert!(plan.apply_required);
        assert!(plan.least_knowledge);
        assert!(plan.requires_route_credentials);
        assert!(plan.requires_xray_validation);
        assert!(plan.safe_restart_after_successful_validation);
        assert!(plan.runtime_components.iter().any(|component| {
            component.owner == ProtocolRuntimeOwner::Xray
                && component.production_ready
                && component.required_binaries == vec!["xray".to_string()]
        }));
        assert!(
            plan.steps
                .iter()
                .any(|step| { step.step == "verify_runtime_components" && step.required })
        );
        assert!(
            plan.steps
                .iter()
                .any(|step| { step.step == "validate_xray_config" && step.required })
        );
        assert!(
            plan.steps
                .iter()
                .any(|step| { step.step == "restart_xray" && step.required })
        );

        let serialized = serde_json::to_string(&plan).expect("apply plan serializes");
        assert!(!serialized.contains("PRIVATE KEY"));
        assert!(!serialized.contains("auth_token"));
        assert!(!serialized.contains("subscription_token"));
    }

    #[test]
    fn node_agent_apply_plan_includes_sidecar_runtime_components_for_non_xray_protocols() {
        let mut projected = node_agent_generated_config(generated_cluster_config(), "node-entry");
        projected.inbounds.push(Inbound {
            tag: "hysteria2-in".to_string(),
            port: 8443,
            protocol: "hysteria2".to_string(),
            network: InboundTransport::Quic,
            tls_enabled: true,
            node_id: None,
            cluster_id: None,
            created_at_unix: 1,
            updated_at_unix: 1,
        });
        let node = projected.nodes[0].clone();
        let apply = NodeAgentApplyDirective {
            apply_required: true,
            target_revision: projected.revision.clone(),
            current_applied_revision: None,
            current_sync_status: NodeSyncStatus::Pending,
            requested_at_unix: Some(42),
            reason: "test apply".to_string(),
        };
        let runtime_config = build_node_runtime_config_document(&node, &projected, apply);

        let plan = build_node_agent_apply_plan(&runtime_config);

        let sidecar = plan
            .runtime_components
            .iter()
            .find(|component| component.owner == ProtocolRuntimeOwner::Sidecar)
            .expect("sidecar runtime requirement exists");
        assert!(sidecar.production_ready);
        assert!(sidecar.disabled_reason.is_none());
        assert_eq!(sidecar.required_binaries, vec!["hysteria".to_string()]);
        assert!(plan.safe_restart_after_successful_validation);
        assert!(
            plan.steps
                .iter()
                .any(|step| { step.step == "verify_runtime_components" && step.required })
        );
    }

    #[test]
    fn route_identity_ref_matches_next_nodes_listen_identity() {
        let generated = generated_cluster_config();
        let entry_next_identity = generated.node_route_assignments[0]
            .next_peer
            .as_ref()
            .and_then(|peer| peer.auth.as_ref())
            .and_then(|auth| auth.identity_ref.as_deref());
        let relay_listen_identity = generated.node_route_assignments[1]
            .listen
            .as_ref()
            .and_then(|listen| listen.auth.as_ref())
            .and_then(|auth| auth.identity_ref.as_deref());

        assert_eq!(entry_next_identity, relay_listen_identity);
        assert_eq!(
            entry_next_identity,
            Some(opaque_cluster_peer_id("cluster-a", "relay-cn").as_str())
        );
        assert_ne!(entry_next_identity, Some("relay-cn"));
    }

    #[test]
    fn generated_assignments_use_local_credential_but_next_peer_identity() {
        let runtime = ClusterRuntime {
            clusters: HashMap::from([("cluster-a".to_string(), runtime_cluster())]),
        };
        let known_node_ids = HashSet::from([
            "node-entry".to_string(),
            "node-relay".to_string(),
            "node-exit".to_string(),
        ]);
        let panel_nodes = HashMap::from([
            ("node-entry".to_string(), test_node("node-entry", "entry")),
            ("node-relay".to_string(), test_node("node-relay", "relay")),
            ("node-exit".to_string(), test_node("node-exit", "exit")),
        ]);

        let assignments = runtime.generated_node_route_assignments(&known_node_ids, &panel_nodes);
        let entry_assignment = assignments
            .iter()
            .find(|assignment| assignment.node_id == "node-entry")
            .expect("entry assignment exists");
        let relay_assignment = assignments
            .iter()
            .find(|assignment| assignment.node_id == "node-relay")
            .expect("relay assignment exists");

        let next_peer = entry_assignment
            .next_peer
            .as_ref()
            .expect("entry has next peer");
        assert_eq!(
            next_peer
                .security
                .as_ref()
                .and_then(|security| security.credential_ref.as_deref()),
            Some("cluster/cluster-a/node/entry-cn/mtls")
        );
        assert_eq!(
            next_peer
                .auth
                .as_ref()
                .and_then(|auth| auth.identity_ref.as_deref()),
            Some(opaque_cluster_peer_id("cluster-a", "relay-cn").as_str())
        );
        assert_eq!(
            relay_assignment
                .listen
                .as_ref()
                .and_then(|listen| listen.auth.as_ref())
                .and_then(|auth| auth.identity_ref.as_deref()),
            next_peer
                .auth
                .as_ref()
                .and_then(|auth| auth.identity_ref.as_deref())
        );
    }

    fn temp_route_material_paths(test_name: &str) -> (String, String) {
        let unique = format!(
            "hydra-panel-{test_name}-{}-{}",
            std::process::id(),
            now_unix()
        );
        let base = std::env::temp_dir().join(unique);
        (
            base.with_extension("route-materials.json")
                .to_string_lossy()
                .to_string(),
            base.with_extension("route-materials.key")
                .to_string_lossy()
                .to_string(),
        )
    }

    fn cleanup_route_material_paths(materials_path: &str, key_path: &str) {
        let _ = std::fs::remove_file(PathBuf::from(materials_path));
        let _ = std::fs::remove_file(PathBuf::from(key_path));
    }

    #[test]
    fn secret_key_readiness_reports_pending_ready_and_invalid_key_files() {
        let (_, pending_key_path) = temp_route_material_paths("secret-readiness-pending");
        let pending = inspect_secret_key(
            SecretKeyKind::RouteMaterials,
            "HYDRA_TEST_SECRET_READINESS_PENDING_B64",
            &pending_key_path,
        );
        assert_eq!(pending.source, SecretKeySource::KeyFilePending);
        assert_eq!(pending.status, SecretKeyReadinessStatus::Pending);

        let (_, ready_key_path) = temp_route_material_paths("secret-readiness-ready");
        let key: [u8; 32] = random();
        std::fs::write(&ready_key_path, BASE64.encode(&key)).expect("valid key file writes");
        let ready = inspect_secret_key(
            SecretKeyKind::RouteMaterials,
            "HYDRA_TEST_SECRET_READINESS_READY_B64",
            &ready_key_path,
        );
        assert_eq!(ready.source, SecretKeySource::KeyFile);
        assert_eq!(ready.status, SecretKeyReadinessStatus::Ready);

        let (_, invalid_key_path) = temp_route_material_paths("secret-readiness-invalid");
        std::fs::write(&invalid_key_path, "not-a-valid-master-key").expect("invalid key writes");
        let invalid = inspect_secret_key(
            SecretKeyKind::RouteMaterials,
            "HYDRA_TEST_SECRET_READINESS_INVALID_B64",
            &invalid_key_path,
        );
        assert_eq!(invalid.source, SecretKeySource::KeyFile);
        assert_eq!(invalid.status, SecretKeyReadinessStatus::Invalid);

        let _ = std::fs::remove_file(PathBuf::from(pending_key_path));
        let _ = std::fs::remove_file(PathBuf::from(ready_key_path));
        let _ = std::fs::remove_file(PathBuf::from(invalid_key_path));
    }

