    #[test]
    fn protocol_capabilities_include_sidecar_targets() {
        let view = protocol_capabilities_view();
        assert_eq!(view.schema_version, 5);
        let xray_component = view
            .runtime_components
            .iter()
            .find(|component| component.owner == ProtocolRuntimeOwner::Xray)
            .expect("xray runtime component exists");
        assert!(xray_component.production_ready);
        assert_eq!(
            xray_component.validation_strategy,
            "internal_raw_validation_then_xray_test_config"
        );
        assert!(
            xray_component
                .supported_actions
                .contains(&RuntimeComponentAction::Validate)
        );
        assert!(
            xray_component
                .supported_actions
                .contains(&RuntimeComponentAction::Logs)
        );
        for owner in [
            ProtocolRuntimeOwner::Sidecar,
            ProtocolRuntimeOwner::NodeNative,
        ] {
            let component = view
                .runtime_components
                .iter()
                .find(|component| component.owner == owner)
                .expect("non-Xray runtime component exists");
            assert!(component.production_ready);
            assert!(component.disabled_reason.is_none());
            assert_eq!(component.supervised_by, "node_agent");
            assert_eq!(
                component.supported_actions,
                RuntimeComponentAction::ALL.to_vec()
            );
        }

        let vless = view
            .capabilities
            .iter()
            .find(|capability| capability.protocol == "vless")
            .expect("vless capability exists");
        assert_eq!(vless.runtime_owner, ProtocolRuntimeOwner::Xray);
        assert_eq!(vless.required_binaries, vec!["xray".to_string()]);
        assert!(vless.disabled_reason.is_none());
        assert!(vless.supported_transports.contains(&InboundTransport::Ws));
        assert!(
            vless
                .supported_security_modes
                .contains(&ProtocolSecurityMode::Tls)
        );

        for sidecar_protocol in ["hysteria2", "wireguard"] {
            let capability = view
                .capabilities
                .iter()
                .find(|capability| capability.protocol == sidecar_protocol)
                .expect("sidecar capability exists");
            assert_eq!(capability.status, ProtocolSupportStatus::Production);
            assert_ne!(capability.runtime_owner, ProtocolRuntimeOwner::Xray);
            assert!(capability.disabled_reason.is_none());
            assert!(!capability.required_binaries.is_empty());
            assert!(!capability.required_secret_classes.is_empty());
            assert!(capability.modes.iter().any(|mode| mode.production_ready));
        }
    }

