    #[test]
    fn runtime_component_action_contract_is_allowlisted() {
        // Parsing comes from ALL, so the allowlist and the registry are one list.
        for component in RuntimeComponent::ALL {
            assert_eq!(
                RuntimeComponent::parse(component.as_str()),
                Some(*component),
                "{} must parse back into itself",
                component.as_str()
            );
        }
        for action in RuntimeComponentAction::ALL {
            assert_eq!(
                RuntimeComponentAction::parse(action.as_str()),
                Some(*action),
                "{} must parse back into itself",
                action.as_str()
            );
        }

        // Anything absent from the registry never reaches business logic: a path
        // segment does not become a type. Directory traversal is inexpressible.
        assert_eq!(RuntimeComponent::parse("unknown"), None);
        assert_eq!(RuntimeComponentAction::parse("../restart"), None);
        assert_eq!(RuntimeComponentAction::parse("shell"), None);
        assert_eq!(RuntimeComponentAction::parse("Status"), None);
        assert_eq!(RuntimeComponentAction::parse(""), None);
    }

    #[test]
    fn ui_contracts_snapshot_exposes_schema_versions_and_enum_values() {
        let snapshot = build_ui_contracts_snapshot();

        fn has_endpoint(
            snapshot: &UiContractsSnapshot,
            group: &str,
            method: &str,
            path: &str,
        ) -> bool {
            snapshot.endpoint_groups.iter().any(|item| {
                item.group == group
                    && item
                        .endpoints
                        .iter()
                        .any(|endpoint| endpoint.method == method && endpoint.path == path)
            })
        }

        fn declares_path(snapshot: &UiContractsSnapshot, path: &str) -> bool {
            snapshot
                .endpoint_groups
                .iter()
                .any(|item| item.endpoints.iter().any(|endpoint| endpoint.path == path))
        }

        // The endpoints shape moved from strings to objects -> document version raised.
        assert_eq!(snapshot.schema_version, 3);
        assert!(
            snapshot
                .schemas
                .iter()
                .any(|schema| schema.name == "ui_bootstrap" && schema.version == 2)
        );
        assert!(
            snapshot
                .schemas
                .iter()
                .any(|schema| schema.name == "node_runtime_config" && schema.version == 1)
        );
        assert!(
            snapshot
                .schemas
                .iter()
                .any(|schema| schema.name == "subscription_catalog" && schema.version == 8)
        );
        assert!(has_endpoint(&snapshot, "ui", "GET", "/api/ui/contracts"));
        assert!(snapshot.enums.iter().any(|item| {
            item.name == "subscription_device_enrollment_status"
                && item.values.contains(&"consumed".to_string())
                && item.values.contains(&"expired".to_string())
        }));
        assert!(has_endpoint(
            &snapshot,
            "subscription_catalog",
            "GET",
            "/api/subscription-plans"
        ));
        assert!(has_endpoint(
            &snapshot,
            "subscription_catalog",
            "POST",
            "/api/subscription-clients/{client_id}/device-enrollments"
        ));
        // Enrollment-code exchange and public subscription delivery are called by a
        // device without an admin session. That is not the browser surface, and the
        // exposure filter removed them from the contract.
        assert!(!declares_path(&snapshot, "/api/device-enrollment/exchange"));
        assert!(!declares_path(&snapshot, "/sub/device/{device_credential}"));
        assert!(snapshot.enums.iter().any(|item| {
            item.name == "node_apply_lifecycle_state"
                && item.values.contains(&"rolled_back".to_string())
        }));
        assert!(has_endpoint(
            &snapshot,
            "nodes",
            "POST",
            "/api/nodes/{node_id}/local/runtime-components/{component}/{action}"
        ));
        assert!(snapshot.enums.iter().any(|item| {
            item.name == "runtime_component"
                && item.values.contains(&"hysteria2_sidecar".to_string())
        }));
        assert!(snapshot.enums.iter().any(|item| {
            item.name == "runtime_component_action"
                && item.values.contains(&"validate".to_string())
                && item.values.contains(&"logs".to_string())
        }));
        assert!(snapshot.enums.iter().any(|item| {
            item.name == "subscription_format"
                && item.values.contains(&"base64".to_string())
                && item.values.contains(&"diagnostic_json".to_string())
        }));

        let serialized = serde_json::to_string(&snapshot).expect("contracts snapshot serializes");
        assert!(!serialized.contains("PRIVATE KEY"));
        assert!(!serialized.contains("subscription_token"));

        // Enum variant names legitimately mention tokens: `node_auth_token_rotated`
        // is an audit event type, not a credential. So the registry is checked by
        // shape rather than substring: a value must be a short snake_case identifier
        // with no room for secret material.
        for item in &snapshot.enums {
            for value in &item.values {
                assert!(
                    value.len() <= 64
                        && value.chars().all(|symbol| symbol.is_ascii_lowercase()
                            || symbol.is_ascii_digit()
                            || symbol == '_'),
                    "{}: value {value} does not look like an identifier",
                    item.name
                );
            }
        }

        // Routes and schema versions are also checked by shape rather than
        // substring: `/api/system/secret-readiness` is a legitimate path, not a
        // leak. Secret material has nowhere to appear in a structure made of
        // constant paths, methods and numbers.
        for group in &snapshot.endpoint_groups {
            for endpoint in &group.endpoints {
                assert!(
                    endpoint.path.starts_with('/') && endpoint.path.len() <= 128,
                    "{}: path {} does not look like a route",
                    group.group,
                    endpoint.path
                );
                assert!(
                    matches!(endpoint.method.as_str(), "GET" | "POST" | "PUT" | "DELETE"),
                    "{}: unknown method {}",
                    group.group,
                    endpoint.method
                );
            }
        }
        for schema in &snapshot.schemas {
            assert!(
                schema.name.len() <= 64
                    && schema.name.chars().all(|symbol| symbol.is_ascii_lowercase()
                        || symbol.is_ascii_digit()
                        || symbol == '_'),
                "schema name {} does not look like an identifier",
                schema.name
            );
        }
    }

