    #[test]
    fn xray_document_contains_raw_like_stream_settings_json() {
        let mut generated = generated_cluster_config();
        generated.inbounds = vec![Inbound {
            tag: "client-in".to_string(),
            port: 443,
            protocol: "vless".to_string(),
            network: InboundTransport::Ws,
            tls_enabled: true,
            node_id: None,
            cluster_id: None,
            created_at_unix: 1,
            updated_at_unix: 1,
        }];
        generated.users[0].inbounds = generated.inbounds.clone();
        generated.users[0].hosts[0].path = Some("/ws".to_string());

        let document = build_xray_config_document(&generated);
        let raw_inbound = document.raw_config["inbounds"][0].clone();
        assert_eq!(raw_inbound["protocol"], "vless");
        assert_eq!(raw_inbound["settings"]["decryption"], "none");
        assert!(
            raw_inbound["settings"]["clients"][0]["id"]
                .as_str()
                .is_some_and(is_uuid_like)
        );
        assert!(raw_inbound["settings"]["clients"][0]["password"].is_null());
        assert_eq!(raw_inbound["streamSettings"]["network"], "ws");
        assert_eq!(raw_inbound["streamSettings"]["security"], "tls");
        assert_eq!(raw_inbound["streamSettings"]["wsSettings"]["path"], "/ws");
        assert_eq!(
            raw_inbound["streamSettings"]["tlsSettings"]["serverName"],
            "vpn.example.test"
        );
        // The key was removed from Xray: it must not be present with any value.
        assert!(
            raw_inbound["streamSettings"]["tlsSettings"]["allowInsecure"].is_null(),
            "allowInsecure was removed from Xray and must not be emitted"
        );
        assert_eq!(
            raw_inbound["streamSettings"]["wsSettings"]["headers"]["Host"],
            "vpn.example.test"
        );
        assert!(
            raw_inbound["streamSettings"]["tlsSettings"]["certificates"][0]["certificateFile"]
                .as_str()
                .is_some_and(|value| value.ends_with("inbound:client-in:tls.crt"))
        );
        assert!(document.raw_config["outbounds"].is_array());
        assert!(document.raw_config["routing"]["rules"].is_array());
        let serialized =
            serde_json::to_string(&document.raw_config).expect("raw config serializes");
        assert!(!serialized.contains("secret-subscription-token"));
        assert!(document.raw_config_validation.valid);
    }

