    #[test]
    fn xray_raw_config_validation_reports_valid_and_invalid_configs() {
        let document = build_xray_config_document(&generated_cluster_config());
        assert!(document.raw_config_validation.valid);
        assert_eq!(document.raw_config_validation.issue_count, 0);
        assert_eq!(
            document.raw_config["api"]["services"][0],
            serde_json::json!("StatsService")
        );
        let stats_inbound = document.raw_config["inbounds"]
            .as_array()
            .and_then(|inbounds| {
                inbounds
                    .iter()
                    .find(|inbound| inbound["tag"] == "hydra-stats-api")
            })
            .expect("stats API inbound is generated");
        assert_eq!(stats_inbound["listen"], "127.0.0.1");
        assert_eq!(
            document.raw_config["policy"]["levels"]["0"]["statsUserUplink"],
            true
        );

        let mut broken = document.raw_config.clone();
        broken["inbounds"][0]["streamSettings"]["tlsSettings"] = serde_json::Value::Null;
        let report = validate_raw_xray_config(&broken, &HashSet::new());
        assert!(!report.valid);
        assert!(report.issue_count > 0);
        assert!(report.issues.iter().any(|issue| {
            issue.path.ends_with(".streamSettings.tlsSettings")
                && issue.reason.contains("tlsSettings")
        }));

        let mut exposed_stats = document.raw_config;
        let stats_inbound = exposed_stats["inbounds"]
            .as_array_mut()
            .and_then(|inbounds| {
                inbounds
                    .iter_mut()
                    .find(|inbound| inbound["tag"] == "hydra-stats-api")
            })
            .expect("stats API inbound is generated");
        stats_inbound["listen"] = serde_json::json!("0.0.0.0");
        let exposed_report = validate_raw_xray_config(&exposed_stats, &HashSet::new());
        assert!(!exposed_report.valid);
        assert!(
            exposed_report
                .issues
                .iter()
                .any(|issue| issue.reason.contains("loopback-only"))
        );
    }

