    /// The XHTTP rules run on real config validation, not only in their own tests.
    ///
    /// They were written against the stream settings document and then never
    /// called from the validation path, so a config Xray accepts at `run -test`
    /// and that does not work passed the panel unremarked.
    #[test]
    fn xray_raw_config_validation_enforces_xhttp_semantics() {
        let mut config = build_xray_config_document(&generated_cluster_config()).raw_config;
        config["inbounds"][0]["streamSettings"]["network"] = serde_json::json!("xhttp");
        config["inbounds"][0]["streamSettings"]["xhttpSettings"] = serde_json::json!({
            "path": "/x",
            "mode": "packet-up",
            "extra": { "xPaddingBytes": XHTTP_PADDING_BYTES }
        });
        config["inbounds"][0]["settings"]["clients"][0]["flow"] =
            serde_json::json!(VlessFlow::XtlsRprxVision.as_str());

        let report = validate_raw_xray_config(&config, &HashSet::new());

        assert!(!report.valid, "packet-up with Vision must be refused");
        assert!(
            report.issues.iter().any(|issue| {
                issue.severity == "error" && issue.reason.contains("requires XHTTP mode stream-one")
            }),
            "the Vision rule did not run on the raw config: {:?}",
            report.issues
        );

        // The same inbound in the mode Vision needs passes.
        config["inbounds"][0]["streamSettings"]["xhttpSettings"]["mode"] =
            serde_json::json!("stream-one");
        let report = validate_raw_xray_config(&config, &HashSet::new());
        assert!(
            !report
                .issues
                .iter()
                .any(|issue| issue.reason.contains("requires XHTTP mode stream-one")),
            "stream-one with Vision must be accepted: {:?}",
            report.issues
        );
    }

