    #[test]
    fn xray_swap_with_backup_replaces_active_binary_and_keeps_backup() {
        let unique = format!("hydra-xray-swap-{}", random::<u64>());
        let base = std::env::temp_dir().join(unique);
        let work_dir = base.join("work");
        fs::create_dir_all(&base).expect("test dir is created");
        let active = base.join(if cfg!(windows) { "xray.exe" } else { "xray" });
        let candidate = base.join(if cfg!(windows) {
            "candidate-xray.exe"
        } else {
            "candidate-xray"
        });
        fs::write(&active, b"old-binary").expect("active binary is written");
        fs::write(&candidate, b"new-binary").expect("candidate binary is written");

        let backup =
            swap_xray_binary_with_backup(&active, &candidate, &work_dir, "v/test").expect("swap");

        assert_eq!(fs::read(&active).expect("active exists"), b"new-binary");
        assert_eq!(fs::read(&backup).expect("backup exists"), b"old-binary");
        assert!(backup.to_string_lossy().contains("v_test"));
        let _ = fs::remove_dir_all(&base);
    }

    #[test]
    fn core_restart_records_xray_update_gate_detail() {
        let unique = format!("hydra-core-restart-gate-{}", random::<u64>());
        let base = std::env::temp_dir().join(unique);
        fs::create_dir_all(&base).expect("test dir is created");
        let mut config = AppConfig {
            core_config_path: base.join("core.json").to_string_lossy().to_string(),
            operational_log_path: base.join("logs.ndjson").to_string_lossy().to_string(),
            ..AppConfig::default()
        };
        config.monitoring.alert_history_path =
            base.join("alerts.ndjson").to_string_lossy().to_string();
        config.xray_update_work_dir = base.join("updates").to_string_lossy().to_string();

        let mut runtime = SystemRuntime::new(&config);
        runtime.last_xray_update = Some(XrayCoreUpdateReport {
            requested_at_unix: 1,
            status: XrayCoreUpdateStatus::Swapped,
            target_version: Some("v25.1.1".to_string()),
            selected_asset_name: Some("Xray-linux-64.zip".to_string()),
            selected_asset_url: Some("https://example.test/xray.zip".to_string()),
            binary_path: Some("/usr/local/bin/xray".to_string()),
            work_dir: config.xray_update_work_dir.clone(),
            downloaded_archive_path: None,
            downloaded_sha256: None,
            candidate_binary_path: None,
            candidate_version: Some("Xray 25.1.1".to_string()),
            active_backup_path: Some("/tmp/xray.backup".to_string()),
            post_swap_version: Some("Xray 25.1.1".to_string()),
            detail: "Xray binary swapped safely; explicit restart is now allowed".to_string(),
            stages: Vec::new(),
        });

        let record = runtime.execute_core_action(&config, CoreAction::Restart);

        assert_eq!(record.result, Some(CoreActionResult::Completed));
        assert_eq!(
            record.detail.as_deref(),
            Some("core restart completed after validated Xray binary swap")
        );
        assert_eq!(
            runtime
                .last_action
                .as_ref()
                .and_then(|action| action.detail.as_deref()),
            Some("core restart completed after validated Xray binary swap")
        );
        assert!(
            runtime
                .logs
                .iter()
                .any(|line| line.message
                    == "core restart completed after validated Xray binary swap")
        );
        let _ = fs::remove_dir_all(&base);
    }

    #[test]
    fn route_material_admin_view_never_exposes_private_key_material() {
        let (materials_path, key_path) = temp_route_material_paths("admin-view-redaction");
        let generated = node_agent_generated_config(generated_cluster_config(), "node-relay");

        let materials =
            ensure_node_route_credentials(&materials_path, &key_path, "node-relay", &generated)
                .expect("route credentials are issued");
        assert!(!materials.is_empty());
        assert!(
            materials
                .iter()
                .all(|material| material.private_key_pem.contains("PRIVATE KEY")),
            "node-agent payload must include private key material"
        );

        let store = load_route_material_store(&materials_path).expect("route material store loads");
        let view = route_material_store_view(&store);
        assert_eq!(view.credential_count, materials.len());
        assert_eq!(view.active_credential_count, materials.len());
        assert_eq!(view.revoked_credential_count, 0);
        assert!(
            view.credentials
                .iter()
                .all(|credential| credential.encrypted_private_key),
            "persisted private keys must be encrypted before admin view is built"
        );

        let serialized_view =
            serde_json::to_string(&view).expect("route material admin view serializes");
        assert!(!serialized_view.contains("PRIVATE KEY"));
        assert!(!serialized_view.contains("private_key_pem"));
        assert!(!serialized_view.contains("private_key_ciphertext"));
        assert!(!serialized_view.contains("private_key_nonce"));

        cleanup_route_material_paths(&materials_path, &key_path);
    }

    #[test]
    fn active_route_materials_are_limited_to_projected_node_assignments() {
        let (materials_path, key_path) = temp_route_material_paths("node-scope");
        let entry_generated = node_agent_generated_config(generated_cluster_config(), "node-entry");
        let relay_generated = node_agent_generated_config(generated_cluster_config(), "node-relay");

        let entry_materials = ensure_node_route_credentials(
            &materials_path,
            &key_path,
            "node-entry",
            &entry_generated,
        )
        .expect("entry route credentials are issued");
        let relay_materials = ensure_node_route_credentials(
            &materials_path,
            &key_path,
            "node-relay",
            &relay_generated,
        )
        .expect("relay route credentials are issued");

        let store = load_route_material_store(&materials_path).expect("route material store loads");
        let master_key =
            load_or_create_route_material_master_key(&key_path).expect("master key loads");
        let filtered_relay_materials =
            active_route_materials_for_node(&relay_generated, &store, &master_key)
                .expect("relay materials decrypt");

        let entry_refs = entry_materials
            .iter()
            .map(|material| material.credential_ref.as_str())
            .collect::<HashSet<_>>();
        let relay_refs = relay_materials
            .iter()
            .map(|material| material.credential_ref.as_str())
            .collect::<HashSet<_>>();
        let filtered_refs = filtered_relay_materials
            .iter()
            .map(|material| material.credential_ref.as_str())
            .collect::<HashSet<_>>();

        assert_eq!(filtered_refs, relay_refs);
        assert!(
            entry_refs
                .difference(&relay_refs)
                .all(|credential_ref| !filtered_refs.contains(credential_ref)),
            "node-agent projection must not receive unrelated route credentials"
        );

        cleanup_route_material_paths(&materials_path, &key_path);
    }

    #[test]
    fn route_credential_rotation_revokes_old_material_and_keeps_view_redacted() {
        let (materials_path, key_path) = temp_route_material_paths("rotate-redaction");
        let generated = node_agent_generated_config(generated_cluster_config(), "node-relay");
        let materials =
            ensure_node_route_credentials(&materials_path, &key_path, "node-relay", &generated)
                .expect("route credentials are issued");
        let credential_ref = materials[0].credential_ref.clone();

        let master_key =
            load_or_create_route_material_master_key(&key_path).expect("master key loads");
        let mut store =
            load_route_material_store(&materials_path).expect("route material store loads");
        rotate_route_credential_in_store(&mut store, &credential_ref, &master_key)
            .expect("credential rotates");
        encrypt_route_material_store(&mut store, &master_key).expect("rotated store encrypts");
        persist_route_material_store(&materials_path, &store).expect("rotated store persists");

        let view = route_material_store_view(&store);
        let matching = view
            .credentials
            .iter()
            .filter(|credential| credential.credential_ref == credential_ref)
            .collect::<Vec<_>>();
        assert_eq!(matching.len(), 2);
        assert_eq!(
            matching
                .iter()
                .filter(|credential| credential.active)
                .count(),
            1
        );
        assert_eq!(
            matching
                .iter()
                .filter(|credential| !credential.active)
                .count(),
            1
        );
        assert!(
            matching
                .iter()
                .all(|credential| credential.encrypted_private_key)
        );

        let active_materials = active_route_materials_for_node(&generated, &store, &master_key)
            .expect("active route materials decrypt");
        assert_eq!(
            active_materials
                .iter()
                .filter(|material| material.credential_ref == credential_ref)
                .count(),
            1
        );

        let serialized_view =
            serde_json::to_string(&view).expect("route material admin view serializes");
        assert!(!serialized_view.contains("PRIVATE KEY"));
        assert!(!serialized_view.contains("private_key_pem"));

        cleanup_route_material_paths(&materials_path, &key_path);
    }

    #[test]
    fn route_material_admin_actions_have_specific_secret_free_audit_events() {
        tokio::runtime::Runtime::new().unwrap().block_on(async {
            let config = isolated_app_config("route-material-audit");
            let materials_path = config.route_materials_path.clone();
            let key_path = config.route_materials_key_path.clone();
            let generated = node_agent_generated_config(generated_cluster_config(), "node-relay");
            let materials =
                ensure_node_route_credentials(&materials_path, &key_path, "node-relay", &generated)
                    .expect("route credentials are issued");
            let credential_ref = materials[0].credential_ref.clone();

            let state = AppState::new(config).expect("panel state loads");
            let login = state
                .login("127.0.0.1", "admin", "password", None, None)
                .await
                .expect("admin login succeeds");

            state
                .rotate_route_credential(&login.token, &credential_ref)
                .await
                .expect("route credential rotates");
            state
                .revoke_route_credential(&login.token, &credential_ref)
                .await
                .expect("route credential revokes");
            state
                .rotate_route_ca(&login.token)
                .await
                .expect("route CA rotates");

            let events = state
                .recent_audit_events(&login.token, AuditEventsQuery::default())
                .await
                .expect("audit query succeeds");

            assert!(
                events
                    .iter()
                    .any(|event| event.event_type == AuditEventType::RouteCredentialRotated)
            );
            assert!(
                events
                    .iter()
                    .any(|event| event.event_type == AuditEventType::RouteCredentialRevoked)
            );
            assert!(
                events
                    .iter()
                    .any(|event| event.event_type == AuditEventType::RouteCaRotated)
            );
            assert!(!events.iter().any(|event| {
                event.detail.contains("PRIVATE KEY")
                    || event.detail.contains("private_key")
                    || event.detail.contains("ciphertext")
            }));
            assert!(!events.iter().any(|event| {
                event.event_type == AuditEventType::SecuritySettingsUpdated
                    && event.detail.contains("route")
            }));

            cleanup_route_material_paths(&materials_path, &key_path);
        });
    }

    #[test]
    fn revoked_route_credential_is_not_reissued_until_explicit_rotation() {
        let (materials_path, key_path) = temp_route_material_paths("revoke-tombstone");
        let generated = node_agent_generated_config(generated_cluster_config(), "node-relay");
        let materials =
            ensure_node_route_credentials(&materials_path, &key_path, "node-relay", &generated)
                .expect("route credentials are issued");
        let credential_ref = materials[0].credential_ref.clone();

        let master_key =
            load_or_create_route_material_master_key(&key_path).expect("master key loads");
        let mut store =
            load_route_material_store(&materials_path).expect("route material store loads");
        revoke_route_credential_in_store(&mut store, &credential_ref)
            .expect("credential is revoked");
        encrypt_route_material_store(&mut store, &master_key).expect("revoked store encrypts");
        persist_route_material_store(&materials_path, &store).expect("revoked store persists");

        let after_revoke =
            ensure_node_route_credentials(&materials_path, &key_path, "node-relay", &generated)
                .expect("node credential request after revoke succeeds");
        assert!(
            after_revoke
                .iter()
                .all(|material| material.credential_ref != credential_ref),
            "revoked credential_ref must not be silently reissued"
        );

        let store = load_route_material_store(&materials_path).expect("route material store loads");
        let view = route_material_store_view(&store);
        assert!(view.revoked_credential_refs.iter().any(|revocation| {
            revocation.credential_ref == credential_ref && revocation.revoked_at_unix > 0
        }));

        let mut store = store;
        rotate_route_credential_in_store(&mut store, &credential_ref, &master_key)
            .expect("explicit rotation restores a new active credential");
        encrypt_route_material_store(&mut store, &master_key).expect("rotated store encrypts");
        persist_route_material_store(&materials_path, &store).expect("rotated store persists");

        let after_rotation =
            ensure_node_route_credentials(&materials_path, &key_path, "node-relay", &generated)
                .expect("node credential request after rotation succeeds");
        assert!(
            after_rotation
                .iter()
                .any(|material| material.credential_ref == credential_ref),
            "explicit rotation must restore delivery for the credential_ref"
        );
        let view = route_material_store_view(&store);
        assert!(
            !view
                .revoked_credential_refs
                .iter()
                .any(|revocation| revocation.credential_ref == credential_ref)
        );

        cleanup_route_material_paths(&materials_path, &key_path);
    }

    #[test]
    fn node_apply_route_credential_diagnostics_fail_closed_on_revoked_ref() {
        let (materials_path, key_path) = temp_route_material_paths("apply-route-tombstone");
        let generated = node_agent_generated_config(generated_cluster_config(), "node-relay");
        let materials =
            ensure_node_route_credentials(&materials_path, &key_path, "node-relay", &generated)
                .expect("route credentials are issued");
        let credential_ref = materials[0].credential_ref.clone();

        let master_key =
            load_or_create_route_material_master_key(&key_path).expect("master key loads");
        let mut store =
            load_route_material_store(&materials_path).expect("route material store loads");
        revoke_route_credential_in_store(&mut store, &credential_ref)
            .expect("credential is revoked");
        encrypt_route_material_store(&mut store, &master_key).expect("revoked store encrypts");
        persist_route_material_store(&materials_path, &store).expect("revoked store persists");

        let config = AppConfig {
            route_materials_path: materials_path.clone(),
            route_materials_key_path: key_path.clone(),
            ..AppConfig::default()
        };
        let diagnostics = route_material_apply_diagnostics(&config, &generated)
            .expect("route material diagnostics are built");

        assert_eq!(diagnostics.status, NodeApplyStageStatus::Failed);
        assert_eq!(diagnostics.required_ref_count, 2);
        assert_eq!(diagnostics.active_required_ref_count, 1);
        assert!(diagnostics.revoked_required_refs.contains(&credential_ref));
        assert!(diagnostics.detail.contains("revoked required refs"));
        let status_view = node_route_credential_status_view(diagnostics.clone());
        assert!(!status_view.safe_to_apply);
        assert_eq!(status_view.required_ref_count, 2);
        assert_eq!(status_view.active_ref_count, 1);
        assert!(status_view.revoked_required_refs.contains(&credential_ref));

        let node = test_node("node-relay", "node-relay");
        let view = build_node_apply_status_view(
            node,
            generated.revision.clone(),
            Vec::new(),
            Vec::new(),
            None,
            Some(diagnostics),
            node_agent_runtime_component_requirements_for_inbounds(&generated.inbounds),
            1_000,
        );

        assert!(view.stages.iter().any(|stage| {
            stage.stage == "route_credentials" && stage.status == NodeApplyStageStatus::Failed
        }));
        assert!(
            view.blocking_issues
                .iter()
                .any(|issue| { issue.contains("route credential") && issue.contains("revoked") })
        );

        cleanup_route_material_paths(&materials_path, &key_path);
    }

    #[test]
    fn subscription_catalog_runtime_manages_plans_clients_and_access_policy() {
        let mut runtime = SubscriptionCatalogRuntime {
            plans: HashMap::new(),
            clients: HashMap::new(),
            devices: HashMap::new(),
            enrollment_grants: HashMap::new(),
            sessions: HashMap::new(),
            enforcement_actions: HashMap::new(),
            usage_points: Vec::new(),
        };

        let plan = runtime
            .create_plan(CreateSubscriptionPlanRequest {
                name: "Premium".to_string(),
                description: Some("EU cluster access".to_string()),
                enabled: Some(true),
            })
            .expect("plan is created");
        let client = runtime
            .create_client(
                &plan.id,
                CreateSubscriptionClientRequest {
                    name: "client-a".to_string(),
                    status: None,
                    max_simultaneous_devices: Some(3),
                    max_simultaneous_ips: None,
                    data_limit_bytes: Some(1000),
                    expire_at_unix: Some(9000),
                    note: Some("test".to_string()),
                    access_policy: Some(SubscriptionClientNodeAccessPolicy {
                        allow_all_nodes: false,
                        node_ids: vec!["node-a".to_string()],
                        cluster_ids: Vec::new(),
                        allow_all_protocols: true,
                        protocols: Vec::new(),
                    }),
                },
            )
            .expect("client is created");

        assert_eq!(
            runtime
                .list_plans(
                    SubscriptionCatalogQuery {
                        search: None,
                        limit: None
                    },
                    TEST_MAX_LIST_PAGE_SIZE
                )
                .len(),
            1
        );
        assert_eq!(
            runtime
                .list_clients(
                    Some(&plan.id),
                    SubscriptionCatalogQuery {
                        search: None,
                        limit: None
                    },
                    TEST_MAX_LIST_PAGE_SIZE
                )
                .len(),
            1
        );
        assert_eq!(client.used_traffic_bytes, 0);
        assert_eq!(client.access_policy.node_ids, vec!["node-a".to_string()]);
        assert!(runtime.delete_plan(&plan.id).is_err());

        let revoked = runtime
            .revoke_client(&client.id)
            .expect("client can be revoked");
        assert_eq!(revoked.status, SubscriptionCatalogClientStatus::Revoked);
        assert_ne!(revoked.subscription_token, client.subscription_token);
    }

