    #[test]
    fn node_agent_usage_report_binds_node_id_to_authenticated_node() {
        tokio::runtime::Runtime::new().unwrap().block_on(async {
            let mut config = isolated_app_config("node-agent-usage-report");
            config.runtime_limits.max_subscription_usage_points_buffered = 10;
            let state = AppState::new(config).expect("panel state loads");
            let login = state
                .login("127.0.0.1", "admin", "password", None, None)
                .await
                .expect("admin login succeeds");
            let node = state
                .create_node(
                    &login.token,
                    CreateNodeRequest {
                        name: "node-a".to_string(),
                        address: "node-a.example.test".to_string(),
                        port: 62050,
                        api_port: 62051,
                        usage_coefficient: 1.0,
                        enabled: true,
                        local_api_token: None,
                    },
                )
                .await
                .expect("node is created");
            let rotated = state
                .rotate_node_auth_token(&login.token, &node.id)
                .await
                .expect("node auth token is issued");
            let plan = state
                .create_subscription_plan(
                    &login.token,
                    CreateSubscriptionPlanRequest {
                        name: "Usage plan".to_string(),
                        description: None,
                        enabled: None,
                    },
                )
                .await
                .expect("plan is created");
            let client = state
                .create_subscription_client(
                    &login.token,
                    &plan.id,
                    CreateSubscriptionClientRequest {
                        name: "usage-client".to_string(),
                        status: None,
                        max_simultaneous_devices: None,
                        max_simultaneous_ips: None,
                        data_limit_bytes: None,
                        expire_at_unix: None,
                        note: None,
                        access_policy: None,
                    },
                )
                .await
                .expect("client is created");

            let rejected = state
                .node_agent_report_subscription_usage(
                    &rotated.auth_token,
                    &client.id,
                    ReportSubscriptionUsageRequest {
                        at_unix: Some(100),
                        node_id: Some("other-node".to_string()),
                        cluster_id: None,
                        bytes_downlink: 1,
                        bytes_uplink: 1,
                    },
                )
                .await;
            assert!(matches!(
                rejected,
                Err(SecurityError::InvalidSecuritySettings(
                    "subscription usage report node_id does not match authenticated node"
                ))
            ));

            state
                .node_agent_report_subscription_usage(
                    &rotated.auth_token,
                    &client.id,
                    ReportSubscriptionUsageRequest {
                        at_unix: Some(101),
                        node_id: None,
                        cluster_id: Some("cluster-a".to_string()),
                        bytes_downlink: 10,
                        bytes_uplink: 5,
                    },
                )
                .await
                .expect("node-bound usage report succeeds");
            let detail = state
                .subscription_client_usage_detail(
                    &login.token,
                    &client.id,
                    SubscriptionUsageQuery {
                        window: Some(SubscriptionUsageWindowPreset::Custom),
                        from_unix: Some(100),
                        to_unix: Some(102),
                    },
                )
                .await
                .expect("usage detail is returned");

            assert_eq!(detail.points.len(), 1);
            assert_eq!(detail.points[0].node_id.as_deref(), Some(node.id.as_str()));
            assert_eq!(detail.points[0].cluster_id.as_deref(), Some("cluster-a"));
        });
    }

    #[test]
    fn subscription_device_registry_hashes_fingerprints_and_enforces_device_limit() {
        let mut runtime = SubscriptionCatalogRuntime {
            plans: HashMap::new(),
            clients: HashMap::new(),
            devices: HashMap::new(),
            enrollment_grants: HashMap::new(),
            sessions: HashMap::new(),
            enforcement_actions: HashMap::new(),
            usage_points: Vec::new(),
        };
        let plan = runtime
            .create_plan(CreateSubscriptionPlanRequest {
                name: "Device plan".to_string(),
                description: None,
                enabled: None,
            })
            .expect("plan is created");
        let client = runtime
            .create_client(
                &plan.id,
                CreateSubscriptionClientRequest {
                    name: "device-client".to_string(),
                    status: None,
                    max_simultaneous_devices: Some(1),
                    max_simultaneous_ips: None,
                    data_limit_bytes: None,
                    expire_at_unix: None,
                    note: None,
                    access_policy: None,
                },
            )
            .expect("client is created");
        let key = [7_u8; 32];
        let first_raw_fingerprint = "raw-device-fingerprint-alpha";
        let first_hash = hash_subscription_device_fingerprint(first_raw_fingerprint, &key)
            .expect("fingerprint is hashed");
        let first = runtime
            .register_device(
                &client.id,
                first_hash,
                None,
                None,
                RegisterSubscriptionDeviceRequest {
                    fingerprint: first_raw_fingerprint.to_string(),
                    label: Some("phone".to_string()),
                    platform: Some("android".to_string()),
                    wireguard_public_key: None,
                    wireguard_allowed_ips: Vec::new(),
                },
                5,
            )
            .expect("first device is registered");

        assert!(first.admitted);
        assert_eq!(first.active_device_count, 1);
        let device = first.device.expect("admitted device is returned");
        let stored_device = runtime
            .devices
            .get(&device.id)
            .expect("device fingerprint is stored internally");
        let stored_fingerprint_hmac = stored_device.fingerprint_hmac_sha256.clone();
        assert_ne!(stored_fingerprint_hmac, first_raw_fingerprint);
        assert!(
            !serde_json::to_string(&device)
                .expect("device serializes")
                .contains(first_raw_fingerprint)
        );
        assert!(
            !serde_json::to_string(&device)
                .expect("device serializes")
                .contains(&stored_fingerprint_hmac)
        );

        let denied = runtime
            .register_device(
                &client.id,
                hash_subscription_device_fingerprint("raw-device-fingerprint-beta", &key)
                    .expect("fingerprint is hashed"),
                None,
                None,
                RegisterSubscriptionDeviceRequest {
                    fingerprint: "raw-device-fingerprint-beta".to_string(),
                    label: None,
                    platform: None,
                    wireguard_public_key: None,
                    wireguard_allowed_ips: Vec::new(),
                },
                5,
            )
            .expect("device decision is returned");
        assert!(!denied.admitted);
        assert!(denied.device.is_none());
        assert_eq!(runtime.devices.len(), 1);

        let revoked = runtime
            .revoke_device(&client.id, &device.id)
            .expect("device is revoked");
        assert_eq!(revoked.status, SubscriptionDeviceStatus::Revoked);
        let denied_revoked = runtime
            .register_device(
                &client.id,
                stored_fingerprint_hmac,
                None,
                None,
                RegisterSubscriptionDeviceRequest {
                    fingerprint: first_raw_fingerprint.to_string(),
                    label: None,
                    platform: None,
                    wireguard_public_key: None,
                    wireguard_allowed_ips: Vec::new(),
                },
                5,
            )
            .expect("revoked device decision is returned");
        assert!(!denied_revoked.admitted);
        assert!(denied_revoked.reason.contains("revoked"));

        let replacement = runtime
            .register_device(
                &client.id,
                hash_subscription_device_fingerprint("raw-device-fingerprint-gamma", &key)
                    .expect("fingerprint is hashed"),
                None,
                None,
                RegisterSubscriptionDeviceRequest {
                    fingerprint: "raw-device-fingerprint-gamma".to_string(),
                    label: None,
                    platform: None,
                    wireguard_public_key: None,
                    wireguard_allowed_ips: Vec::new(),
                },
                5,
            )
            .expect("replacement device is registered");
        assert!(replacement.admitted);
        runtime
            .revoke_client(&client.id)
            .expect("client is revoked");
        assert!(
            runtime
                .list_devices(
                    &client.id,
                    SubscriptionDevicesQuery {
                        status: Some(SubscriptionDeviceStatus::Active),
                        limit: None,
                    },
                    TEST_MAX_LIST_PAGE_SIZE
                )
                .expect("devices list")
                .is_empty()
        );
    }

    #[test]
    fn wireguard_device_key_lifecycle_projects_active_unique_peers_fail_closed() {
        let mut runtime = SubscriptionCatalogRuntime {
            plans: HashMap::new(),
            clients: HashMap::new(),
            devices: HashMap::new(),
            enrollment_grants: HashMap::new(),
            sessions: HashMap::new(),
            enforcement_actions: HashMap::new(),
            usage_points: Vec::new(),
        };
        let plan = runtime
            .create_plan(CreateSubscriptionPlanRequest {
                name: "WireGuard plan".to_string(),
                description: None,
                enabled: None,
            })
            .expect("plan is created");
        let client = runtime
            .create_client(
                &plan.id,
                CreateSubscriptionClientRequest {
                    name: "wireguard-client".to_string(),
                    status: None,
                    max_simultaneous_devices: Some(2),
                    max_simultaneous_ips: None,
                    data_limit_bytes: None,
                    expire_at_unix: None,
                    note: None,
                    access_policy: None,
                },
            )
            .expect("client is created");
        let master_key = [19_u8; 32];
        let public_key = "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=";
        let request = RegisterSubscriptionDeviceRequest {
            fingerprint: "wireguard-device-alpha".to_string(),
            label: Some("phone".to_string()),
            platform: Some("android".to_string()),
            wireguard_public_key: Some(public_key.to_string()),
            wireguard_allowed_ips: vec!["10.77.0.2/32".to_string()],
        };
        validate_register_subscription_device_request(&request)
            .expect("WireGuard registration request is valid");
        let response = runtime
            .register_device(
                &client.id,
                hash_subscription_device_fingerprint(&request.fingerprint, &master_key)
                    .expect("generic fingerprint is hashed"),
                None,
                Some(
                    hash_subscription_device_fingerprint(
                        &wireguard_device_fingerprint(public_key),
                        &master_key,
                    )
                    .expect("WireGuard fingerprint is hashed"),
                ),
                request,
                10,
            )
            .expect("WireGuard device is registered");
        assert!(response.admitted);
        let device_id = response.device.expect("device view is returned").id;

        let (verdict, _, admitted_device_id) = runtime
            .session_device_verdict(
                &client,
                Some(&wireguard_device_fingerprint(public_key)),
                &master_key,
            )
            .expect("WireGuard fingerprint policy is evaluated");
        assert_eq!(verdict, SubscriptionSessionVerdict::Allow);
        assert_eq!(admitted_device_id.as_deref(), Some(device_id.as_str()));

        let duplicate_key = runtime.register_device(
            &client.id,
            hash_subscription_device_fingerprint("wireguard-device-beta", &master_key)
                .expect("second fingerprint is hashed"),
            None,
            Some(
                hash_subscription_device_fingerprint(
                    &wireguard_device_fingerprint(public_key),
                    &master_key,
                )
                .expect("WireGuard fingerprint is hashed"),
            ),
            RegisterSubscriptionDeviceRequest {
                fingerprint: "wireguard-device-beta".to_string(),
                label: None,
                platform: None,
                wireguard_public_key: Some(public_key.to_string()),
                wireguard_allowed_ips: vec!["10.77.0.3/32".to_string()],
            },
            10,
        );
        assert!(duplicate_key.is_err());

        let network = NetworkRuntime {
            inbounds: HashMap::new(),
            hosts: HashMap::new(),
            proxy_profiles: HashMap::from([(
                "wg-main".to_string(),
                ProxyProfile {
                    id: "wg-main".to_string(),
                    name: "WireGuard".to_string(),
                    proxy_type: ProxyType::Wireguard,
                    settings_json:
                        r#"{"inbound":"wg-in","private_key":"server-private","address":"10.77.0.1/24"}"#
                            .to_string(),
                    excluded_inbound_tags: Vec::new(),
                    created_at_unix: 1,
                    updated_at_unix: 1,
                },
            )]),
        };
        let devices = runtime.devices.values().cloned().collect::<Vec<_>>();
        let generated = network
            .generated_subscription_client_config_for_runtime(&client, &devices)
            .expect("active WireGuard peer is projected");
        assert_eq!(generated.proxy_profiles.len(), 1);
        let settings: serde_json::Value =
            serde_json::from_str(&generated.proxy_profiles[0].settings_json)
                .expect("generated WireGuard settings are JSON");
        assert_eq!(settings["peer_public_key"], public_key);
        assert_eq!(settings["allowed_ips"][0], "10.77.0.2/32");
        assert_eq!(
            settings["device_fingerprint"],
            wireguard_device_fingerprint(public_key)
        );

        runtime
            .revoke_device(&client.id, &device_id)
            .expect("WireGuard device is revoked");
        let devices = runtime.devices.values().cloned().collect::<Vec<_>>();
        let generated = network
            .generated_subscription_client_config_for_runtime(&client, &devices)
            .expect("revoked WireGuard peer is omitted");
        assert!(generated.proxy_profiles.is_empty());
    }

    #[test]
    fn device_limit_generates_unique_credentials_for_every_supported_protocol() {
        let mut catalog = SubscriptionCatalogRuntime {
            plans: HashMap::new(),
            clients: HashMap::new(),
            devices: HashMap::new(),
            enrollment_grants: HashMap::new(),
            sessions: HashMap::new(),
            enforcement_actions: HashMap::new(),
            usage_points: Vec::new(),
        };
        let plan = catalog
            .create_plan(CreateSubscriptionPlanRequest {
                name: "Universal devices".to_string(),
                description: None,
                enabled: None,
            })
            .expect("plan is created");
        let client = catalog
            .create_client(
                &plan.id,
                CreateSubscriptionClientRequest {
                    name: "multi-protocol".to_string(),
                    status: None,
                    max_simultaneous_devices: Some(2),
                    max_simultaneous_ips: None,
                    data_limit_bytes: None,
                    expire_at_unix: None,
                    note: None,
                    access_policy: None,
                },
            )
            .expect("client is created");
        let key = [23_u8; 32];
        let mut device_ids = Vec::new();
        for (fingerprint, label) in [
            ("universal-device-alpha", "phone"),
            ("universal-device-beta", "laptop"),
        ] {
            let response = catalog
                .register_device(
                    &client.id,
                    hash_subscription_device_fingerprint(fingerprint, &key)
                        .expect("fingerprint is hashed"),
                    None,
                    None,
                    RegisterSubscriptionDeviceRequest {
                        fingerprint: fingerprint.to_string(),
                        label: Some(label.to_string()),
                        platform: None,
                        wireguard_public_key: None,
                        wireguard_allowed_ips: Vec::new(),
                    },
                    10,
                )
                .expect("device is registered");
            device_ids.push(response.device.expect("device view").id);
        }
        assert!(
            catalog.subscription_render_device(&client, None).is_err(),
            "limited subscriptions must not render a shared credential"
        );

        let profiles = [
            (ProxyType::Vless, r#"{"id":"shared-vless"}"#),
            (
                ProxyType::Hysteria2,
                r#"{"password":"shared-hy2","tls_certificate_file":"/etc/hy2.crt","tls_key_file":"/etc/hy2.key"}"#,
            ),
        ]
        .into_iter()
        .enumerate()
        .map(|(index, (proxy_type, settings_json))| {
            let id = format!("profile-{index}");
            (
                id.clone(),
                ProxyProfile {
                    id,
                    name: format!("Profile {index}"),
                    proxy_type,
                    settings_json: settings_json.to_string(),
                    excluded_inbound_tags: Vec::new(),
                    created_at_unix: 1,
                    updated_at_unix: 1,
                },
            )
        })
        .collect();
        let network = NetworkRuntime {
            inbounds: HashMap::new(),
            hosts: HashMap::new(),
            proxy_profiles: profiles,
        };
        let devices = catalog.devices.values().cloned().collect::<Vec<_>>();
        let generated = network.generated_core_config(
            Vec::new(),
            vec![client.clone()],
            devices,
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
        );
        assert_eq!(generated.users.len(), 2);
        assert!(generated.users.iter().all(|user| {
            user.username
                .starts_with(&format!("catalog/{}/device/", client.id))
                && user.proxy_profiles.len() == 2
        }));
        for profile_index in 0..2 {
            let left: serde_json::Value = serde_json::from_str(
                &generated.users[0].proxy_profiles[profile_index].settings_json,
            )
            .expect("left profile settings");
            let right: serde_json::Value = serde_json::from_str(
                &generated.users[1].proxy_profiles[profile_index].settings_json,
            )
            .expect("right profile settings");
            let left_credential = left
                .get("id")
                .or_else(|| left.get("password"))
                .expect("device credential");
            let right_credential = right
                .get("id")
                .or_else(|| right.get("password"))
                .expect("device credential");
            assert_ne!(left_credential, right_credential);
            assert_eq!(left["runtime_username"], generated.users[0].username);
            assert_eq!(right["runtime_username"], generated.users[1].username);
        }

        let runtime_username = generated.users[0].username.clone();
        let (_, runtime_device_id) = parse_subscription_runtime_username(&runtime_username)
            .expect("device principal parses");
        let (verdict, _, admitted_device_id) = catalog.session_runtime_device_verdict(
            &client,
            runtime_device_id.expect("device id is present"),
        );
        assert_eq!(verdict, SubscriptionSessionVerdict::Allow);
        assert_eq!(admitted_device_id.as_deref(), runtime_device_id);

        catalog
            .revoke_device(&client.id, &device_ids[0])
            .expect("first device is revoked");
        let generated = network.generated_core_config(
            Vec::new(),
            vec![client],
            catalog.devices.values().cloned().collect(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
        );
        assert_eq!(generated.users.len(), 1);
        assert!(generated.users[0].username.ends_with(&device_ids[1]));
    }

